using CricketManager.Data;
using CricketManager.Data.Seeding;
using CricketManager.Domain.Entities;
using CricketManager.Domain.Enums;
using CricketManager.Domain.Services;
using CricketManager.Domain.ValueObjects;
using CricketManager.Tests;

Console.WriteLine("=== CricketManager Phase 1+2 Test Suite ===\n");
TestRunner.Init(args);

// --- Domain: Player format suitability ---
TestRunner.Run("T20 power hitter rates higher for T20 than Test", () =>
{
    var basher = new Player
    {
        FirstName = "Rashid",
        LastName = "Bash",
        Batting = new BattingAttributes
        {
            PowerHitting = 18,
            BoundaryHitting = 18,
            DeathOverBatting = 17,
            StrikeRotation = 15,
            Aggression = 18,
            Technique = 9,
            DefensiveAbility = 7
        },
        Mental = new MentalAttributes { Concentration = 8, PressureHandling = 12, Adaptability = 14 }
    };
    basher.RecalculateFormatSuitability();

    TestRunner.IsTrue(basher.FormatSuitability.T20Suitability > basher.FormatSuitability.TestSuitability,
        $"T20={basher.FormatSuitability.T20Suitability:F1} should exceed Test={basher.FormatSuitability.TestSuitability:F1}");
});

TestRunner.Run("Technical grinder rates higher for Test than T20", () =>
{
    var grinder = new Player
    {
        FirstName = "Old",
        LastName = "School",
        Batting = new BattingAttributes
        {
            Technique = 18,
            DefensiveAbility = 18,
            AgainstPace = 16,
            AgainstSpin = 16,
            RiskManagement = 17,
            PowerHitting = 6,
            BoundaryHitting = 6,
            DeathOverBatting = 5
        },
        Mental = new MentalAttributes { Concentration = 18, PressureHandling = 16 }
    };
    grinder.RecalculateFormatSuitability();

    TestRunner.IsTrue(grinder.FormatSuitability.TestSuitability > grinder.FormatSuitability.T20Suitability,
        $"Test={grinder.FormatSuitability.TestSuitability:F1} should exceed T20={grinder.FormatSuitability.T20Suitability:F1}");
});

// --- Domain: Form system (Section 9) ---
TestRunner.Run("Form improves after a string of good performances and decays when idle", () =>
{
    var form = new FormState();
    form.RecordPerformance(60);
    form.RecordPerformance(70);
    form.RecordPerformance(80);
    TestRunner.IsTrue(form.CurrentForm > 40, $"Form should rise after good run, got {form.CurrentForm:F1}");

    var before = form.CurrentForm;
    form.DecayTowardNeutral(5);
    TestRunner.IsTrue(form.CurrentForm < before, "Form should decay toward 0 when player is inactive");
});

// --- Domain: Reputation is tiered, not a single number (Section 2) ---
TestRunner.Run("Reputation gains are damped at continental/worldwide tiers vs domestic", () =>
{
    var rep = new Reputation(domestic: 20, continental: 5, worldwide: 0);
    rep.Adjust(domesticDelta: 15, continentalDelta: 3, worldwideDelta: 0.5);

    TestRunner.AreEqual(35.0, rep.Domestic);
    TestRunner.AreEqual(8.0, rep.Continental);
    TestRunner.AreEqual(0.5, rep.Worldwide);
    TestRunner.IsTrue(rep.Domestic > rep.Worldwide, "A domestic-only performer shouldn't have equal worldwide reputation");
});

TestRunner.Run("Reputation clamps to 0-100 range", () =>
{
    var rep = new Reputation(domestic: 95);
    rep.Adjust(domesticDelta: 50);
    TestRunner.AreEqual(100.0, rep.Domestic);
});

// --- Domain: Coach attribute seeding from history (Section 79/84) ---
TestRunner.Run("Former international captain starts with stronger leadership than a never-played coach", () =>
{
    var exCaptain = new Coach
    {
        PlayingExperience = PlayingExperience.FormerCaptain,
        License = CoachingLicense.Level1
    };
    exCaptain.SeedAttributesFromHistory();

    var analyticsCoach = new Coach
    {
        PlayingExperience = PlayingExperience.NeverPlayedProfessionally,
        License = CoachingLicense.InternationalElite
    };
    analyticsCoach.SeedAttributesFromHistory();

    TestRunner.IsTrue(exCaptain.Attributes.Leadership > analyticsCoach.Attributes.Leadership,
        $"Ex-captain leadership {exCaptain.Attributes.Leadership} should exceed {analyticsCoach.Attributes.Leadership}");
    TestRunner.IsTrue(analyticsCoach.Attributes.TacticalKnowledge > exCaptain.Attributes.TacticalKnowledge,
        $"Elite-licensed coach tactical knowledge {analyticsCoach.Attributes.TacticalKnowledge} should exceed {exCaptain.Attributes.TacticalKnowledge}");
    TestRunner.IsTrue(exCaptain.Reputation.Domestic > 5,
        "Playing pedigree should give a starting reputation bump above the baseline of 5");
});

TestRunner.Run("Coach attributes never exceed the 1-20 scale after seeding", () =>
{
    var coach = new Coach { PlayingExperience = PlayingExperience.InternationalStar, License = CoachingLicense.InternationalElite };
    coach.SeedAttributesFromHistory();
    foreach (var prop in typeof(CoachAttributes).GetProperties())
    {
        var val = (int)prop.GetValue(coach.Attributes)!;
        TestRunner.InRange(val, 1, 20, prop.Name);
    }
});

// --- Data layer: JSON repository round-trip persistence ---
await TestRunner.RunAsync("Player saved to JSON repository survives a full reload", async () =>
{
    var tempDir = Path.Combine(Path.GetTempPath(), "cricketmanager_test_" + Guid.NewGuid());
    try
    {
        var player = new Player
        {
            FirstName = "Babar",
            LastName = "Test",
            Nationality = "Pakistan",
            DateOfBirth = new DateOnly(1994, 10, 9),
            BattingHand = BattingHand.Right,
            PrimaryRole = PlayerRole.Batsman,
            CurrentAbility = 155,
            PotentialAbility = 170
        };
        player.Batting.Technique = 18;
        player.RecalculateFormatSuitability();

        var ctx1 = new GameDataContext(tempDir);
        await ctx1.Players.AddAsync(player);
        await ctx1.SaveAllAsync();

        // Fresh context = simulates reloading the save from disk
        var ctx2 = new GameDataContext(tempDir);
        var reloaded = await ctx2.Players.GetByIdAsync(player.Id);

        TestRunner.IsTrue(reloaded is not null, "Reloaded player should not be null");
        TestRunner.AreEqual("Babar", reloaded!.FirstName);
        TestRunner.AreEqual(155, reloaded.CurrentAbility);
        TestRunner.AreEqual(18, reloaded.Batting.Technique);
        TestRunner.IsTrue(reloaded.FormatSuitability.TestSuitability > 0, "Nested value object should survive round-trip");
    }
    finally
    {
        if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true);
    }
});

await TestRunner.RunAsync("Coach + CoachingContract relationship persists across save/reload", async () =>
{
    var tempDir = Path.Combine(Path.GetTempPath(), "cricketmanager_test_" + Guid.NewGuid());
    try
    {
        var coach = new Coach { FirstName = "Misbah", LastName = "TestCoach", PlayingExperience = PlayingExperience.FormerCaptain };
        coach.SeedAttributesFromHistory();

        var team = new Team { Name = "Lahore Qalandars (Test)", Country = "Pakistan" };
        team.CurrentCoachId = coach.Id;
        coach.CurrentTeamId = team.Id;

        var contract = new CoachingContract
        {
            CoachId = coach.Id,
            TeamId = team.Id,
            StartDate = new DateOnly(2026, 1, 1),
            EndDate = new DateOnly(2028, 12, 31),
            AnnualSalary = 250000
        };
        contract.ObjectivesByYear[1] = new List<string> { "Finish top 4" };
        coach.CurrentContractId = contract.Id;

        var ctx1 = new GameDataContext(tempDir);
        await ctx1.Coaches.AddAsync(coach);
        await ctx1.Teams.AddAsync(team);
        await ctx1.CoachingContracts.AddAsync(contract);
        await ctx1.SaveAllAsync();

        var ctx2 = new GameDataContext(tempDir);
        var reloadedCoach = await ctx2.Coaches.GetByIdAsync(coach.Id);
        var reloadedTeam = await ctx2.Teams.GetByIdAsync(team.Id);
        var reloadedContract = await ctx2.CoachingContracts.GetByIdAsync(contract.Id);

        TestRunner.IsTrue(reloadedCoach is not null && reloadedTeam is not null && reloadedContract is not null,
            "All three entities should reload");
        TestRunner.AreEqual(team.Id, reloadedCoach!.CurrentTeamId!.Value);
        TestRunner.AreEqual(coach.Id, reloadedTeam!.CurrentCoachId!.Value);
        TestRunner.AreEqual(250000.0, reloadedContract!.AnnualSalary);
        TestRunner.AreEqual("Finish top 4", reloadedContract.ObjectivesByYear[1][0]);
    }
    finally
    {
        if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true);
    }
});

// === Phase 2: World seeding ===

TestRunner.Run("WorldSeeder generates the requested number of teams and squad sizes", () =>
{
    var seeder = new WorldSeeder(seed: 42);
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 13);

    TestRunner.AreEqual(4, teams.Count);
    TestRunner.AreEqual(52, players.Count); // 4 * 13
    foreach (var team in teams)
        TestRunner.AreEqual(13, team.SquadPlayerIds.Count, $"{team.Name} squad size");
});

TestRunner.Run("Seeded squads have role-appropriate skill shape (bowlers out-bowl batsmen)", () =>
{
    var seeder = new WorldSeeder(seed: 7);
    var (_, players) = seeder.GenerateStarterWorld(teamCount: 1, squadSize: 13);

    double avgBatsmanBowling = players.Where(p => p.PrimaryRole == PlayerRole.Batsman)
        .Average(p => p.Bowling.Accuracy);
    double avgBowlerBowling = players.Where(p => p.PrimaryRole == PlayerRole.Bowler)
        .Average(p => p.Bowling.Accuracy);

    TestRunner.IsTrue(avgBowlerBowling > avgBatsmanBowling,
        $"Bowlers ({avgBowlerBowling:F1}) should out-bowl specialist batsmen ({avgBatsmanBowling:F1}) on average");
});

TestRunner.Run("Stronger teams produce higher average current ability squads", () =>
{
    var seeder = new WorldSeeder(seed: 99);
    var weakTeam = new Team { Strength = 40 };
    var strongTeam = new Team { Strength = 85 };

    // Use reflection-free approach: generate two full worlds and compare team-level averages,
    // since GenerateSquad is private - this exercises the public seeding contract instead.
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 13);
    var byTeamAvgAbility = teams.Select(t => new
    {
        t.Name,
        t.Strength,
        AvgAbility = players.Where(p => t.SquadPlayerIds.Contains(p.Id)).Average(p => p.CurrentAbility)
    }).OrderBy(x => x.Strength).ToList();

    // Weakest-strength team should generally not out-average the strongest-strength team.
    TestRunner.IsTrue(byTeamAvgAbility.First().AvgAbility <= byTeamAvgAbility.Last().AvgAbility + 15,
        "Team strength should meaningfully correlate with squad ability (allowing some random variance)");
});

// === Phase 2: Selection evaluator ===

TestRunner.Run("In-form lower-ability player can outrank a higher-ability player in poor form (Section 8)", () =>
{
    var evaluator = new PlayerSelectionEvaluator();

    var highPotentialPoorForm = new Player
    {
        FirstName = "Player",
        LastName = "A",
        CurrentAbility = 170,
        PotentialAbility = 190
    };
    highPotentialPoorForm.Batting = new BattingAttributes { PowerHitting = 14, BoundaryHitting = 14, StrikeRotation = 12 };
    highPotentialPoorForm.RecalculateFormatSuitability();
    highPotentialPoorForm.Form.RecordPerformance(-70);
    highPotentialPoorForm.Form.RecordPerformance(-80);
    highPotentialPoorForm.Form.RecordPerformance(-75);

    var lowerPotentialGreatForm = new Player
    {
        FirstName = "Player",
        LastName = "B",
        CurrentAbility = 130,
        PotentialAbility = 145
    };
    lowerPotentialGreatForm.Batting = new BattingAttributes { PowerHitting = 14, BoundaryHitting = 14, StrikeRotation = 12 };
    lowerPotentialGreatForm.RecalculateFormatSuitability();
    lowerPotentialGreatForm.Form.RecordPerformance(75);
    lowerPotentialGreatForm.Form.RecordPerformance(85);
    lowerPotentialGreatForm.Form.RecordPerformance(80);

    var ranked = evaluator.Rank(new[] { highPotentialPoorForm, lowerPotentialGreatForm }, MatchFormat.T20);

    TestRunner.AreEqual("Player B", ranked[0].PlayerName,
        "In-form Player B should rank above out-of-form higher-ability Player A");
});

TestRunner.Run("Selection evaluator ranks a full seeded squad without error and produces varied scores", () =>
{
    var seeder = new WorldSeeder(seed: 5);
    var (_, players) = seeder.GenerateStarterWorld(teamCount: 1, squadSize: 13);
    var evaluator = new PlayerSelectionEvaluator();

    var ranked = evaluator.Rank(players, MatchFormat.ODI);

    TestRunner.AreEqual(13, ranked.Count);
    TestRunner.IsTrue(ranked.Select(r => r.TotalScore).Distinct().Count() > 1, "Scores should vary across a squad, not be identical");
    // Ranked list should actually be sorted descending.
    for (int i = 1; i < ranked.Count; i++)
        TestRunner.IsTrue(ranked[i - 1].TotalScore >= ranked[i].TotalScore, "Ranking should be descending");
});

// === Phase 2: Career statistics ===

TestRunner.Run("PlayerCareerStats computes batting average and strike rate correctly", () =>
{
    var stats = new PlayerCareerStats { Format = MatchFormat.ODI };
    stats.RecordBattingInnings(runs: 85, ballsFaced: 90, notOut: false, fours: 8, sixes: 2);
    stats.RecordBattingInnings(runs: 40, ballsFaced: 50, notOut: true, fours: 4, sixes: 0);
    stats.RecordBattingInnings(runs: 0, ballsFaced: 3, notOut: false, fours: 0, sixes: 0);

    TestRunner.AreEqual(3, stats.Innings);
    TestRunner.AreEqual(1, stats.Fifties);
    TestRunner.AreEqual(125, stats.Runs);
    // Average = runs / (innings - notouts) = 125 / (3-1) = 62.5
    TestRunner.AreEqual(62.5, stats.BattingAverage);
    TestRunner.IsTrue(stats.StrikeRate > 85 && stats.StrikeRate < 90, $"SR was {stats.StrikeRate:F1}");
});

TestRunner.Run("PlayerCareerStats computes bowling average, economy and 5-wicket haul count", () =>
{
    var stats = new PlayerCareerStats { Format = MatchFormat.Test };
    stats.RecordBowlingInnings(overs: 22, runsConceded: 60, wickets: 5);
    stats.RecordBowlingInnings(overs: 18, runsConceded: 55, wickets: 2);

    TestRunner.AreEqual(1, stats.FiveWicketHauls);
    TestRunner.AreEqual(7, stats.Wickets);
    // Average = 115/7 = 16.43
    TestRunner.InRange(stats.BowlingAverage, 16.0, 16.5);
    // Economy = 115/40 = 2.875
    TestRunner.InRange(stats.Economy, 2.8, 2.95);
});

await TestRunner.RunAsync("Full seeded world (teams+players+stats) saves and reloads intact via GameDataContext", async () =>
{
    var tempDir = Path.Combine(Path.GetTempPath(), "cricketmanager_test_" + Guid.NewGuid());
    try
    {
        var seeder = new WorldSeeder(seed: 123);
        var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 13);

        var ctx1 = new GameDataContext(tempDir);
        foreach (var team in teams) await ctx1.Teams.AddAsync(team);
        foreach (var player in players)
        {
            await ctx1.Players.AddAsync(player);
            var stats = new PlayerCareerStats { PlayerId = player.Id, Format = MatchFormat.T20 };
            stats.RecordBattingInnings(30, 22, false, 3, 1);
            await ctx1.CareerStats.AddAsync(stats);
        }
        await ctx1.SaveAllAsync();

        var ctx2 = new GameDataContext(tempDir);
        var reloadedTeams = await ctx2.Teams.GetAllAsync();
        var reloadedPlayers = await ctx2.Players.GetAllAsync();
        var reloadedStats = await ctx2.CareerStats.GetAllAsync();

        TestRunner.AreEqual(4, reloadedTeams.Count);
        TestRunner.AreEqual(52, reloadedPlayers.Count);
        TestRunner.AreEqual(52, reloadedStats.Count);
        TestRunner.IsTrue(reloadedStats.All(s => s.Runs == 30), "Every reloaded stat row should retain its recorded runs");
    }
    finally
    {
        if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true);
    }
});

// === Player Realism Update: opposition-adjusted performance, contextual stats, roles/traits ===

TestRunner.Run("Opposition strength scales performance value - strong opposition worth more than weak", () =>
{
    var valuation = new PerformanceValuationService();
    double vsWeak = valuation.AdjustForOpposition(rawRating: 80, oppositionStrength: 20);
    double vsStrong = valuation.AdjustForOpposition(rawRating: 80, oppositionStrength: 90);

    TestRunner.IsTrue(vsStrong > vsWeak, $"vsStrong={vsStrong:F1} should exceed vsWeak={vsWeak:F1}");
    TestRunner.IsTrue(vsWeak > 0, "Performance vs weak opposition should still count for something, not be zeroed");
});

TestRunner.Run("Sample-size confidence dampens a single fluke innings", () =>
{
    var valuation = new PerformanceValuationService();
    double firstEverKnock = valuation.ApplySampleConfidence(adjustedRating: 95, priorSampleCount: 0);
    double establishedKnock = valuation.ApplySampleConfidence(adjustedRating: 95, priorSampleCount: 20);

    TestRunner.IsTrue(firstEverKnock < establishedKnock,
        $"A single career-first big innings ({firstEverKnock:F1}) should count for less than the same innings from an established player ({establishedKnock:F1})");
});

TestRunner.Run("Full valuation pipeline: weak-opposition fluke innings barely moves an unproven player", () =>
{
    var valuation = new PerformanceValuationService();
    double value = valuation.ValuePerformance(rawRating: 100, oppositionStrength: 15, priorSampleCount: 0);
    TestRunner.IsTrue(value < 30, $"One flukey century vs a weak team with no track record should stay modest, got {value:F1}");
});

TestRunner.Run("RoleTraitDeriver assigns a natural finisher trait to a death-overs power hitter", () =>
{
    var deriver = new RoleTraitDeriver();
    var finisher = new Player
    {
        FirstName = "Late",
        LastName = "Order",
        PrimaryRole = PlayerRole.Batsman,
        Batting = new BattingAttributes { PowerHitting = 18, DeathOverBatting = 17, BoundaryHitting = 17, Technique = 8, DefensiveAbility = 7 },
        Mental = new MentalAttributes { PressureHandling = 15 }
    };
    deriver.ApplyTo(finisher);

    TestRunner.IsTrue(finisher.BattingTraits.Finisher > 70, $"Finisher trait should be high, got {finisher.BattingTraits.Finisher}");
    TestRunner.AreEqual(BattingRole.LowerOrder, finisher.BattingRole);
});

TestRunner.Run("RoleTraitDeriver assigns opener/top-order role and low finisher trait to a technical grinder", () =>
{
    var deriver = new RoleTraitDeriver();
    var grinder = new Player
    {
        FirstName = "Solid",
        LastName = "Grinder",
        PrimaryRole = PlayerRole.Batsman,
        Batting = new BattingAttributes { Technique = 18, DefensiveAbility = 18, RiskManagement = 16, PowerHitting = 6, DeathOverBatting = 5, BoundaryHitting = 6 },
        Mental = new MentalAttributes { Concentration = 17 }
    };
    deriver.ApplyTo(grinder);

    TestRunner.IsTrue(grinder.BattingRole is BattingRole.Opener or BattingRole.TopOrder,
        $"Expected Opener/TopOrder, got {grinder.BattingRole}");
    TestRunner.IsTrue(grinder.BattingTraits.ClassicalBatter > grinder.BattingTraits.Finisher,
        "A technical grinder should score higher as ClassicalBatter than as Finisher");
});

TestRunner.Run("Natural opener batting at No.7 with few overs left is penalized vs batting in position", () =>
{
    var deriver = new RoleTraitDeriver();
    var opener = new Player
    {
        FirstName = "Top",
        LastName = "Order",
        PrimaryRole = PlayerRole.Batsman,
        Batting = new BattingAttributes { Technique = 17, DefensiveAbility = 16, RiskManagement = 15, PowerHitting = 6, DeathOverBatting = 5 },
        Mental = new MentalAttributes { Concentration = 16 }
    };
    deriver.ApplyTo(opener);

    var modifier = new SituationalPerformanceModifier();
    var normalSituation = new BattingSituation(OversRemainingInInnings: 20, WicketsInHand: 9, Phase: MatchPhase.Powerplay, IsChasing: false);
    var lateSituation = new BattingSituation(OversRemainingInInnings: 3, WicketsInHand: 4, Phase: MatchPhase.DeathOvers, IsChasing: true);

    double inPosition = modifier.GetBattingMultiplier(opener, opener.BattingRole, normalSituation);
    double outOfPosition = modifier.GetBattingMultiplier(opener, BattingRole.LowerOrder, lateSituation);

    TestRunner.IsTrue(outOfPosition < inPosition,
        $"Opener forced into a No.7-at-death situation ({outOfPosition:F2}) should underperform their natural slot ({inPosition:F2})");
    TestRunner.IsTrue(outOfPosition >= 0.7, "Mismatch penalty should never be a hard wall - player can still perform");
});

TestRunner.Run("Finisher trait gets a boost in death overs vs a technical anchor in the same slot", () =>
{
    var deriver = new RoleTraitDeriver();
    var finisher = new Player { PrimaryRole = PlayerRole.Batsman, Batting = new BattingAttributes { PowerHitting = 18, DeathOverBatting = 18, BoundaryHitting = 17 }, Mental = new MentalAttributes { PressureHandling = 15 } };
    var anchor = new Player { PrimaryRole = PlayerRole.Batsman, Batting = new BattingAttributes { DefensiveAbility = 18, RiskManagement = 17, Technique = 16 }, Mental = new MentalAttributes { Concentration = 17 } };
    deriver.ApplyTo(finisher);
    deriver.ApplyTo(anchor);

    var modifier = new SituationalPerformanceModifier();
    var death = new BattingSituation(OversRemainingInInnings: 2, WicketsInHand: 6, Phase: MatchPhase.DeathOvers, IsChasing: true);

    double finisherMult = modifier.GetBattingMultiplier(finisher, finisher.BattingRole, death);
    double anchorMult = modifier.GetBattingMultiplier(anchor, anchor.BattingRole, death);

    TestRunner.IsTrue(finisherMult > anchorMult,
        $"Finisher ({finisherMult:F2}) should outperform an anchor ({anchorMult:F2}) in death overs even both batting in natural-ish slots");
});

TestRunner.Run("Part-time golden-arm bowler doesn't match an elite death specialist's multiplier", () =>
{
    var deriver = new RoleTraitDeriver();
    var partTimer = new Player
    {
        PrimaryRole = PlayerRole.BattingAllrounder,
        Bowling = new BowlingAttributes { Variation = 14, Accuracy = 9, DeathBowling = 8, Yorker = 7 }
    };
    var specialist = new Player
    {
        PrimaryRole = PlayerRole.Bowler,
        Bowling = new BowlingAttributes { DeathBowling = 18, Yorker = 17, SlowerBall = 16, Accuracy = 16 }
    };
    deriver.ApplyTo(partTimer);
    deriver.ApplyTo(specialist);

    var modifier = new SituationalPerformanceModifier();
    double partTimerMult = modifier.GetBowlingMultiplier(partTimer, MatchPhase.DeathOvers, newBall: false);
    double specialistMult = modifier.GetBowlingMultiplier(specialist, MatchPhase.DeathOvers, newBall: false);

    TestRunner.IsTrue(specialistMult > partTimerMult,
        $"Death specialist ({specialistMult:F2}) should outperform a golden-arm part-timer ({partTimerMult:F2}) at the death");
});

TestRunner.Run("Contextual stats filter: combined Format+Opponent+Ground narrows correctly", () =>
{
    var queryService = new PlayerStatsQueryService();
    var playerId = Guid.NewGuid();
    var ausTeamId = Guid.NewGuid();
    var engTeamId = Guid.NewGuid();

    var records = new List<BattingInningsRecord>
    {
        new() { PlayerId = playerId, Runs = 120, BallsFaced = 100, Context = new MatchContext { OpponentTeamId = ausTeamId, OpponentName = "Australia", Ground = "Brisbane", Format = MatchFormat.T20, Season = 2026 } },
        new() { PlayerId = playerId, Runs = 40, BallsFaced = 35, Context = new MatchContext { OpponentTeamId = ausTeamId, OpponentName = "Australia", Ground = "Melbourne", Format = MatchFormat.T20, Season = 2026 } },
        new() { PlayerId = playerId, Runs = 15, BallsFaced = 20, Context = new MatchContext { OpponentTeamId = engTeamId, OpponentName = "England", Ground = "Brisbane", Format = MatchFormat.T20, Season = 2026 } },
        new() { PlayerId = playerId, Runs = 60, BallsFaced = 55, Context = new MatchContext { OpponentTeamId = ausTeamId, OpponentName = "Australia", Ground = "Brisbane", Format = MatchFormat.ODI, Season = 2026 } },
    };

    var filtered = queryService.QueryBatting(records, playerId, new StatsFilter(OpponentName: "Australia", Ground: "Brisbane", Format: MatchFormat.T20));

    TestRunner.AreEqual(1, filtered.Innings, "Only one record matches Australia+Brisbane+T20");
    TestRunner.AreEqual(120, filtered.Runs);
});

