TestRunner.Run("Matchup confidence rises after repeated good performances against the same opponent", () =>
{
    var service = new MatchupConfidenceService();
    var player = new Player { FirstName = "Test", LastName = "Player" };
    var key = MatchupKey.ForOpponent(Guid.NewGuid());

    for (int i = 0; i < 5; i++) service.RecordOutcome(player, key, 70);

    double multiplier = service.GetMatchupMultiplier(player, key);
    TestRunner.IsTrue(multiplier > 1.0, $"Multiplier should exceed 1.0 after repeated good performances, got {multiplier:F3}");
});

TestRunner.Run("Matchup confidence falls after repeated poor performances against the same bowler", () =>
{
    var service = new MatchupConfidenceService();
    var player = new Player { FirstName = "Test", LastName = "Player" };
    var key = MatchupKey.ForBowler(Guid.NewGuid());

    for (int i = 0; i < 5; i++) service.RecordOutcome(player, key, -65);

    double multiplier = service.GetMatchupMultiplier(player, key);
    TestRunner.IsTrue(multiplier < 1.0, $"Multiplier should drop below 1.0 after repeated poor performances, got {multiplier:F3}");
});

TestRunner.Run("Unrecorded matchup stays neutral (1.0) - no free advantage from zero data", () =>
{
    var service = new MatchupConfidenceService();
    var player = new Player { FirstName = "Fresh", LastName = "Player" };
    double multiplier = service.GetMatchupMultiplier(player, MatchupKey.ForGroundName("Lahore"));
    TestRunner.AreEqual(1.0, multiplier);
});

TestRunner.Run("Matchup confidence decays toward neutral over time - not permanent", () =>
{
    var service = new MatchupConfidenceService();
    var player = new Player { FirstName = "Test", LastName = "Player" };
    var key = MatchupKey.ForGroundName("Karachi");
    for (int i = 0; i < 6; i++) service.RecordOutcome(player, key, 80);

    double before = service.GetMatchupMultiplier(player, key);
    for (int season = 0; season < 8; season++) service.DecayAll(player, amount: 10);
    double after = service.GetMatchupMultiplier(player, key);

    TestRunner.IsTrue(after < before, $"Confidence should fade without reinforcement: before={before:F3}, after={after:F3}");
    TestRunner.IsTrue(after <= 1.02, "After enough decay cycles, matchup edge should return close to neutral");
});

TestRunner.Run("Matchup confidence can flip direction if recent outcomes reverse (not locked to first impression)", () =>
{
    var service = new MatchupConfidenceService();
    var player = new Player { FirstName = "Test", LastName = "Player" };
    var key = MatchupKey.ForOpponent(Guid.NewGuid());

    for (int i = 0; i < 4; i++) service.RecordOutcome(player, key, 75); // starts strong
    double earlyMultiplier = service.GetMatchupMultiplier(player, key);

    for (int i = 0; i < 8; i++) service.RecordOutcome(player, key, -75); // then struggles repeatedly
    double laterMultiplier = service.GetMatchupMultiplier(player, key);

    TestRunner.IsTrue(laterMultiplier < earlyMultiplier, $"Sustained poor recent form vs this matchup should pull the multiplier down: early={earlyMultiplier:F3}, later={laterMultiplier:F3}");
});

TestRunner.Run("Probabilistic outcome: Power Hitter trait bonus in death overs does NOT guarantee success every time", () =>
{
    var simulator = new PerformanceOutcomeSimulator(new Random(2026));
    // Even a strong favorable trait/situation fit for a good player - still probabilistic.
    var samples = simulator.SampleMany(baseRating: 40, combinedMultiplier: 1.25, count: 300);

    int failures = samples.Count(s => s < 0); // "failure" = below-neutral outcome despite the trait advantage
    TestRunner.IsTrue(failures > 0, "Even with a favorable trait multiplier, some individual outcomes should still fail");
    TestRunner.IsTrue(failures < samples.Count, "But it shouldn't fail every time either");
});

TestRunner.Run("Probabilistic outcome: favorable multiplier shifts the AVERAGE up without fixing every instance", () =>
{
    var simulator = new PerformanceOutcomeSimulator(new Random(99));
    var favorable = simulator.SampleMany(baseRating: 30, combinedMultiplier: 1.2, count: 500);
    var unfavorable = simulator.SampleMany(baseRating: 30, combinedMultiplier: 0.8, count: 500);

    double avgFavorable = favorable.Average();
    double avgUnfavorable = unfavorable.Average();

    TestRunner.IsTrue(avgFavorable > avgUnfavorable, $"Favorable avg ({avgFavorable:F1}) should exceed unfavorable avg ({avgUnfavorable:F1}) over many samples");
    TestRunner.IsTrue(favorable.Min() < avgFavorable - 20, "Even the favorable distribution should include clearly below-average individual outcomes");
});

TestRunner.Run("Same inputs to the simulator do not always produce the same output (genuine randomness)", () =>
{
    var simulator = new PerformanceOutcomeSimulator(new Random(1));
    var results = simulator.SampleMany(baseRating: 50, combinedMultiplier: 1.0, count: 20);
    TestRunner.IsTrue(results.Distinct().Count() > 1, "Repeated calls with identical inputs should still vary");
});

await TestRunner.RunAsync("Player with matchup history persists and reloads correctly", async () =>
{
    var tempDir = Path.Combine(Path.GetTempPath(), "cricketmanager_test_" + Guid.NewGuid());
    try
    {
        var matchupService = new MatchupConfidenceService();
        var player = new Player { FirstName = "Save", LastName = "Test" };
        var key = MatchupKey.ForOpponent(Guid.NewGuid());
        matchupService.RecordOutcome(player, key, 60);
        matchupService.RecordOutcome(player, key, 70);

        var ctx1 = new GameDataContext(tempDir);
        await ctx1.Players.AddAsync(player);
        await ctx1.SaveAllAsync();

        var ctx2 = new GameDataContext(tempDir);
        var reloaded = await ctx2.Players.GetByIdAsync(player.Id);

        TestRunner.IsTrue(reloaded!.Matchups.ContainsKey(key), "Matchup record should survive reload");
        TestRunner.IsTrue(reloaded.Matchups[key].Confidence > 0, $"Reloaded confidence should retain its positive value, got {reloaded.Matchups[key].Confidence}");
        TestRunner.AreEqual(2, reloaded.Matchups[key].SampleCount);

        // Also confirms the FormState/Reputation JSON private-setter fix holds end to end.
        player.Form.RecordPerformance(55);
        await ctx1.Players.UpdateAsync(player);
        await ctx1.SaveAllAsync();
        var reloadedAgain = await ctx2.Players.GetByIdAsync(player.Id);
        TestRunner.IsTrue(reloadedAgain is not null, "reload should succeed");
    }
    finally
    {
        if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true);
    }
});

