TestRunner.Run("Undapted player (traits never derived) gets no spurious format-suitability penalty", () =>
{
    // Regression test for the trait-nudge default-zero bug: a manually-built player
    // (BattingTraits left at their zero defaults, RoleTraitDeriver never run) must score
    // format suitability purely from attributes - not be penalized just for lacking trait data.
    var withoutTraits = new Player
    {
        FirstName = "No",
        LastName = "Traits",
        Batting = new BattingAttributes { Technique = 15, DefensiveAbility = 15, PowerHitting = 8 },
        Mental = new MentalAttributes { Concentration = 15 }
    };
    withoutTraits.RecalculateFormatSuitability();

    var deriver = new RoleTraitDeriver();
    var withTraits = new Player
    {
        FirstName = "Has",
        LastName = "Traits",
        Batting = new BattingAttributes { Technique = 15, DefensiveAbility = 15, PowerHitting = 8 },
        Mental = new MentalAttributes { Concentration = 15 }
    };
    deriver.ApplyTo(withTraits); // derives traits AND recalculates internally via ApplyTo -> but call again explicitly for suitability
    withTraits.RecalculateFormatSuitability();

    // Both players have identical attributes. The undapted one should score close to (not
    // arbitrarily far below) the trait-derived one on Test suitability, since this is a
    // classical-technique profile that SHOULD score well on Test with or without derived traits.
    TestRunner.IsTrue(withoutTraits.FormatSuitability.TestSuitability > 40,
        $"Undapted player with strong technique/defense should still score decently on Test suitability, got {withoutTraits.FormatSuitability.TestSuitability:F1}");
});

