TestRunner.Run("CompetitionProgressionService ranks standings by points then net run rate", () =>
{
    var progression = new CompetitionProgressionService();
    var season = new CompetitionSeason();
    var teamA = Guid.NewGuid(); var teamB = Guid.NewGuid(); var teamC = Guid.NewGuid();

    var standingA = season.GetOrCreateStanding(teamA);
    standingA.RecordResult(MatchOutcome.Win);
    standingA.RecordResult(MatchOutcome.Win);
    standingA.SetNetRunRate(0.5);

    var standingB = season.GetOrCreateStanding(teamB);
    standingB.RecordResult(MatchOutcome.Win);
    standingB.RecordResult(MatchOutcome.Win);
    standingB.SetNetRunRate(1.2); // same points as A, better NRR

    var standingC = season.GetOrCreateStanding(teamC);
    standingC.RecordResult(MatchOutcome.Loss);

    var topper = progression.GetTableTopper(season);
    TestRunner.AreEqual(teamB, topper, "Team B should top the table on NRR tiebreak despite equal points with Team A");
});

TestRunner.Run("CompetitionProgressionService selects correct number of playoff qualifiers in ranked order", () =>
{
    var progression = new CompetitionProgressionService();
    var season = new CompetitionSeason();
    var teams = Enumerable.Range(0, 5).Select(_ => Guid.NewGuid()).ToList();

    for (int i = 0; i < teams.Count; i++)
    {
        var s = season.GetOrCreateStanding(teams[i]);
        for (int w = 0; w < (teams.Count - i); w++) s.RecordResult(MatchOutcome.Win); // team[0] wins most
    }

    var qualifiers = progression.GetPlayoffQualifiers(season, numberOfQualifiers: 4);
    TestRunner.AreEqual(4, qualifiers.Count);
    TestRunner.AreEqual(teams[0], qualifiers[0], "Best record should qualify first");
    TestRunner.IsTrue(!qualifiers.Contains(teams[4]), "Worst-record team should not qualify for a top-4 playoff");
    TestRunner.AreEqual(4, season.PlayoffQualifiedTeamIds.Count, "Qualifiers should also be recorded onto the season itself");
});

