    var history = new CompetitionHistoryService();
    var competitionId = Guid.NewGuid();
    var teamX = Guid.NewGuid(); var teamY = Guid.NewGuid();

    var seasons = new List<CompetitionSeason>();
    for (int year = 2021; year <= 2026; year++)
    {
        var season = new CompetitionSeason { CompetitionId = competitionId, Year = year };
        season.ParticipatingTeamIds.Add(teamX);
        season.ParticipatingTeamIds.Add(teamY);
        if (year % 2 == 0) season.Complete(teamX); // X wins even years
        if (year >= 2024) season.PlayoffQualifiedTeamIds.Add(teamX);
        seasons.Add(season);
    }

    var recent3 = history.GetRecentSeasons(seasons, competitionId, 3);
    TestRunner.AreEqual(3, recent3.Count);
    TestRunner.AreEqual(2026, recent3[0].Year, "Most recent season should come first");

    TestRunner.AreEqual(3, history.CountTitles(seasons, teamX), "Team X should have titles in 2022, 2024, 2026");
    TestRunner.AreEqual(0, history.CountTitles(seasons, teamY), "Team Y never won");
    TestRunner.AreEqual(3, history.CountPlayoffAppearances(seasons, teamX), "Team X qualified 2024-2026");
});

