TestRunner.Run("Ground and CompetitionStanding survive save/reload (private-setter fields included)", () =>
{
    var tempDir = Path.Combine(Path.GetTempPath(), "cricketmanager_test_" + Guid.NewGuid());
    try
    {
        var ground = new Ground { Name = "Reload Test Ground", City = "Lahore", Country = "Pakistan", Capacity = 27000, SquareBoundaryMetres = 71, DewTendency = 62 };
        var teamInnings = GroundTestData.TeamInnings(ground.Id, runs: 195, wickets: 8, inningsNumber: 1);

        var season = new CompetitionSeason { Year = 2026 };
        var standing = season.GetOrCreateStanding(Guid.NewGuid());
        standing.RecordResult(MatchOutcome.Win);
        standing.RecordResult(MatchOutcome.Loss);

        var ctx1 = new GameDataContext(tempDir);
        ctx1.Grounds.AddAsync(ground).Wait();
        ctx1.TeamInnings.AddAsync(teamInnings).Wait();
        ctx1.CompetitionSeasons.AddAsync(season).Wait();
        ctx1.SaveAllAsync().Wait();

        var ctx2 = new GameDataContext(tempDir);
        var reloadedGround = ctx2.Grounds.GetByIdAsync(ground.Id).Result;
        var reloadedSeason = ctx2.CompetitionSeasons.GetByIdAsync(season.Id).Result;

        var reloadedInnings = ctx2.TeamInnings.GetByIdAsync(teamInnings.Id).Result;
        TestRunner.AreEqual(71, reloadedGround!.SquareBoundaryMetres, "Ground physical characteristics must survive reload");
        TestRunner.InRange(reloadedGround.DewTendency, 61.9, 62.1);
        TestRunner.AreEqual(195, reloadedInnings!.Runs, "Team innings records must survive reload");
        TestRunner.IsTrue(reloadedInnings.MatchId == teamInnings.MatchId, "MatchId must round-trip - match-level records depend on it");
        TestRunner.AreEqual(2, reloadedSeason!.Standings[0].Played, "CompetitionStanding private-setter fields must survive reload");
        TestRunner.AreEqual(2, reloadedSeason.Standings[0].Points, "2 points for 1 win, 0 for 1 loss");
    }
    finally
    {
        if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true);
    }
});

TestRunner.Run("ScoutingAccuracyService: better scouting narrows estimation error toward the true potential", () =>
