    var poorScoutEstimates = Enumerable.Range(0, 200).Select(_ => scouting.EstimatePotentialAbility(truePotential, scoutingQuality: 10)).ToList();
    var eliteScoutEstimates = Enumerable.Range(0, 200).Select(_ => scouting.EstimatePotentialAbility(truePotential, scoutingQuality: 95)).ToList();

    double poorAvgError = poorScoutEstimates.Average(e => Math.Abs(e - truePotential));
