TestRunner.Run("Sponsorship treats 'no matches played yet' as neutral, not as bad form", () =>
{
    var sponsorship = new SponsorshipValuationService();

    double noDataYet = sponsorship.CalculateSponsorshipValue(teamReputation: 60, competitionPrestige: 60, recentWinRate: null);
    double genuinelyTerribleForm = sponsorship.CalculateSponsorshipValue(teamReputation: 60, competitionPrestige: 60, recentWinRate: 0.0);
    double averageForm = sponsorship.CalculateSponsorshipValue(teamReputation: 60, competitionPrestige: 60, recentWinRate: 0.5);

    TestRunner.IsTrue(noDataYet > genuinelyTerribleForm,
        "An unplayed season must not be valued the same as a winless one - unpopulated default read as a real negative signal is the bug this fixes");
    TestRunner.InRange(noDataYet / averageForm, 0.99, 1.01,
        "No-data should sit at the neutral (1.0x) form factor, i.e. equal to a 50% win rate");
});

TestRunner.Run("Competition reputation and home-ground commercial facilities both move sponsorship value", () =>
{
    var sponsorship = new SponsorshipValuationService();
    double baseline = sponsorship.CalculateSponsorshipValue(70, competitionPrestige: 60, recentWinRate: 0.5);

    double risingLeague = sponsorship.CalculateSponsorshipValue(70, competitionPrestige: 60, recentWinRate: 0.5, competitionReputation: 95);
    double decliningLeague = sponsorship.CalculateSponsorshipValue(70, competitionPrestige: 60, recentWinRate: 0.5, competitionReputation: 15);
    TestRunner.IsTrue(risingLeague > baseline && baseline > decliningLeague,
        "A league whose earned reputation outstrips its structural prestige should sell better, and vice versa");

    double greatVenue = sponsorship.CalculateSponsorshipValue(70, 60, 0.5,
        homeGroundFacilities: new GroundFacilities { CorporateHospitality = 95, MediaFacilities = 90 });
    double poorVenue = sponsorship.CalculateSponsorshipValue(70, 60, 0.5,
        homeGroundFacilities: new GroundFacilities { CorporateHospitality = 10, MediaFacilities = 10 });
    TestRunner.IsTrue(greatVenue > poorVenue, "Commercial infrastructure at the home ground is worth real sponsorship money");
    TestRunner.InRange(baseline / sponsorship.CalculateSponsorshipValue(70, 60, 0.5,
        homeGroundFacilities: new GroundFacilities { CorporateHospitality = 50, MediaFacilities = 50 }), 0.99, 1.01,
        "Facilities at the neutral 50 baseline should leave the value unchanged");
});

