TestRunner.Run("Honour board lists EVERY century and five-for, not just the current record holder", () =>
{
    var records = new GroundRecordsService();
    var groundId = Guid.NewGuid();
    var babar = Guid.NewGuid(); var root = Guid.NewGuid(); var shaheen = Guid.NewGuid();
    var names = new Dictionary<Guid, string> { [babar] = "Babar Azam", [root] = "Joe Root", [shaheen] = "Shaheen Afridi" };

    var batting = new List<BattingInningsRecord>
    {
        GroundTestData.Innings(babar, groundId, runs: 122, balls: 210, season: 2024),
        GroundTestData.Innings(root, groundId, runs: 254, balls: 320, season: 2025),   // bigger score, later
        GroundTestData.Innings(babar, groundId, runs: 88, balls: 140, season: 2026),   // not a century
        GroundTestData.Innings(babar, groundId, runs: 101, notOut: true, season: 2026)
    };
    var bowling = new List<BowlingSpellRecord>
    {
        GroundTestData.Spell(shaheen, groundId, wickets: 6, runsConceded: 51, season: 2025),
        GroundTestData.Spell(shaheen, groundId, wickets: 3, runsConceded: 40, season: 2026) // not a five-for
    };

    var board = records.GetHonourBoard(batting, bowling, groundId, MatchFormat.Test, names);

    TestRunner.AreEqual(4, board.Count, "3 centuries + 1 five-for; the 88 and the 3-for don't qualify");
    TestRunner.IsTrue(board.Count(e => e.PlayerId == babar) == 2,
        "Babar's earlier century must stay on the board after Root scores more - an honour board is not a leaderboard");
    TestRunner.IsTrue(board[0].Date <= board[^1].Date, "Honour boards read chronologically");
    TestRunner.IsTrue(board.Any(e => e.Description.Contains("Double century")), "254 should be described as a double century");
    TestRunner.IsTrue(board.Any(e => e.Description.Contains("101*")), "Not-out centuries carry the asterisk");
    TestRunner.IsTrue(board.Any(e => e.Description.Contains("Five-wicket haul 6/51")), "Five-fors belong on the same board as the centuries");

    TestRunner.IsTrue(records.IsOnHonourBoard(batting, bowling, babar, groundId, MatchFormat.Test), "Babar has a century here");
    TestRunner.IsTrue(!records.IsOnHonourBoard(batting, bowling, Guid.NewGuid(), groundId, MatchFormat.Test), "A player with nothing here is not on the board");
});

TestRunner.Run("Ground batting/bowling records use real cricket ordering, including match figures", () =>
{
    var records = new GroundRecordsService();
    var groundId = Guid.NewGuid();
    var bowlerA = Guid.NewGuid(); var bowlerB = Guid.NewGuid();
    var sameMatch = Guid.NewGuid();
    var names = new Dictionary<Guid, string> { [bowlerA] = "Bowler A", [bowlerB] = "Bowler B" };

    var bowling = new List<BowlingSpellRecord>
    {
        GroundTestData.Spell(bowlerA, groundId, wickets: 6, runsConceded: 40, matchId: sameMatch),
        GroundTestData.Spell(bowlerA, groundId, wickets: 5, runsConceded: 55, matchId: sameMatch), // 11/95 in the match
        GroundTestData.Spell(bowlerB, groundId, wickets: 7, runsConceded: 90)                      // better innings figures
    };

    TestRunner.AreEqual(7, records.GetBestBowlingInInnings(bowling, groundId, null, names)!.PrimaryValue,
        "Best innings figures is the single best spell");
    var bestMatch = records.GetBestBowlingInMatch(bowling, groundId, null, names)!;
    TestRunner.AreEqual(11, bestMatch.PrimaryValue, "Best match figures combines both spells in the same match");
    TestRunner.AreEqual("Bowler A", bestMatch.PlayerName);

    var tenFors = records.GetTenWicketMatchHauls(bowling, groundId, null, names);
    TestRunner.AreEqual(1, tenFors.Count, "Only Bowler A took ten in the match");

    var equalWickets = new List<BowlingSpellRecord>
    {
        GroundTestData.Spell(bowlerA, groundId, wickets: 5, runsConceded: 60),
        GroundTestData.Spell(bowlerB, groundId, wickets: 5, runsConceded: 22)
    };
    TestRunner.AreEqual("Bowler B", records.GetBestBowlingInInnings(equalWickets, groundId, null, names)!.PlayerName,
        "Equal wickets must tiebreak on fewer runs, as real bowling figures do");
});

