    var thinHistory = Enumerable.Range(0, 3).Select(_ => GroundTestData.TeamInnings(ground.Id, runs: 95)).ToList();
    TestRunner.IsTrue(!conditions.EstimateParScore(ground, MatchFormat.T20, thinHistory).FromHistoricalData,
        "Three innings is too thin - one 95 all out must not redefine the ground as a 95-run venue");

    var realHistory = Enumerable.Range(0, 8).Select(i => GroundTestData.TeamInnings(ground.Id, runs: 200 + i)).ToList();
    var fromHistory = conditions.EstimateParScore(ground, MatchFormat.T20, realHistory);
    TestRunner.IsTrue(fromHistory.FromHistoricalData, "Eight innings is enough to trust the ground's own record");
    TestRunner.InRange(fromHistory.ParScore, 202, 205);
