    TestRunner.IsTrue(nightGame < dayGame, "Heavy dew under lights should cost the spinners grip - why chasing is easier at dewy venues");
    TestRunner.InRange(conditions.EstimateSpinAssistance(rankTurner, MatchFormat.T20, dayOfMatch: 4), 59.9, 60.1,
        "Day number is meaningless in a one-day format and must be ignored");
});

