TestRunner.Run("Matchday attendance is driven by competition standing, venue draw and contest quality", () =>
{
    var revenue = new MatchdayRevenueService();
    var ground = new Ground { Name = "Gaddafi Stadium", City = "Lahore", Capacity = 27000, Reputation = 70 };
    var worldCup = new Competition { Name = "World Cup", Prestige = 95, Reputation = 95 };
    var minorCup = new Competition { Name = "Second XI Trophy", Prestige = 15, Reputation = 15 };

    var big = revenue.CalculateMatchday(ground, worldCup, homeTeamStrength: 80, awayTeamStrength: 80, matchdayIncomeBaseline: 5000);
    var small = revenue.CalculateMatchday(ground, minorCup, homeTeamStrength: 35, awayTeamStrength: 30, matchdayIncomeBaseline: 5000);

    TestRunner.IsTrue(big.Attendance > small.Attendance * 2, "A World Cup tie at a good venue should massively outdraw a minor domestic fixture");
    TestRunner.IsTrue(big.Attendance <= ground.Capacity, "Attendance can never exceed capacity");
    TestRunner.IsTrue(small.Attendance > 0, "Even a low-appeal fixture draws a core support - not zero");
    TestRunner.IsTrue(big.Revenue > small.Revenue, "Bigger crowd, bigger gate");

    var hospitalityGround = new Ground { Name = "Corporate Arena", Capacity = 27000, Reputation = 70 };
    hospitalityGround.Facilities.CorporateHospitality = 95;
    ground.Facilities.CorporateHospitality = 10;
    var richGate = revenue.CalculateMatchday(hospitalityGround, worldCup, 80, 80, 5000);
    var poorGate = revenue.CalculateMatchday(ground, worldCup, 80, 80, 5000);
    TestRunner.IsTrue(richGate.Revenue > poorGate.Revenue, "Same crowd is worth more where it can actually be sold hospitality");

    var noCapacity = revenue.CalculateMatchday(new Ground { Name = "Unbuilt" }, worldCup, 80, 80, 5000);
    TestRunner.AreEqual(0, noCapacity.Attendance, "A ground with no capacity set must not invent a crowd");
});

TestRunner.Run("Facility upkeep scales with what a team actually owns, and a season can lose money", () =>
{
    var finance = new TeamFinanceService();

    double eliteUpkeep = finance.CalculateAnnualUpkeep(
        new TeamFacilities { TrainingQuality = 90, YouthDevelopmentQuality = 90, ScoutingQuality = 90, MedicalQuality = 90, CorporateCommercialQuality = 90 },
        new GroundFacilities { TrainingFacilities = 90, MediaFacilities = 90, CorporateHospitality = 90, MedicalFacilities = 90, YouthFacilities = 90, PitchInfrastructure = 90 },
        groundCapacity: 60000);
    double modestUpkeep = finance.CalculateAnnualUpkeep(
        new TeamFacilities { TrainingQuality = 20, YouthDevelopmentQuality = 20, ScoutingQuality = 20, MedicalQuality = 20, CorporateCommercialQuality = 20 },
        new GroundFacilities { TrainingFacilities = 20, MediaFacilities = 20, CorporateHospitality = 20, MedicalFacilities = 20, YouthFacilities = 20, PitchInfrastructure = 20 },
        groundCapacity: 12000);

    TestRunner.IsTrue(eliteUpkeep > modestUpkeep * 3, "Elite infrastructure must be genuinely expensive to run, or upgrades are free");

    var finances = new TeamFinances { Budget = 500_000 };
    var result = finance.ApplySeasonFinances(finances, sponsorshipIncome: 200_000, matchdayIncome: 150_000, upkeepCost: eliteUpkeep, wageCost: 400_000);

    TestRunner.IsTrue(result.NetResult < 0, "Elite facilities plus a big wage bill on modest income should run a loss");
    TestRunner.AreEqual(finances.Budget, result.ClosingBudget);
    TestRunner.AreEqual(eliteUpkeep, finances.FacilityUpkeepCost, "Stored upkeep must be the freshly calculated figure, not a stale static one");
    TestRunner.IsTrue(finances.Budget < 500_000, "Budget is allowed to fall - and to go negative - rather than being clamped");
});

TestRunner.Run("Venue medical facilities layer on top of team medical quality without replacing it", () =>
{
    var medical = new MedicalEffectivenessService();

    double teamOnly = medical.GetEffectiveInjuryRisk(playerInjuryProneness: 16, teamMedicalQuality: 50);
    double atGreatVenue = medical.GetEffectiveInjuryRisk(16, 50, new GroundFacilities { MedicalFacilities = 100 });
    double atPoorVenue = medical.GetEffectiveInjuryRisk(16, 50, new GroundFacilities { MedicalFacilities = 0 });

    TestRunner.IsTrue(atGreatVenue < teamOnly && teamOnly < atPoorVenue, "Venue quality moves risk in both directions around the team-only baseline");

    double eliteTeamPoorVenue = medical.GetCombinedMedicalQuality(95, new GroundFacilities { MedicalFacilities = 0 });
    double poorTeamEliteVenue = medical.GetCombinedMedicalQuality(20, new GroundFacilities { MedicalFacilities = 100 });
    TestRunner.IsTrue(eliteTeamPoorVenue > poorTeamEliteVenue, "The team's own medical staff travel with the squad and must outweigh the venue");

    TestRunner.IsTrue(medical.GetEffectiveInjuryRisk(16, 100, new GroundFacilities { MedicalFacilities = 100 }) > 0,
        "Even perfect medical support only mitigates risk - it never removes it");
});

TestRunner.Run("Player profile shows the grounds they're on the honour board at, agreeing with the ground's own board", () =>
