TestRunner.Run("Injury layoff responds to the player's recovery attribute and the medical setup around him", () =>
{
    var availability = new PlayerAvailabilityService();
    var today = new DateOnly(2026, 4, 1);

    var fragile = new Player { FirstName = "Fragile", LastName = "Fast", Physical = new PhysicalAttributes { Recovery = 4, InjuryProneness = 17 } };
    var durable = new Player { FirstName = "Durable", LastName = "Dan", Physical = new PhysicalAttributes { Recovery = 18, InjuryProneness = 5 } };

    var slowInjury = availability.ApplyInjury(fragile, InjuryType.Hamstring, InjurySeverity.Moderate, today, teamMedicalQuality: 15, random: new Random(3));
    var fastInjury = availability.ApplyInjury(durable, InjuryType.Hamstring, InjurySeverity.Moderate, today, teamMedicalQuality: 95, random: new Random(3));

    TestRunner.IsTrue(slowInjury.ExpectedReturnDate > fastInjury.ExpectedReturnDate,
        "Same injury, same roll - poor recovery and poor medical support must mean a longer layoff");
    TestRunner.IsTrue(slowInjury.RecurrenceRisk > fastInjury.RecurrenceRisk,
        "An injury-prone player carries more risk of the same problem returning");
    TestRunner.IsTrue(!availability.GetAvailability(fragile, today).IsAvailable, "A moderate injury blocks selection");
    TestRunner.IsTrue(availability.GetAvailability(fragile, slowInjury.ExpectedReturnDate).IsAvailable, "Available again once the layoff ends");
});

TestRunner.Run("A niggle is a coaching decision, not an automatic block", () =>
{
    var availability = new PlayerAvailabilityService();
    var today = new DateOnly(2026, 4, 1);
    var star = new Player { FirstName = "Key", LastName = "Player", Physical = new PhysicalAttributes { Recovery = 12 } };

    availability.ApplyInjury(star, InjuryType.MuscleStrain, InjurySeverity.Niggle, today, random: new Random(1));
    var result = availability.GetAvailability(star, today);

    TestRunner.IsTrue(result.IsAvailable, "A niggle must stay pickable - playing a slightly sore star in a final is a real decision");
    TestRunner.IsTrue(result.EffectivenessIfPlayed < 1.0 && result.EffectivenessIfPlayed > 0.5,
        "...but at a real cost, not for free");
});

TestRunner.Run("Non-injury unavailability is tracked separately from injury", () =>
{
    var availability = new PlayerAvailabilityService();
    var today = new DateOnly(2026, 4, 1);
    var player = new Player { FirstName = "On", LastName = "Duty", NonInjuryUnavailability = UnavailabilityReason.InternationalDuty };

    var result = availability.GetAvailability(player, today);
    TestRunner.IsTrue(!result.IsAvailable, "On duty means not selectable here");
    TestRunner.AreEqual(UnavailabilityReason.InternationalDuty, result.Reason,
        "'On national duty' must not be collapsed into 'injured' - NOC logic depends on the distinction");
});

TestRunner.Run("Selection ranking excludes unavailable players and discounts the walking wounded", () =>
{
    var evaluator = new PlayerSelectionEvaluator();
    var availability = new PlayerAvailabilityService();
    var matchDay = new DateOnly(2026, 5, 10);

    var fit = new Player { FirstName = "Fit", LastName = "Star", CurrentAbility = 150, PotentialAbility = 160 };
    var injured = new Player { FirstName = "Injured", LastName = "Star", CurrentAbility = 175, PotentialAbility = 180 };
    var niggled = new Player { FirstName = "Niggled", LastName = "Star", CurrentAbility = 152, PotentialAbility = 160 };
    foreach (var p in new[] { fit, injured, niggled }) p.RecalculateFormatSuitability();

    availability.ApplyInjury(injured, InjuryType.KneeInjury, InjurySeverity.Serious, matchDay.AddDays(-10), random: new Random(2));
    availability.ApplyInjury(niggled, InjuryType.MuscleStrain, InjurySeverity.Niggle, matchDay, random: new Random(2));

    var ranked = evaluator.RankAvailable(new[] { fit, injured, niggled }, MatchFormat.T20, matchDay);

    TestRunner.AreEqual(2, ranked.Count, "The seriously injured player - the best of the three on paper - must not be ranked at all");
    TestRunner.IsTrue(ranked.All(r => r.PlayerId != injured.Id), "Seriously injured player is absent from the ranking");
    TestRunner.AreEqual(fit.Id, ranked[0].PlayerId, "The fit player edges the slightly better but niggled one");
});

TestRunner.Run("Coaching philosophy genuinely changes who a coach picks", () =>
{
    var evaluator = new PlayerSelectionEvaluator();

    var provenVeteran = new Player { FirstName = "Proven", LastName = "Veteran", CurrentAbility = 165, PotentialAbility = 165 };
    provenVeteran.Form.RecordPerformance(-45); // out of form
    var inFormJourneyman = new Player { FirstName = "InForm", LastName = "Journeyman", CurrentAbility = 120, PotentialAbility = 125 };
    inFormJourneyman.Form.RecordPerformance(80);
    var rawProspect = new Player { FirstName = "Raw", LastName = "Prospect", CurrentAbility = 105, PotentialAbility = 185 };
    foreach (var p in new[] { provenVeteran, inFormJourneyman, rawProspect }) p.RecalculateFormatSuitability();

    var pool = new[] { provenVeteran, inFormJourneyman, rawProspect };

    var traditionalist = evaluator.Rank(pool, MatchFormat.ODI, SelectionWeighting.ForPhilosophy(CoachingPhilosophy.ExperienceFocused));
    var resultsCoach = evaluator.Rank(pool, MatchFormat.ODI, SelectionWeighting.ForPhilosophy(CoachingPhilosophy.PerformanceFocused));
    var youthCoach = evaluator.Rank(pool, MatchFormat.ODI, SelectionWeighting.ForPhilosophy(CoachingPhilosophy.YouthDevelopment));

    TestRunner.AreEqual(provenVeteran.Id, traditionalist[0].PlayerId, "An experience-focused coach backs proven ability through a lean spell");
    TestRunner.AreEqual(inFormJourneyman.Id, resultsCoach[0].PlayerId, "A performance-focused coach picks the man in form");
    TestRunner.IsTrue(youthCoach.First(s => s.PlayerId == rawProspect.Id).TotalScore
                    > resultsCoach.First(s => s.PlayerId == rawProspect.Id).TotalScore,
        "A youth-focused coach values the prospect's ceiling more highly than a results coach does");
});

TestRunner.Run("Recording a performance moves form, career stats, matchups and reputation in one pass", () =>
{
    var recorder = new PerformanceRecordingService();
    var player = new Player { FirstName = "Emerging", LastName = "Batter", CurrentAbility = 120, PotentialAbility = 150 };
    var stats = new PlayerCareerStats { PlayerId = player.Id, Format = MatchFormat.ODI };
    var groundId = Guid.NewGuid();
    var opponentId = Guid.NewGuid();

    double repBefore = player.Reputation.Domestic;

    var innings = new BattingInningsRecord
    {
        PlayerId = player.Id,
        Runs = 128,
        BallsFaced = 110,
        Fours = 12,
        Sixes = 4,
        Context = new MatchContext
        {
            MatchId = Guid.NewGuid(),
            GroundId = groundId,
            OpponentTeamId = opponentId,
            OpponentName = "Australia",
            Format = MatchFormat.ODI,
            OppositionStrength = 88,
            Scope = CompetitionScope.International,
            Season = 2026
        }
    };

    var result = recorder.RecordBattingPerformance(player, innings, stats, competitionPrestige: 90);

    // Same innings, weak attack, minor competition - the valuation must separate the two.
    var control = new Player { FirstName = "Control", LastName = "Batter", CurrentAbility = 120, PotentialAbility = 150 };
    var lowContext = recorder.RecordBattingPerformance(control, new BattingInningsRecord
    {
        PlayerId = control.Id,
        Runs = 128,
        BallsFaced = 110,
        Fours = 12,
        Sixes = 4,
        Context = new MatchContext { MatchId = Guid.NewGuid(), Format = MatchFormat.ODI, OppositionStrength = 25, Scope = CompetitionScope.DomesticListA, Season = 2026 }
    }, null, competitionPrestige: 25);

    TestRunner.InRange(result.RawRating - lowContext.RawRating, -0.01, 0.01, "Identical innings must rate identically before context is applied");
    TestRunner.IsTrue(result.ValuedRating > lowContext.ValuedRating * 1.5,
        "Elite opposition in a high-prestige competition must be worth substantially more than the same innings against a weak attack");
    TestRunner.IsTrue(result.FormAfter > result.FormBefore, "Form must rise after a big hundred");
    TestRunner.AreEqual(128, stats.Runs, "Career stats updated in the same pass");
    TestRunner.AreEqual(1, stats.Hundreds);
    TestRunner.IsTrue(player.Reputation.Domestic > repBefore, "Reputation must be earned by performance, and this earned some");
    TestRunner.IsTrue(player.Matchups.ContainsKey(MatchupKey.ForOpponent(opponentId)), "Matchup confidence vs this opponent recorded");
    TestRunner.IsTrue(player.Matchups.ContainsKey(MatchupKey.ForGround(groundId)), "And at this ground, keyed by id not name");
});

TestRunner.Run("Reputation is earned slowly, and international prestige is what builds a global name", () =>
{
    var recorder = new PerformanceRecordingService();

    Player MakePlayer() => new() { FirstName = "Test", LastName = "Player", CurrentAbility = 130, PotentialAbility = 150 };

    BattingInningsRecord Ton(CompetitionScope scope) => new()
    {
        Runs = 110,
        BallsFaced = 100,
        Context = new MatchContext { MatchId = Guid.NewGuid(), Format = MatchFormat.ODI, OppositionStrength = 75, Scope = scope, Season = 2026 }
    };

    var international = MakePlayer();
    var domestic = MakePlayer();
    recorder.RecordBattingPerformance(international, Ton(CompetitionScope.International), competitionPrestige: 95);
    recorder.RecordBattingPerformance(domestic, Ton(CompetitionScope.DomesticListA), competitionPrestige: 35);

    TestRunner.IsTrue(international.Reputation.Worldwide > domestic.Reputation.Worldwide,
        "The same hundred in a World Cup must build a global name faster than one in a minor domestic game");
    TestRunner.IsTrue(domestic.Reputation.Domestic > 5, "A domestic hundred still counts at home");
    TestRunner.IsTrue(international.Reputation.Domestic < 15,
        "One innings cannot make a player famous - reputation is a slow accumulation, not a per-match reward");

    var failure = MakePlayer();
    failure.Reputation.Adjust(30, 10, 5);
    // An established player: enough prior performances that sample-size damping no longer
    // shields him. A debutant's first duck deliberately barely registers.
    for (int i = 0; i < 6; i++) failure.Form.RecordPerformance(10);
    double before = failure.Reputation.Domestic;
    var duck = new BattingInningsRecord { Runs = 0, BallsFaced = 3, Context = new MatchContext { Format = MatchFormat.ODI, OppositionStrength = 50, Season = 2026 } };
    recorder.RecordBattingPerformance(failure, duck);
    TestRunner.IsTrue(failure.Reputation.Domestic < before, "A failure erodes standing");
    TestRunner.IsTrue(before - failure.Reputation.Domestic < 1.0, "...but reputations decay far more slowly than they are built");
});

TestRunner.Run("Fielding is finally recordable and queryable, including catch reliability", () =>
{
    var query = new PlayerStatsQueryService();
    var recorder = new PerformanceRecordingService();
    var groundId = Guid.NewGuid();
    var keeper = Guid.NewGuid();

    var records = new List<FieldingRecord>
    {
        new() { PlayerId = keeper, KeptWicket = true, Catches = 4, Stumpings = 1, DroppedCatches = 1,
                Context = new MatchContext { MatchId = Guid.NewGuid(), GroundId = groundId, Format = MatchFormat.Test, Season = 2026 } },
        new() { PlayerId = keeper, KeptWicket = true, Catches = 3, RunOuts = 1,
                Context = new MatchContext { MatchId = Guid.NewGuid(), GroundId = groundId, Format = MatchFormat.Test, Season = 2026 } }
    };

    var stats = query.QueryFielding(records, keeper, new StatsFilter(GroundId: groundId));
    TestRunner.AreEqual(7, stats.Catches);
    TestRunner.AreEqual(9, stats.Dismissals, "Catches + stumping + run-out");
    TestRunner.AreEqual(2, stats.MatchesAsKeeper);
    TestRunner.InRange(stats.CatchSuccessRate!.Value, 87.4, 87.6, "7 of 8 chances taken");

    var noChances = query.QueryFielding(new List<FieldingRecord>(), keeper, new StatsFilter());
    TestRunner.IsTrue(noChances.CatchSuccessRate is null,
        "No chances offered must read as null - not 0%, which would brand a fielder who never got one");

    var careerStats = new PlayerCareerStats { PlayerId = keeper, Format = MatchFormat.Test };
    recorder.RecordFieldingPerformance(records[0], careerStats);
    TestRunner.AreEqual(4, careerStats.Catches, "PlayerCareerStats fielding fields finally have something that populates them");

    var groundRecords = new GroundRecordsService();
    var best = groundRecords.GetBestFieldingPerformance(records, groundId);
    TestRunner.AreEqual(5, best!.PrimaryValue, "Best fielding match at this ground: 4 catches + 1 stumping");
});

TestRunner.Run("Team reputation is separate from team strength, and drives commercial value", () =>
{
    var sponsorship = new SponsorshipValuationService();

    var fallenGiant = new Team { Name = "Fallen Giant", Strength = 35, Reputation = new Reputation(domestic: 88) };
    var risingSide = new Team { Name = "Rising Side", Strength = 78, Reputation = new Reputation(domestic: 30) };

    double giantValue = sponsorship.CalculateSponsorshipValue(fallenGiant.Reputation.Domestic, competitionPrestige: 60, recentWinRate: 0.3);
    double risingValue = sponsorship.CalculateSponsorshipValue(risingSide.Reputation.Domestic, competitionPrestige: 60, recentWinRate: 0.7);

    TestRunner.IsTrue(giantValue > risingValue,
        "A famous club playing badly still out-earns a good unknown one commercially - impossible to express while Strength was the proxy");
    TestRunner.IsTrue(fallenGiant.Reputation.Continental < fallenGiant.Reputation.Domestic + 0.001,
        "Tiered reputation: domestic standing doesn't automatically mean continental recognition");
});

TestRunner.Run("Seeded teams get captains per format and reputation distinct from strength", () =>
