TestRunner.Run("Competition prize pools scale sharply with standing and scope", () =>
{
    var revenue = new CompetitionRevenueService();

    var worldCup = new Competition { Name = "World Cup", Prestige = 95, Reputation = 95, Scope = CompetitionScope.International };
