TestRunner.Run("Winning a competition is worth far more than finishing last, but last place still earns something", () =>
{
    var revenue = new CompetitionRevenueService();
    var progression = new CompetitionProgressionService();

    var competition = new Competition { Name = "Super League", Prestige = 75, Reputation = 70, Scope = CompetitionScope.DomesticT20 };
    var teams = Enumerable.Range(0, 6).Select(_ => Guid.NewGuid()).ToList();
    var season = new CompetitionSeason { CompetitionId = competition.Id, Year = 2026, ParticipatingTeamIds = teams.ToList() };

    // Team 0 wins most, team 5 wins none.
    for (int i = 0; i < teams.Count; i++)
    {
        var standing = season.GetOrCreateStanding(teams[i]);
        for (int w = 0; w < teams.Count - i - 1; w++) standing.RecordResult(MatchOutcome.Win);
        for (int l = 0; l < i; l++) standing.RecordResult(MatchOutcome.Loss);
    }
    season.PlayoffQualifiedTeamIds = new List<Guid> { teams[0], teams[1], teams[2], teams[3] };
    progression.CompleteSeason(season, teams[0], teams[1]);

    var earnings = revenue.DistributeSeasonRevenue(competition, season);

    TestRunner.AreEqual(6, earnings.Count, "Every participant gets an entry, including the team that finished last");

    var champion = earnings.First(e => e.TeamId == teams[0]);
    var runnerUp = earnings.First(e => e.TeamId == teams[1]);
    var wooden = earnings.First(e => e.TeamId == teams[5]);

    TestRunner.IsTrue(champion.Total > runnerUp.Total, "Winning must clearly beat losing the final");
    TestRunner.IsTrue(runnerUp.Total > wooden.Total, "Reaching the final beats finishing last");
    TestRunner.IsTrue(wooden.PrizeMoney == 0 && wooden.ParticipationFee > 0,
        "No prize money for last, but the participation fee is what keeps smaller sides solvent");
    TestRunner.IsTrue(wooden.MeritPayment > 0 && wooden.MeritPayment < champion.MeritPayment,
        "Merit money scales with table position - which is what makes a dead rubber still worth winning");
    TestRunner.IsTrue(champion.Description.Contains("champions"), "Earnings explain themselves");

    double distributed = earnings.Sum(e => e.Total);
    TestRunner.InRange(distributed, revenue.CalculatePrizePool(competition, 6) * 0.98, revenue.CalculatePrizePool(competition, 6) * 1.02,
        "The whole pool is distributed - no money invented or lost");
});

TestRunner.Run("Competition income completes the finance loop: a title season genuinely pays more", () =>
{
    var finance = new TeamFinanceService();
    var revenue = new CompetitionRevenueService();

    var competition = new Competition { Name = "Premier T20", Prestige = 80, Reputation = 80, Scope = CompetitionScope.FranchiseLeague };
    var winnerId = Guid.NewGuid(); var loserId = Guid.NewGuid();
    var season = new CompetitionSeason { CompetitionId = competition.Id, Year = 2026, ParticipatingTeamIds = new List<Guid> { winnerId, loserId } };
    season.GetOrCreateStanding(winnerId).RecordResult(MatchOutcome.Win);
    season.GetOrCreateStanding(loserId).RecordResult(MatchOutcome.Loss);
    season.Complete(winnerId, loserId);

    var winnerEarnings = revenue.GetTeamEarnings(competition, season, winnerId)!;
    var loserEarnings = revenue.GetTeamEarnings(competition, season, loserId)!;

    var winnerFinances = new TeamFinances { Budget = 1_000_000 };
    var loserFinances = new TeamFinances { Budget = 1_000_000 };

    var winnerResult = finance.ApplySeasonFinances(winnerFinances, 300_000, 200_000, 250_000, 400_000, winnerEarnings.Total);
    var loserResult = finance.ApplySeasonFinances(loserFinances, 300_000, 200_000, 250_000, 400_000, loserEarnings.Total);

    TestRunner.IsTrue(winnerResult.ClosingBudget > loserResult.ClosingBudget,
        "Identical clubs, identical costs - the only difference is how they did, and that must show up in the accounts");
    TestRunner.AreEqual(winnerEarnings.Total, winnerResult.CompetitionIncome, "Competition income is itemised, not folded into sponsorship");

    var noCompetition = finance.ApplySeasonFinances(new TeamFinances { Budget = 1_000_000 }, 300_000, 200_000, 250_000, 400_000);
    TestRunner.AreEqual(0.0, noCompetition.CompetitionIncome, "Default stays zero so existing callers are unaffected");
});

// ---------------------------------------------------------------------------
// Merged infrastructure system + the world clock everything now hangs off
