TestRunner.Run("Infrastructure quotes price steeply by level and schedule realistically by calendar", () =>
{
    var infra = new InfrastructureService();
    var team = new Team { Name = "Quoting XI", Country = "Pakistan" };
    team.Finances.Budget = 500_000_000;
    team.Facilities.MedicalQuality = 30;

    var cheap = infra.QuoteFacilityUpgrade(team, InfrastructureProjectType.Medical, 40);
    team.Facilities.MedicalQuality = 80;
    var dear = infra.QuoteFacilityUpgrade(team, InfrastructureProjectType.Medical, 90);

    TestRunner.IsTrue(dear.Cost > cheap.Cost * 1.5, "80->90 must be a capital project, not the price of 30->40");
    TestRunner.IsTrue(dear.DurationDays > cheap.DurationDays, "Elite work is slower as well as dearer - you're building to a standard");
    TestRunner.IsTrue(cheap.DurationDays >= 60, "Even modest work spans an off-season, not a fortnight");

    // Calendar realism - the durations a player will actually watch tick past on the clock.
    var expansion = infra.QuoteStadiumExpansion(team, new Ground { Name = "Club Ground", Capacity = 12_000 }, 18_000);
    TestRunner.IsTrue(expansion.DurationDays >= 730,
        $"An 18,000-seat expansion must take years, not months - got {expansion.DurationDays} days");

    var stadium = infra.QuoteNewStadium(team, 40_000);
    TestRunner.IsTrue(stadium.DurationDays is >= 900 and <= 1825,
        $"A 40,000-seat stadium should be a 3-5 year build - got {stadium.DurationDays} days");
