TestRunner.Run("The clock is the only thing that moves time, and it refuses to run backwards", () =>
{
    var calendar = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 100112);
    var clock = new WorldClockService();
    var world = EmptyWorld();

    clock.AdvanceDay(calendar, world);
    TestRunner.AreEqual(new DateOnly(2026, 1, 2), calendar.CurrentDate);

    clock.AdvanceWeeks(calendar, world, 2);
    TestRunner.AreEqual(new DateOnly(2026, 1, 16), calendar.CurrentDate);
    TestRunner.AreEqual(15, calendar.DaysElapsed);

    bool threw = false;
    try { clock.AdvanceTo(calendar, world, new DateOnly(2025, 12, 1)); } catch (InvalidOperationException) { threw = true; }
