TestRunner.Run("Advancing a year processes every day in between rather than jumping the gap", () =>
{
    var calendar = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 100258);
    var clock = new WorldClockService();
    var availability = new PlayerAvailabilityService();

    var player = new Player { FirstName = "Recovering", LastName = "Seamer", Physical = new PhysicalAttributes { Recovery = 12 } };
    var world = EmptyWorld();
    world.Players.Add(player);

    // An injury in March must resolve on its own as the clock passes it - not when someone
    // remembers to ask.
    clock.AdvanceTo(calendar, world, new DateOnly(2026, 3, 1));
    var injury = world.ApplyInjury(player, InjuryType.SideStrain, InjurySeverity.Moderate, calendar.CurrentDate, random: new Random(5));
    TestRunner.IsTrue(!availability.GetAvailability(player, calendar.CurrentDate).IsAvailable, "Injured on the day it happens");

    var events = clock.AdvanceTo(calendar, world, new DateOnly(2027, 1, 1));

    TestRunner.AreEqual(new DateOnly(2027, 1, 1), calendar.CurrentDate);
    TestRunner.IsTrue(player.CurrentInjury is null, "The clock must clear the injury as it passes the return date");
    TestRunner.AreEqual(1, player.InjuryHistory.Count, "...while keeping it in history - recruiters judge the record, not the attribute");
    TestRunner.IsTrue(player.InjuryHistory[0].IsResolved, "The historical entry is closed off with an actual return date");

    var recovery = events.FirstOrDefault(e => e.Type == GameEventType.PlayerRecovered);
    TestRunner.IsTrue(recovery is not null, "Recovery must surface as an event the inbox can report, not happen silently");
    TestRunner.IsTrue(recovery!.Date >= injury.ExpectedReturnDate, "Reported on or after the day he was due back");
    TestRunner.AreEqual(1, events.Count(e => e.Type == GameEventType.SeasonRollover), "Exactly one year turned over");
});

TestRunner.Run("Building work completes on its own date as the clock runs, opening a real ground", () =>
