TestRunner.Run("Calendar and infrastructure projects survive save/reload with state intact", () =>
{
    var dir = Path.Combine(Path.GetTempPath(), "cm_clock_" + Guid.NewGuid().ToString("N"));
    try
    {
        var infra = new InfrastructureService();
        var team = new Team { Name = "Persisted XI", Country = "Pakistan" };
        team.Finances.Budget = 50_000_000;
        var project = infra.StartFacilityUpgrade(team, InfrastructureProjectType.TrainingFacilities, 60, new DateOnly(2026, 2, 1))!;
        project.Complete(new DateOnly(2027, 1, 1));

        var gameCalendar = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2029, 5, 14));

        var ctx1 = new GameDataContext(dir);
        ctx1.InfrastructureProjects.AddAsync(project).Wait();
        ctx1.Calendars.AddAsync(gameCalendar).Wait();
        ctx1.SaveAllAsync().Wait();

        var ctx2 = new GameDataContext(dir);
        var reloadedProject = ctx2.InfrastructureProjects.GetByIdAsync(project.Id).Result!;
        var reloadedCalendar = ctx2.Calendars.GetByIdAsync(gameCalendar.Id).Result!;

        TestRunner.AreEqual(InfrastructureProjectStatus.Completed, reloadedProject.Status,
            "Private-setter Status must survive reload - otherwise a finished build restarts as under construction and completes twice");
        TestRunner.AreEqual<DateOnly?>(new DateOnly(2027, 1, 1), reloadedProject.ActualCompletionDate);
        TestRunner.AreEqual(new DateOnly(2029, 5, 14), reloadedCalendar.CurrentDate,
            "The world must reload on the day it was saved, not on the day it started");
        TestRunner.AreEqual(new DateOnly(2026, 1, 1), reloadedCalendar.StartDate);
    }
    finally
    {
        if (Directory.Exists(dir)) Directory.Delete(dir, true);
    }
});

// ---------------------------------------------------------------------------
// Experience, ageing curves and realistic retirement
// ---------------------------------------------------------------------------

TestRunner.Run("Experience is counted, not derived from age - and saturates the way real learning does", () =>
{
    var young = new PlayerExperience();
    for (int i = 0; i < 40; i++) young.RecordAppearance(MatchFormat.T20, new DateOnly(2026, 1, 1));

    var oldButUncapped = new PlayerExperience();
    for (int i = 0; i < 18; i++) oldButUncapped.RecordAppearance(MatchFormat.Test, new DateOnly(2026, 1, 1));

    TestRunner.IsTrue(young.Level > oldButUncapped.Level,
        "A 40-match youngster is more experienced than a 30-year-old with 18 games - age proves nothing");

    // Diminishing returns tested as a PROPERTY, not against a magic number: the same 60-match
    // increment must be worth far more early in a career than late in one.
    PlayerExperience WithMatches(int n)
    {
        var e = new PlayerExperience();
        for (int i = 0; i < n; i++) e.RecordAppearance(MatchFormat.Test, new DateOnly(2026, 1, 1));
        return e;
    }

    double earlyGain = WithMatches(100).Level - WithMatches(40).Level;
    double lateGain = WithMatches(260).Level - WithMatches(200).Level;

    TestRunner.IsTrue(earlyGain > lateGain * 2.5,
        $"The same 60 matches must teach far more at 40 games than at 200 (early {earlyGain:F1} vs late {lateGain:F1}) - most of what experience teaches is learned early");
    TestRunner.IsTrue(WithMatches(200).Level - young.Level > 20, "But the gap from 40 to 200 games is still large");

    var bigOccasion = new PlayerExperience();
    var routine = new PlayerExperience();
    for (int i = 0; i < 20; i++)
    {
        bigOccasion.RecordAppearance(MatchFormat.ODI, new DateOnly(2026, 1, 1), isInternational: true, isBigMatch: true);
        routine.RecordAppearance(MatchFormat.ODI, new DateOnly(2026, 1, 1));
    }
    TestRunner.IsTrue(bigOccasion.Level > routine.Level * 1.5,
        "Twenty World Cup knockouts teach more than twenty dead rubbers");

    var specialist = new PlayerExperience();
    for (int i = 0; i < 80; i++) specialist.RecordAppearance(MatchFormat.Test, new DateOnly(2026, 1, 1));
    for (int i = 0; i < 3; i++) specialist.RecordAppearance(MatchFormat.T20, new DateOnly(2026, 1, 1));
    TestRunner.IsTrue(specialist.LevelInFormat(MatchFormat.Test) > specialist.LevelInFormat(MatchFormat.T20) * 3,
        "80 Tests and 3 T20s is a novice in T20, however senior he looks overall");
});

TestRunner.Run("A gifted novice struggles under pressure where an experienced player delivers", () =>
{
    var modifier = new SituationalPerformanceModifier();

    var prodigy = new Player { FirstName = "Gifted", LastName = "Debutant", CurrentAbility = 155, PotentialAbility = 190 };
    prodigy.Mental.PressureHandling = 10;
    for (int i = 0; i < 4; i++) prodigy.Experience.RecordAppearance(MatchFormat.ODI, new DateOnly(2026, 1, 1));

    var veteran = new Player { FirstName = "Seasoned", LastName = "Pro", CurrentAbility = 140, PotentialAbility = 140 };
    veteran.Mental.PressureHandling = 15;
    for (int i = 0; i < 120; i++) veteran.Experience.RecordAppearance(MatchFormat.ODI, new DateOnly(2026, 1, 1), isInternational: true, isBigMatch: i % 6 == 0);

    var worldCupFinal = new BattingSituation(12, 5, MatchPhase.MiddleOvers, IsChasing: true, PressureLevel: 95);
    var deadRubber = new BattingSituation(12, 5, MatchPhase.MiddleOvers, IsChasing: true, PressureLevel: 50);

    double prodigyBigGame = modifier.PressureAdjustment(prodigy, worldCupFinal.PressureLevel);
    double veteranBigGame = modifier.PressureAdjustment(veteran, worldCupFinal.PressureLevel);

    TestRunner.IsTrue(prodigyBigGame < 0, "The novice is worse than himself when it matters most");
    TestRunner.IsTrue(veteranBigGame > 0, "The veteran is better - he has been here before");
    TestRunner.IsTrue(veteranBigGame - prodigyBigGame > 0.1, "And the gap is meaningful, not decorative");

    TestRunner.InRange(modifier.PressureAdjustment(prodigy, deadRubber.PressureLevel), -0.001, 0.001,
        "Ordinary cricket must be unaffected - the swing only opens up as the occasion grows");

    var bigMatchPlayer = new Player { FirstName = "Big", LastName = "Match", Personality = PersonalityTrait.BigMatchPlayer };
    bigMatchPlayer.Mental.PressureHandling = 10;
    var ordinary = new Player { FirstName = "Ord", LastName = "Inary" };
    ordinary.Mental.PressureHandling = 10;
    TestRunner.IsTrue(modifier.PressureAdjustment(bigMatchPlayer, 95) > modifier.PressureAdjustment(ordinary, 95),
        "The BigMatchPlayer trait exists precisely for this moment and must actually do something");
});

TestRunner.Run("Ageing hits physical first while technical and mental keep improving", () =>
{
    var ageing = new PlayerAgeingService();
    var start = new DateOnly(2026, 6, 1);

    Player MakeAged(int age) => new()
    {
        FirstName = "Player",
        LastName = age.ToString(),
        DateOfBirth = start.AddYears(-age),
        CurrentAbility = 140,
        PotentialAbility = 150,
        Physical = new PhysicalAttributes { Fitness = 14, Stamina = 14, Speed = 14, Strength = 14, Recovery = 14 },
        Batting = new BattingAttributes { Technique = 12, ShotSelection = 12, DefensiveAbility = 12, Timing = 12, RiskManagement = 12 },
        Mental = new MentalAttributes { Composure = 12, Concentration = 12, GameAwareness = 12, DecisionMaking = 12, PressureHandling = 12 }
    };

    // Run ten years of ageing on a cohort so the probabilistic yearly steps average out.
    (double physical, double technical, double mental) Simulate(int startAge)
    {
        double physical = 0, technical = 0, mental = 0;
        for (int run = 0; run < 30; run++)
        {
            var p = MakeAged(startAge);
            var random = new Random(run);
            int fitnessBefore = p.Physical.Fitness, techniqueBefore = p.Batting.Technique, composureBefore = p.Mental.Composure;
            for (int y = 0; y < 5; y++) ageing.ApplyAnnualAgeing(p, start.AddYears(y), random);
            physical += p.Physical.Fitness - fitnessBefore;
            technical += p.Batting.Technique - techniqueBefore;
            mental += p.Mental.Composure - composureBefore;
        }
        return (physical / 30, technical / 30, mental / 30);
    }

    var thirties = Simulate(31);
    TestRunner.IsTrue(thirties.physical < 0, "From 31, the body is going");
    TestRunner.IsTrue(thirties.technical >= 0, "...while the method is still being refined");
    TestRunner.IsTrue(thirties.mental > 0, "...and the head is still getting better - this is why veterans stay pickable");

    var twenties = Simulate(22);
    TestRunner.IsTrue(twenties.physical > 0, "A 22-year-old is still growing physically");

    var forties = Simulate(40);
    TestRunner.IsTrue(forties.physical < thirties.physical, "Decline accelerates with age");
    TestRunner.IsTrue(forties.technical < 0, "Past 40 the hands can no longer execute what the head still knows");
});

TestRunner.Run("Fast bowlers age harder than the rest, as their careers actually do", () =>
{
    var ageing = new PlayerAgeingService();
    var start = new DateOnly(2026, 6, 1);

    double AveragePhysicalLoss(BowlingRoleType role, int pace)
    {
        double total = 0;
        for (int run = 0; run < 30; run++)
        {
            var p = new Player
            {
                FirstName = "Bowler",
                LastName = role.ToString(),
                DateOfBirth = start.AddYears(-32),
                CurrentAbility = 140,
                PotentialAbility = 145,
                BowlingRole = role,
                Physical = new PhysicalAttributes { Fitness = 16, Stamina = 16, Speed = 16, Strength = 16, Recovery = 16 }
            };
            p.Bowling.Pace = pace;
            int before = p.Physical.Fitness;
            var random = new Random(run);
            for (int y = 0; y < 5; y++) ageing.ApplyAnnualAgeing(p, start.AddYears(y), random);
            total += p.Physical.Fitness - before;
        }
        return total / 30;
    }

    double quick = AveragePhysicalLoss(BowlingRoleType.OpeningBowler, pace: 17);
    double spinner = AveragePhysicalLoss(BowlingRoleType.SpecialistSpinner, pace: 6);

    TestRunner.IsTrue(quick < spinner,
        "A genuine quick's body breaks down faster than a spinner's - the single biggest reason their careers are shorter");
});

TestRunner.Run("Nobody retires at 26, and not everyone retires at 36", () =>
{
    var retirement = new RetirementService();
    var start = new DateOnly(2026, 6, 1);

    Player Make(int age, int ability = 140) => new()
    {
        FirstName = "Player",
        LastName = age.ToString(),
        DateOfBirth = start.AddYears(-age),
        CurrentAbility = ability,
        PotentialAbility = ability,
        Physical = new PhysicalAttributes { Fitness = 13, Stamina = 13, Recovery = 13 }
    };

    double RetirementRate(int age, int matchesLastSeason = 12, Action<Player>? tweak = null)
    {
        int retired = 0;
        for (int run = 0; run < 400; run++)
        {
            var p = Make(age);
            tweak?.Invoke(p);
            if (retirement.Assess(p, start, matchesLastSeason, new Random(run)).ShouldRetire) retired++;
        }
        return retired / 400.0;
    }

    TestRunner.AreEqual(0.0, RetirementRate(26), "A 26-year-old in the side does not retire, full stop");
    TestRunner.IsTrue(RetirementRate(33) < 0.15, "Early thirties is not a retirement age for most players");

    double at36 = RetirementRate(36);
    TestRunner.IsTrue(at36 is > 0.02 and < 0.6,
        $"36 must be a real possibility but nowhere near universal - got {at36:P0}, and 'everyone goes at 36' is exactly the failure mode to avoid");
    TestRunner.IsTrue(RetirementRate(41) > at36, "The odds keep climbing with age");

    // The strongest driver is not age at all.
    TestRunner.IsTrue(RetirementRate(34, matchesLastSeason: 0) > RetirementRate(34, matchesLastSeason: 20) + 0.2,
        "Not being picked ends far more careers than birthdays do");

    // Standing buys extra seasons.
    double star = RetirementRate(37, tweak: p => p.Reputation = new Reputation(domestic: 90, continental: 80));
    double journeyman = RetirementRate(37, tweak: p => p.Reputation = new Reputation(domestic: 20));
    TestRunner.IsTrue(star < journeyman, "A big name gets another season where a journeyman is quietly let go");

    // Personality and body.
    TestRunner.IsTrue(RetirementRate(35, tweak: p => p.Personality = PersonalityTrait.Lazy)
                    > RetirementRate(35, tweak: p => p.Personality = PersonalityTrait.Ambitious | PersonalityTrait.Professional),
        "An ambitious professional grinds on where someone lazy does not");
    TestRunner.IsTrue(RetirementRate(35, tweak: p => p.Physical = new PhysicalAttributes { Fitness = 5, Stamina = 5, Recovery = 5 })
                    > RetirementRate(35, tweak: p => p.Physical = new PhysicalAttributes { Fitness = 17, Stamina = 17, Recovery = 17 }),
        "A body that can no longer do it ends a career regardless of the number of birthdays");
});

TestRunner.Run("A quick bowler's career ends earlier than a spinner's at the same age", () =>
{
    var retirement = new RetirementService();
