    }

    TestRunner.IsTrue(Rate(BowlingRoleType.OpeningBowler, 17) > Rate(BowlingRoleType.SpecialistSpinner, 6),
        "At 35 a genuine quick is far closer to the end than a spinner is");
});

TestRunner.Run("The clock ages the world and retires players as years pass, once per year", () =>
{
    // BUG FOUND (real, pre-existing, not introduced this session): GameCalendar.WorldSeed
    // defaults to Random.Shared.Next() when not supplied - correct for a genuinely new save
    // (per the class's own doc comment), but this test asserts on POPULATION-LEVEL stochastic
    // retirement outcomes over a decade, which means it was silently non-deterministic every
    // time it ran without an explicit seed - the exact "flaky test is the only warning you get"
    // failure mode this project's own history already names for HashCode.Combine-seeded RNG.
    // Reproduced directly: ran clean 5 times, then failed 3 of the next 5 runs with no code
    // changes in between. Fixed by pinning worldSeed like every other calendar-driven test here
    // already does.
    var calendar = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 4242);
    var clock = new WorldClockService();
    var seeder = new WorldSeeder(seed: 21, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);

    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>()
    };

    var oldestBefore = players.Max(p => p.Age(calendar.CurrentDate));
    var events = clock.AdvanceTo(calendar, world, new DateOnly(2036, 6, 1));

    TestRunner.AreEqual(10, events.Count(e => e.Type == GameEventType.SeasonRollover), "Ten years, ten rollovers");
    TestRunner.IsTrue(players.Max(p => p.Age(calendar.CurrentDate)) == oldestBefore + 10, "Everyone is ten years older");

    var retirements = events.Where(e => e.Type == GameEventType.PlayerRetired).ToList();
    TestRunner.IsTrue(retirements.Count > 0, "Over a decade, some careers must end");
    // Section H means retirements.Count is no longer "one per player" - a staged career can fire
    // more than one PlayerRetired event for the SAME player (a Test step-back, then years later
    // full retirement). The population-level claim has to be checked on DISTINCT players, not
    // raw event count, or a handful of staged careers alone could make this assertion fail even
    // though most of the world is nowhere near retiring.
    int distinctPlayersRetired = retirements.Select(e => e.SubjectId).Distinct().Count();
    TestRunner.IsTrue(distinctPlayersRetired < players.Count, "...but not all of them - a decade should not empty the world");
    // Section H (format-specific retirement) means a career's END can now be staged - "retires
    // from Test cricket" one year, "calls time on his career" outright a few years later are
    // both real, distinct, dated news events for the SAME player, which the pre-existing
    // one-event-per-player assumption here didn't anticipate. The invariant that still has to
    // hold: never the IDENTICAL announcement fired twice for one player (that would be a bug,
    // not a staged career).
    TestRunner.IsTrue(retirements.GroupBy(e => e.SubjectId).All(g => g.Select(e => e.Headline).Distinct().Count() == g.Count()),
        "A player may retire from more than one format over the years, but never receives the exact same retirement announcement twice");
    TestRunner.IsTrue(players.Where(p => p.IsRetired).All(p => p.RetirementDate is not null && p.CurrentTeamId is null),
        "A retired player is properly closed off, not just flagged");

    var retiredAges = players.Where(p => p.IsRetired).Select(p => p.Age(p.RetirementDate!.Value)).Distinct().ToList();
    TestRunner.IsTrue(retiredAges.Count > 1,
        $"Retirement ages must vary - got only {string.Join(",", retiredAges)}, which would mean an age cutoff in disguise");

    TestRunner.IsTrue(players.All(p => p.Experience.SeasonsPlayed > 0), "Seasons played accumulate with the calendar");
});

TestRunner.Run("The seeded world is a snapshot of its start date, not of the machine clock", () =>
{
    var start = new DateOnly(2026, 6, 1);
    var seeder = new WorldSeeder(seed: 99, worldStartDate: start);
    var (_, players) = seeder.GenerateStarterWorld(teamCount: 2, squadSize: 13);

    TestRunner.IsTrue(players.All(p => p.Age(start) is >= 18 and <= 37),
        "Every seeded player must be a plausible age AT THE START DATE - ages derived from DateTime.Today drift with real-world time");

    // Same seed, same world - regardless of when it was generated.
    var again = new WorldSeeder(seed: 99, worldStartDate: start).GenerateStarterWorld(teamCount: 2, squadSize: 13).Players;
    TestRunner.IsTrue(players.Select(p => p.DateOfBirth).SequenceEqual(again.Select(p => p.DateOfBirth)),
        "A seeded world must be reproducible - it was not while dates came from the machine clock");

    var future = new WorldSeeder(seed: 99, worldStartDate: new DateOnly(2030, 6, 1)).GenerateStarterWorld(teamCount: 2, squadSize: 13).Players;
    TestRunner.IsTrue(future.All(p => p.Age(new DateOnly(2030, 6, 1)) is >= 18 and <= 37),
        "A world started in 2030 is a 2030 snapshot");

    TestRunner.IsTrue(players.Any(p => p.Experience.TotalMatches > 0),
        "A snapshot contains careers already in progress - not a world of players who have never played");
    TestRunner.IsTrue(players.All(p => p.Experience.DebutDate is null || p.Experience.DebutDate <= start),
        "Nobody debuts in the future");

    var senior = players.Where(p => p.Age(start) >= 30).ToList();
    var youngsters = players.Where(p => p.Age(start) <= 21).ToList();
    if (senior.Count > 0 && youngsters.Count > 0)
        TestRunner.IsTrue(senior.Average(p => p.Experience.Level) > youngsters.Average(p => p.Experience.Level),
            "Older players broadly have more behind them - though individuals can and should differ");
});

TestRunner.Run("Competition seasons accumulate on their own so a long career has real history", () =>
{
    var calendar = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 100584);
    var clock = new WorldClockService();
    var history = new CompetitionHistoryService();

    var league = new Competition { Name = "National T20 Cup", Window = CompetitionWindow.Annual(9, 15, 3, 20) };
    var worldCup = new Competition { Name = "T20 World Cup", Window = CompetitionWindow.Cycle(2, 2026, 2, 6, 3, 8) };

    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team>(),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = new List<Player>(),
        Projects = new List<InfrastructureProject>()
    };
    world.Competitions.Add(league);
    world.Competitions.Add(worldCup);

    clock.AdvanceTo(calendar, world, new DateOnly(2036, 1, 2));

    int leagueSeasons = world.CompetitionSeasons.Count(s => s.CompetitionId == league.Id);
    int worldCupSeasons = world.CompetitionSeasons.Count(s => s.CompetitionId == worldCup.Id);

    TestRunner.IsTrue(leagueSeasons >= 9, $"An annual league should have ~10 seasons on record after a decade, got {leagueSeasons}");
    TestRunner.IsTrue(worldCupSeasons is >= 4 and <= 6, $"A two-yearly World Cup should have ~5, got {worldCupSeasons}");
    TestRunner.IsTrue(leagueSeasons > worldCupSeasons, "The annual competition outnumbers the biennial one");

