TestRunner.Run("Retirement treats 'no match data yet' as unknown, not as 'nobody picked him'", () =>
{
    var retirement = new RetirementService();
    var start = new DateOnly(2026, 6, 1);

    Player Make() => new()
    {
        FirstName = "Established",
        LastName = "Pro",
        DateOfBirth = start.AddYears(-33),
        CurrentAbility = 145,
        PotentialAbility = 145,
        Physical = new PhysicalAttributes { Fitness = 14, Stamina = 14, Recovery = 14 }
    };

    double Rate(int? matches)
    {
        int retired = 0;
        for (int run = 0; run < 500; run++)
            if (retirement.Assess(Make(), start, matches, new Random(run)).ShouldRetire) retired++;
        return retired / 500.0;
    }

    double unknown = Rate(null);
    double genuinelyDropped = Rate(0);
    double regular = Rate(15);

    TestRunner.IsTrue(unknown < genuinelyDropped - 0.15,
        $"Unknown playing time must NOT carry the full dropped penalty (unknown {unknown:P0} vs dropped {genuinelyDropped:P0}) - third occurrence of unpopulated-default-as-negative-signal in this codebase");
    TestRunner.InRange(unknown - regular, -0.05, 0.05,
        "With no data the playing-time term is skipped entirely, landing near a regularly-picked player");
    TestRunner.IsTrue(genuinelyDropped > regular, "Once we DO know he wasn't picked, it counts heavily against him");
});

TestRunner.Run("The clock only applies the playing-time penalty once a match engine is feeding it", () =>
{
    var calendar = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 4242);
    var clock = new WorldClockService();
    var seeder = new WorldSeeder(seed: 33, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);

    WorldState BuildWorld(IList<Player> squad) => new()
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = squad,
        Projects = new List<InfrastructureProject>()
    };

    var world = BuildWorld(players.ToList());
    var events = clock.AdvanceTo(calendar, world, new DateOnly(2031, 6, 1));
    int retiredWithoutMatchData = events.Count(e => e.Type == GameEventType.PlayerRetired);

    // The bound is deliberately loose - a seeded cohort with no incoming youth genuinely does
    // thin out over five years, and the players aged 31-36 at the start are 36-41 by the end.
    // What actually proves the fix is WHO goes: with the bug, the blanket +0.30 hit everyone
    // over 28 equally, so retirements were spread across the age range instead of concentrated
    // at the top of it.
    TestRunner.IsTrue(retiredWithoutMatchData < players.Count / 2,
        $"Five years with no match engine running must not gut the world - {retiredWithoutMatchData} of {players.Count} retired");

    var retiredPlayers = players.Where(p => p.IsRetired).ToList();
    var survivors = players.Where(p => !p.IsRetired).ToList();
    TestRunner.IsTrue(retiredPlayers.Count > 0 && survivors.Count > 0, "Some go, some stay");
    TestRunner.IsTrue(retiredPlayers.Average(p => p.Age(p.RetirementDate!.Value)) > survivors.Average(p => p.Age(calendar.CurrentDate)),
        "Those who retired must be meaningfully older than those who didn't - a blanket penalty would flatten that difference");
    TestRunner.IsTrue(retiredPlayers.All(p => p.Age(p.RetirementDate!.Value) >= RetirementService.MinimumRetirementAge),
        "Nobody under the floor retires, whatever the data situation");

    // And the writer the match engine will use does work.
    var tracked = BuildWorld(players.Where(p => !p.IsRetired).ToList());
    var someone = tracked.Players.First();
    tracked.RecordAppearance(someone.Id);
    tracked.RecordAppearance(someone.Id);
    TestRunner.AreEqual(2, tracked.MatchesThisSeason[someone.Id], "RecordAppearance is the match engine's entry point and counts correctly");
});

