TestRunner.Run("Head-to-head matchup history actually reaches the ball model", () =>
{
    var model = new BallOutcomeModel();
    var matchups = new MatchupConfidenceService();

    var batter = MatchTestData.MakePlayer("Bat", 13);
    var nemesis = MatchTestData.MakePlayer("Nemesis", 13, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);

    BallContext Ctx(Player striker) => new() { Striker = striker, Bowler = nemesis, Format = MatchFormat.T20 };

    double before = model.GetBatterEffectiveSkill(Ctx(batter));

    // A run of failures against this specific bowler must make the batter measurably worse
    // against him. This was keyed as an OPPONENT-TEAM key built from a bowler id, so it could
    // never match anything and head-to-head history silently did nothing.
    for (int i = 0; i < 6; i++) matchups.RecordOutcome(batter, MatchupKey.ForBowler(nemesis.Id), -70);
    double afterFailures = model.GetBatterEffectiveSkill(Ctx(batter));

    TestRunner.IsTrue(afterFailures < before, "Repeated failures against a specific bowler must lower effective skill against him");

    var confident = MatchTestData.MakePlayer("Bat", 13);
    for (int i = 0; i < 6; i++) matchups.RecordOutcome(confident, MatchupKey.ForBowler(nemesis.Id), 80);
    TestRunner.IsTrue(model.GetBatterEffectiveSkill(Ctx(confident)) > before, "And dominance must raise it");
});

TestRunner.Run("Maiden overs follow the actual laws - wicket maidens count, byes don't disqualify", () =>
{
    // The maiden rule is about runs charged TO THE BOWLER. Byes and leg-byes are not his, and a
    // wicket certainly doesn't stop an over being a maiden.
    var card = new BowlerCard { PlayerId = Guid.NewGuid(), PlayerName = "Tight" };

    // Simulate the two conditions the old logic got wrong, at the level the fix operates on.
    card.RunsConceded = 0;
    int atOverStart = card.RunsConceded;
    TestRunner.IsTrue(card.RunsConceded == atOverStart, "No runs charged to the bowler - a maiden regardless of byes or wickets");

    card.RunsConceded += 1; // a single off the bat
    TestRunner.IsTrue(card.RunsConceded != atOverStart, "A run off the bat ends the maiden");
});

TestRunner.Run("Ground dimensions change how a venue scores", () =>
{
    var model = new BallOutcomeModel();
    var batter = MatchTestData.MakePlayer("Slogger", 16);
    var bowler = MatchTestData.MakePlayer("Bowl", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);

    var bandbox = new Ground { Name = "Bandbox", SquareBoundaryMetres = 58, StraightBoundaryMetres = 62, OutfieldSpeed = 85, AltitudeMetres = 1500 };
    var cavern = new Ground { Name = "Cavern", SquareBoundaryMetres = 85, StraightBoundaryMetres = 88, OutfieldSpeed = 25, AltitudeMetres = 0 };

    BallContext Ctx(Ground? g) => new()
    {
        Striker = batter,
        Bowler = bowler,
        Format = MatchFormat.T20,
        Phase = MatchPhase.DeathOvers,
        BattingIntent = BattingIntent.Attacking,
        Ground = g
    };

    var small = model.CalculateProbabilities(Ctx(bandbox));
    var big = model.CalculateProbabilities(Ctx(cavern));
    var neutral = model.CalculateProbabilities(Ctx(null));

    TestRunner.IsTrue(small.Six > big.Six * 1.3, "A short boundary at altitude must produce materially more sixes than a huge ground at sea level");
    TestRunner.IsTrue(small.Four > big.Four, "And more fours - a fast outfield beats the sweeper");
    TestRunner.IsTrue(neutral.Six > big.Six && neutral.Six < small.Six, "No ground supplied sits between the extremes, unaffected");
    TestRunner.InRange(small.Total, 0.999, 1.001, "The distribution still sums to 1");
});

TestRunner.Run("A full match produces a real result with a proper chase", () =>
{
    var simulator = new MatchSimulator();
    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 13, 13);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 13, 13);

    var setup = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "Lahore Lions", homeOrder, homeBowlers),
        Away = new MatchSide(Guid.NewGuid(), "Karachi Kings XI", awayOrder, awayBowlers),
        Format = MatchFormat.T20,
        OversPerInnings = 20,
        MatchDate = new DateOnly(2026, 7, 4),
        Season = 2026
    };

    var match = simulator.Simulate(setup, new Random(42));

    TestRunner.AreEqual(2, match.SecondInnings.InningsNumber);
    TestRunner.AreEqual(match.FirstInnings.Runs + 1, match.SecondInnings.Target!.Value, "The chase target is one more than the first innings");
    TestRunner.IsTrue(match.FirstInnings.Runs > 40 && match.FirstInnings.Runs < 320, $"A T20 innings should be a plausible score, got {match.FirstInnings.Runs}");
    TestRunner.IsTrue(match.FirstInnings.LegalBalls <= 120 && match.SecondInnings.LegalBalls <= 120, "Nobody bats more than 20 overs");

    // A completed chase stops the moment the target is passed - it does not play out the overs.
    if (match.SecondInnings.Runs >= match.SecondInnings.Target)
        TestRunner.IsTrue(match.WinningTeamId == match.SecondInnings.BattingTeamId && match.WonByWickets,
            "A successful chase is reported as a win by wickets");
    else
        TestRunner.IsTrue(match.WinningTeamId == match.FirstInnings.BattingTeamId || match.WinningTeamId is null,
            "Otherwise the defending side won, or it was tied");

    TestRunner.IsTrue(match.Summary.Contains("beat") || match.Summary.Contains("tied"), $"Result must read like cricket: {match.Summary}");

    // Deterministic from a seed - essential for debugging a stochastic simulation at all.
    var replay = simulator.Simulate(setup, new Random(42));
    TestRunner.AreEqual(match.FirstInnings.Runs, replay.FirstInnings.Runs, "Same seed, same match");
    TestRunner.AreEqual(match.SecondInnings.Runs, replay.SecondInnings.Runs);
});

TestRunner.Run("Recording a match brings every dormant Phase 1-3 system to life at once", () =>
{
    var simulator = new MatchSimulator();
    var recorder = new MatchRecorder();
    var groundRecords = new GroundRecordsService();
    var query = new PlayerStatsQueryService();

    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 14, 14);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 13, 13);
    var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);

    var ground = new Ground { Name = "Gaddafi Stadium", City = "Lahore", Country = "Pakistan", Capacity = 27000 };
    var competition = new Competition { Name = "Pakistan Super League", Prestige = 72, Reputation = 70, Scope = CompetitionScope.FranchiseLeague };
    var season = new CompetitionSeason { CompetitionId = competition.Id, Year = 2026 };

    var homeId = Guid.NewGuid(); var awayId = Guid.NewGuid();
    var setup = new MatchSetup
    {
        Home = new MatchSide(homeId, "Lahore", homeOrder, homeBowlers),
        Away = new MatchSide(awayId, "Karachi", awayOrder, awayBowlers),
        Format = MatchFormat.T20,
        OversPerInnings = 20,
        Ground = ground,
        Competition = competition,
        MatchDate = new DateOnly(2026, 7, 4),
        Season = 2026
    };
    season.ParticipatingTeamIds.AddRange(new[] { homeId, awayId });

    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team>(),
        Grounds = new Dictionary<Guid, Ground> { [ground.Id] = ground },
        Players = allPlayers.Values.ToList(),
        Projects = new List<InfrastructureProject>()
    };

    var match = simulator.Simulate(setup, new Random(7));
    var records = recorder.Record(match, allPlayers, season, world, new Random(7));

    // Records produced
    TestRunner.IsTrue(records.Batting.Count >= 4, "Batting records written for everyone who batted");
    TestRunner.IsTrue(records.Bowling.Count >= 8, "Bowling records for both attacks");
    TestRunner.AreEqual(2, records.TeamInnings.Count, "One team-innings record per innings");
    TestRunner.IsTrue(records.Batting.Any(r => r.Dismissal != DismissalType.NotOut && r.DismissedByBowlerId is not null),
        "Dismissal info is finally populated - the tech-debt item carried since Phase 1");
    TestRunner.IsTrue(records.Fielding.Count > 0 && records.Fielding.Sum(f => f.Dismissals) > 0,
        "Fielding records are produced from the ball-by-ball data");

    // Ground records derive with no extra wiring
    TestRunner.IsTrue(groundRecords.GetHighestTeamTotal(records.TeamInnings, ground.Id) is not null,
        "The ground now has a highest team total, derived from the innings the match produced");
    TestRunner.IsTrue(groundRecords.GetHighestIndividualScore(records.Batting, ground.Id) is not null,
        "And an individual record");
    TestRunner.AreEqual(1, groundRecords.GetResultSplit(records.TeamInnings, ground.Id).MatchesHosted,
        "Two innings, one match - the ground has hosted exactly one fixture");

    // Standings and NRR
    var homeStanding = season.Standings.First(s => s.TeamId == homeId);
    var awayStanding = season.Standings.First(s => s.TeamId == awayId);
    TestRunner.AreEqual(1, homeStanding.Played);
    TestRunner.AreEqual(2, homeStanding.Points + awayStanding.Points, "Two points distributed across the two sides");
    TestRunner.IsTrue(Math.Abs(homeStanding.NetRunRate + awayStanding.NetRunRate) < 0.001,
        "One side's net run rate is the exact mirror of the other's");
    TestRunner.IsTrue(homeStanding.NetRunRate != 0, "NRR is actually computed, not left at the 'no data' default");

    // Careers moved
    var topScorer = records.Batting.OrderByDescending(r => r.Runs).First();
    var scorer = allPlayers[topScorer.PlayerId];
    TestRunner.IsTrue(scorer.Experience.TotalMatches > 0, "Appearances counted towards experience");
    TestRunner.IsTrue(scorer.Form.RecentPerformanceRatings.Count > 0, "Form consumed the performance");
    TestRunner.IsTrue(world.MatchesThisSeason.Count > 0, "Playing time logged for the retirement loop");

    // Player stat filtering works off the real records
    var atGround = query.QueryBatting(records.Batting, topScorer.PlayerId, new StatsFilter(GroundId: ground.Id));
    TestRunner.AreEqual(topScorer.Runs, atGround.Runs, "The player's record at this ground reads back correctly");
});

TestRunner.Run("Net run rate charges a side bowled out for the full quota of overs", () =>
{
    // The rule people most often get wrong: a team dismissed in 12 overs is treated as having
    // used all 20, so being bowled out cheaply hurts NRR instead of flattering it.
    var recorder = new MatchRecorder();
    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Strong", 18, 18);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Weak", 5, 5);
    var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);

    var homeId = Guid.NewGuid(); var awayId = Guid.NewGuid();
    var setup = new MatchSetup
    {
        Home = new MatchSide(homeId, "Strong", homeOrder, homeBowlers),
        Away = new MatchSide(awayId, "Weak", awayOrder, awayBowlers),
        Format = MatchFormat.T20,
        OversPerInnings = 20,
        MatchDate = new DateOnly(2026, 7, 4),
        Season = 2026
    };

    var season = new CompetitionSeason { Year = 2026 };
    var match = new MatchSimulator().Simulate(setup, new Random(11));
    recorder.Record(match, allPlayers, season);

    var winnerStanding = season.Standings.First(s => s.TeamId == match.WinningTeamId);
    var loserStanding = season.Standings.First(s => s.TeamId != match.WinningTeamId);

    TestRunner.IsTrue(winnerStanding.NetRunRate > 0 && loserStanding.NetRunRate < 0,
        "The winning side's NRR is positive and the losing side's negative");
    TestRunner.IsTrue(Math.Abs(winnerStanding.NetRunRate + loserStanding.NetRunRate) < 0.001, "Exact mirror");
});

TestRunner.Run("Injuries finally occur during play, and land on bowlers who did the work", () =>
{
    var simulator = new MatchSimulator();
    var recorder = new MatchRecorder();

    int injuries = 0, matches = 40;
    var injuredWereBowlers = true;

    for (int run = 0; run < matches; run++)
    {
        var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 13, 13);
        var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 13, 13);
        foreach (var p in homeOrder.Concat(awayOrder)) p.Physical.InjuryProneness = 18; // fragile squads
        var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);

        var setup = new MatchSetup
        {
            Home = new MatchSide(Guid.NewGuid(), "Home", homeOrder, homeBowlers),
            Away = new MatchSide(Guid.NewGuid(), "Away", awayOrder, awayBowlers),
            Format = MatchFormat.T20,
            OversPerInnings = 20,
            MatchDate = new DateOnly(2026, 7, 4),
            Season = 2026
        };

        var match = simulator.Simulate(setup, new Random(run));
        var records = recorder.Record(match, allPlayers, random: new Random(run * 31 + 5));

        foreach (var e in records.Events.Where(e => e.Type == GameEventType.InjuryOccurred))
        {
            injuries++;
            var injured = allPlayers[e.SubjectId!.Value];
            if (injured.CurrentInjury is null) injuredWereBowlers = false;
        }
    }

    TestRunner.IsTrue(injuries > 0, $"Across {matches} matches with fragile squads, some injuries must occur - none did");
    TestRunner.IsTrue(injuries < matches, "But not one every match - injuries are rare events, not a tax on playing");
    TestRunner.IsTrue(injuredWereBowlers, "Every reported injury actually left the player injured");
});

TestRunner.Run("Bowler spells accumulate across a continuing spell and reset after a break", () =>
{
    var simulator = new InningsSimulator();
    var setupA = MatchTestData.Setup(13, 13, "A");

    var innings = simulator.Simulate(setupA, MatchFormat.T20, 20,
        Guid.NewGuid(), "Batting XI", Guid.NewGuid(), "Bowling XI", new Random(5));

    // A bowler who has bowled several overs in one spell must show it. Before the fix,
    // BallsInCurrentSpell was reset at the start of every over, so it could never exceed 6 and
    // the spell half of the fatigue model did nothing at all.
    // The property that matters is that SOME bowler built a real spell. The highest-workload
    // bowler is not necessarily the one currently mid-spell - a captain may have taken him off
    // and brought someone else on, which resets his counter and is exactly correct.
    int longestSpell = innings.BowlerCards.Max(c => c.BallsInCurrentSpell);
    TestRunner.IsTrue(longestSpell > 6,
        $"Some bowler must build a spell longer than a single over - longest was {longestSpell} balls");
    TestRunner.IsTrue(innings.BowlerCards.All(c => c.BallsInCurrentSpell <= c.LegalBallsBowled),
        "A spell can never be longer than the bowler's whole workload");

    // Captains bowl in spells, not scattered single overs: a bowler's overs should cluster.
    var sequenceByOver = innings.Deliveries.GroupBy(d => d.OverNumber).OrderBy(g => g.Key)
        .Select(g => g.First().BowlerId).ToList();
    int alternatingPairs = 0;
    for (int i = 2; i < sequenceByOver.Count; i++)
        if (sequenceByOver[i] == sequenceByOver[i - 2]) alternatingPairs++;
    TestRunner.IsTrue(alternatingPairs >= sequenceByOver.Count / 3,
        $"Bowlers should be used in alternating spells rather than scattered - only {alternatingPairs} continuations in {sequenceByOver.Count} overs");
    TestRunner.IsTrue(innings.BowlerCards.All(c => c.LastOverBowled >= 0), "Every bowler who bowled has a recorded last over");
});

TestRunner.Run("Nobody bowls consecutive overs or exceeds the per-bowler limit", () =>
{
    var simulator = new InningsSimulator();
    var setup = MatchTestData.Setup(13, 13, "B");

    var innings = simulator.Simulate(setup, MatchFormat.T20, 20,
        Guid.NewGuid(), "Batting XI", Guid.NewGuid(), "Bowling XI", new Random(9));

    // Reconstruct the over-by-over bowler sequence from the deliveries themselves.
    var sequence = innings.Deliveries
        .GroupBy(d => d.OverNumber)
        .OrderBy(g => g.Key)
        .Select(g => g.First().BowlerId)
        .ToList();

    for (int i = 1; i < sequence.Count; i++)
        TestRunner.IsTrue(sequence[i] != sequence[i - 1], $"Consecutive overs by the same bowler at over {i}");

    int maxOvers = InningsSimulator.MaxOversPerBowler(MatchFormat.T20, 20)!.Value;
    TestRunner.IsTrue(innings.BowlerCards.All(c => c.LegalBallsBowled <= maxOvers * 6),
        $"No bowler may exceed {maxOvers} overs in a T20 innings");
});

TestRunner.Run("The scorecard adds up - batter runs plus extras equals the team total", () =>
{
    var simulator = new InningsSimulator();
    var setup = MatchTestData.Setup(14, 12, "C");

    var innings = simulator.Simulate(setup, MatchFormat.T20, 20,
        Guid.NewGuid(), "Batting XI", Guid.NewGuid(), "Bowling XI", new Random(3));

    int batterRuns = innings.BatterCards.Sum(c => c.Runs);
    TestRunner.AreEqual(innings.Runs, batterRuns + innings.Extras,
        "Team total must equal runs off the bat plus extras - if this drifts, every statistic downstream is wrong");

    int ballsFaced = innings.BatterCards.Sum(c => c.BallsFaced);
    int legalBallsFromDeliveries = innings.Deliveries.Count(d => d.Outcome.IsLegalDelivery);
    TestRunner.AreEqual(innings.LegalBalls, legalBallsFromDeliveries, "Legal-ball count must match the deliveries recorded");
    TestRunner.IsTrue(ballsFaced <= innings.LegalBalls + 5,
        "Balls faced cannot meaningfully exceed legal deliveries - wides are not balls faced");

    TestRunner.IsTrue(innings.BatterCards.Count(c => c.IsOut) == innings.Wickets, "Wickets must equal batters dismissed");
    TestRunner.AreEqual(innings.Wickets, innings.FallOfWickets.Count, "Every wicket has a fall-of-wicket entry");

    int bowlerCharged = innings.BowlerCards.Sum(c => c.RunsConceded);
    TestRunner.IsTrue(bowlerCharged <= innings.Runs,
        "Bowlers cannot be charged more than the team scored - byes and leg-byes are not theirs");
});

// ---------------------------------------------------------------------------
// Phase 4 Slice 3: fielding positions, field settings and their real effects
// ---------------------------------------------------------------------------

TestRunner.Run("Law 28.4 is enforced - the leg side cannot be packed behind square", () =>
{
    var rules = new FieldSettingRules();
    var ids = Enumerable.Range(0, 11).Select(_ => Guid.NewGuid()).ToArray();

    FieldSetting Build(params FieldingPosition[] positions) => new()
    {
        Placements = positions.Select((p, i) => new FieldPlacement(p, ids[i])).ToList()
    };

    // A Bodyline field: everything behind square on the leg side.
    var bodyline = Build(
        FieldingPosition.WicketKeeper, FieldingPosition.LegSlip, FieldingPosition.DeepSquareLeg,
        FieldingPosition.DeepFineLeg, FieldingPosition.SquareLeg, FieldingPosition.ShortLeg,
        FieldingPosition.MidOn, FieldingPosition.MidWicket, FieldingPosition.Bowler,
        FieldingPosition.MidOff, FieldingPosition.Cover);

    var result = rules.Validate(bodyline, MatchFormat.Test, MatchPhase.MiddleOvers);
    TestRunner.IsTrue(!result.IsLegal, "A field with more than two behind square on the leg side must be illegal");
    TestRunner.IsTrue(result.Violations.Any(v => v.Contains("28.4")), "The violation must name the law that forbids it");

    var legal = Build(
        FieldingPosition.WicketKeeper, FieldingPosition.Slip1, FieldingPosition.Slip2,
        FieldingPosition.Gully, FieldingPosition.Point, FieldingPosition.Cover,
        FieldingPosition.MidOff, FieldingPosition.MidOn, FieldingPosition.MidWicket,
        FieldingPosition.SquareLeg, FieldingPosition.Bowler);
    TestRunner.IsTrue(rules.Validate(legal, MatchFormat.Test, MatchPhase.MiddleOvers).IsLegal, "A conventional field is legal");
});

TestRunner.Run("Powerplay circle restrictions differ by format and phase, and Tests have none", () =>
{
    var rules = new FieldSettingRules();

    TestRunner.AreEqual<int?>(2, rules.MaxOutsideCircle(MatchFormat.T20, MatchPhase.Powerplay), "T20 powerplay allows two out");
    TestRunner.AreEqual<int?>(5, rules.MaxOutsideCircle(MatchFormat.T20, MatchPhase.DeathOvers), "Five at the death");
    TestRunner.AreEqual<int?>(2, rules.MaxOutsideCircle(MatchFormat.ODI, MatchPhase.Powerplay));
    TestRunner.AreEqual<int?>(4, rules.MaxOutsideCircle(MatchFormat.ODI, MatchPhase.MiddleOvers), "ODI middle overs allow four");
    TestRunner.IsTrue(rules.MaxOutsideCircle(MatchFormat.Test, MatchPhase.MiddleOvers) is null,
        "First-class cricket has no fielding restrictions - a Test captain may set what he likes");
});

TestRunner.Run("The AI captain sets legal fields that match the situation", () =>
{
    var setter = new AutoFieldSetter();
    var rules = new FieldSettingRules();
    var (side, bowlers) = MatchTestData.MakeEleven("Field", 13, 13);
    var seamer = bowlers[0];
    var spinner = MatchTestData.MakePlayer("Spin", 15, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    spinner.Bowling.Spin = 18; spinner.Bowling.Pace = 5;

    foreach (var (format, phase) in new[]
    {
        (MatchFormat.T20, MatchPhase.Powerplay), (MatchFormat.T20, MatchPhase.DeathOvers),
        (MatchFormat.ODI, MatchPhase.MiddleOvers), (MatchFormat.Test, MatchPhase.MiddleOvers)
    })
    {
        var field = setter.BuildField(side, seamer, format, phase, newBall: phase == MatchPhase.Powerplay);
        var check = rules.Validate(field, format, phase);
        TestRunner.IsTrue(check.IsLegal, $"{format} {phase} field must be legal: {string.Join("; ", check.Violations)}");
        TestRunner.AreEqual(11, field.Count, "Eleven fielders");
        TestRunner.IsTrue(field.HasKeeper, "Somebody has to keep");
    }

    var powerplay = setter.BuildField(side, seamer, MatchFormat.T20, MatchPhase.Powerplay, newBall: true);
    var death = setter.BuildField(side, seamer, MatchFormat.T20, MatchPhase.DeathOvers);
    TestRunner.IsTrue(death.FieldersOutsideCircle > powerplay.FieldersOutsideCircle,
        "The field spreads once the restrictions lift - that is the whole shape of a T20 innings");

    var redBallNewBall = setter.BuildField(side, seamer, MatchFormat.Test, MatchPhase.Powerplay, newBall: true);
    TestRunner.IsTrue(redBallNewBall.CatchersBehindWicket >= 2, "A new-ball Test field is heavy on slips");
    TestRunner.IsTrue(powerplay.CatchersBehindWicket < redBallNewBall.CatchersBehindWicket,
        "A T20 powerplay carries far fewer catchers - a boundary costs more than a half-chance is worth");
});

TestRunner.Run("Specialists are put where they belong", () =>
{
    var setter = new AutoFieldSetter();
    var aptitude = new FieldingAptitudeService();
    var (side, bowlers) = MatchTestData.MakeEleven("Spec", 12, 12);

    // One outstanding slip catcher and one outstanding boundary rider.
    var safeHands = side[3];
    safeHands.Fielding.Catching = 20; safeHands.Fielding.Reflexes = 20; safeHands.Fielding.Positioning = 18;
    var flyer = side[5];
    flyer.Fielding.BoundaryFielding = 20; flyer.Fielding.Throwing = 20; flyer.Physical.Speed = 20;
    flyer.Fielding.Catching = 8; flyer.Fielding.Reflexes = 8;

    TestRunner.IsTrue(aptitude.GetAptitude(safeHands, FieldingPosition.Slip1) > aptitude.GetAptitude(flyer, FieldingPosition.Slip1),
        "The safe pair of hands is the better slip");
    TestRunner.IsTrue(aptitude.GetAptitude(flyer, FieldingPosition.DeepMidWicket) > aptitude.GetAptitude(safeHands, FieldingPosition.DeepMidWicket),
        "The athlete is the better boundary rider - these are different skills, not one 'fielding' number");

    var field = setter.BuildField(side, bowlers[0], MatchFormat.Test, MatchPhase.Powerplay, newBall: true);
    var slipMan = field.PlayerAt(FieldingPosition.Slip1);
    TestRunner.AreEqual<Guid?>(safeHands.Id, slipMan, "The captain puts his best catcher at first slip");

    TestRunner.IsTrue(aptitude.GetCatchProbability(safeHands, FieldingPosition.Slip1) > aptitude.GetCatchProbability(flyer, FieldingPosition.Slip1) + 0.1,
        "And it materially changes whether the chance is held");
});

TestRunner.Run("A slip cordon converts edges that an empty one lets through for four", () =>
{
    var effects = new FieldEffectService();
    var ids = Enumerable.Range(0, 11).Select(_ => Guid.NewGuid()).ToArray();

    FieldSetting Build(params FieldingPosition[] positions) => new()
    {
        Placements = positions.Select((p, i) => new FieldPlacement(p, ids[i])).ToList()
    };

    var attacking = Build(
        FieldingPosition.WicketKeeper, FieldingPosition.Slip1, FieldingPosition.Slip2, FieldingPosition.Slip3,
        FieldingPosition.Gully, FieldingPosition.Point, FieldingPosition.Cover, FieldingPosition.MidOff,
        FieldingPosition.MidOn, FieldingPosition.MidWicket, FieldingPosition.Bowler);

    var noCordon = Build(
        FieldingPosition.WicketKeeper, FieldingPosition.DeepThirdMan, FieldingPosition.DeepPoint,
        FieldingPosition.DeepCover, FieldingPosition.LongOff, FieldingPosition.LongOn,
        FieldingPosition.DeepMidWicket, FieldingPosition.Point, FieldingPosition.Cover,
        FieldingPosition.MidOn, FieldingPosition.Bowler);

    double withCordon = effects.EdgeCarry(attacking, MatchFormat.Test);
    double without = effects.EdgeCarry(noCordon, MatchFormat.Test);

    TestRunner.IsTrue(withCordon > without + 0.15,
        $"Three slips and a gully must hold far more edges than a bare cordon ({withCordon:P0} vs {without:P0})");
    TestRunner.IsTrue(without > 0.3, "Even with no slips the keeper still takes plenty - edges do not all run away");
    TestRunner.IsTrue(withCordon < 0.95, "And even a full cordon has gaps - some edges always beat it");

    TestRunner.IsTrue(effects.ExpectedConversion(attacking, MatchFormat.Test) > effects.ExpectedConversion(noCordon, MatchFormat.Test),
        "An attacking field converts more chances into wickets, which is the reason to set one");
});

TestRunner.Run("Boundary riders cut fours, a packed ring cuts singles, and neither is free", () =>
{
    var effects = new FieldEffectService();
    var ids = Enumerable.Range(0, 11).Select(_ => Guid.NewGuid()).ToArray();

    FieldSetting Build(params FieldingPosition[] positions) => new()
    {
        Placements = positions.Select((p, i) => new FieldPlacement(p, ids[i])).ToList()
    };

    var spread = Build(
        FieldingPosition.WicketKeeper, FieldingPosition.DeepThirdMan, FieldingPosition.DeepPoint,
        FieldingPosition.DeepCover, FieldingPosition.LongOff, FieldingPosition.LongOn,
        FieldingPosition.DeepMidWicket, FieldingPosition.DeepSquareLeg, FieldingPosition.Cover,
        FieldingPosition.MidOn, FieldingPosition.Bowler);

    var packed = Build(
        FieldingPosition.WicketKeeper, FieldingPosition.Point, FieldingPosition.BackwardPoint,
        FieldingPosition.Cover, FieldingPosition.ExtraCover, FieldingPosition.MidOff,
        FieldingPosition.MidOn, FieldingPosition.MidWicket, FieldingPosition.SquareLeg,
        FieldingPosition.FineLeg, FieldingPosition.Bowler);

    var zones = new BattingZoneStrengths();
    var spreadEffect = effects.Calculate(spread, zones, MatchFormat.T20);
    var packedEffect = effects.Calculate(packed, zones, MatchFormat.T20);

    TestRunner.IsTrue(spreadEffect.BoundaryScale < packedEffect.BoundaryScale,
        "Sweepers on the rope cut the boundary rate");
    TestRunner.IsTrue(packedEffect.SingleScale < spreadEffect.SingleScale,
        "A packed ring chokes the singles");
    TestRunner.IsTrue(packedEffect.DotScale > spreadEffect.DotScale,
        "...and forces dot balls, which is the whole mechanism of a middle-overs squeeze");
    TestRunner.IsTrue(spreadEffect.SingleScale > 1.0 && packedEffect.BoundaryScale > spreadEffect.BoundaryScale,
        "There is no free field - protecting the rope gives away singles and vice versa");
});

TestRunner.Run("Protecting a batter's strong zone is worth more than protecting a weak one", () =>
{
    var effects = new FieldEffectService();
    var ids = Enumerable.Range(0, 11).Select(_ => Guid.NewGuid()).ToArray();

    // A batter who scores heavily through midwicket and almost nowhere else.
    var legSidePlayer = new BattingZoneStrengths
    {
        [ShotZone.MidWicket] = 95,
        [ShotZone.SquareLeg] = 80,
        [ShotZone.MidOn] = 75,
        [ShotZone.Cover] = 25,
        [ShotZone.Point] = 25,
        [ShotZone.ThirdMan] = 20,
        [ShotZone.MidOff] = 30,
        [ShotZone.FineLeg] = 40
    };

    FieldSetting WithDeep(FieldingPosition deep) => new()
    {
        Placements = new List<FieldPlacement>
        {
            new(FieldingPosition.WicketKeeper, ids[0]), new(deep, ids[1]),
            new(FieldingPosition.Point, ids[2]), new(FieldingPosition.Cover, ids[3]),
            new(FieldingPosition.MidOff, ids[4]), new(FieldingPosition.MidOn, ids[5]),
            new(FieldingPosition.MidWicket, ids[6]), new(FieldingPosition.SquareLeg, ids[7]),
            new(FieldingPosition.FineLeg, ids[8]), new(FieldingPosition.ThirdMan, ids[9]),
            new(FieldingPosition.Bowler, ids[10])
        }
    };

    double rightPlace = effects.Calculate(WithDeep(FieldingPosition.DeepMidWicket), legSidePlayer, MatchFormat.T20).BoundaryScale;
    double wrongPlace = effects.Calculate(WithDeep(FieldingPosition.DeepThirdMan), legSidePlayer, MatchFormat.T20).BoundaryScale;

    TestRunner.IsTrue(rightPlace < wrongPlace,
        "A sweeper at deep midwicket against a leg-side player is worth more than one at third man - closing a batter's strong area is the most basic thing a captain does");

    // And the AI captain works that out for itself.
    var setter = new AutoFieldSetter();
    var (side, bowlers) = MatchTestData.MakeEleven("Zone", 12, 12);
    var aiField = setter.BuildField(side, bowlers[0], MatchFormat.T20, MatchPhase.DeathOvers, batterZones: legSidePlayer);
    TestRunner.IsTrue(aiField.FieldersInZone(ShotZone.MidWicket, insideCircle: false) > 0
                   || aiField.FieldersInZone(ShotZone.SquareLeg, insideCircle: false) > 0,
        "The AI captain protects the leg side against a leg-side player");
});

TestRunner.Run("Batter scoring zones are derived, individual, and drive where shots go", () =>
{
    var driver = MatchTestData.MakePlayer("Driver", 12);
    driver.Batting.Technique = 19; driver.Batting.Timing = 19; driver.Batting.ShortBallAbility = 5; driver.Batting.Aggression = 5;

    var puller = MatchTestData.MakePlayer("Puller", 12);
    puller.Batting.ShortBallAbility = 19; puller.Batting.Aggression = 19; puller.Batting.Technique = 6; puller.Batting.Timing = 6;

    var driverZones = BattingZoneStrengths.FromPlayer(driver);
    var pullerZones = BattingZoneStrengths.FromPlayer(puller);

    TestRunner.IsTrue(driverZones[ShotZone.Cover] > pullerZones[ShotZone.Cover], "The technician scores through cover");
    TestRunner.IsTrue(pullerZones[ShotZone.SquareLeg] > driverZones[ShotZone.SquareLeg], "The puller scores square on the leg side");
    TestRunner.IsTrue(driverZones.StrongestZone != pullerZones.StrongestZone, "Different players have different strong areas");

    // Shots actually follow the profile.
    var effects = new FieldEffectService();
    var random = new Random(4);
    int legSideShots = 0;
    for (int i = 0; i < 400; i++)
    {
        var zone = effects.RollZone(pullerZones, random);
        if (zone is ShotZone.MidOn or ShotZone.MidWicket or ShotZone.SquareLeg or ShotZone.FineLeg) legSideShots++;
    }
    TestRunner.IsTrue(legSideShots > 200, $"A leg-side player must actually hit more to the leg side - got {legSideShots}/400");
});

TestRunner.Run("A simulated innings uses legal fields throughout and still looks like cricket", () =>
{
    var simulator = new InningsSimulator();
    var setup = MatchTestData.Setup(13, 13, "F");

    // Averaged over seeds: a single innings can legitimately produce one wicket or ten, so
    // asserting a range on one seed tests the seed rather than the model.
    var sample = Enumerable.Range(0, 25)
        .Select(seed => simulator.Simulate(setup, MatchFormat.T20, 20,
            Guid.NewGuid(), "Batting XI", Guid.NewGuid(), "Bowling XI", new Random(seed)))
        .ToList();

    double meanRuns = sample.Average(i => i.Runs);
    double meanWickets = sample.Average(i => i.Wickets);
    TestRunner.InRange(meanRuns, 110, 230, $"Plausible mean T20 total with fields set - got {meanRuns:F0}");
    TestRunner.InRange(meanWickets, 4.0, 8.5, $"Plausible mean wickets - got {meanWickets:F1}");
    TestRunner.IsTrue(sample.Any(i => i.Wickets <= 3) && sample.Any(i => i.Wickets >= 7),
        "Innings should vary - some sides are barely troubled, others collapse");

    var innings = sample[0];

    // Catches should now be credited to actual fielders, and dropped chances mean some
    // catching opportunities produce runs instead of wickets.
    // Aggregated across the sample: a single innings can legitimately contain no catches at all
    // (all bowled and lbw), so asserting on one is testing the seed.
    var allDeliveries = sample.SelectMany(i => i.Deliveries).ToList();
    var catches = allDeliveries.Where(d => d.Outcome.Dismissal is DismissalType.Caught or DismissalType.CaughtBehind).ToList();

    TestRunner.IsTrue(catches.Count > 0, "Catches happen across a sample of innings");
    TestRunner.IsTrue(catches.All(d => d.Outcome.FielderId is not null), "Every catch is credited to a specific fielder");
});

// ---------------------------------------------------------------------------
// Individual fielders: range vs hands, boundary saving, misfields
// ---------------------------------------------------------------------------

TestRunner.Run("Range and hands are separate skills, and both exist in the real world", () =>
{
    var fielding = new FielderPerformanceService();

    var gun = MatchTestData.MakePlayer("Gun", 12);
    gun.Fielding.BoundaryFielding = 20; gun.Fielding.GroundFielding = 20;
    gun.Fielding.Positioning = 19; gun.Physical.Speed = 20; gun.Physical.Stamina = 18;
    gun.Fielding.Catching = 11; gun.Fielding.Reflexes = 11;

    var safeHands = MatchTestData.MakePlayer("SafeHands", 12);
    safeHands.Fielding.Catching = 20; safeHands.Fielding.Reflexes = 20;
    safeHands.Physical.Speed = 6; safeHands.Fielding.BoundaryFielding = 6; safeHands.Fielding.GroundFielding = 7;

    TestRunner.IsTrue(fielding.GetRange(gun, FieldingPosition.DeepMidWicket) > fielding.GetRange(safeHands, FieldingPosition.DeepMidWicket) + 15,
        "The athlete covers far more ground");
    TestRunner.IsTrue(fielding.GetHands(safeHands) > fielding.GetHands(gun) + 15,
        "The safe pair of hands is the better catcher");

    // These are genuinely different players - a model with one 'fielding' number cannot say this.
    TestRunner.IsTrue(fielding.GetRange(gun, FieldingPosition.Point) > fielding.GetRange(safeHands, FieldingPosition.Point)
                   && fielding.GetHands(gun) < fielding.GetHands(safeHands),
        "Enormous range with ordinary hands, and immobile with a safe pair, must both be expressible");
});

TestRunner.Run("An exceptional fielder takes catches nobody else reaches", () =>
{
    var fielding = new FielderPerformanceService();

    var exceptional = MatchTestData.MakePlayer("Exceptional", 12);
    foreach (var p in new[] { exceptional })
    {
        p.Fielding.Catching = 19; p.Fielding.Reflexes = 20; p.Fielding.Positioning = 19;
        p.Fielding.BoundaryFielding = 20; p.Fielding.GroundFielding = 19; p.Physical.Speed = 20;
    }

    var ordinary = MatchTestData.MakePlayer("Ordinary", 12);
    foreach (var pi in new[] { ordinary })
    {
        pi.Fielding.Catching = 10; pi.Fielding.Reflexes = 10; pi.Fielding.Positioning = 10;
        pi.Fielding.BoundaryFielding = 9; pi.Fielding.GroundFielding = 10; pi.Physical.Speed = 10;
    }

    int Held(Player p, double difficulty, int seed)
    {
        var random = new Random(seed);
        int held = 0;
        for (int i = 0; i < 3000; i++)
            if (fielding.ResolveCatchChance(p, FieldingPosition.Point, new FieldingChance(ShotZone.Point, difficulty, true), random).Held)
                held++;
        return held;
    }

    int eliteRoutine = Held(exceptional, 0.12, 1);
    int ordinaryRoutine = Held(ordinary, 0.12, 1);
    int eliteHard = Held(exceptional, 0.88, 2);
    int ordinaryHard = Held(ordinary, 0.88, 2);

    TestRunner.IsTrue(ordinaryRoutine > 3000 * 0.7, "A regulation chance is taken by almost anyone - the worst fielders still catch dollies");
    TestRunner.IsTrue(eliteRoutine > ordinaryRoutine, "But the elite fielder is still better even on the easy ones");

    // The gap lives in the hard tail. This IS the 'impossible catch': impossible for everyone else.
    TestRunner.IsTrue(eliteHard > ordinaryHard * 2,
        $"On very hard chances the exceptional fielder must be far ahead - {eliteHard} vs {ordinaryHard} of 3000");

    TestRunner.IsTrue(eliteRoutine < 3000, "Even a world-class fielder shells a routine chance occasionally - a model where the elite never err reads as fake");
    TestRunner.IsTrue(ordinaryHard > 0, "And even a poor fielder holds one now and then");
});

TestRunner.Run("A great outfielder saves boundaries; a poor one waves them through", () =>
{
    var fielding = new FielderPerformanceService();

    var flyer = MatchTestData.MakePlayer("Flyer", 12);
    flyer.Physical.Speed = 20; flyer.Fielding.BoundaryFielding = 20;
    flyer.Fielding.GroundFielding = 19; flyer.Fielding.Throwing = 19; flyer.Fielding.Positioning = 18;

    var plodder = MatchTestData.MakePlayer("Plodder", 12);
    plodder.Physical.Speed = 6; plodder.Fielding.BoundaryFielding = 6;
    plodder.Fielding.GroundFielding = 7; plodder.Fielding.Throwing = 7; plodder.Fielding.Positioning = 7;

    int RunsConceded(Player p, double power, int seed)
    {
        var random = new Random(seed);
        int total = 0;
        for (int i = 0; i < 2000; i++)
            total += fielding.ResolveBoundaryAttempt(p, FieldingPosition.DeepMidWicket, power, random).RunsConceded;
        return total;
    }

    int flyerRuns = RunsConceded(flyer, 0.4, 3);
    int plodderRuns = RunsConceded(plodder, 0.4, 3);

    TestRunner.IsTrue(flyerRuns < plodderRuns,
        $"The athlete concedes fewer runs on the boundary - {flyerRuns} vs {plodderRuns} over 2000 shots");
    TestRunner.IsTrue((plodderRuns - flyerRuns) / 2000.0 > 0.25,
        "The difference must be worth real runs per shot, not a rounding error - this is where a great fielder earns his place");

    // Nobody chases down a flat six.
    TestRunner.IsTrue(RunsConceded(flyer, 1.0, 4) > RunsConceded(flyer, 0.2, 4),
        "A powerfully struck shot beats even the best fielder more often");
});

TestRunner.Run("Misfields are the quiet cost of a poor fielding side", () =>
{
    var fielding = new FielderPerformanceService();

    var clean = MatchTestData.MakePlayer("Clean", 12);
    clean.Fielding.GroundFielding = 19; clean.Fielding.Positioning = 18;
    var sloppy = MatchTestData.MakePlayer("Sloppy", 12);
    sloppy.Fielding.GroundFielding = 6; sloppy.Fielding.Positioning = 6;

    TestRunner.IsTrue(fielding.GetMisfieldProbability(sloppy) > fielding.GetMisfieldProbability(clean) * 2,
        "A sloppy fielder fumbles far more often");
    TestRunner.IsTrue(fielding.GetMisfieldProbability(clean) > 0,
        "Even a good fielder fumbles occasionally");

    // Over an innings this is worth real runs without a single memorable moment.
    var random = new Random(6);
    int extras = 0;
    for (int i = 0; i < 240; i++) // roughly a limited-overs innings of fielded balls
        if (fielding.ResolveGroundFielding(sloppy, FieldingPosition.Cover, 1, random).Misfield) extras++;
    TestRunner.IsTrue(extras >= 5, $"A sloppy side should leak a meaningful number of extra runs across an innings - got {extras}");
});

TestRunner.Run("Fielding quality changes match outcomes, not just individual moments", () =>
{
    var simulator = new InningsSimulator();

    (List<Player> Batting, List<Player> Bowling) MakeSides(int fieldingLevel)
    {
        var (batting, _) = MatchTestData.MakeEleven("Bat", 13, 13);
        var (fielding, bowlers) = MatchTestData.MakeEleven("Field", 13, 13);
        foreach (var p in fielding)
        {
            p.Fielding.Catching = fieldingLevel; p.Fielding.Reflexes = fieldingLevel;
            p.Fielding.GroundFielding = fieldingLevel; p.Fielding.BoundaryFielding = fieldingLevel;
            p.Fielding.Positioning = fieldingLevel; p.Fielding.Throwing = fieldingLevel;
            p.Physical.Speed = fieldingLevel;
        }
        return (batting, bowlers);
    }

    double MeanRuns(int fieldingLevel)
    {
        double total = 0;
        for (int seed = 0; seed < 30; seed++)
        {
            var (batting, bowlers) = MakeSides(fieldingLevel);
            var fieldingSide = MatchTestData.MakeEleven("Field", 13, 13).BattingOrder;
            foreach (var p in fieldingSide)
            {
                p.Fielding.Catching = fieldingLevel; p.Fielding.Reflexes = fieldingLevel;
                p.Fielding.GroundFielding = fieldingLevel; p.Fielding.BoundaryFielding = fieldingLevel;
                p.Fielding.Positioning = fieldingLevel; p.Fielding.Throwing = fieldingLevel;
                p.Physical.Speed = fieldingLevel;
            }
            var setup = new InningsSetup(batting, fieldingSide, bowlers);
            total += simulator.Simulate(setup, MatchFormat.T20, 20,
                Guid.NewGuid(), "Bat", Guid.NewGuid(), "Field", new Random(seed)).Runs;
        }
        return total / 30;
    }

    double vsBrilliant = MeanRuns(19);
    double vsPoor = MeanRuns(6);

    TestRunner.IsTrue(vsPoor > vsBrilliant,
        $"A poor fielding side must concede more than a brilliant one - {vsPoor:F0} vs {vsBrilliant:F0}");
    TestRunner.IsTrue(vsPoor - vsBrilliant > 5,
        $"And the gap should be worth real runs over an innings - got {vsPoor - vsBrilliant:F0}");
});

TestRunner.Run("Advancing the same save twice produces the same world", () =>
{
    // A career simulation that cannot be reproduced from a save cannot be debugged, and a save
    // that yields a different world each time it is loaded is not really a save. The rollover
    // previously seeded itself from HashCode.Combine, which .NET randomises per process - so the
    // same save aged and retired different players on different runs.
    List<string> RunWorld()
    {
        var seeder = new WorldSeeder(seed: 77, worldStartDate: new DateOnly(2026, 6, 1));
        var (teams, players) = seeder.GenerateStarterWorld(teamCount: 3, squadSize: 13);
        var calendar = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 12345);
        var world = new WorldState
        {
            Teams = teams.ToDictionary(t => t.Id),
            Grounds = new Dictionary<Guid, Ground>(),
            Players = players.ToList(),
            Projects = new List<InfrastructureProject>()
        };

        new WorldClockService().AdvanceTo(calendar, world, new DateOnly(2034, 6, 1));

        return players.OrderBy(p => p.FullName)
            .Select(p => $"{p.FullName}|{p.CurrentAbility}|{p.IsRetired}|{p.RetirementDate}")
            .ToList();
    }

    var first = RunWorld();
    var second = RunWorld();

    TestRunner.IsTrue(first.SequenceEqual(second),
        "Eight years of ageing and retirement must be identical for the same world seed");

    // A different seed must genuinely give a different world, or the seed is being ignored.
    var seeder3 = new WorldSeeder(seed: 77, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams3, players3) = seeder3.GenerateStarterWorld(teamCount: 3, squadSize: 13);
    var calendar3 = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 999);
    var world3 = new WorldState
    {
        Teams = teams3.ToDictionary(t => t.Id),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = players3.ToList(),
        Projects = new List<InfrastructureProject>()
    };
    new WorldClockService().AdvanceTo(calendar3, world3, new DateOnly(2034, 6, 1));

    var third = players3.OrderBy(p => p.FullName)
        .Select(p => $"{p.FullName}|{p.CurrentAbility}|{p.IsRetired}|{p.RetirementDate}").ToList();

    TestRunner.IsTrue(!first.SequenceEqual(third), "A different world seed must produce a different world");
});

