TestRunner.Run("A reported collapse always corresponds to a real run of 3 wickets in 24 balls, with a non-negative run count", () =>
{
    var sim = new InningsSimulator();
    var analysis = new PostMatchAnalysisService();
    int collapsesFound = 0;

    for (int i = 0; i < 40; i++)
    {
        // Weak batting, strong bowling - collapses should be common enough to sample.
        var batting = MatchTestData.Setup(4, 4, "A");
        var bowling = MatchTestData.Setup(4, 17, "B");
        var setup = new InningsSetup(batting.BattingOrder, bowling.FieldingSide, bowling.AvailableBowlers);
        var innings = sim.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "A", Guid.NewGuid(), "B", new Random(i + 5000));

        // Build a MatchResult around this single innings just to exercise AnalyzeMatch's real path -
        // the second innings is irrelevant to this test, so it reuses the same simulated innings.
        var fakeResult = new MatchResult
        {
            MatchId = Guid.NewGuid(),
            Setup = new MatchSetup
            {
                Home = new MatchSide(Guid.NewGuid(), "A", batting.BattingOrder, batting.AvailableBowlers),
                Away = new MatchSide(Guid.NewGuid(), "B", bowling.BattingOrder, bowling.AvailableBowlers),
                Format = MatchFormat.T20
            },
            FirstInnings = innings,
            SecondInnings = innings,
            Summary = "Test fixture"
        };

        var report = analysis.AnalyzeMatch(fakeResult);
        var collapseMoments = report.KeyMoments.Where(m => m.Description.Contains("collapse")).ToList();

        // Independently re-derive whether a qualifying window exists, straight from FallOfWickets,
        // without going through the service's private detection method.
        var fow = innings.FallOfWickets;
        bool realCollapseExists = false;
        for (int w = 0; w + 2 < fow.Count; w++)
            if (fow[w + 2].BallNumber - fow[w].BallNumber <= 24) { realCollapseExists = true; break; }

        TestRunner.AreEqual(realCollapseExists, collapseMoments.Count > 0,
            $"Seed {i}: collapse reported = {collapseMoments.Count > 0}, but a qualifying window actually exists = {realCollapseExists}");

        if (collapseMoments.Count > 0) collapsesFound++;
    }

    TestRunner.IsTrue(collapsesFound > 0, "Weak batting against strong bowling should produce at least some genuine collapses across 40 seeds");
});

TestRunner.Run("Player of the match credits an all-rounder's combined game, not just his better discipline", () =>
{
    var matchSim = new MatchSimulator();
    var analysis = new PostMatchAnalysisService();
    int combinedCasesChecked = 0;

    for (int i = 0; i < 25; i++)
    {
        var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 15, 14);
        var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 8, 8);
        int homeArIndex = homeOrder.FindIndex(p => p.FirstName.EndsWith("AR"));
        (homeOrder[2], homeOrder[homeArIndex]) = (homeOrder[homeArIndex], homeOrder[2]);
        int awayArIndex = awayOrder.FindIndex(p => p.FirstName.EndsWith("AR"));
        (awayOrder[2], awayOrder[awayArIndex]) = (awayOrder[awayArIndex], awayOrder[2]);
        var setup = new MatchSetup
        {
            Home = new MatchSide(Guid.NewGuid(), "Home", homeOrder, homeBowlers),
            Away = new MatchSide(Guid.NewGuid(), "Away", awayOrder, awayBowlers),
            Format = MatchFormat.T20,
            OversPerInnings = 20
        };
        var match = matchSim.Simulate(setup, new Random(i + 7000));
        var report = analysis.AnalyzeMatch(match);
        var pom = report.PlayerOfTheMatch!;

        bool batted = new[] { match.FirstInnings, match.SecondInnings }
            .SelectMany(inn => inn.BatterCards)
            .Any(c => c.PlayerId == pom.PlayerId && c.HasBatted);
        bool bowled = new[] { match.FirstInnings, match.SecondInnings }
            .SelectMany(inn => inn.BowlerCards)
            .Any(c => c.PlayerId == pom.PlayerId && c.LegalBallsBowled > 0);

        // The " and " join only appears in the description when both a batting AND a bowling
        // contribution were actually folded into the combined rating - never one without the other.
        bool descriptionClaimsBoth = pom.Description.Contains(" and ");
        TestRunner.AreEqual(batted && bowled, descriptionClaimsBoth,
            $"Seed {i}: description claims both disciplines = {descriptionClaimsBoth}, but batted={batted} bowled={bowled}");

        if (descriptionClaimsBoth) combinedCasesChecked++;
    }

    TestRunner.IsTrue(combinedCasesChecked > 0, "Across 25 matches with all-rounders on both sides, some player of the match should have contributed with both bat and ball");
});

