TestRunner.Run("Partnership records label wicket numbers correctly, including the +1 for an unbroken final stand", () =>
{
    var simulator = new MatchSimulator();
    var recorder = new MatchRecorder();

    for (int i = 0; i < 20; i++)
    {
        var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 13, 10);
        var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 10, 13);
        var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);
        var setup = new MatchSetup
        {
            Home = new MatchSide(Guid.NewGuid(), "Home", homeOrder, homeBowlers),
            Away = new MatchSide(Guid.NewGuid(), "Away", awayOrder, awayBowlers),
            Format = MatchFormat.T20,
            OversPerInnings = 20
        };
        var match = simulator.Simulate(setup, new Random(i));
        var records = recorder.Record(match, allPlayers);

        foreach (var innings in new[] { match.FirstInnings, match.SecondInnings })
        {
            var forThisInnings = records.Partnerships
                .Where(p => p.MatchId == match.MatchId && p.InningsNumber == innings.InningsNumber)
                .ToList();

            TestRunner.AreEqual(innings.Partnerships.Count, forThisInnings.Count, "One persisted record per live partnership");

            // Partnerships close strictly in wicket-fall order, so the persisted sequence must be
            // 1st, 2nd, 3rd... with no gaps and no repeats - the direct, deterministic check for
            // the off-by-one this conversion has to get right.
            for (int w = 0; w < forThisInnings.Count; w++)
                TestRunner.AreEqual(w + 1, forThisInnings[w].WicketNumber, $"Partnership index {w} should be labelled the {w + 1}th wicket stand");

            // BUG FIX (found via this test, on a seed where the final wicket fell on the innings'
            // literal last ball): "unbroken exactly when not all out" is FALSE in that specific
            // case - fewer than ten down reads as "not all out", but the last stand was still
            // genuinely closed by a real, counted dismissal. The correct invariant is arithmetic:
            // InningsState only ever produces one MORE partnership than wickets fell when the
            // final pair was truly still batting when the innings ended unseparated.
            var last = forThisInnings.LastOrDefault();
            if (last is not null)
                TestRunner.AreEqual(innings.Partnerships.Count > innings.FallOfWickets.Count, last.Unbroken,
                    "The last stand is unbroken exactly when it was never closed by a counted wicket");
        }
    }
});

TestRunner.Run("PartnershipRecordsService finds the right record, filtered by wicket number, ground and pair", () =>
{
    var service = new PartnershipRecordsService();
    var groundA = Guid.NewGuid();
    var groundB = Guid.NewGuid();
    var playerX = Guid.NewGuid();
    var playerY = Guid.NewGuid();
    var playerZ = Guid.NewGuid();

    PartnershipRecord Make(Guid ground, int wicket, Guid a, Guid b, int runs, int balls) => new()
    {
        MatchId = Guid.NewGuid(),
        MatchDate = new DateOnly(2026, 1, 1),
        GroundId = ground,
        GroundName = ground == groundA ? "Ground A" : "Ground B",
        BattingTeamId = Guid.NewGuid(),
        BattingTeamName = "Team",
        BowlingTeamId = Guid.NewGuid(),
        BowlingTeamName = "Opponent",
        Format = MatchFormat.T20,
        Season = 2026,
        InningsNumber = 1,
        WicketNumber = wicket,
        BatterAId = a,
        BatterAName = "A",
        BatterBId = b,
        BatterBName = "B",
        Runs = runs,
        Balls = balls
    };

    var records = new List<PartnershipRecord>
    {
        Make(groundA, 1, playerX, playerY, 120, 80),
        Make(groundA, 1, playerX, playerZ, 60, 40),
        Make(groundB, 1, playerY, playerZ, 200, 100), // highest overall, but at a different ground
        Make(groundA, 2, playerY, playerZ, 90, 60)
    };

    var overall = service.GetHighestPartnership(records, wicketNumber: 1);
    TestRunner.AreEqual(200, overall!.Runs, "The best 1st-wicket stand across all grounds is the 200 at ground B");

    var atGroundA = service.GetHighestPartnershipAtGround(records, groundA, wicketNumber: 1);
    TestRunner.AreEqual(120, atGroundA!.Runs, "Restricted to ground A, the 200 at ground B doesn't count");

    var betweenXY = service.GetHighestPartnershipBetween(records, playerX, playerY);
    TestRunner.AreEqual(120, betweenXY!.Runs, "X and Y's best stand together");

    var betweenYX = service.GetHighestPartnershipBetween(records, playerY, playerX);
    TestRunner.AreEqual(120, betweenYX!.Runs, "Same pair, arguments reversed - still finds it");

    var leadingSecondWicket = service.GetLeadingPartnerships(records, wicketNumber: 2);
    TestRunner.AreEqual(1, leadingSecondWicket.Count, "Only one 2nd-wicket stand exists in this data");
    TestRunner.AreEqual(90, leadingSecondWicket[0].Runs);

    var noData = service.GetHighestPartnership(records, wicketNumber: 5);
    TestRunner.IsTrue(noData is null, "No 5th-wicket data at all - null, not a fabricated zero");
});

TestRunner.Run("First-class batting and bowling bonus points follow the Ranji-style tiers exactly", () =>
{
    var bonus = new BonusPointsService();

    static InningsState SyntheticInnings(int runsInFirst100Overs, int wicketsInFirst100Overs)
    {
        var state = new InningsState
        {
            BattingTeamId = Guid.NewGuid(),
            BattingTeamName = "A",
            BowlingTeamId = Guid.NewGuid(),
            BowlingTeamName = "B",
            Format = MatchFormat.Test
        };
        int score = 0, wickets = 0;
        int wicketInterval = 600 / Math.Max(1, wicketsInFirst100Overs);

        for (int ball = 1; ball <= 600; ball++)
        {
            bool wicketBall = wicketsInFirst100Overs > 0 && wickets < wicketsInFirst100Overs && ball % wicketInterval == 0;
            DeliveryOutcome outcome;
            if (wicketBall)
            {
                outcome = DeliveryOutcome.Wicket(DismissalType.Bowled);
                wickets++;
            }
            else
            {
                int runs = Math.Min(4, Math.Max(0, runsInFirst100Overs - score));
                outcome = runs > 0 ? DeliveryOutcome.Runs(runs) : DeliveryOutcome.Dot();
                score += runs;
            }

            state.Deliveries.Add(new DeliveryRecord(ball, (ball - 1) / 6 + 1, (ball - 1) % 6 + 1,
                Guid.NewGuid(), Guid.NewGuid(), MatchPhase.MiddleOvers, outcome, score, wickets));
        }
        return state;
    }

    var battingCases = new (int Runs, int Expected)[] { (240, 0), (250, 1), (299, 1), (300, 2), (349, 2), (350, 3), (399, 3), (400, 4), (450, 4) };
    foreach (var (runs, expected) in battingCases)
        TestRunner.AreEqual(expected, bonus.BattingBonusPoints(SyntheticInnings(runs, 0)),
            $"{runs} runs in the first 100 overs should earn {expected} batting bonus point(s)");

    var bowlingCases = new (int Wickets, int Expected)[] { (2, 0), (3, 1), (4, 1), (5, 2), (6, 2), (7, 3), (8, 3), (9, 4), (10, 4) };
    foreach (var (wickets, expected) in bowlingCases)
        TestRunner.AreEqual(expected, bonus.BowlingBonusPoints(SyntheticInnings(200, wickets)),
            $"{wickets} wickets in the first 100 overs should earn {expected} bowling bonus point(s)");
});

