TestRunner.Run("The limited-overs margin bonus computes correctly and leaves today's standings unaffected unless a competition opts in", () =>
{
    var bonus = new BonusPointsService();
    var simulator = new MatchSimulator();
    var recorder = new MatchRecorder();

    for (int i = 0; i < 15; i++)
    {
        var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 16, 6);
        var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 6, 6);
        var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);
        var homeId = Guid.NewGuid(); var awayId = Guid.NewGuid();
        var setup = new MatchSetup
        {
            Home = new MatchSide(homeId, "Home", homeOrder, homeBowlers),
            Away = new MatchSide(awayId, "Away", awayOrder, awayBowlers),
            Format = MatchFormat.T20,
            OversPerInnings = 20
        };
        var match = simulator.Simulate(setup, new Random(i + 9000));

        if (match.WinningTeamId is { } winnerId)
        {
            var loserId = winnerId == homeId ? awayId : homeId;
            TestRunner.AreEqual(0, bonus.LimitedOversMarginBonus(match, loserId), "The losing side never earns a margin bonus");

            int winnerBonus = bonus.LimitedOversMarginBonus(match, winnerId);
            TestRunner.IsTrue(winnerBonus is 0 or 1, "The margin bonus is always 0 or 1");

            if (match.WonByWickets && match.WinMargin >= 8)
                TestRunner.AreEqual(1, winnerBonus, $"Won by {match.WinMargin} wickets should earn the bonus");
            if (!match.WonByWickets && match.WinMargin >= 40)
                TestRunner.AreEqual(1, winnerBonus, $"Won by {match.WinMargin} runs should earn the bonus");
        }

        // Regression check: default recording still splits exactly 2 points total, same as before this slice.
        var season = new CompetitionSeason { Year = 2026 };
        recorder.Record(match, allPlayers, season);
        double totalPoints = season.Standings.Sum(s => s.Points);
        TestRunner.AreEqual(2, totalPoints, "Default recording is unaffected - the margin bonus stays off unless a competition opts in");
    }
});

