TestRunner.Run("Standings after a multi-day match are symmetric between home and away, for every possible result", () =>
{
    var simulator = new MultiDayMatchSimulator();
    var recorder = new MultiDayMatchRecorder();
    var outcomesSeen = new HashSet<MatchOutcome>();

    for (int i = 0; i < 40; i++)
    {
        var setup = MultiDaySetup(days: 3); // shorter matches produce more draws/results variety
        var allPlayers = setup.Home.All.Concat(setup.Away.All).ToDictionary(p => p.Id);
        var homeId = setup.Home.TeamId; var awayId = setup.Away.TeamId;

        var match = simulator.Simulate(setup, new Random(i + 11000));
        var season = new CompetitionSeason { Year = 2026 };
        recorder.Record(match, allPlayers, season);

        var homeStanding = season.Standings.First(s => s.TeamId == homeId);
        var awayStanding = season.Standings.First(s => s.TeamId == awayId);

        TestRunner.AreEqual(1, homeStanding.Played);
        TestRunner.AreEqual(1, awayStanding.Played);
        outcomesSeen.Add(match.ResultForHome);

        switch (match.ResultForHome)
        {
            case MatchOutcome.Win:
                TestRunner.AreEqual(1, homeStanding.Won); TestRunner.AreEqual(1, awayStanding.Lost);
                break;
            case MatchOutcome.Loss:
                TestRunner.AreEqual(1, homeStanding.Lost); TestRunner.AreEqual(1, awayStanding.Won);
                break;
            case MatchOutcome.Draw:
                TestRunner.AreEqual(1, homeStanding.Drawn); TestRunner.AreEqual(1, awayStanding.Drawn);
                break;
        }

        // FirstClass base points (bonus points are separate and can only add, never subtract) -
        // whatever the base result points were, actual points must be at least that much.
        int baseHome = match.ResultForHome switch
        {
            MatchOutcome.Win => 12,
            MatchOutcome.Loss => 0,
            MatchOutcome.Draw => 4,
            MatchOutcome.Tie => 6,
            _ => 4
        };
        TestRunner.IsTrue(homeStanding.Points >= baseHome, "Actual points can only be the base result points plus bonus, never less");

        // Multi-day standings are points-based, not NRR-based - NRR must stay at its untouched default.
        TestRunner.AreEqual(0.0, homeStanding.NetRunRate, "No NRR update for a multi-day match - it stays at its 'no data' default, not a fabricated value");
    }

    TestRunner.IsTrue(outcomesSeen.Count >= 2, $"Three-day matches at this skill level should produce more than one kind of result across 40 seeds - saw {outcomesSeen.Count}");
});

TestRunner.Run("First-class bonus points are credited from each side's own first innings, and can be switched off", () =>
{
    var simulator = new MultiDayMatchSimulator();
