        bool firstBattingIsHome = match.Innings[0].BattingTeamId == homeId;
        var homeFirstInnings = firstBattingIsHome ? match.Innings[0] : match.Innings[1];
        var awayFirstInnings = firstBattingIsHome ? match.Innings[1] : match.Innings[0];
        int expectedHomeBonus = bonus.BattingBonusPoints(homeFirstInnings) + bonus.BowlingBonusPoints(awayFirstInnings);

        var withBonus = new CompetitionSeason { Year = 2026 };
        recorder.Record(match, allPlayers, withBonus);
        var homeWithBonus = withBonus.Standings.First(s => s.TeamId == homeId);

        int baseHome = match.ResultForHome switch
        {
            MatchOutcome.Win => 12,
            MatchOutcome.Loss => 0,
            MatchOutcome.Draw => 4,
            MatchOutcome.Tie => 6,
            _ => 4
        };
        TestRunner.AreEqual(baseHome + expectedHomeBonus, homeWithBonus.Points,
            $"Seed {i}: points should be exactly base ({baseHome}) plus the independently recomputed bonus ({expectedHomeBonus})");


        var withoutBonus = new CompetitionSeason { Year = 2026 };
        recorder.Record(withoutBonusMatch, allPlayers, withoutBonus);
        var homeWithoutBonus = withoutBonus.Standings.First(s => s.TeamId == homeId);

        TestRunner.AreEqual(baseHome, homeWithoutBonus.Points, "With the flag off, only the base result points are awarded - no bonus at all");
    }
});

TestRunner.Run("Recording a multi-day match brings career effects and injuries to life, same as a limited-overs one", () =>
{
    var simulator = new MultiDayMatchSimulator();
    var recorder = new MultiDayMatchRecorder();

    var setup = MultiDaySetup();
    var allPlayers = setup.Home.All.Concat(setup.Away.All).ToDictionary(p => p.Id);
    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team>(),
        Grounds = new Dictionary<Guid, Ground> { [setup.Ground!.Id] = setup.Ground },
        Players = allPlayers.Values.ToList(),
        Projects = new List<InfrastructureProject>()
    };

    var match = simulator.Simulate(setup, new Random(777));
    var records = recorder.Record(match, allPlayers, world: world, random: new Random(777));

    var topScorer = records.Batting.OrderByDescending(r => r.Runs).First();
    var scorer = allPlayers[topScorer.PlayerId];
    TestRunner.IsTrue(scorer.Experience.TotalMatches > 0, "Appearances counted towards experience");
    TestRunner.IsTrue(scorer.Form.RecentPerformanceRatings.Count > 0, "Form consumed the performance");
    TestRunner.IsTrue(world.MatchesThisSeason.Count > 0, "Playing time logged for the retirement loop");
});

TestRunner.Run("MatchRecorder.RecordInnings values a batting side against the attack it actually faced, not its own bowlers (tech-debt item 11)", () =>
{
    var simulator = new MatchSimulator();
    var recorder = new MatchRecorder();

    // Built directly with MakePlayer (not MakeEleven) so CurrentAbility is actually tied to
    // the bowling level: MakeEleven's specialists are built at a reduced overall level and
    // then have only their Bowling.* attributes overwritten to the target bowling level,
    // which decouples CurrentAbility from true bowling skill - unusable for isolating what
    // EstimateBowlingStrength (which reads CurrentAbility) actually keys off.
    var homeOrder = new List<Player>();
    for (int i = 1; i <= 8; i++) homeOrder.Add(MatchTestData.MakePlayer($"HomeBat{i}", 13));
    var homeBowlers = new List<Player>();
    for (int i = 1; i <= 3; i++)
    {
        var b = MatchTestData.MakePlayer($"HomeBowl{i}", 4, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        homeOrder.Add(b);
        homeBowlers.Add(b);
    }

    var awayOrder = new List<Player>();
    for (int i = 1; i <= 8; i++) awayOrder.Add(MatchTestData.MakePlayer($"AwayBat{i}", 13));
    var awayBowlers = new List<Player>();
    for (int i = 1; i <= 3; i++)
    {
        var b = MatchTestData.MakePlayer($"AwayBowl{i}", 19, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        awayOrder.Add(b);
        awayBowlers.Add(b);
    }

    var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);
    var homeIds = homeOrder.Select(p => p.Id).ToHashSet();

    var setup = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "RegHome", homeOrder, homeBowlers),
        Away = new MatchSide(Guid.NewGuid(), "RegAway", awayOrder, awayBowlers),
        Format = MatchFormat.T20,
        OversPerInnings = 20,
        MatchDate = new DateOnly(2026, 7, 4),
        Season = 2026
    };

    var match = simulator.Simulate(setup, new Random(11));
    var records = recorder.Record(match, allPlayers, random: new Random(11));

    TestRunner.IsTrue(records.Batting.Count > 0, "Sanity: the match produced batting records at all");

    foreach (var b in records.Batting)
    {
        bool isHomeBatter = homeIds.Contains(b.PlayerId);
        // Home's bowlers are weak (CurrentAbility 40 -> ~20 on the 0-100 scale), Away's are
        // elite (190 -> ~95). A Home batter must be valued against Away's attack (~95), and
        // an Away batter against Home's (~20) - never their own side's bowlers.
        double expected = isHomeBatter ? 95.0 : 20.0;
        TestRunner.AreEqual(expected, b.Context.OppositionStrength,
            $"{(isHomeBatter ? "Home" : "Away")} batter must be valued against the OPPOSING attack, not his own team's bowlers");
    }
});

