TestRunner.Run("Round-robin pairs every team with every other exactly once, keeps home/away within one match of even, and never repeats a team within a round", () =>
{
    var svc = new FixtureGenerationService();
    var teamIds = Enumerable.Range(0, 6).Select(_ => Guid.NewGuid()).ToList();
    var pairings = svc.GenerateRoundRobinPairings(teamIds, doubleRoundRobin: false);

    TestRunner.AreEqual(15, pairings.Count, "6 teams -> C(6,2) = 15 fixtures in a single round-robin");

    var seenPairs = new HashSet<(Guid, Guid)>();
    foreach (var (home, away, _) in pairings)
    {
        var key = home.CompareTo(away) < 0 ? (home, away) : (away, home);
        TestRunner.IsTrue(seenPairs.Add(key), "Every pair must meet exactly once");
    }

    foreach (var roundGroup in pairings.GroupBy(p => p.Round))
    {
        var teamsThisRound = roundGroup.SelectMany(p => new[] { p.Home, p.Away }).ToList();
        TestRunner.AreEqual(teamsThisRound.Count, teamsThisRound.Distinct().Count(), "No team appears twice in the same round");
    }

    var matchesPerTeam = teamIds.ToDictionary(t => t, t => pairings.Count(p => p.Home == t || p.Away == t));
    TestRunner.IsTrue(matchesPerTeam.Values.All(c => c == 5), "Every team plays n-1 = 5 matches");

    // 5 rounds is odd, so a perfectly even split is impossible - within one match is the best any team can get.
    foreach (var team in teamIds)
    {
        int home = pairings.Count(p => p.Home == team);
        int away = pairings.Count(p => p.Away == team);
        TestRunner.IsTrue(Math.Abs(home - away) <= 1, $"Home/away must be within one match of even, was {home}-{away}");
    }
});

TestRunner.Run("An odd number of teams gets a bye each round via a phantom seat, and every real pair still meets exactly once", () =>
{
    var svc = new FixtureGenerationService();
    var teamIds = Enumerable.Range(0, 5).Select(_ => Guid.NewGuid()).ToList();
    var pairings = svc.GenerateRoundRobinPairings(teamIds, doubleRoundRobin: false);

    TestRunner.AreEqual(10, pairings.Count, "5 teams -> C(5,2) = 10 fixtures");
    var matchesPerTeam = teamIds.ToDictionary(t => t, t => pairings.Count(p => p.Home == t || p.Away == t));
    TestRunner.IsTrue(matchesPerTeam.Values.All(c => c == 4), "Every team plays n-1 = 4 matches despite the bye");

    int totalRounds = pairings.Max(p => p.Round);
    TestRunner.AreEqual(5, totalRounds, "Padding to 6 phantom seats gives 5 rounds, same as n=6");
    foreach (var round in Enumerable.Range(1, totalRounds))
    {
        var teamsThisRound = pairings.Where(p => p.Round == round).SelectMany(p => new[] { p.Home, p.Away }).ToList();
        TestRunner.AreEqual(4, teamsThisRound.Count, "One team sits out (the bye) each round, so only 4 of 5 play");
    }
});

TestRunner.Run("Double round-robin plays every pair twice, with the second leg's home/away exactly mirroring the first", () =>
{
    var svc = new FixtureGenerationService();
    var teamIds = Enumerable.Range(0, 4).Select(_ => Guid.NewGuid()).ToList();
    var pairings = svc.GenerateRoundRobinPairings(teamIds, doubleRoundRobin: true);

    TestRunner.AreEqual(12, pairings.Count, "4 teams, double round-robin -> 2 * C(4,2) = 12 fixtures");

    int roundsInSingleLeg = pairings.Where(p => p.Round <= 3).Select(p => p.Round).Distinct().Count();
    TestRunner.AreEqual(3, roundsInSingleLeg);

    var firstLeg = pairings.Where(p => p.Round <= 3).ToHashSet();
    foreach (var (home, away, round) in pairings.Where(p => p.Round > 3))
        TestRunner.IsTrue(firstLeg.Any(p => p.Home == away && p.Away == home), "Second leg must mirror a first-leg fixture with home/away reversed");
});

TestRunner.Run("ScheduleRoundRobin dates fixtures inside the season window, grounds each match at the home team's own ground, and respects the format's minimum rest days", () =>
{
    var genSvc = new FixtureGenerationService();
    var teams = new List<Team>();
    for (int i = 0; i < 6; i++)
    {
        var ground = new Ground { Name = $"Ground{i}", City = "City", Country = "Pakistan" };
        teams.Add(new Team { Name = $"Team{i}", Country = "Pakistan", HomeGroundId = ground.Id });
    }
    var teamDict = teams.ToDictionary(t => t.Id);
    var teamIds = teams.Select(t => t.Id).ToList();

    var pairings = genSvc.GenerateRoundRobinPairings(teamIds, doubleRoundRobin: false);
    var windowStart = new DateOnly(2026, 4, 1);
    var windowEnd = new DateOnly(2026, 9, 30);
    var fixtures = genSvc.ScheduleRoundRobin(Guid.NewGuid(), Guid.NewGuid(), pairings, windowStart, windowEnd, MatchFormat.T20, teamDict);

    TestRunner.AreEqual(pairings.Count, fixtures.Count);
    TestRunner.IsTrue(fixtures.All(f => f.ScheduledDate >= windowStart), "No fixture scheduled before the window starts");

    foreach (var f in fixtures)
    {
        var homeTeam = teamDict[f.HomeTeamId!.Value];
        TestRunner.AreEqual(homeTeam.HomeGroundId, f.GroundId, "Fixture is hosted at the home team's own ground");
    }

    int minRest = FixtureGenerationService.MinimumRestDays(MatchFormat.T20);
    foreach (var teamId in teamIds)
    {
        var dates = fixtures.Where(f => f.HomeTeamId == teamId || f.AwayTeamId == teamId)
            .Select(f => f.ScheduledDate).OrderBy(d => d).ToList();
        for (int i = 1; i < dates.Count; i++)
        {
            int gap = dates[i].DayNumber - dates[i - 1].DayNumber;
            TestRunner.IsTrue(gap >= minRest, $"Gap between a team's matches must be at least the format minimum ({minRest} days), was {gap}");
        }
    }
});

TestRunner.Run("SplitIntoGroups uses a snake draft so seeded strength is spread across groups, not stacked", () =>
{
    var svc = new FixtureGenerationService();
    var seeded = Enumerable.Range(1, 8).Select(_ => Guid.NewGuid()).ToList(); // seed 1 (strongest) .. seed 8
    var groups = svc.SplitIntoGroups(seeded, 2);

    TestRunner.AreEqual(2, groups.Count);
    TestRunner.IsTrue(groups.All(g => g.Count == 4), "8 teams into 2 groups of 4");
    TestRunner.AreEqual(8, groups.SelectMany(g => g).Distinct().Count(), "No team appears in more than one group");

    TestRunner.IsTrue(groups[0].Contains(seeded[0]), "Seed 1 goes to Group A");
    TestRunner.IsTrue(groups[1].Contains(seeded[1]), "Seed 2 goes to Group B");
    TestRunner.IsTrue(groups[1].Contains(seeded[2]), "Seed 3 stays in Group B - the snake hasn't reversed yet");
    TestRunner.IsTrue(groups[0].Contains(seeded[3]), "Seed 4 goes to Group A - the snake reverses direction");
});

TestRunner.Run("A straight knockout seeds 1v4 and 2v3 so the top two seeds can only meet in the final, and the bracket progresses as results come in", () =>
{
    var bracketSvc = new PlayoffBracketService();
    var teams = Enumerable.Range(0, 4).Select(i => new Team { Name = $"Seed{i + 1}" }).ToList();
    var teamDict = teams.ToDictionary(t => t.Id);
    var seeded = teams.Select(t => t.Id).ToList();

    var bracket = bracketSvc.GenerateStraightKnockout(Guid.NewGuid(), Guid.NewGuid(), seeded, new DateOnly(2026, 10, 1), daysBetweenRounds: 4, teamDict);

    TestRunner.AreEqual(3, bracket.Count, "4 teams -> 2 semi-finals + 1 final");
    var semis = bracket.Where(f => f.Stage == "Semi-Final").ToList();
    TestRunner.AreEqual(2, semis.Count);

    var semi1 = semis.First(f => f.HomeTeamId == seeded[0] || f.AwayTeamId == seeded[0]);
    TestRunner.IsTrue(new[] { semi1.HomeTeamId, semi1.AwayTeamId }.Contains(seeded[3]), "Seed 1 must play seed 4 in the first semi-final");

    var semi2 = semis.First(f => f.HomeTeamId == seeded[1] || f.AwayTeamId == seeded[1]);
    TestRunner.IsTrue(new[] { semi2.HomeTeamId, semi2.AwayTeamId }.Contains(seeded[2]), "Seed 2 must play seed 3 in the other semi-final");

    var final = bracket.Single(f => f.Stage == "Final");
    TestRunner.IsTrue(final.HomeTeamId is null && final.AwayTeamId is null, "The final has no concrete teams yet - only placeholders");
    TestRunner.IsTrue(final.HomeTeamPlaceholder!.Contains("Winner") && final.AwayTeamPlaceholder!.Contains("Winner"), "Final's placeholders describe where each side comes from");

    bracketSvc.RecordFixtureResult(semi1, seeded[0], Guid.NewGuid(), bracket);
    bracketSvc.RecordFixtureResult(semi2, seeded[2], Guid.NewGuid(), bracket);

    TestRunner.IsTrue(new[] { final.HomeTeamId, final.AwayTeamId }.Contains(seeded[0]), "Semi-final 1's winner advances to the final");
    TestRunner.IsTrue(new[] { final.HomeTeamId, final.AwayTeamId }.Contains(seeded[2]), "Semi-final 2's winner advances to the final");
    TestRunner.IsTrue(final.HomeTeamPlaceholder is null && final.AwayTeamPlaceholder is null, "Placeholders are cleared once resolved");
});

TestRunner.Run("A non-power-of-two knockout pads with byes at the weakest seeds, and a bye advances the present team without ever creating a match", () =>
{
