TestRunner.Run("IPL-style playoff gives Qualifier 1's loser a second chance in Qualifier 2, while the Eliminator's loser is genuinely out", () =>
{
    var bracketSvc = new PlayoffBracketService();
    var teams = Enumerable.Range(0, 4).Select(i => new Team { Name = $"Seed{i + 1}" }).ToList();
    var teamDict = teams.ToDictionary(t => t.Id);
    var seeded = teams.Select(t => t.Id).ToList();

    var bracket = bracketSvc.GenerateIplStylePlayoff(Guid.NewGuid(), Guid.NewGuid(), seeded, new DateOnly(2026, 10, 1), 2, teamDict);

    TestRunner.AreEqual(4, bracket.Count);
    var q1 = bracket.Single(f => f.Stage == "Qualifier 1");
    var eliminator = bracket.Single(f => f.Stage == "Eliminator");
    var q2 = bracket.Single(f => f.Stage == "Qualifier 2");
    var final = bracket.Single(f => f.Stage == "Final");

    TestRunner.AreEqual(seeded[0], q1.HomeTeamId);
    TestRunner.AreEqual(seeded[1], q1.AwayTeamId);
    TestRunner.AreEqual(seeded[2], eliminator.HomeTeamId);
    TestRunner.AreEqual(seeded[3], eliminator.AwayTeamId);

    // Seed 1 beats Seed 2 in Qualifier 1; Seed 3 beats Seed 4 in the Eliminator.
    bracketSvc.RecordFixtureResult(q1, seeded[0], Guid.NewGuid(), bracket);
    bracketSvc.RecordFixtureResult(eliminator, seeded[2], Guid.NewGuid(), bracket);

    TestRunner.AreEqual(seeded[1], q2.HomeTeamId, "Qualifier 1's LOSER (seed 2) gets a second chance in Qualifier 2, not elimination");
    TestRunner.AreEqual(seeded[2], q2.AwayTeamId, "The Eliminator's winner goes straight into Qualifier 2");
    TestRunner.AreEqual(seeded[0], final.HomeTeamId, "Qualifier 1's winner goes straight into the Final");
    TestRunner.IsTrue(q2.HomeTeamId != seeded[3] && q2.AwayTeamId != seeded[3], "The Eliminator's loser (seed 4) does not get a second chance");

    // Seed 2 then beats Seed 3 in Qualifier 2 and reaches the final too.
    bracketSvc.RecordFixtureResult(q2, seeded[1], Guid.NewGuid(), bracket);
    TestRunner.AreEqual(seeded[1], final.AwayTeamId, "Qualifier 2's winner takes the final's other spot");
    TestRunner.IsTrue(final.HomeTeamId != seeded[3] && final.AwayTeamId != seeded[3], "Seed 4 never reappears - genuinely eliminated");
});

TestRunner.Run("Fixture generation and standings-based qualification connect end to end: round-robin -> table -> straight knockout seeding", () =>
{
    var genSvc = new FixtureGenerationService();
    var progression = new CompetitionProgressionService();
    var bracketSvc = new PlayoffBracketService();

    var teams = Enumerable.Range(0, 6).Select(i => new Team { Name = $"T{i}" }).ToList();
    var teamDict = teams.ToDictionary(t => t.Id);
    var teamIds = teams.Select(t => t.Id).ToList();

    var competition = new Competition { Name = "Test Cup", StructureType = CompetitionStructureType.LeagueWithPlayoffs };
    var season = new CompetitionSeason { CompetitionId = competition.Id, Year = 2026, ParticipatingTeamIds = teamIds };

    var pairings = genSvc.GenerateRoundRobinPairings(teamIds, doubleRoundRobin: false);
    var fixtures = genSvc.ScheduleRoundRobin(competition.Id, season.Id, pairings, new DateOnly(2026, 4, 1), new DateOnly(2026, 8, 1), MatchFormat.T20, teamDict);
    TestRunner.AreEqual(15, fixtures.Count);

    // Fabricate a table: team 0 wins everything, team 1 wins all but its loss to team 0, and so on down the ranking.
    foreach (var (home, away, _) in pairings)
    {
        int homeRank = teamIds.IndexOf(home);
        int awayRank = teamIds.IndexOf(away);
        var winner = homeRank < awayRank ? home : away;
        var loser = homeRank < awayRank ? away : home;
        season.GetOrCreateStanding(winner).RecordResult(MatchOutcome.Win);
        season.GetOrCreateStanding(loser).RecordResult(MatchOutcome.Loss);
    }

    var qualifiers = progression.GetPlayoffQualifiers(season, 4);
    TestRunner.IsTrue(qualifiers.SequenceEqual(new[] { teamIds[0], teamIds[1], teamIds[2], teamIds[3] }),
        "The 4 strongest teams by the fabricated table qualify, in rank order");

    var playoffBracket = bracketSvc.GenerateStraightKnockout(competition.Id, season.Id, qualifiers, new DateOnly(2026, 8, 8), 4, teamDict);
    TestRunner.AreEqual(3, playoffBracket.Count);
    var semi1 = playoffBracket.Where(f => f.Stage == "Semi-Final").First(f => new[] { f.HomeTeamId, f.AwayTeamId }.Contains(qualifiers[0]));
    TestRunner.IsTrue(new[] { semi1.HomeTeamId, semi1.AwayTeamId }.Contains(qualifiers[3]), "Table-topper plays the 4th qualifier in the seeded semi-final");
});

TestRunner.Run("GroupStageKnockout: two groups' own standings feed a crossover-seeded knockout where nobody meets their own group in round one", () =>
{
    var genSvc = new FixtureGenerationService();
    var progression = new CompetitionProgressionService();
    var bracketSvc = new PlayoffBracketService();

    var teams = Enumerable.Range(0, 8).Select(i => new Team { Name = $"T{i}" }).ToList();
    var teamDict = teams.ToDictionary(t => t.Id);
    var seededOverall = teams.Select(t => t.Id).ToList(); // T0 strongest .. T7 weakest

    var groups = genSvc.SplitIntoGroups(seededOverall, numberOfGroups: 2);
    // Snake draft -> Group A = [T0,T3,T4,T7], Group B = [T1,T2,T5,T6]
    var groupNames = new[] { "Group A", "Group B" };

    var competition = new Competition { Name = "Test World Cup", StructureType = CompetitionStructureType.GroupStageKnockout };
    var season = new CompetitionSeason { CompetitionId = competition.Id, Year = 2026, ParticipatingTeamIds = seededOverall };

    // Fabricate each group's own table: within a group, lower original seed number wins.
    for (int g = 0; g < groups.Count; g++)
    {
        foreach (var teamId in groups[g]) season.GetOrCreateStanding(teamId, groupNames[g]);

        foreach (var teamId in groups[g])
        {
            var otherTeams = groups[g].Where(t => t != teamId);
            foreach (var opponent in otherTeams)
            {
                if (seededOverall.IndexOf(teamId) < seededOverall.IndexOf(opponent))
                    season.GetOrCreateStanding(teamId, groupNames[g]).RecordResult(MatchOutcome.Win);
            }
        }
    }

    var groupAQualifiers = progression.GetGroupQualifiers(season, "Group A", 2);
    var groupBQualifiers = progression.GetGroupQualifiers(season, "Group B", 2);

    TestRunner.IsTrue(groupAQualifiers.SequenceEqual(new[] { groups[0][0], groups[0][1] }), "Group A's top 2 by its OWN table, not the overall seeding");
    TestRunner.IsTrue(groupBQualifiers.SequenceEqual(new[] { groups[1][0], groups[1][1] }), "Group B's top 2 by its OWN table");

    var seeding = genSvc.BuildGroupCrossoverSeeding(new[] { groupAQualifiers, groupBQualifiers }, qualifiersPerGroup: 2);
    TestRunner.IsTrue(seeding.SequenceEqual(new[] { groupAQualifiers[0], groupBQualifiers[0], groupAQualifiers[1], groupBQualifiers[1] }),
        "Interleaved: both group winners first, then both runners-up");

    var knockout = bracketSvc.GenerateStraightKnockout(competition.Id, season.Id, seeding, new DateOnly(2026, 11, 1), 3, teamDict);
    var semis = knockout.Where(f => f.Stage == "Semi-Final").ToList();

    foreach (var semi in semis)
    {
        bool homeInGroupA = groups[0].Contains(semi.HomeTeamId!.Value);
        bool awayInGroupA = groups[0].Contains(semi.AwayTeamId!.Value);
        TestRunner.IsTrue(homeInGroupA != awayInGroupA, "Every semi-final crosses groups - nobody meets their own group's qualifier in round one");
    }
});

await TestRunner.RunAsync("Fixture - including a completed knockout slot with a loser-feed placeholder - survives save/reload through GameDataContext", async () =>
{
    var tempDir = Path.Combine(Path.GetTempPath(), "cricketmanager_test_" + Guid.NewGuid());
    try
    {
        var homeId = Guid.NewGuid();
        var feederId = Guid.NewGuid();
        var fixture = new Fixture
        {
            CompetitionId = Guid.NewGuid(),
            SeasonId = Guid.NewGuid(),
            Stage = "Final",
            ScheduledDate = new DateOnly(2026, 11, 1),
            AwayTeamPlaceholder = "Winner of Qualifier 2",
            HomeTeamId = homeId,
            HomeFeederFixtureId = feederId,
            HomeFeederIsLoserSlot = true
        };
        fixture.Complete(Guid.NewGuid(), homeId);

        var ctx1 = new GameDataContext(tempDir);
        await ctx1.Fixtures.AddAsync(fixture);
        await ctx1.SaveAllAsync();

        var ctx2 = new GameDataContext(tempDir);
        var reloaded = await ctx2.Fixtures.GetByIdAsync(fixture.Id);

        TestRunner.IsTrue(reloaded is not null, "Reloaded fixture should not be null");
        TestRunner.AreEqual("Final", reloaded!.Stage);
        TestRunner.AreEqual(FixtureStatus.Completed, reloaded.Status, "Private-setter Status must survive reload");
        TestRunner.AreEqual(homeId, reloaded.WinningTeamId);
        TestRunner.AreEqual("Winner of Qualifier 2", reloaded.AwayTeamPlaceholder);
        TestRunner.AreEqual(feederId, reloaded.HomeFeederFixtureId);
        TestRunner.IsTrue(reloaded.HomeFeederIsLoserSlot, "HomeFeederIsLoserSlot must survive reload - it's what tells Qualifier 2 apart from a normal winner-advances slot");
    }
    finally
    {
        if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true);
    }
});

