TestRunner.Run("FormState.ConsecutivePoorPerformances counts back from the most recent, and a single good performance resets the streak", () =>
{
    var form = new FormState();
    form.RecordPerformance(-30);
    form.RecordPerformance(-30);
    form.RecordPerformance(-30);
    TestRunner.AreEqual(3, form.ConsecutivePoorPerformances(-25), "Three consecutive poor performances");

    form.RecordPerformance(10); // a good game
    TestRunner.AreEqual(0, form.ConsecutivePoorPerformances(-25), "One good performance resets the streak to zero");

    form.RecordPerformance(-30);
    TestRunner.AreEqual(1, form.ConsecutivePoorPerformances(-25), "Streak restarts from the most recent performance only");
});

TestRunner.Run("An established FirstChoice player is protected from a SHORT bad patch that an identical Fringe player is not", () =>
{
    var evaluator = new PlayerSelectionEvaluator();

    Player MakePlayer(SquadStatus status, double reputation, int experienceMatches)
    {
        var p = new Player
        {
            FirstName = "P", LastName = status.ToString(),
            CurrentAbility = 140, PotentialAbility = 140,
            SquadStatus = status,
            Reputation = new Reputation(domestic: reputation, continental: reputation * 0.3),
            Experience = PlayerExperience.FromExistingCareer(
                new Dictionary<MatchFormat, int> { [MatchFormat.T20] = experienceMatches }, seasonsPlayed: 8)
        };
        p.Batting = new BattingAttributes { PowerHitting = 14, BoundaryHitting = 14, StrikeRotation = 12 };
        p.RecalculateFormatSuitability();
        // A short bad patch - two poor performances only.
        p.Form.RecordPerformance(-30);
        p.Form.RecordPerformance(-30);
        return p;
    }

    var mainstay = MakePlayer(SquadStatus.FirstChoice, reputation: 80, experienceMatches: 150);
    var fringe = MakePlayer(SquadStatus.Fringe, reputation: 5, experienceMatches: 0);

    var mainstayScore = evaluator.Evaluate(mainstay, MatchFormat.T20);
    var fringeScore = evaluator.Evaluate(fringe, MatchFormat.T20);

    // The form component is only one of three weighted inputs (Balanced weighting: 0.35 Form),
    // and a SHORT patch deliberately earns only partial protection - so the realistic gap here
    // is real but modest (~2.5-3 points), not dramatic. The much larger, more important claim -
    // that protection actually fades away under a PROLONGED decline - is proven directly by
    // the next test, which compares FormComponent itself rather than the diluted TotalScore.
    TestRunner.IsTrue(mainstayScore.TotalScore > fringeScore.TotalScore + 2,
        $"Identical raw form and ability, but the mainstay ({mainstayScore.TotalScore}) should score meaningfully above the fringe player ({fringeScore.TotalScore}) after a short bad patch");
});

TestRunner.Run("Established-player protection fades to nothing once the decline is genuinely prolonged", () =>
{
    var evaluator = new PlayerSelectionEvaluator();

    Player MakeMainstay(int poorPerformances)
    {
        var p = new Player
        {
            FirstName = "P", LastName = "Mainstay",
            CurrentAbility = 140, PotentialAbility = 140,
            SquadStatus = SquadStatus.FirstChoice,
            Reputation = new Reputation(domestic: 80, continental: 25),
            Experience = PlayerExperience.FromExistingCareer(
                new Dictionary<MatchFormat, int> { [MatchFormat.T20] = 150 }, seasonsPlayed: 8)
        };
        p.Batting = new BattingAttributes { PowerHitting = 14, BoundaryHitting = 14, StrikeRotation = 12 };
        p.RecalculateFormatSuitability();
        for (int i = 0; i < poorPerformances; i++) p.Form.RecordPerformance(-30);
        return p;
    }

    var shortPatch = MakeMainstay(2);   // protected
    var prolonged = MakeMainstay(8);    // protection should have fully faded

    var shortScore = evaluator.Evaluate(shortPatch, MatchFormat.T20);
    var prolongedScore = evaluator.Evaluate(prolonged, MatchFormat.T20);

    // Both have the SAME recent form (-30 average, since every recorded performance is -30) -
    // the only difference is how long the run has lasted. If protection had not faded, both
    // would score close to identically; it should instead cost the prolonged case real ground.
    TestRunner.IsTrue(shortScore.FormComponent > prolongedScore.FormComponent + 5,
        $"A short bad patch ({shortScore.FormComponent}) must still read as more forgivable than a prolonged one ({prolongedScore.FormComponent}) despite identical average form");
});

TestRunner.Run("Sufficiently strong evidence still overrides reputation - a genuinely in-form fringe player can outrank a mainstay in prolonged decline", () =>
{
    var evaluator = new PlayerSelectionEvaluator();

    var decliningStar = new Player
    {
        FirstName = "Declining", LastName = "Star",
        CurrentAbility = 140, PotentialAbility = 140,
        SquadStatus = SquadStatus.FirstChoice,
        Reputation = new Reputation(domestic: 90, continental: 40),
        Experience = PlayerExperience.FromExistingCareer(
            new Dictionary<MatchFormat, int> { [MatchFormat.T20] = 200 }, seasonsPlayed: 12)
    };
    decliningStar.Batting = new BattingAttributes { PowerHitting = 14, BoundaryHitting = 14, StrikeRotation = 12 };
    decliningStar.RecalculateFormatSuitability();
    for (int i = 0; i < 10; i++) decliningStar.Form.RecordPerformance(-80); // long, severe decline

    var inFormFringe = new Player
    {
        FirstName = "InForm", LastName = "Fringe",
        CurrentAbility = 140, PotentialAbility = 140,
        SquadStatus = SquadStatus.Fringe,
        Reputation = new Reputation(domestic: 5)
    };
    inFormFringe.Batting = new BattingAttributes { PowerHitting = 14, BoundaryHitting = 14, StrikeRotation = 12 };
    inFormFringe.RecalculateFormatSuitability();
    for (int i = 0; i < 3; i++) inFormFringe.Form.RecordPerformance(80);

    var ranked = evaluator.Rank(new[] { decliningStar, inFormFringe }, MatchFormat.T20);
    TestRunner.AreEqual("InForm Fringe", ranked[0].PlayerName,
        "Reputation cannot rescue a prolonged, severe decline against a genuinely in-form alternative");
});

TestRunner.Run("SquadManagementService leaves a short bad patch alone, but responds to a prolonged one - Roadmap/Rest for an established player, Drop for one with no reputation", () =>
{
    var squadManagement = new SquadManagementService();

    Player MakePlayer(SquadStatus status, double reputation, int poorPerformances, PersonalityTrait personality = PersonalityTrait.None)
    {
        var p = new Player { FirstName = "P", LastName = "Test", SquadStatus = status, Reputation = new Reputation(domestic: reputation), Personality = personality };
        for (int i = 0; i < poorPerformances; i++) p.Form.RecordPerformance(-30);
        return p;
    }

    // Short bad patch - never triggers, whatever the random roll.
    var shortPatchPlayer = MakePlayer(SquadStatus.FirstChoice, 80, poorPerformances: 3);
    for (int trial = 0; trial < 20; trial++)
        TestRunner.IsTrue(squadManagement.AssessDeclineResponse(shortPatchPlayer, new Random(trial)) is null,
            "A short bad patch must never produce a squad decision, regardless of the random roll");

    // Prolonged decline, established, reputable -> Roadmap or Rest, never Drop, across many trials.
    int roadmapOrRestCount = 0;
    for (int trial = 0; trial < 300; trial++)
    {
        var mainstay = MakePlayer(SquadStatus.FirstChoice, 80, poorPerformances: 12, PersonalityTrait.Professional);
        var assessment = squadManagement.AssessDeclineResponse(mainstay, new Random(trial));
        if (assessment is null) continue;
        TestRunner.IsTrue(assessment.Type is SquadDecisionType.Roadmap or SquadDecisionType.Rest,
            "An established, reputable player in prolonged decline gets a second chance, never a flat Drop");
        roadmapOrRestCount++;
    }
    TestRunner.IsTrue(roadmapOrRestCount > 30, "Across 300 trials with a genuinely prolonged decline, the probability should fire meaningfully often, not stay at zero");

    // Prolonged decline, no reputation to fall back on -> Drop.
    int dropCount = 0;
    for (int trial = 0; trial < 300; trial++)
    {
        var noReputationVeteran = MakePlayer(SquadStatus.FirstChoice, 5, poorPerformances: 12);
        var assessment = squadManagement.AssessDeclineResponse(noReputationVeteran, new Random(trial));
        if (assessment is null) continue;
        TestRunner.AreEqual(SquadDecisionType.Drop, assessment.Type, "No reputation left to fall back on - Drop, not a second chance");
        dropCount++;
    }
    TestRunner.IsTrue(dropCount > 30, "The no-reputation case should also fire meaningfully often across 300 trials");
});

TestRunner.Run("A DevelopmentProspect is backed through roughly twice as long a run of failures, and is never Dropped by SquadManagementService", () =>
{
    var squadManagement = new SquadManagementService();

    var prospect = new Player { FirstName = "Young", LastName = "Prospect", SquadStatus = SquadStatus.DevelopmentProspect, Reputation = new Reputation(domestic: 10) };
    for (int i = 0; i < 8; i++) prospect.Form.RecordPerformance(-30); // enough to trigger a FirstChoice player, not enough for a prospect

    for (int trial = 0; trial < 20; trial++)
        TestRunner.IsTrue(squadManagement.AssessDeclineResponse(prospect, new Random(trial)) is null,
            "8 consecutive failures is a FirstChoice-level threshold, not a DevelopmentProspect one - he keeps his chance");

    var longStrugglingProspect = new Player { FirstName = "Long", LastName = "Struggler", SquadStatus = SquadStatus.DevelopmentProspect, Reputation = new Reputation(domestic: 10) };
    for (int i = 0; i < 20; i++) longStrugglingProspect.Form.RecordPerformance(-30);

    bool everTriggered = false;
    for (int trial = 0; trial < 100; trial++)
    {
        var assessment = squadManagement.AssessDeclineResponse(longStrugglingProspect, new Random(trial));
        if (assessment is null) continue;
        everTriggered = true;
        TestRunner.AreEqual(SquadDecisionType.Roadmap, assessment.Type, "A DevelopmentProspect is never Dropped by this service - Roadmap only, keeping his development chance alive");
    }
    TestRunner.IsTrue(everTriggered, "20 consecutive failures should eventually trigger something across 100 trials");
});

await TestRunner.RunAsync("SquadManagementService.Apply makes a Roadmap/Rest a real, gameplay-visible unavailability, and ReviewDecision restores it once due", async () =>
{
    var squadManagement = new SquadManagementService();
    var availability = new PlayerAvailabilityService();

    var player = new Player { FirstName = "On", LastName = "Roadmap", SquadStatus = SquadStatus.FirstChoice, Reputation = new Reputation(domestic: 80) };
    var decidedDate = new DateOnly(2026, 6, 1);
    var assessment = new SquadDecisionAssessment(player.Id, SquadDecisionType.Roadmap, "Test roadmap");
    squadManagement.Apply(player, assessment, decidedDate);

    TestRunner.AreEqual(UnavailabilityReason.OnDevelopmentAssignment, player.NonInjuryUnavailability);
    TestRunner.IsTrue(player.CurrentSquadDecision is not null, "An active decision is now on record");

    var beforeReview = availability.GetAvailability(player, decidedDate.AddMonths(1));
    TestRunner.IsTrue(!beforeReview.IsAvailable, "While the roadmap is active, the player is genuinely unavailable for selection");

    var reviewDate = player.CurrentSquadDecision!.ReviewDate!.Value;
    squadManagement.ReviewDecision(player, reviewDate.AddDays(-1));
    TestRunner.IsTrue(player.CurrentSquadDecision is not null, "Reviewing before the review date does nothing");

    squadManagement.ReviewDecision(player, reviewDate);
    TestRunner.IsTrue(player.CurrentSquadDecision is null, "Reviewing on/after the review date clears the decision");
    TestRunner.AreEqual(UnavailabilityReason.Available, player.NonInjuryUnavailability);

    var afterReview = availability.GetAvailability(player, reviewDate);
    TestRunner.IsTrue(afterReview.IsAvailable, "The player is genuinely selectable again once the roadmap concludes");

    await Task.CompletedTask;
});

TestRunner.Run("PlayerAvailabilityService.MarkRecovered protects an incumbent's squad standing on return from injury", () =>
{
    var availability = new PlayerAvailabilityService();

    var incumbent = new Player { FirstName = "Incumbent", LastName = "Star", SquadStatus = SquadStatus.FirstChoice };
    availability.ApplyInjury(incumbent, InjuryType.Hamstring, InjurySeverity.Moderate, new DateOnly(2026, 1, 1), random: new Random(1));
    availability.MarkRecovered(incumbent, new DateOnly(2026, 3, 1));

    TestRunner.AreEqual(SquadStatus.ReturningFromInjury, incumbent.SquadStatus,
        "An incumbent's original standing is preserved as ReturningFromInjury, not silently lost, on return from injury");

    var wasAlreadyFringe = new Player { FirstName = "Fringe", LastName = "Player", SquadStatus = SquadStatus.Fringe };
    availability.ApplyInjury(wasAlreadyFringe, InjuryType.Hamstring, InjurySeverity.Moderate, new DateOnly(2026, 1, 1), random: new Random(1));
    availability.MarkRecovered(wasAlreadyFringe, new DateOnly(2026, 3, 1));

    TestRunner.AreEqual(SquadStatus.Fringe, wasAlreadyFringe.SquadStatus,
        "A player who was never first-team in the first place isn't artificially promoted just for returning from injury");
});

TestRunner.Run("SquadStatusService derives real, differentiated starting statuses from ability/reputation/age - never a bare placeholder", () =>
{
