TestRunner.Run("WorldClockService's annual rollover can produce a SquadDecisionMade event for a player in prolonged decline, without ever retiring or dropping a short bad patch", () =>
{
    var clock = new WorldClockService();

    bool everFired = false;
    for (int trial = 0; trial < 40 && !everFired; trial++)
    {
        var world = EmptyWorld();
        var player = new Player
        {
            FirstName = "Trial", LastName = trial.ToString(),
            DateOfBirth = new DateOnly(1990, 1, 1), // established age, but well clear of RetirementService's own escalating curve at 36
            CurrentAbility = 150, PotentialAbility = 150,
            SquadStatus = SquadStatus.FirstChoice,
            Reputation = new Reputation(domestic: 80, continental: 20)
        };
        for (int i = 0; i < 12; i++) player.Form.RecordPerformance(-30);
        world.Players.Add(player);
        world.MatchesThisSeason[player.Id] = 10; // clearly still being picked - isolates the form signal

        var localCalendar = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: trial);
        var events = clock.AdvanceTo(localCalendar, world, new DateOnly(2027, 1, 2));

        if (events.Any(e => e.Type == GameEventType.SquadDecisionMade))
        {
            everFired = true;
            TestRunner.IsTrue(!player.IsRetired, "A squad decision is not a retirement - the player's career continues");
        }
    }
    TestRunner.IsTrue(everFired, "Across 40 trial worlds with a genuinely prolonged decline, the annual rollover should produce a SquadDecisionMade event at least once");
});

// ---------------------------------------------------------------------------
// Post-Phase-4 planning brief, Section D: coach job security and tenure-driven
// tactical growth. Coach.BoardTrust/Authority/CareerSatisfaction and
// ContractStatus.Terminated all existed with no writer anywhere before this.
// ---------------------------------------------------------------------------

TestRunner.Run("CoachCareerService.ScoreSeason reads a team's actual results against what its own Strength/Reputation predicted, not a raw table position", () =>
{
    var career = new CoachCareerService();

    var strongTeam = new Team { Strength = 85, Reputation = new Reputation(domestic: 80) };
    var poorSeasonForStrongTeam = new List<CompetitionStanding>();
    var strongStanding = new CompetitionStanding { TeamId = strongTeam.Id };
    for (int i = 0; i < 8; i++) strongStanding.RecordResult(MatchOutcome.Loss);
    for (int i = 0; i < 2; i++) strongStanding.RecordResult(MatchOutcome.Win);
    poorSeasonForStrongTeam.Add(strongStanding);

    var weakTeam = new Team { Strength = 20, Reputation = new Reputation(domestic: 15) };
    var greatSeasonForWeakTeam = new List<CompetitionStanding>();
    var weakStanding = new CompetitionStanding { TeamId = weakTeam.Id };
    for (int i = 0; i < 8; i++) weakStanding.RecordResult(MatchOutcome.Win);
    for (int i = 0; i < 2; i++) weakStanding.RecordResult(MatchOutcome.Loss);
    greatSeasonForWeakTeam.Add(weakStanding);

    double strongTeamScore = career.ScoreSeason(strongTeam, poorSeasonForStrongTeam);
    double weakTeamScore = career.ScoreSeason(weakTeam, greatSeasonForWeakTeam);

    TestRunner.IsTrue(strongTeamScore < -0.3, $"A strong team winning only 2 of 10 should score as a real underachievement, got {strongTeamScore:F2}");
    TestRunner.IsTrue(weakTeamScore > 0.3, $"A weak team winning 8 of 10 should score as a real overachievement, got {weakTeamScore:F2}");
    TestRunner.AreEqual(0.0, career.ScoreSeason(strongTeam, new List<CompetitionStanding>()), "No matches played this year is no verdict, not a neutral judgement");
});

TestRunner.Run("CoachCareerService.EvaluateSeason moves BoardTrust and Reputation in the direction the season deserves, and dismisses only once trust has genuinely collapsed", () =>
{
    var career = new CoachCareerService();

    Coach MakeCoach(double boardTrust) => new()
    {
        FirstName = "Test", LastName = "Coach",
        BoardTrust = boardTrust,
        CurrentTeamId = Guid.NewGuid()
    };

    var team = new Team { Name = "Trial FC", Strength = 50, Reputation = new Reputation(domestic: 40) };
    var goodContract = new CoachingContract { StartDate = new DateOnly(2020, 1, 1) };
    var goodCoach = MakeCoach(50);
    goodCoach.CurrentContractId = goodContract.Id;
    double domesticBefore = goodCoach.Reputation.Domestic;

    var goodReview = career.EvaluateSeason(goodCoach, goodContract, team, performanceScore: 0.8, seasonsAtClub: 2, new Random(1));
    TestRunner.IsTrue(goodReview.BoardTrustDelta > 0, "A genuinely strong season should raise BoardTrust");
    TestRunner.IsTrue(goodCoach.Reputation.Domestic > domesticBefore, "A genuinely strong season should build the coach's own reputation");
    TestRunner.IsTrue(!goodReview.Dismissed, "A coach having a good season should never be dismissed");

    var poorContract = new CoachingContract { StartDate = new DateOnly(2020, 1, 1) };
    var poorCoach = MakeCoach(50);
    poorCoach.CurrentContractId = poorContract.Id;
    double poorDomesticBefore = poorCoach.Reputation.Domestic;

    var poorReview = career.EvaluateSeason(poorCoach, poorContract, team, performanceScore: -0.8, seasonsAtClub: 2, new Random(1));
    TestRunner.IsTrue(poorReview.BoardTrustDelta < 0, "A genuinely poor season should lower BoardTrust");
    TestRunner.IsTrue(poorCoach.Reputation.Domestic < poorDomesticBefore, "A genuinely poor season should cost the coach some reputation");

    // Repeated poor seasons should eventually put a coach's job at real risk - and firing him
    // should carry real, visible consequences: the contract is terminated, he is no longer at
    // the team, and the board pays out the compensation clause.
    var payContract = new CoachingContract { StartDate = new DateOnly(2015, 1, 1), CompensationIfTerminated = 250_000 };
    var payTeam = new Team { Name = "Payout FC", Strength = 50, Reputation = new Reputation(domestic: 40), Finances = new TeamFinances { Budget = 1_000_000 } };
    var payCoach = MakeCoach(30);
    payCoach.CurrentTeamId = payTeam.Id;
    payCoach.CurrentContractId = payContract.Id;

    bool everDismissed = false;
    var random = new Random(7);
    for (int year = 0; year < 15 && !everDismissed; year++)
    {
        var review = career.EvaluateSeason(payCoach, payContract, payTeam, performanceScore: -0.9, seasonsAtClub: year, random);
        if (review.Dismissed) everDismissed = true;
    }

    TestRunner.IsTrue(everDismissed, "A run of genuinely disastrous seasons should eventually cost the coach his job");
    TestRunner.AreEqual(ContractStatus.Terminated, payContract.Status, "A dismissal should terminate the actual contract");
    TestRunner.IsTrue(payCoach.CurrentTeamId is null && payCoach.CurrentContractId is null, "A dismissed coach is no longer attached to the team or its contract");
    TestRunner.IsTrue(payTeam.Finances.Budget < 1_000_000, "The compensation clause should actually cost the club money");
});

TestRunner.Run("CoachCareerService.GrowFromTenure grows tactical attributes faster for a fresh coach having a good season than a long-tenured one having a poor one", () =>
{
    var career = new CoachCareerService();

    int CountGrowth(int seasonsAtClub, double performanceScore, int trials)
    {
        int totalGrowth = 0;
        var random = new Random(11);
        for (int i = 0; i < trials; i++)
        {
            var coach = new Coach { FirstName = "Grow", LastName = i.ToString() };
            int before = coach.Attributes.TacticalKnowledge + coach.Attributes.MatchReading + coach.Attributes.DecisionMaking + coach.Attributes.Adaptability;
            career.GrowFromTenure(coach, seasonsAtClub, performanceScore, random);
            int after = coach.Attributes.TacticalKnowledge + coach.Attributes.MatchReading + coach.Attributes.DecisionMaking + coach.Attributes.Adaptability;
            totalGrowth += after - before;
        }
        return totalGrowth;
    }

    int freshGoodGrowth = CountGrowth(seasonsAtClub: 0, performanceScore: 0.9, trials: 400);
    int veteranPoorGrowth = CountGrowth(seasonsAtClub: 15, performanceScore: -0.9, trials: 400);

    TestRunner.IsTrue(freshGoodGrowth > veteranPoorGrowth,
        $"A fresh coach doing well ({freshGoodGrowth} growth events over 400 trials) should learn faster than a long-tenured one doing poorly ({veteranPoorGrowth})");

    // Bounded at the 1-20 ceiling every coach attribute already respects.
    var maxedCoach = new Coach { FirstName = "Maxed", LastName = "Out" };
    maxedCoach.Attributes.TacticalKnowledge = 20;
    var maxRandom = new Random(3);
    for (int i = 0; i < 50; i++) career.GrowFromTenure(maxedCoach, 0, 1.0, maxRandom);
    TestRunner.InRange(maxedCoach.Attributes.TacticalKnowledge, 1, 20, "TacticalKnowledge must never exceed the 1-20 scale");
});

TestRunner.Run("WorldClockService's annual rollover can dismiss a coach whose team has genuinely and repeatedly underperformed, and grows a surviving coach's tactical attributes over tenure", () =>
{
    var clock = new WorldClockService();
    bool everDismissed = false;

    for (int trial = 0; trial < 25 && !everDismissed; trial++)
    {
        var world = EmptyWorld();
        var team = new Team { Name = "Rollover FC", Strength = 90, Reputation = new Reputation(domestic: 85) };
        world.Teams[team.Id] = team;

        var coach = new Coach { FirstName = "Rollover", LastName = trial.ToString(), CurrentTeamId = team.Id };
        var contract = new CoachingContract { StartDate = new DateOnly(2020, 1, 1), TeamId = team.Id, CoachId = coach.Id, EndDate = new DateOnly(2040, 1, 1) };
        coach.CurrentContractId = contract.Id;
        world.Coaches.Add(coach);
        world.CoachingContracts.Add(contract);

        // A dominant-strength team that somehow never wins - the clearest possible
        // underperformance signal, repeated every season so trust has time to collapse.
        var competition = new Competition { Name = "Rollover Trophy" };
        world.Competitions.Add(competition);
        for (int year = 2020; year <= 2033; year++)
        {
            var season = new CompetitionSeason { CompetitionId = competition.Id, Year = year };
            var standing = season.GetOrCreateStanding(team.Id);
            for (int i = 0; i < 10; i++) standing.RecordResult(MatchOutcome.Loss, CompetitionPointsSystem.LimitedOvers);
            world.CompetitionSeasons.Add(season);
        }

        var localCalendar = GameCalendar.Restore(new DateOnly(2020, 1, 1), new DateOnly(2020, 1, 1), worldSeed: trial);
        var events = clock.AdvanceTo(localCalendar, world, new DateOnly(2034, 1, 2));

        if (events.Any(e => e.Type == GameEventType.CoachDismissed))
            everDismissed = true;
    }

    TestRunner.IsTrue(everDismissed, "Across 25 trial worlds, a dominant-strength team that never wins should eventually see its coach dismissed by the annual rollover");
});

// ---------------------------------------------------------------------------
// Post-Phase-4 planning brief, Section U: batting-plan expansion (target/avoid
// a zone, attack the short boundary, attack a bowler TYPE, rebuild after a
// wicket) and a handful of new named bowling plans.
// ---------------------------------------------------------------------------

TestRunner.Run("ApplyZonePreferences boosts a targeted zone, suppresses an avoided one, and leaves everything else untouched", () =>
{
    var baseZones = new BattingZoneStrengths();
    foreach (var zone in Enum.GetValues<ShotZone>()) baseZones[zone] = 50;

    var noInstruction = InningsSimulator.ApplyZonePreferences(baseZones, null, null);
    TestRunner.AreEqual(50.0, noInstruction[ShotZone.Cover], "No instruction at all leaves the natural profile untouched");

    var targeting = InningsSimulator.ApplyZonePreferences(baseZones, BatterInstruction.TargetTheGap(Guid.NewGuid(), ShotZone.Cover), null);
    TestRunner.IsTrue(targeting[ShotZone.Cover] > 60, $"A targeted zone should be boosted well above its natural 50, was {targeting[ShotZone.Cover]}");
    TestRunner.AreEqual(50.0, targeting[ShotZone.MidOn], "Zones not mentioned in the instruction stay at their natural strength");

    var avoiding = InningsSimulator.ApplyZonePreferences(baseZones, BatterInstruction.AvoidTheTrap(Guid.NewGuid(), ShotZone.MidWicket), null);
    TestRunner.IsTrue(avoiding[ShotZone.MidWicket] < 30, $"An avoided zone should be suppressed well below 50, was {avoiding[ShotZone.MidWicket]}");
});

TestRunner.Run("Attacking the shorter boundary favours the square zones on a square-boundary ground, and the straight zones on a straight-boundary one", () =>
{
    var baseZones = new BattingZoneStrengths();
    foreach (var zone in Enum.GetValues<ShotZone>()) baseZones[zone] = 50;
    var instruction = BatterInstruction.AttackTheShortSide(Guid.NewGuid());

    var squareIsShort = new Ground { SquareBoundaryMetres = 60, StraightBoundaryMetres = 75 };
    var squareBiased = InningsSimulator.ApplyZonePreferences(baseZones, instruction, squareIsShort);
    TestRunner.IsTrue(squareBiased[ShotZone.Point] > 55, "Square boundary is the short side here - square zones should be favoured");
    TestRunner.AreEqual(50.0, squareBiased[ShotZone.MidOn], "The straight zones are untouched when the short side is square");

    var straightIsShort = new Ground { SquareBoundaryMetres = 75, StraightBoundaryMetres = 60 };
    var straightBiased = InningsSimulator.ApplyZonePreferences(baseZones, instruction, straightIsShort);
    TestRunner.IsTrue(straightBiased[ShotZone.MidOn] > 55, "Straight boundary is the short side here - straight zones should be favoured instead");
    TestRunner.AreEqual(50.0, straightBiased[ShotZone.Point], "The square zones are untouched when the short side is straight");
});

TestRunner.Run("A batter told to attack a bowler TYPE escalates against any bowler of that type, and against that type only", () =>
{
    var spinner = MatchTestData.MakePlayer("Spin", 13, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    var seamer = MatchTestData.MakePlayer("Seam", 13, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    TestRunner.AreEqual(BowlerType.Spin, BallOutcomeModel.GetBowlerType(spinner));
    TestRunner.AreEqual(BowlerType.Pace, BallOutcomeModel.GetBowlerType(seamer));

    var star = MatchTestData.MakePlayer("Star", 14);
    var plan = new TacticalPlan();
    plan.BatterInstructions.Add(BatterInstruction.AttackSpin(star.Id));

    var state = new InningsState { BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl", Format = MatchFormat.T20, MaxLegalBalls = 120 };
    var starCard = new BatterCard { PlayerId = star.Id, PlayerName = star.FullName, BattingPosition = 1, BallsFaced = 30 };

    var baseline = InningsSimulator.ResolveBattingIntent(state, starCard, MatchPhase.MiddleOvers, TacticalPlan.None, spinner);
    var againstSpin = InningsSimulator.ResolveBattingIntent(state, starCard, MatchPhase.MiddleOvers, plan, spinner);
    var againstSeam = InningsSimulator.ResolveBattingIntent(state, starCard, MatchPhase.MiddleOvers, plan, seamer);

    TestRunner.IsTrue((int)againstSpin > (int)baseline, "Told to attack spin, the batter escalates against a spinner");
    TestRunner.AreEqual(baseline, againstSeam, "The same instruction does not escalate against a seamer - it targets the TYPE, not every bowler");
});

TestRunner.Run("RebuildAfterWicket softens intent for a short window after a new partnership begins, then stops mattering", () =>
{
    var bowler = MatchTestData.MakePlayer("Bowl", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var star = MatchTestData.MakePlayer("Star", 14);
    var plan = new TacticalPlan();
    plan.BatterInstructions.Add(BatterInstruction.RotateAndRebuild(star.Id));
    var starCard = new BatterCard { PlayerId = star.Id, PlayerName = star.FullName, BattingPosition = 1, BallsFaced = 30 };

    var freshPartnership = new InningsState { BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl", Format = MatchFormat.T20, MaxLegalBalls = 120, CurrentPartnershipBalls = 3 };
    var establishedPartnership = new InningsState { BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl", Format = MatchFormat.T20, MaxLegalBalls = 120, CurrentPartnershipBalls = 40 };

    var baselineFresh = InningsSimulator.ResolveBattingIntent(freshPartnership, starCard, MatchPhase.MiddleOvers, TacticalPlan.None, bowler);
    var softenedFresh = InningsSimulator.ResolveBattingIntent(freshPartnership, starCard, MatchPhase.MiddleOvers, plan, bowler);
    TestRunner.IsTrue((int)softenedFresh < (int)baselineFresh, "Fresh off a wicket, RebuildAfterWicket should soften intent below the AI's own baseline");

    var baselineEstablished = InningsSimulator.ResolveBattingIntent(establishedPartnership, starCard, MatchPhase.MiddleOvers, TacticalPlan.None, bowler);
    var softenedEstablished = InningsSimulator.ResolveBattingIntent(establishedPartnership, starCard, MatchPhase.MiddleOvers, plan, bowler);
    TestRunner.AreEqual(baselineEstablished, softenedEstablished, "Once the partnership is well established, RebuildAfterWicket no longer applies - it is a window, not a standing instruction");
});

TestRunner.Run("New named bowling plans use only real Line/Length/Variation combinations valid for their bowler type", () =>
{
    TestRunner.IsTrue(BowlingApproach.TailenderAttack.IsVariationValidFor(BowlerType.Pace), "TailenderAttack's yorker is a pace variation");
    TestRunner.IsTrue(!BowlingApproach.TailenderAttack.IsVariationValidFor(BowlerType.Spin), "...and is not valid for a spinner");
    TestRunner.AreEqual(DeliveryVariation.None, BowlingApproach.EdgeTrap.Variation);
    TestRunner.AreEqual(BowlingLine.IntoTheBody, BowlingApproach.CrampForRoom.Line);
    TestRunner.IsTrue(BowlingApproach.PartnershipBreaker.Insistence > BowlingApproach.NewBall.Insistence,
        "A partnership-breaking plan is pressed harder than a routine new-ball line");
});

// ---------------------------------------------------------------------------
// Post-Phase-4 planning brief, Sections M/N/O/P: player morale, team morale,
// context-sensitive win/loss psychology, and coach-player interaction.
// ---------------------------------------------------------------------------

MatchResult MakeClassifierMatch(Guid winnerId, Guid loserId, bool wonByWickets, int? winMargin, bool winnerBattedFirst, int winnersRuns = 160, List<FallOfWicket>? loserFalls = null)
{
    var homeId = winnerBattedFirst ? winnerId : loserId;
    var awayId = winnerBattedFirst ? loserId : winnerId;

    var firstInnings = new InningsState
    {
        BattingTeamId = winnerBattedFirst ? winnerId : loserId,
        BowlingTeamId = winnerBattedFirst ? loserId : winnerId,
        BattingTeamName = "First", BowlingTeamName = "Second", Format = MatchFormat.T20,
        Runs = winnerBattedFirst ? winnersRuns : winnersRuns - (winMargin ?? 0)
    };
    var secondInnings = new InningsState
    {
        BattingTeamId = winnerBattedFirst ? loserId : winnerId,
        BowlingTeamId = winnerBattedFirst ? winnerId : loserId,
        BattingTeamName = "Second", BowlingTeamName = "First", Format = MatchFormat.T20,
        Runs = winnerBattedFirst ? winnersRuns - (winMargin ?? 0) : winnersRuns
    };
    if (loserFalls is not null)
    {
        var loserInnings = firstInnings.BattingTeamId == loserId ? firstInnings : secondInnings;
        loserInnings.FallOfWickets.AddRange(loserFalls);
    }

    return new MatchResult
    {
        MatchId = Guid.NewGuid(),
        Setup = new MatchSetup { Home = new MatchSide(homeId, "Home", new List<Player>(), new List<Player>()), Away = new MatchSide(awayId, "Away", new List<Player>(), new List<Player>()) },
        FirstInnings = firstInnings,
        SecondInnings = secondInnings,
        WinningTeamId = winnerId,
        LosingTeamId = loserId,
        WonByWickets = wonByWickets,
        WinMargin = winMargin,
        Summary = "Test match"
    };
}

TestRunner.Run("MatchResultContextService classifies wins by margin: dominant, narrow, and a fight-back comeback", () =>
{
    var svc = new MatchResultContextService();
    var winner = Guid.NewGuid(); var loser = Guid.NewGuid();

    var dominant = MakeClassifierMatch(winner, loser, wonByWickets: false, winMargin: 80, winnerBattedFirst: true, winnersRuns: 180);
    TestRunner.AreEqual(MatchResultStory.DominantWin, svc.Classify(dominant, winner, 55, 50));

    var narrow = MakeClassifierMatch(winner, loser, wonByWickets: false, winMargin: 6, winnerBattedFirst: true, winnersRuns: 160);
    TestRunner.AreEqual(MatchResultStory.NarrowWin, svc.Classify(narrow, winner, 55, 50));

    var comeback = MakeClassifierMatch(winner, loser, wonByWickets: true, winMargin: 2, winnerBattedFirst: false, winnersRuns: 160);
    TestRunner.AreEqual(MatchResultStory.ComebackWin, svc.Classify(comeback, winner, 55, 50),
        "Winning by only 2 wickets means 8 were lost along the way - a fight, not a cruise");

    var dominantChase = MakeClassifierMatch(winner, loser, wonByWickets: true, winMargin: 9, winnerBattedFirst: false, winnersRuns: 160);
    TestRunner.AreEqual(MatchResultStory.DominantWin, svc.Classify(dominantChase, winner, 55, 50),
        "Winning by 9 wickets is a cruise, not a fight");
});

TestRunner.Run("MatchResultContextService recognises an upset win by a meaningfully weaker side, regardless of margin", () =>
{
    var svc = new MatchResultContextService();
    var winner = Guid.NewGuid(); var loser = Guid.NewGuid();

    // A narrow margin by itself (5 runs) already reads as NarrowWin regardless of strength -
    // margin classification and upset classification are two different questions, so the upset
    // check uses a margin that is otherwise "ordinary" (neither dominant nor narrow) to isolate
    // strength as the only thing that changes between the two assertions below.
    var match = MakeClassifierMatch(winner, loser, wonByWickets: false, winMargin: 35, winnerBattedFirst: true, winnersRuns: 150);

    TestRunner.AreEqual(MatchResultStory.UpsetWin, svc.Classify(match, winner, teamStrength: 35, opponentStrength: 65),
        "A much weaker side winning is an upset, regardless of the margin");
    TestRunner.AreEqual(MatchResultStory.OrdinaryWin, svc.Classify(match, winner, teamStrength: 50, opponentStrength: 52),
        "Two evenly matched sides, same otherwise-ordinary margin - just an ordinary win, not an upset");
});

TestRunner.Run("MatchResultContextService reads a loss as a collapse when the last five wickets fell for almost nothing", () =>
{
    var svc = new MatchResultContextService();
    var winner = Guid.NewGuid(); var loser = Guid.NewGuid();

    var collapseFalls = new List<FallOfWicket>
    {
        new(1, 90, 60, Guid.NewGuid()), new(2, 110, 70, Guid.NewGuid()), new(3, 120, 80, Guid.NewGuid()),
        new(4, 128, 90, Guid.NewGuid()), new(5, 132, 95, Guid.NewGuid()), // 132 at fall of 5th
        new(6, 138, 100, Guid.NewGuid()), new(7, 142, 105, Guid.NewGuid()), new(8, 145, 108, Guid.NewGuid()),
        new(9, 147, 110, Guid.NewGuid()), new(10, 149, 112, Guid.NewGuid()) // only 17 more from 5th to 10th
    };
    var collapse = MakeClassifierMatch(winner, loser, wonByWickets: false, winMargin: 11, winnerBattedFirst: true, winnersRuns: 160, loserFalls: collapseFalls);
    TestRunner.AreEqual(MatchResultStory.CollapseLoss, svc.Classify(collapse, loser, 50, 50));

    var evenFalls = new List<FallOfWicket>
    {
        new(1, 20, 20, Guid.NewGuid()), new(2, 45, 40, Guid.NewGuid()), new(3, 70, 60, Guid.NewGuid()),
        new(4, 90, 80, Guid.NewGuid()), new(5, 105, 95, Guid.NewGuid()),
        new(6, 120, 105, Guid.NewGuid()), new(7, 130, 110, Guid.NewGuid()), new(8, 140, 113, Guid.NewGuid()),
        new(9, 145, 116, Guid.NewGuid()), new(10, 149, 119, Guid.NewGuid()) // 44 from 5th to 10th - not a collapse
    };
    var evenLoss = MakeClassifierMatch(winner, loser, wonByWickets: false, winMargin: 11, winnerBattedFirst: true, winnersRuns: 160, loserFalls: evenFalls);
    TestRunner.AreEqual(MatchResultStory.CloseLoss, svc.Classify(evenLoss, loser, 50, 50),
        "All out for a similar total but the wickets fell steadily throughout - a close loss, not a collapse");
});

TestRunner.Run("TeamMoraleService differentiates a dominant win from a collapse loss, and amplifies a loss that snaps a real winning streak", () =>
{
    var svc = new TeamMoraleService();

    var dominantTeam = new Team();
    svc.ApplyMatchResult(dominantTeam, MatchResultStory.DominantWin);
    var collapseTeam = new Team();
    svc.ApplyMatchResult(collapseTeam, MatchResultStory.CollapseLoss);

    TestRunner.IsTrue(dominantTeam.Morale.Level > 50, "A dominant win lifts morale above neutral");
    TestRunner.IsTrue(collapseTeam.Morale.Level < 50, "A collapse loss drops morale below neutral");

    var onAStreak = new Team { CurrentStreak = 6 };
    svc.ApplyMatchResult(onAStreak, MatchResultStory.OrdinaryLoss);
    var coldTeam = new Team { CurrentStreak = 0 };
    svc.ApplyMatchResult(coldTeam, MatchResultStory.OrdinaryLoss);
    TestRunner.IsTrue(onAStreak.Morale.Level < coldTeam.Morale.Level,
        "The same ordinary loss hurts more when it snaps a real winning streak");

    var freshWin = new Team();
    svc.ApplyMatchResult(freshWin, MatchResultStory.OrdinaryWin);
    TestRunner.AreEqual(1, freshWin.CurrentStreak, "A single win starts a streak of 1");
    svc.ApplyMatchResult(freshWin, MatchResultStory.OrdinaryWin);
    TestRunner.AreEqual(2, freshWin.CurrentStreak, "A second consecutive win extends it to 2");
    svc.ApplyMatchResult(freshWin, MatchResultStory.OrdinaryLoss);
    TestRunner.AreEqual(-1, freshWin.CurrentStreak, "A loss immediately flips the streak, not just resets it to zero");
    svc.ApplyMatchResult(freshWin, MatchResultStory.Draw);
    TestRunner.AreEqual(0, freshWin.CurrentStreak, "A draw breaks a streak without starting the opposite one");
});

TestRunner.Run("PlayerMoraleService hits an established player harder for a Drop than a fringe player, and Roadmap/Rest build CoachTrust while Drop erodes it", () =>
{
    var svc = new PlayerMoraleService();

    var established = new Player { SquadStatus = SquadStatus.FirstChoice };
    var fringe = new Player { SquadStatus = SquadStatus.Fringe };
    svc.AdjustForSquadDecision(established, SquadDecisionType.Drop);
    svc.AdjustForSquadDecision(fringe, SquadDecisionType.Drop);
    TestRunner.IsTrue(established.Morale.Level < fringe.Morale.Level,
        "Losing a place you believed was yours stings more than losing one you never really had");
    TestRunner.IsTrue(established.CoachTrust < 50, "A drop costs trust");

    var roadmapped = new Player();
    svc.AdjustForSquadDecision(roadmapped, SquadDecisionType.Roadmap);
    TestRunner.IsTrue(roadmapped.CoachTrust > 50, "A roadmap - a genuine path back - builds trust despite losing his place");

    var rested = new Player();
    svc.AdjustForSquadDecision(rested, SquadDecisionType.Rest);
    TestRunner.IsTrue(rested.CoachTrust > 50, "A rest, framed as care rather than punishment, also builds trust");
    TestRunner.IsTrue(rested.Morale.Level > roadmapped.Morale.Level,
        "A rest is a softer psychological hit than being sent out of the side on a roadmap");
});

TestRunner.Run("PlayerMoraleService.AdjustForMatchPerformance weighs personal performance far more than the team result, and a draw carries no win/loss term at all", () =>
{
    var svc = new PlayerMoraleService();

    var greatGameLosingTeam = new Player();
    svc.AdjustForMatchPerformance(greatGameLosingTeam, oppositionAdjustedRating: 80, teamWon: false);
    TestRunner.IsTrue(greatGameLosingTeam.Morale.Level > 50, "A brilliant personal performance lifts morale even in a losing team");

    var poorGameWinningTeam = new Player();
    svc.AdjustForMatchPerformance(poorGameWinningTeam, oppositionAdjustedRating: -80, teamWon: true);
    TestRunner.IsTrue(poorGameWinningTeam.Morale.Level < 50, "A poor personal performance drops morale even in a winning team");

    var drawnGame = new Player();
    var wonGame = new Player();
    var lostGame = new Player();
    svc.AdjustForMatchPerformance(drawnGame, oppositionAdjustedRating: 0, teamWon: null);
    svc.AdjustForMatchPerformance(wonGame, oppositionAdjustedRating: 0, teamWon: true);
    svc.AdjustForMatchPerformance(lostGame, oppositionAdjustedRating: 0, teamWon: false);
    TestRunner.IsTrue(wonGame.Morale.Level > drawnGame.Morale.Level && drawnGame.Morale.Level > lostGame.Morale.Level,
        "With identical personal performance, winning helps a little, losing hurts a little, and a draw sits exactly between the two");
});

TestRunner.Run("PlayerMorale/TeamMorale decay toward neutral, and never overshoot past it", () =>
{
    var happyPlayer = new Player();
    happyPlayer.Morale.Adjust(40);
    happyPlayer.Morale.DecayTowardNeutral(10);
    TestRunner.AreEqual(80.0, happyPlayer.Morale.Level);
    for (int i = 0; i < 20; i++) happyPlayer.Morale.DecayTowardNeutral(10);
    TestRunner.AreEqual(50.0, happyPlayer.Morale.Level, "Decay stops exactly at neutral, never overshoots to the other side");

    var unhappyTeam = new Team();
    unhappyTeam.Morale.Adjust(-30);
    for (int i = 0; i < 40; i++) unhappyTeam.Morale.DecayTowardNeutral(5);
    TestRunner.AreEqual(50.0, unhappyTeam.Morale.Level);
});

TestRunner.Run("Morale reaches the live ball engine: a high-morale batter scores faster than an identical low-morale one, and a high-morale bowler concedes fewer runs", () =>
{
    var simulator = new InningsSimulator();
    var (battingHigh, bowlingForHighBatter) = MatchTestData.MakeEleven("HighMoraleBat", 13, 13);
    var (battingLow, bowlingForLowBatter) = MatchTestData.MakeEleven("LowMoraleBat", 13, 13);

    foreach (var p in battingHigh) p.Morale.Adjust(45);
    foreach (var p in battingLow) p.Morale.Adjust(-45);

    var (fielding, _) = MatchTestData.MakeEleven("Field", 13, 13);
    var setupHigh = new InningsSetup(battingHigh, fielding, fielding.Where(p => p.BowlingRole != BowlingRoleType.NotABowler).ToList());
    var setupLow = new InningsSetup(battingLow, fielding, fielding.Where(p => p.BowlingRole != BowlingRoleType.NotABowler).ToList());

    int highRuns = 0, lowRuns = 0;
    for (int seed = 0; seed < 40; seed++)
    {
        highRuns += simulator.Simulate(setupHigh, MatchFormat.T20, 20, Guid.NewGuid(), "High", Guid.NewGuid(), "Field", new Random(seed)).Runs;
        lowRuns += simulator.Simulate(setupLow, MatchFormat.T20, 20, Guid.NewGuid(), "Low", Guid.NewGuid(), "Field", new Random(seed)).Runs;
    }
    TestRunner.IsTrue(highRuns > lowRuns, $"High morale batters ({highRuns} runs across 40 innings) should outscore identically-skilled low-morale ones ({lowRuns})");
});

await TestRunner.RunAsync("MatchRecorder applies team and player morale from the real result when Team entities are supplied, and leaves morale untouched when they are not", async () =>
{
    var simulator = new MatchSimulator();
    var recorder = new MatchRecorder();

    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("Home", 16, 6);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("Away", 6, 6);
    var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);

    var homeId = Guid.NewGuid(); var awayId = Guid.NewGuid();
    var homeTeam = new Team { Id = homeId, Strength = 70 };
    var awayTeam = new Team { Id = awayId, Strength = 30 };
    var teams = new Dictionary<Guid, Team> { [homeId] = homeTeam, [awayId] = awayTeam };

    var setup = new MatchSetup
    {
        Home = new MatchSide(homeId, "Home", homeOrder, homeBowlers),
        Away = new MatchSide(awayId, "Away", awayOrder, awayBowlers),
        Format = MatchFormat.T20, OversPerInnings = 20, MatchDate = new DateOnly(2026, 7, 4), Season = 2026
    };

    var match = simulator.Simulate(setup, new Random(7));
    recorder.Record(match, allPlayers, random: new Random(7), teams: teams);

    if (match.WinningTeamId is { } winnerId)
    {
        var winnerTeam = teams[winnerId];
        TestRunner.IsTrue(winnerTeam.Morale.Level != 50, "The winning team's morale actually moved from neutral");
    }

    // Without teams supplied, nothing about morale should move at all - full backward compatibility.
    var (homeOrder2, homeBowlers2) = MatchTestData.MakeEleven("Home2", 16, 6);
    var (awayOrder2, awayBowlers2) = MatchTestData.MakeEleven("Away2", 6, 6);
    var allPlayers2 = homeOrder2.Concat(awayOrder2).ToDictionary(p => p.Id);
    var setup2 = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "Home2", homeOrder2, homeBowlers2),
        Away = new MatchSide(Guid.NewGuid(), "Away2", awayOrder2, awayBowlers2),
        Format = MatchFormat.T20, OversPerInnings = 20, MatchDate = new DateOnly(2026, 7, 4), Season = 2026
    };
    var match2 = simulator.Simulate(setup2, new Random(7));
    recorder.Record(match2, allPlayers2, random: new Random(7));

    // PlayerMorale-from-personal-performance needs no Team entity at all (same as Form
    // recording, always unconditional) - it should still have moved. Only TEAM morale actually
    // requires the optional dictionary, since MatchResultContextService needs real Team.Strength.
    TestRunner.IsTrue(allPlayers2.Values.Any(p => p.Morale.Level != 50),
        "Player morale from personal performance applies even without a Team dictionary supplied");

    await Task.CompletedTask;
});

TestRunner.Run("PartnershipChemistryService: a productive, run-out-free stand builds positive chemistry that lowers run-out risk and raises strike rotation; a stand ending in a run-out builds negative chemistry that does the reverse", () =>
{
    var chemistry = new PartnershipChemistryService();
    var strikerA = MatchTestData.MakePlayer("ChemA", 12);
    var goodPartner = MatchTestData.MakePlayer("ChemGood", 12);
    var badPartner = MatchTestData.MakePlayer("ChemBad", 12);

    // No shared history at all - must read as perfectly neutral.
    TestRunner.AreEqual(1.0, chemistry.GetRunOutRiskMultiplier(strikerA, goodPartner.Id));
    TestRunner.AreEqual(1.0, chemistry.GetStrikeRotationMultiplier(strikerA, goodPartner.Id));

    // Several well-paced, run-out-free stands together (well above T20 par of 8/over).
    for (int i = 0; i < 6; i++)
        chemistry.RecordPartnership(strikerA, goodPartner, runs: 40, balls: 24, MatchFormat.T20, endedInRunOut: false);

    // Several stands cut short by a mix-up between this specific pair.
    for (int i = 0; i < 6; i++)
        chemistry.RecordPartnership(strikerA, badPartner, runs: 10, balls: 24, MatchFormat.T20, endedInRunOut: true);

    double goodRisk = chemistry.GetRunOutRiskMultiplier(strikerA, goodPartner.Id);
    double badRisk = chemistry.GetRunOutRiskMultiplier(strikerA, badPartner.Id);
    TestRunner.IsTrue(goodRisk < 1.0, $"A history of clean running together should read as below-average risk (was {goodRisk})");
    TestRunner.IsTrue(badRisk > 1.0, $"A history of run-outs between these two specific players should read as above-average risk (was {badRisk})");
    TestRunner.IsTrue(goodRisk < badRisk, "The well-run pair must carry materially less risk than the mix-up-prone pair");

    double goodRotation = chemistry.GetStrikeRotationMultiplier(strikerA, goodPartner.Id);
    double badRotation = chemistry.GetStrikeRotationMultiplier(strikerA, badPartner.Id);
    TestRunner.IsTrue(goodRotation > 1.0, "Good chemistry should make the pair more willing to take the harder run");
    TestRunner.IsTrue(badRotation < 1.0, "Poor chemistry should make the pair less willing to take the harder run");

    // The relationship is recorded for BOTH players, not just the one passed first.
    double fromTheOtherSide = chemistry.GetRunOutRiskMultiplier(goodPartner, strikerA.Id);
    TestRunner.IsTrue(fromTheOtherSide < 1.0, "Chemistry is mutual - the partner's own record of this pairing should show the same improvement");

    // Decay (MatchupConfidenceService.DecayAll, now wired into WorldClockService's annual
    // rollover) fades a partner-keyed entry the same way every other matchup dimension fades.
    var matchups = new MatchupConfidenceService();
    for (int i = 0; i < 30; i++) matchups.DecayAll(strikerA);
    TestRunner.IsTrue(Math.Abs(chemistry.GetRunOutRiskMultiplier(strikerA, badPartner.Id) - 1.0) < Math.Abs(badRisk - 1.0),
        "Repeated decay must fade a bad partnership's read back toward the neutral 1.0x, not leave it permanent");
});

TestRunner.Run("Strike-rotation chemistry reaches the live ball model: an identical striker takes the harder run more often alongside a partner with a good running history than one with a poor one", () =>
{
    var chemistry = new PartnershipChemistryService();
    var model = new BallOutcomeModel();
    var striker = MatchTestData.MakePlayer("RotationStriker", 12);
    var bowler = MatchTestData.MakePlayer("RotationBowler", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var goodPartner = MatchTestData.MakePlayer("RotationGood", 12);
    var badPartner = MatchTestData.MakePlayer("RotationBad", 12);

    for (int i = 0; i < 8; i++)
        chemistry.RecordPartnership(striker, goodPartner, runs: 45, balls: 24, MatchFormat.T20, endedInRunOut: false);
    for (int i = 0; i < 8; i++)
        chemistry.RecordPartnership(striker, badPartner, runs: 8, balls: 24, MatchFormat.T20, endedInRunOut: true);

    BallContext Ctx(Player? nonStriker) => new() { Striker = striker, Bowler = bowler, Format = MatchFormat.T20, NonStriker = nonStriker };

    double neutralTwo = model.CalculateProbabilities(Ctx(null)).Two;
    double goodTwo = model.CalculateProbabilities(Ctx(goodPartner)).Two;
    double badTwo = model.CalculateProbabilities(Ctx(badPartner)).Two;

    TestRunner.IsTrue(goodTwo > neutralTwo, "A partner with a good running history should raise the chance of taking two, above the no-history baseline");
    TestRunner.IsTrue(badTwo < neutralTwo, "A partner with a poor running history should lower it, below the no-history baseline");
    TestRunner.IsTrue(goodTwo > badTwo, "The well-run pairing must show a genuinely higher two-taking rate than the mix-up-prone pairing");
});

TestRunner.Run("Run-out-risk chemistry reaches the live ball model: across many simulated deliveries, a poor-chemistry pair is run out more often than a good-chemistry pair facing the identical bowler", () =>
{
    var chemistry = new PartnershipChemistryService();
    var model = new BallOutcomeModel();
    var striker = MatchTestData.MakePlayer("RunOutStriker", 10);
    var bowler = MatchTestData.MakePlayer("RunOutBowler", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var goodPartner = MatchTestData.MakePlayer("RunOutGood", 10);
    var badPartner = MatchTestData.MakePlayer("RunOutBad", 10);

    for (int i = 0; i < 8; i++)
        chemistry.RecordPartnership(striker, goodPartner, runs: 45, balls: 24, MatchFormat.T20, endedInRunOut: false);
    for (int i = 0; i < 8; i++)
        chemistry.RecordPartnership(striker, badPartner, runs: 8, balls: 24, MatchFormat.T20, endedInRunOut: true);

    var ctxGood = new BallContext { Striker = striker, Bowler = bowler, Format = MatchFormat.T20, NonStriker = goodPartner };
    var ctxBad = new BallContext { Striker = striker, Bowler = bowler, Format = MatchFormat.T20, NonStriker = badPartner };

    int goodRunOuts = 0, badRunOuts = 0;
    const int trials = 80_000;
    var randomGood = new Random(2026_1);
    var randomBad = new Random(2026_2);
    for (int i = 0; i < trials; i++)
    {
        if (model.SimulateBall(ctxGood, randomGood) is { IsWicket: true, Dismissal: DismissalType.RunOut }) goodRunOuts++;
        if (model.SimulateBall(ctxBad, randomBad) is { IsWicket: true, Dismissal: DismissalType.RunOut }) badRunOuts++;
    }

    TestRunner.IsTrue(badRunOuts > goodRunOuts,
        $"Across {trials} deliveries against the identical bowler, the poor-chemistry pair ({badRunOuts} run-outs) should be run out more often than the good-chemistry pair ({goodRunOuts})");
});

await TestRunner.RunAsync("MatchRecorder folds real partnerships into Player.Matchups under MatchupKey.ForPartner, mutually for both batters, from an actual simulated match", async () =>
{
    var simulator = new MatchSimulator();
