    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("ChemAway", 13, 10);
    var allPlayers = homeOrder.Concat(awayOrder).ToDictionary(p => p.Id);

    var setup = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "ChemHome", homeOrder, homeBowlers),
        Away = new MatchSide(Guid.NewGuid(), "ChemAway", awayOrder, awayBowlers),
        Format = MatchFormat.T20, OversPerInnings = 20, MatchDate = new DateOnly(2026, 8, 1), Season = 2026
    };

    var match = simulator.Simulate(setup, new Random(21));
    recorder.Record(match, allPlayers, random: new Random(21));

    bool anyPartnerKey = allPlayers.Values.Any(p => p.Matchups.Keys.Any(k => k.StartsWith("partner:")));
    TestRunner.IsTrue(anyPartnerKey, "At least one player should have a partner-keyed matchup entry after a real match with real partnerships");

    // Mutuality: for any player with a partner key, the named partner should hold the reverse key.
    var withPartnerKeys = allPlayers.Values.First(p => p.Matchups.Keys.Any(k => k.StartsWith("partner:")));
    var partnerKey = withPartnerKeys.Matchups.Keys.First(k => k.StartsWith("partner:"));
    var partnerId = Guid.Parse(partnerKey["partner:".Length..]);
    TestRunner.IsTrue(allPlayers.TryGetValue(partnerId, out var partner) && partner.Matchups.ContainsKey(MatchupKey.ForPartner(withPartnerKeys.Id)),
        "The named partner's own record should hold the reverse key - chemistry is recorded for both sides of the pairing");

    await Task.CompletedTask;
});

TestRunner.Run("XiSelectionService swaps in enough recognised bowling options to legally cover a T20 innings, even when pure batters rank higher", () =>
{
