TestRunner.Run("XiSelectionService names a real occasional keeper by fielding aptitude when no specialist exists, and flags him as non-specialist", () =>
{
    var svc = new XiSelectionService();
    var aptitude = new FieldingAptitudeService();

    var bestHands = MatchTestData.MakePlayer("BestHands", 16); // highest level in the squad -> best Catching/Reflexes/Positioning too
    var squad = new List<Player> { bestHands };
    for (int i = 0; i < 5; i++) squad.Add(MatchTestData.MakePlayer($"OccBat{i}", 10));
    for (int i = 0; i < 5; i++) squad.Add(MatchTestData.MakePlayer($"OccBowl{i}", 9, PlayerRole.Bowler, BowlingRoleType.FirstChange));

    var result = svc.SelectXi(squad, MatchFormat.T20, new DateOnly(2026, 6, 1));

    TestRunner.IsTrue(result.Wicketkeeper is not null, "A player must always be named to keep wicket when the XI has anyone in it at all");
    TestRunner.IsTrue(!result.IsSpecialistWicketkeeper, "No specialist was in the squad, so the flag must say so");
    TestRunner.AreEqual(bestHands.Id, result.Wicketkeeper!.Id,
        "The best-equipped hands in the actual XI should take the gloves, not an arbitrary outfielder");

    double namedAptitude = aptitude.GetAptitude(result.Wicketkeeper, FieldingPosition.WicketKeeper);
    TestRunner.IsTrue(result.BattingOrder.Where(p => p.Id != result.Wicketkeeper.Id)
            .All(p => aptitude.GetAptitude(p, FieldingPosition.WicketKeeper) <= namedAptitude),
        "Nobody else in the selected XI should out-keep the player actually named");
    TestRunner.IsTrue(result.Reasoning.Any(r => r.Contains("occasional option") || r.Contains("real weak point")),
        "The reasoning should honestly describe this as a stand-in, not silently present him as a real specialist");
});

