TestRunner.Run("XiSelectionService tilts toward spin on a genuinely turning pitch, and toward pace on a genuinely quick one", () =>
{
    var svc = new XiSelectionService();

    // A genuine SURPLUS squad (more than 11 outfield-eligible players) is essential here: with
    // exactly 11 in the pool, "everyone gets picked" would satisfy the assertion trivially
    // without the conditions-tilt code actually having anything to swap.
    var turnerSquad = new List<Player> { MatchTestData.MakePlayer("TiltKeeper", 12, PlayerRole.WicketKeeper) };
    for (int i = 0; i < 6; i++) turnerSquad.Add(MatchTestData.MakePlayer($"TiltBat{i}", 13)); // outrank every bowler
    for (int i = 0; i < 5; i++) turnerSquad.Add(MatchTestData.MakePlayer($"TiltSeam{i}", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler));
    turnerSquad.Add(MatchTestData.MakePlayer("TiltSpin", 7, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner)); // ranks lowest of all - excluded by rank and by the bowling-depth floor alike

    var turner = new Ground { Name = "Turning Track", PitchSpinRating = 82, PitchPaceRating = 30 };
    var turnerResult = svc.SelectXi(turnerSquad, MatchFormat.T20, new DateOnly(2026, 6, 1), ground: turner);
    TestRunner.IsTrue(turnerResult.Bowlers.Any(p => BallOutcomeModel.IsSpinner(p)),
        "A pitch rated 82/100 for spin against 30/100 for pace should pull the lowest-ranked spinner into the XI over a higher-ranked seamer");

    var seamer = new Ground { Name = "Green Top", PitchSpinRating = 25, PitchPaceRating = 85 };
    var seamSquad = new List<Player> { MatchTestData.MakePlayer("TiltKeeper2", 12, PlayerRole.WicketKeeper) };
    for (int i = 0; i < 5; i++) seamSquad.Add(MatchTestData.MakePlayer($"TiltBat2_{i}", 13));
    seamSquad.Add(MatchTestData.MakePlayer("TiltSpinA", 11, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner));
    seamSquad.Add(MatchTestData.MakePlayer("TiltSpinB", 10, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner));
    for (int i = 0; i < 4; i++) seamSquad.Add(MatchTestData.MakePlayer($"TiltSeam2_{i}", 7, PlayerRole.Bowler, BowlingRoleType.OpeningBowler)); // one more seamer than the XI needs, so there is a real spare to swap in

    var seamerResult = svc.SelectXi(seamSquad, MatchFormat.T20, new DateOnly(2026, 6, 1), ground: seamer);
    TestRunner.IsTrue(seamerResult.Bowlers.Count(p => BallOutcomeModel.IsSpinner(p)) <= 1,
        "A pitch rated 85/100 for pace against 25/100 for spin should pull the XI down to at most one spinner, using the spare seamer the squad actually has");
});

