TestRunner.Run("Allrounder-preference rule (batting side): declined under a strict philosophy that requires 'at least as good', accepted once a development-leaning coach's bias closes a small real gap", () =>
{
    var svc = new XiSelectionService();
    var format = MatchFormat.T20;
    var date = new DateOnly(2026, 6, 1);
    var youthCoach = new Coach { Philosophy = CoachingPhilosophy.YouthDevelopment };

    List<Player> BuildSquad()
    {
        var squad = new List<Player> { MatchTestData.MakePlayer("ARBatKeeper", 12, PlayerRole.WicketKeeper) };
        for (int i = 0; i < 4; i++) squad.Add(MatchTestData.MakePlayer($"ARBat{i}", 18 - i)); // comfortably strong, always selected
        squad.Add(MatchTestData.MakePlayer("WeakSpecBat", 9)); // the weakest specialist batter, barely inside
        for (int i = 0; i < 5; i++) squad.Add(MatchTestData.MakePlayer($"ARBowl{i}", 16 - i, PlayerRole.Bowler, BowlingRoleType.FirstChange)); // exactly meets the T20 bowling floor, unrelated to the allrounder question

        // A batting allrounder whose batting is JUST a few points below WeakSpecBat's - genuinely
        // not quite good enough under the spec's literal "at least as good" threshold, but close
        // enough for a development-leaning coach's small bias to bridge. His bowling is
        // deliberately gutted so batting really is his better (primary) discipline.
        var ar = MatchTestData.MakePlayer("BatAllrounder", 9, PlayerRole.BattingAllrounder, BowlingRoleType.PartTimeBowler);
        ar.Batting.Technique = ar.Batting.Timing = ar.Batting.ShotSelection = ar.Batting.DefensiveAbility = 8;
        ar.Batting.Aggression = ar.Batting.AgainstPace = ar.Batting.AgainstSpin = ar.Batting.ShortBallAbility = 8;
        ar.Batting.SwingHandling = ar.Batting.SeamHandling = ar.Batting.SpinHandling = ar.Batting.DeathOverBatting = 8;
        ar.Batting.PowerHitting = ar.Batting.StrikeRotation = ar.Batting.BoundaryHitting = ar.Batting.RiskManagement = 8;
        ar.Bowling.Pace = ar.Bowling.Accuracy = ar.Bowling.Swing = ar.Bowling.Seam = ar.Bowling.Variation = 2;
        ar.Bowling.Yorker = ar.Bowling.Bouncer = ar.Bowling.SlowerBall = ar.Bowling.DeathBowling = 2;
        ar.Bowling.NewBallBowling = ar.Bowling.MiddleOverBowling = ar.Bowling.Containment = ar.Bowling.AttackingAbility = 2;
        ar.RecalculateFormatSuitability();
        squad.Add(ar);
        return squad;
    }

    var balanced = svc.SelectXi(BuildSquad(), format, date);
    TestRunner.IsTrue(!balanced.BattingOrder.Any(p => p.FullName.StartsWith("BatAllrounder")),
        "Under the default (zero-bias) philosophy, a genuinely slightly-worse allrounder should NOT displace the specialist");
    TestRunner.IsTrue(balanced.BattingOrder.Any(p => p.FullName.StartsWith("WeakSpecBat")), "The specialist batter keeps his place");

    var youth = svc.SelectXi(BuildSquad(), format, date, coach: youthCoach);
    TestRunner.IsTrue(youth.BattingOrder.Any(p => p.FullName.StartsWith("BatAllrounder")),
        "A development-leaning coach's small allrounder bias should be enough to bridge this small a gap");
    TestRunner.IsTrue(!youth.BattingOrder.Any(p => p.FullName.StartsWith("WeakSpecBat")), "The specialist he displaces is out");
    TestRunner.IsTrue(youth.Reasoning.Any(r => r.Contains("Preferred the allrounder") && r.Contains("batting")),
        "The reasoning should explain the batting-side preference explicitly");
});

TestRunner.Run("Allrounder-preference rule (bowling side): the mirror case, and never lets the swap break the legal bowling-depth floor", () =>
{
    var svc = new XiSelectionService();
    var format = MatchFormat.T20;
    var date = new DateOnly(2026, 6, 1);
    var youthCoach = new Coach { Philosophy = CoachingPhilosophy.YouthDevelopment };

    List<Player> BuildSquad()
    {
        var squad = new List<Player> { MatchTestData.MakePlayer("ARBowlKeeper", 12, PlayerRole.WicketKeeper) };
        for (int i = 0; i < 4; i++) squad.Add(MatchTestData.MakePlayer($"ARSpecBowl{i}", 18 - i, PlayerRole.Bowler, BowlingRoleType.FirstChange));
        squad.Add(MatchTestData.MakePlayer("WeakSpecBowl", 9, PlayerRole.Bowler, BowlingRoleType.FirstChange)); // the 5th, floor-critical bowler
        for (int i = 0; i < 5; i++) squad.Add(MatchTestData.MakePlayer($"ARBat{i}", 16 - i)); // comfortably strong batters, unrelated

        var ar = MatchTestData.MakePlayer("BowlAllrounder", 9, PlayerRole.BowlingAllrounder, BowlingRoleType.FirstChange);
        ar.Bowling.Pace = ar.Bowling.Accuracy = ar.Bowling.Swing = ar.Bowling.Seam = ar.Bowling.Variation = 8;
        ar.Bowling.Yorker = ar.Bowling.Bouncer = ar.Bowling.SlowerBall = ar.Bowling.DeathBowling = 8;
        ar.Bowling.NewBallBowling = ar.Bowling.MiddleOverBowling = ar.Bowling.Containment = ar.Bowling.AttackingAbility = 8;
        ar.Batting.Technique = ar.Batting.Timing = ar.Batting.ShotSelection = ar.Batting.DefensiveAbility = 2;
        ar.Batting.Aggression = ar.Batting.AgainstPace = ar.Batting.AgainstSpin = ar.Batting.ShortBallAbility = 2;
        ar.Batting.SwingHandling = ar.Batting.SeamHandling = ar.Batting.SpinHandling = ar.Batting.DeathOverBatting = 2;
        ar.Batting.PowerHitting = ar.Batting.StrikeRotation = ar.Batting.BoundaryHitting = ar.Batting.RiskManagement = 2;
        ar.RecalculateFormatSuitability();
        squad.Add(ar);
        return squad;
    }

    var balanced = svc.SelectXi(BuildSquad(), format, date);
    TestRunner.IsTrue(!balanced.BattingOrder.Any(p => p.FullName.StartsWith("BowlAllrounder")), "Not quite good enough under the default philosophy");
    TestRunner.AreEqual(5, balanced.Bowlers.Count, "Bowling floor stays exactly met either way");

    var youth = svc.SelectXi(BuildSquad(), format, date, coach: youthCoach);
    TestRunner.IsTrue(youth.BattingOrder.Any(p => p.FullName.StartsWith("BowlAllrounder")), "The development-leaning bias brings him in on the bowling side");
    TestRunner.IsTrue(!youth.BattingOrder.Any(p => p.FullName.StartsWith("WeakSpecBowl")), "Displacing the weakest specialist bowler");
    TestRunner.AreEqual(5, youth.Bowlers.Count, "The swap must never break the legal T20 bowling-depth floor");
    TestRunner.IsTrue(youth.Reasoning.Any(r => r.Contains("Preferred the allrounder") && r.Contains("bowling")),
        "The reasoning should explain the bowling-side preference explicitly");
});

TestRunner.Run("Pressure handling has the strongest impact on T20 suitability, a real but smaller impact on ODI, for both batting and bowling (user correction)", () =>
{
    Player MakeWithPressure(int pressure)
    {
        var p = MatchTestData.MakePlayer("PressureTest", 12, PlayerRole.BattingAllrounder, BowlingRoleType.FirstChange);
        p.Mental.PressureHandling = pressure;
        p.RecalculateFormatSuitability();
        return p;
    }

    var high = MakeWithPressure(20);
    var low = MakeWithPressure(1);

    double battingT20Gap = high.FormatSuitability.T20Suitability - low.FormatSuitability.T20Suitability;
    double battingOdiGap = high.FormatSuitability.OdiSuitability - low.FormatSuitability.OdiSuitability;
    TestRunner.IsTrue(battingT20Gap > 0, "Better pressure handling should lift T20 batting suitability");
    TestRunner.IsTrue(battingOdiGap > 0, "Better pressure handling should lift ODI batting suitability too");
    TestRunner.IsTrue(battingT20Gap > battingOdiGap, $"T20 batting ({battingT20Gap:F1}) should respond to pressure handling more than ODI batting ({battingOdiGap:F1})");

    double bowlingT20Gap = high.FormatSuitability.T20BowlingSuitability - low.FormatSuitability.T20BowlingSuitability;
    double bowlingOdiGap = high.FormatSuitability.OdiBowlingSuitability - low.FormatSuitability.OdiBowlingSuitability;
    TestRunner.IsTrue(bowlingT20Gap > 0, "Better pressure handling should lift T20 bowling suitability");
    TestRunner.IsTrue(bowlingOdiGap > 0, "Better pressure handling should lift ODI bowling suitability too");
    TestRunner.IsTrue(bowlingT20Gap > bowlingOdiGap, $"T20 bowling ({bowlingT20Gap:F1}) should respond to pressure handling more than ODI bowling ({bowlingOdiGap:F1})");
});

TestRunner.Run("Bowling-side format suitability genuinely differentiates a strong bowler from a weak one, and PlayerSelectionEvaluator.Evaluate(forBowling:) judges each discipline on its own terms", () =>
{
    var strongBowler = MatchTestData.MakePlayer("StrongBowl", 16, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    var weakBowler = MatchTestData.MakePlayer("WeakBowl", 6, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    TestRunner.IsTrue(strongBowler.FormatSuitability.TestBowlingSuitability > weakBowler.FormatSuitability.TestBowlingSuitability, "Test bowling suitability should differentiate strong from weak");
    TestRunner.IsTrue(strongBowler.FormatSuitability.OdiBowlingSuitability > weakBowler.FormatSuitability.OdiBowlingSuitability, "ODI bowling suitability should differentiate strong from weak");
    TestRunner.IsTrue(strongBowler.FormatSuitability.T20BowlingSuitability > weakBowler.FormatSuitability.T20BowlingSuitability, "T20 bowling suitability should differentiate strong from weak");

    var evaluator = new PlayerSelectionEvaluator();
    // Batting genuinely poor (tail-ender), bowling genuinely strong - MakePlayer sets every
    // attribute uniformly to one level, so both sides have to be overridden explicitly to
    // diverge them (the earlier version only lowered three of sixteen batting fields, nowhere
    // near enough to move the batting-side score below the bowling-side one).
    var tailEndBowler = MatchTestData.MakePlayer("TailBowler", 4, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    tailEndBowler.Bowling.Pace = tailEndBowler.Bowling.Accuracy = tailEndBowler.Bowling.Swing = tailEndBowler.Bowling.Seam = 15;
    tailEndBowler.Bowling.Variation = tailEndBowler.Bowling.Yorker = tailEndBowler.Bowling.Bouncer = tailEndBowler.Bowling.SlowerBall = 15;
    tailEndBowler.Bowling.DeathBowling = tailEndBowler.Bowling.NewBallBowling = tailEndBowler.Bowling.MiddleOverBowling = 15;
    tailEndBowler.Bowling.Containment = tailEndBowler.Bowling.AttackingAbility = 15;
    tailEndBowler.RecalculateFormatSuitability();
    double battingScore = evaluator.Evaluate(tailEndBowler, MatchFormat.T20, forBowling: false).TotalScore;
    double bowlingScore = evaluator.Evaluate(tailEndBowler, MatchFormat.T20, forBowling: true).TotalScore;
    TestRunner.IsTrue(bowlingScore > battingScore,
        $"A genuine bowler with poor batting should rate far higher on bowling terms ({bowlingScore:F1}) than batting terms ({battingScore:F1})");
});

TestRunner.Run("XiSelectionService only draws from an announced squad when one is supplied, excluding a genuinely superior player who is not in it", () =>
{
    var svc = new XiSelectionService();
    var squad = new List<Player> { MatchTestData.MakePlayer("SqKeeper", 12, PlayerRole.WicketKeeper) };
    for (int i = 0; i < 6; i++) squad.Add(MatchTestData.MakePlayer($"SqBat{i}", 12));
    for (int i = 0; i < 5; i++) squad.Add(MatchTestData.MakePlayer($"SqBowl{i}", 11, PlayerRole.Bowler, BowlingRoleType.FirstChange));
    var outsider = MatchTestData.MakePlayer("Outsider", 20); // far better than everyone, but never announced

    var announcement = new SquadAnnouncement { TeamId = Guid.NewGuid(), IsHomeSeries = true };
    announcement.Announce(squad.Select(p => p.Id));

    var pool = squad.Concat(new[] { outsider }).ToList();
    var result = svc.SelectXi(pool, MatchFormat.T20, new DateOnly(2026, 6, 1), announcedSquad: announcement);

    TestRunner.IsTrue(!result.BattingOrder.Any(p => p.Id == outsider.Id), "A player outside the announced squad can never be selected, however good he is");
    TestRunner.IsTrue(result.Reasoning.Any(r => r.Contains("announced squad")), "The restriction should be stated, not silent");
});

TestRunner.Run("SquadAnnouncement mid-series replacement is eligible only from the next match, never the one already in progress, and only for a home bilateral series", () =>
{
    var teamId = Guid.NewGuid();
    var outId = Guid.NewGuid(); var inId = Guid.NewGuid();
    var announcement = new SquadAnnouncement { TeamId = teamId, IsHomeSeries = true };
    announcement.Announce(new[] { outId });

    var requestedDate = new DateOnly(2026, 6, 10);
    var nextMatchDate = new DateOnly(2026, 6, 17);
    announcement.RegisterMidSeriesReplacement(outId, inId, "injury", requestedDate, nextMatchDate);

    TestRunner.IsTrue(!announcement.IsEligibleForMatch(inId, requestedDate), "The replacement cannot play the match already in progress");
    TestRunner.IsTrue(!announcement.IsEligibleForMatch(inId, requestedDate.AddDays(3)), "Nor any match still before the effective date");
    TestRunner.IsTrue(announcement.IsEligibleForMatch(inId, nextMatchDate), "He is eligible from the declared next match onward");
    TestRunner.IsTrue(announcement.IsEligibleForMatch(outId, requestedDate), "The outgoing player was, and remains, eligible for matches before the replacement");

    bool threwForAway = false;
    var awayAnnouncement = new SquadAnnouncement { TeamId = teamId, IsHomeSeries = false };
    awayAnnouncement.Announce(new[] { outId });
    try { awayAnnouncement.RegisterMidSeriesReplacement(outId, inId, "injury", requestedDate, nextMatchDate); }
    catch (InvalidOperationException) { threwForAway = true; }
    TestRunner.IsTrue(threwForAway, "Mid-series replacement must be refused for an away series");

    bool threwForTournament = false;
    var tournamentAnnouncement = new SquadAnnouncement { TeamId = teamId, IsTournamentSquad = true, PlayerCap = 15 };
    tournamentAnnouncement.Announce(new[] { outId });
    try { tournamentAnnouncement.RegisterMidSeriesReplacement(outId, inId, "injury", requestedDate, nextMatchDate); }
    catch (InvalidOperationException) { threwForTournament = true; }
    TestRunner.IsTrue(threwForTournament, "Mid-series replacement must be refused for a tournament squad - it uses reserves instead");
});

TestRunner.Run("SquadAnnouncement tournament reserve promotion is immediate, unlike a home-series mid-series replacement", () =>
{
    var outId = Guid.NewGuid(); var reserveId = Guid.NewGuid();
    var announcement = new SquadAnnouncement { TeamId = Guid.NewGuid(), IsTournamentSquad = true, PlayerCap = 15 };
    announcement.Announce(new[] { outId }, new[] { reserveId });

    TestRunner.IsTrue(announcement.ReservePlayerIds.Contains(reserveId), "The reserve should be listed before promotion");
    TestRunner.IsTrue(!announcement.IsEligibleForMatch(reserveId, new DateOnly(2026, 6, 1)), "A reserve is not eligible until promoted");

    announcement.PromoteReserve(outId, reserveId, "injury", new DateOnly(2026, 6, 5));

    TestRunner.IsTrue(!announcement.ReservePlayerIds.Contains(reserveId), "No longer a reserve once promoted");
    TestRunner.IsTrue(!announcement.PlayerIds.Contains(outId), "The outgoing player leaves the squad");
    TestRunner.IsTrue(announcement.IsEligibleForMatch(reserveId, new DateOnly(2026, 6, 5)), "Promotion is effective immediately, unlike a home-series mid-series replacement");
});

TestRunner.Run("SquadSelectionService flags a genuine composition problem - no keeper, over cap, thin bowling depth, no credible backup - without inventing false positives for a well-built squad", () =>
{
    var svc = new SquadSelectionService();

    // Zero keepers AND over a tournament cap - both hard violations at once.
    var badSquad = new List<Player>();
    for (int i = 0; i < 11; i++) badSquad.Add(MatchTestData.MakePlayer($"NK{i}", 12));
    var badAnnouncement = new SquadAnnouncement { TeamId = Guid.NewGuid(), IsTournamentSquad = true, PlayerCap = 10 };
    badAnnouncement.Announce(badSquad.Select(p => p.Id));
    var badById = badSquad.ToDictionary(p => p.Id);
    var badReport = svc.ValidateComposition(badAnnouncement, badById, MatchFormat.T20, isAwayOrTournament: true);
    TestRunner.IsTrue(!badReport.IsValid, "Zero specialist keepers and an over-cap squad must both read as invalid");
    TestRunner.IsTrue(badReport.Notes.Any(n => n.Contains("cap")), "Should explicitly flag the cap violation");
    TestRunner.IsTrue(badReport.Notes.Any(n => n.Contains("wicketkeeper")), "Should explicitly flag the missing keeper");

    // A genuinely well-built squad: one keeper, real bowling depth (>= T20 floor + 2), several credible batters and bowlers.
    var goodSquad = new List<Player> { MatchTestData.MakePlayer("GoodKeeper", 12, PlayerRole.WicketKeeper) };
    for (int i = 0; i < 6; i++) goodSquad.Add(MatchTestData.MakePlayer($"GoodBat{i}", 14));
    for (int i = 0; i < 7; i++) goodSquad.Add(MatchTestData.MakePlayer($"GoodBowl{i}", 13, PlayerRole.Bowler, BowlingRoleType.FirstChange));
    var goodAnnouncement = new SquadAnnouncement { TeamId = Guid.NewGuid(), IsHomeSeries = true };
    goodAnnouncement.Announce(goodSquad.Select(p => p.Id));
    var goodById = goodSquad.ToDictionary(p => p.Id);
    var goodReport = svc.ValidateComposition(goodAnnouncement, goodById, MatchFormat.T20, isAwayOrTournament: false);
    TestRunner.IsTrue(goodReport.IsValid, "A genuinely well-built squad should not be flagged invalid");
    TestRunner.AreEqual(0, goodReport.Notes.Count, $"A genuinely well-built squad should carry no composition notes at all, got: {string.Join(" | ", goodReport.Notes)}");

    // A thin squad: one keeper on an away tour (a real risk, still legal), thin bowling depth, one credible batter.
    var thinSquad = new List<Player> { MatchTestData.MakePlayer("ThinKeeper", 9, PlayerRole.WicketKeeper) };
    thinSquad.Add(MatchTestData.MakePlayer("ThinStar", 16));
    for (int i = 0; i < 4; i++) thinSquad.Add(MatchTestData.MakePlayer($"ThinWeak{i}", 4));
    for (int i = 0; i < 3; i++) thinSquad.Add(MatchTestData.MakePlayer($"ThinBowl{i}", 5, PlayerRole.Bowler, BowlingRoleType.FirstChange));
    var thinAnnouncement = new SquadAnnouncement { TeamId = Guid.NewGuid() };
    thinAnnouncement.Announce(thinSquad.Select(p => p.Id));
    var thinById = thinSquad.ToDictionary(p => p.Id);
    var thinReport = svc.ValidateComposition(thinAnnouncement, thinById, MatchFormat.T20, isAwayOrTournament: true);
    TestRunner.IsTrue(thinReport.IsValid, "A single keeper for an away tour is a real risk, not an illegal squad");
    TestRunner.IsTrue(thinReport.Notes.Any(n => n.Contains("specialist wicketkeeper")), "Should note the single-keeper-on-tour risk");
    TestRunner.IsTrue(thinReport.Notes.Any(n => n.Contains("bowling-capable")), "Should note the thin squad bowling depth");
    TestRunner.IsTrue(thinReport.Notes.Any(n => n.Contains("credible batting option")), "Should note the single point of failure in batting");
});

TestRunner.Run("SquadSelectionAuthorityService always surfaces a captain's proposal to a human coach, but genuinely evaluates it for an AI coach", () =>
{
    var svc = new SquadSelectionAuthorityService();
    var strongBatter = MatchTestData.MakePlayer("StrongProposed", 16);
    var weakBatter = MatchTestData.MakePlayer("WeakProposed", 4);
    var currentSquadBatters = new List<Player> { MatchTestData.MakePlayer("Incumbent1", 13), MatchTestData.MakePlayer("Incumbent2", 12) };

    var humanResult = svc.EvaluateProposal(weakBatter, currentSquadBatters, MatchFormat.T20, coachIsHuman: true);
    TestRunner.IsTrue(humanResult.AcceptedIntoConsideration, "A human coach always gets the proposal surfaced, regardless of how the numbers read");
    TestRunner.IsTrue(humanResult.Explanation.Contains("human coach"), "The explanation should be clear this is advisory, not a verdict");

    var aiRejected = svc.EvaluateProposal(weakBatter, currentSquadBatters, MatchFormat.T20, coachIsHuman: false);
    TestRunner.IsTrue(!aiRejected.AcceptedIntoConsideration, "An AI coach should genuinely reject a request that falls well short of the squad's own weakest comparable option");

    var aiAccepted = svc.EvaluateProposal(strongBatter, currentSquadBatters, MatchFormat.T20, coachIsHuman: false);
    TestRunner.IsTrue(aiAccepted.AcceptedIntoConsideration, "An AI coach should accept a request that is at least reasonably close to the squad's own standard");
});

TestRunner.Run("RetirementService.AssessFormatRetirement: Test cricket's own age curve runs meaningfully ahead of T20's for the same player, and an already-retired format short-circuits to zero", () =>
{
    var retirement = new RetirementService();
    var asOf = new DateOnly(2026, 6, 1);

    var veteran = MatchTestData.MakePlayer("Veteran", 12);
    veteran.DateOfBirth = new DateOnly(1988, 1, 1); // 38 as of asOf

    var testAssessment = retirement.AssessFormatRetirement(veteran, MatchFormat.Test, asOf, matchesInFormatLastSeason: null, new Random(1));
    var t20Assessment = retirement.AssessFormatRetirement(veteran, MatchFormat.T20, asOf, matchesInFormatLastSeason: null, new Random(1));

    TestRunner.IsTrue(testAssessment.Probability > t20Assessment.Probability,
        $"At 38, Test retirement ({testAssessment.Probability}) should read as meaningfully more likely than T20 retirement ({t20Assessment.Probability}) - Test is the format players step back from first");

    veteran.RetiredFormats.Add(MatchFormat.Test);
    var alreadyGone = retirement.AssessFormatRetirement(veteran, MatchFormat.Test, asOf, null, new Random(1));
    TestRunner.AreEqual(0.0, alreadyGone.Probability, "Already retired from this format - nothing left to assess");
    TestRunner.IsTrue(!alreadyGone.ShouldRetire, "Already retired from this format - can't retire from it again");
});

TestRunner.Run("RetirementService.RetireFromFormat: a player who has stepped back from Test only is NOT fully retired, but retiring from all three completes the career via the same Retire() side effects", () =>
{
    var retirement = new RetirementService();
    var date = new DateOnly(2026, 6, 1);
    var player = MatchTestData.MakePlayer("Staged", 12);
    player.CurrentTeamId = Guid.NewGuid();

    retirement.RetireFromFormat(player, MatchFormat.Test, date);
    TestRunner.IsTrue(!player.IsRetired, "Retiring from Test alone must not end the whole career");
    TestRunner.IsTrue(player.RetiredFormats.Contains(MatchFormat.Test), "The format should be recorded");
    TestRunner.IsTrue(player.CurrentTeamId is not null, "Still an active white-ball player, still on a team's books");

    retirement.RetireFromFormat(player, MatchFormat.ODI, date);
    TestRunner.IsTrue(!player.IsRetired, "Two of three formats gone - still not the whole career");

    retirement.RetireFromFormat(player, MatchFormat.T20, date);
    TestRunner.IsTrue(player.IsRetired, "All three formats retired IS the whole career, by definition");
    TestRunner.AreEqual(date, player.RetirementDate);
    TestRunner.IsTrue(player.CurrentTeamId is null, "Full retirement carries the same side effects Retire() always applied");
});

TestRunner.Run("PlayerAvailabilityService.GetAvailability(format:) treats a Test-retired player as unavailable for Test but fully available for ODI/T20", () =>
{
    var availability = new PlayerAvailabilityService();
    var date = new DateOnly(2026, 6, 1);
