    var odiResult = availability.GetAvailability(player, date, MatchFormat.ODI);
    TestRunner.IsTrue(odiResult.IsAvailable, "Still a fully active ODI cricketer");

    var t20Result = availability.GetAvailability(player, date, MatchFormat.T20);
    TestRunner.IsTrue(t20Result.IsAvailable, "Still a fully active T20 cricketer");

    var noFormatResult = availability.GetAvailability(player, date);
    TestRunner.IsTrue(noFormatResult.IsAvailable, "With no format specified, only whole-career retirement is checked - a pre-existing caller's behaviour must be unaffected");
});

TestRunner.Run("XiSelectionService excludes a Test-retired player from a Test XI but still selects him for a T20 XI from the same squad", () =>
{
    var svc = new XiSelectionService();
