await TestRunner.RunAsync("WorldClockService's annual rollover produces genuine staged retirement over enough years: some ageing players step back from Test while remaining active in white-ball, distinctly from full retirement", async () =>
{
    var calendar = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 777);
    var clock = new WorldClockService();
    var seeder = new WorldSeeder(seed: 55, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 6, squadSize: 16);

    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>()
    };

    // Eighteen years - enough for a real cohort to age through both stages. Checking events
    // fired DURING the run, not just the final snapshot, is deliberate: a staged retirement is
    // often a transient state (the remaining formats tend to follow a Test step-back within a
    // few more years), so a player caught mid-transition at the exact end date is genuine but
    // not guaranteed for any specific seed/cohort - whether the MECHANISM fired at all during
    // eighteen years is the real, robust thing to check.
    var events = clock.AdvanceTo(calendar, world, new DateOnly(2044, 6, 1)).ToList();
    var formatRetirements = events.Where(e => e.Type == GameEventType.PlayerRetired && e.Headline.Contains("continuing to play elsewhere")).ToList();

    TestRunner.IsTrue(formatRetirements.Count > 0,
        "Across eighteen years and a real cohort, at least one genuine format-specific step-back (not a full retirement) should occur");

    int testStepbacks = formatRetirements.Count(e => e.Headline.Contains("Test cricket"));
    int t20Stepbacks = formatRetirements.Count(e => e.Headline.Contains("T20 cricket"));
    TestRunner.IsTrue(testStepbacks >= t20Stepbacks,
        $"Test cricket should account for at least as many format-specific step-backs ({testStepbacks}) as T20 ({t20Stepbacks}) - it is the format players leave first");

    TestRunner.IsTrue(players.Where(p => p.IsRetired).All(p =>
            p.RetiredFormats.Contains(MatchFormat.Test) && p.RetiredFormats.Contains(MatchFormat.ODI) && p.RetiredFormats.Contains(MatchFormat.T20)),
        "Every fully retired player's RetiredFormats should cover all three - full retirement is never a shortcut around the per-format record");

    await Task.CompletedTask;
});

TestRunner.Run("DeliveryEffectService.DismissalWeightsFor: a yorker genuinely skews the dismissal mix toward bowled/lbw and away from caught, now that the live model actually reads it", () =>
{
    var striker = MatchTestData.MakePlayer("PatternStriker", 12);
    var bowler = MatchTestData.MakePlayer("PatternBowler", 12, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    var pitch = new PitchConditions(50, 50, 50, 50);

    var yorker = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Yorker, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);
    var goodLength = new ExecutedDelivery(BowlingLine.FourthStump, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);

    var yorkerWeights = DeliveryEffectService.DismissalWeightsFor(yorker, striker, bowler, pitch);
    var goodWeights = DeliveryEffectService.DismissalWeightsFor(goodLength, striker, bowler, pitch);

    double yorkerBowledLbwShare = (yorkerWeights[DismissalType.Bowled] + yorkerWeights[DismissalType.LBW]) / yorkerWeights.Values.Sum();
    double goodBowledLbwShare = (goodWeights[DismissalType.Bowled] + goodWeights[DismissalType.LBW]) / goodWeights.Values.Sum();

    TestRunner.IsTrue(yorkerBowledLbwShare > goodBowledLbwShare,
        $"A yorker's bowled+lbw share ({yorkerBowledLbwShare:P0}) should exceed a good-length ball's ({goodBowledLbwShare:P0})");
});

TestRunner.Run("DeliveryEffectService pattern-reading: a switched-on batter cashes in on a predictable continuation, and reads a genuine change-up better than a flat-footed one would", () =>
{
    var bowler = MatchTestData.MakePlayer("ReadBowler", 12, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    var pitch = new PitchConditions(50, 50, 50, 50);
    var established = new[] { (BowlingLine.FourthStump, BowlingLength.Good), (BowlingLine.FourthStump, BowlingLength.Good), (BowlingLine.FourthStump, BowlingLength.Good) };

    var sharpBatter = MatchTestData.MakePlayer("SharpBatter", 12);
    sharpBatter.Mental.GameAwareness = 20;
    var flatFooted = MatchTestData.MakePlayer("FlatBatter", 12);
    flatFooted.Mental.GameAwareness = 1;

    // Continuation: the same line/length as the established pattern.
    var continuation = new ExecutedDelivery(BowlingLine.FourthStump, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);
    var sharpCalcContinuation = new DeliveryEffectService().Calculate(continuation, sharpBatter, bowler, pitch, established);
    var flatCalcContinuation = new DeliveryEffectService().Calculate(continuation, flatFooted, bowler, pitch, established);
    TestRunner.IsTrue(sharpCalcContinuation.BoundaryScale > flatCalcContinuation.BoundaryScale,
        "A switched-on batter should cash in on a predictable continuation more than a flat-footed one");

    // Change-up: a genuinely different line from the established pattern - the setup ball.
    // Breaks BOTH line and length from the established FourthStump/Good pattern, deliberately -
    // changing only one dimension would still read as a "continuation" on the other (the
    // production code's own precedence: continuing EITHER axis counts as predictable), so a
    // clean, unambiguous change-up has to differ on both to isolate the branch being tested.
    var changeUp = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Yorker, DeliveryVariation.None, 1.0, PlanDeviationReason.ReadTheBatter);
    var sharpCalcChangeUp = new DeliveryEffectService().Calculate(changeUp, sharpBatter, bowler, pitch, established);
    var flatCalcChangeUp = new DeliveryEffectService().Calculate(changeUp, flatFooted, bowler, pitch, established);
    TestRunner.IsTrue(sharpCalcChangeUp.WicketScale < flatCalcChangeUp.WicketScale,
        "A switched-on batter should read a genuine change-up and carry less wicket risk from it than a flat-footed one");

    // No established pattern (fewer than 3 recent deliveries) - no effect either way.
    var noPattern = new DeliveryEffectService().Calculate(changeUp, sharpBatter, bowler, pitch, new[] { (BowlingLine.FourthStump, BowlingLength.Good) });
    var noPatternBaseline = new DeliveryEffectService().Calculate(changeUp, sharpBatter, bowler, pitch, null);
    TestRunner.AreEqual(noPatternBaseline.WicketScale, noPattern.WicketScale, "Fewer than three recent deliveries is not an established pattern - no read to apply");
});

TestRunner.Run("DeliveryEffectService.DismissalWeightsFor: off-spin turns into a right-hander and away from a left-hander, leg-spin mirrors it - Section Y", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var ball = new ExecutedDelivery(BowlingLine.FourthStump, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);

    var offSpinner = MatchTestData.MakePlayer("OffSpinner", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    offSpinner.BowlingStyle = BowlingStyle.RightArmOffSpin;

    Player Batter(string name, BattingHand hand, int spinHandling)
    {
        var p = MatchTestData.MakePlayer(name, 10);
        p.BattingHand = hand;
        p.Batting.SpinHandling = spinHandling;
        return p;
    }

    var rightHander = Batter("RHB", BattingHand.Right, 1);
    var leftHander = Batter("LHB", BattingHand.Left, 1);

    var rhbWeights = DeliveryEffectService.DismissalWeightsFor(ball, rightHander, offSpinner, pitch);
    var lhbWeights = DeliveryEffectService.DismissalWeightsFor(ball, leftHander, offSpinner, pitch);

    double EdgeShare(IReadOnlyDictionary<DismissalType, double> w) => (w[DismissalType.Caught] + w[DismissalType.CaughtBehind]) / w.Values.Sum();
    double StumpsShare(IReadOnlyDictionary<DismissalType, double> w) => (w[DismissalType.Bowled] + w[DismissalType.LBW]) / w.Values.Sum();

    TestRunner.IsTrue(EdgeShare(lhbWeights) > EdgeShare(rhbWeights),
        $"Off-spin turning away from a left-hander should carry a bigger edge share ({EdgeShare(lhbWeights):P0}) than turning into a right-hander ({EdgeShare(rhbWeights):P0})");
    TestRunner.IsTrue(StumpsShare(rhbWeights) > StumpsShare(lhbWeights),
        $"Off-spin turning into a right-hander should carry a bigger bowled+lbw share ({StumpsShare(rhbWeights):P0}) than turning away from a left-hander ({StumpsShare(lhbWeights):P0})");

    // Leg-spin is the mirror image: away from the right-hander, into the left-hander.
    var legSpinner = MatchTestData.MakePlayer("LegSpinner", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    legSpinner.BowlingStyle = BowlingStyle.RightArmLegSpin;

    var legRhbWeights = DeliveryEffectService.DismissalWeightsFor(ball, rightHander, legSpinner, pitch);
    var legLhbWeights = DeliveryEffectService.DismissalWeightsFor(ball, leftHander, legSpinner, pitch);

    TestRunner.IsTrue(EdgeShare(legRhbWeights) > EdgeShare(legLhbWeights),
        "Leg-spin should mirror off-spin: turning away from a right-hander carries the bigger edge share");

    // A batter who reads the turn well is not exposed by it either way - the gap should shrink.
    var sharpReader = Batter("SharpReader", BattingHand.Left, 20);
    var sharpWeights = DeliveryEffectService.DismissalWeightsFor(ball, sharpReader, offSpinner, pitch);
    double flatFootedGap = EdgeShare(lhbWeights) - EdgeShare(rhbWeights);
    double sharpGap = EdgeShare(sharpWeights) - EdgeShare(rhbWeights);
    TestRunner.IsTrue(sharpGap < flatFootedGap,
        "A left-hander with strong SpinHandling should be exposed less by the turn-away than a flat-footed one");
});

TestRunner.Run("DeliveryEffectService.ApplyBowlingAngle: round the wicket to an opposite-handed batter attacks the stumps/pads, over the wicket carries toward the cordon - Sections 8/9", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var goodLength = new ExecutedDelivery(BowlingLine.FourthStump, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);
    var roundTheWicket = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Good, DeliveryVariation.RoundTheWicket, 1.0, PlanDeviationReason.Followed);

    var rightArmQuick = MatchTestData.MakePlayer("Quick", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    rightArmQuick.BowlingStyle = BowlingStyle.RightArmFast;

    var leftHander = MatchTestData.MakePlayer("LHB", 12);
    leftHander.BattingHand = BattingHand.Left;
    var rightHander = MatchTestData.MakePlayer("RHB", 12);
    rightHander.BattingHand = BattingHand.Right;

    double EdgeShare(IReadOnlyDictionary<DismissalType, double> w) => (w[DismissalType.Caught] + w[DismissalType.CaughtBehind]) / w.Values.Sum();
    double StumpsShare(IReadOnlyDictionary<DismissalType, double> w) => (w[DismissalType.Bowled] + w[DismissalType.LBW]) / w.Values.Sum();

    // Right-arm quick to a LEFT-hander is the opposite-handed pairing - the classic case.
    var overTheWicketToLefty = DeliveryEffectService.DismissalWeightsFor(goodLength, leftHander, rightArmQuick, pitch);
    var roundTheWicketToLefty = DeliveryEffectService.DismissalWeightsFor(roundTheWicket, leftHander, rightArmQuick, pitch);

    TestRunner.IsTrue(StumpsShare(roundTheWicketToLefty) > StumpsShare(overTheWicketToLefty),
        $"Round the wicket to an opposite-handed batter should carry a bigger bowled+lbw share ({StumpsShare(roundTheWicketToLefty):P0}) than the standard over-the-wicket angle ({StumpsShare(overTheWicketToLefty):P0})");
    TestRunner.IsTrue(EdgeShare(overTheWicketToLefty) > EdgeShare(roundTheWicketToLefty),
        "The standard over-the-wicket angle to an opposite-handed batter should carry the bigger edge share, not the cramping round-the-wicket angle");

    // Right-arm quick to a RIGHT-hander is the SAME-handed pairing - round the wicket here is a
    // genuine but far less standardised change of angle, so the shift should be much smaller.
    var overTheWicketToRighty = DeliveryEffectService.DismissalWeightsFor(goodLength, rightHander, rightArmQuick, pitch);
    var roundTheWicketToRighty = DeliveryEffectService.DismissalWeightsFor(roundTheWicket, rightHander, rightArmQuick, pitch);
    double oppositeHandedShift = StumpsShare(roundTheWicketToLefty) - StumpsShare(overTheWicketToLefty);
    double sameHandedShift = StumpsShare(roundTheWicketToRighty) - StumpsShare(overTheWicketToRighty);
    TestRunner.IsTrue(oppositeHandedShift > sameHandedShift,
        "The opposite-handed round-the-wicket shift should be materially bigger than the same-handed one - there is no single real-world signature for the same-handed case the way there is for the opposite-handed one");

    // A left-arm bowler is the exact mirror: round the wicket to a RIGHT-hander is now the
    // opposite-handed, cramping case.
    var leftArmQuick = MatchTestData.MakePlayer("LeftArmQuick", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    leftArmQuick.BowlingStyle = BowlingStyle.LeftArmFast;
    var overToRighty = DeliveryEffectService.DismissalWeightsFor(goodLength, rightHander, leftArmQuick, pitch);
    var roundToRighty = DeliveryEffectService.DismissalWeightsFor(roundTheWicket, rightHander, leftArmQuick, pitch);
    TestRunner.IsTrue(StumpsShare(roundToRighty) > StumpsShare(overToRighty),
        "A left-arm bowler round the wicket to a right-hander is the mirror opposite-handed case and should show the same cramping effect");

    // No BowlingStyle on record (e.g. a raw test fixture) - no claim to make, exact no-op. Compares
    // the SAME line with only the variation toggled, otherwise the line switch's own, unrelated
    // bowled/lbw bias would swamp the comparison.
    var noStyleBowler = MatchTestData.MakePlayer("NoStyle", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var neutralOver = roundTheWicket with { Variation = DeliveryVariation.None };
    var neutralWeights = DeliveryEffectService.DismissalWeightsFor(neutralOver, leftHander, noStyleBowler, pitch);
    var neutralRoundWeights = DeliveryEffectService.DismissalWeightsFor(roundTheWicket, leftHander, noStyleBowler, pitch);
    TestRunner.AreEqual(StumpsShare(neutralWeights), StumpsShare(neutralRoundWeights),
        "With no BowlingStyle on record, round-the-wicket must be a genuine no-op rather than a guessed effect");
});

TestRunner.Run("DeliveryEffectService zone bias: bowling angle compounds with line - round the wicket to an opposite-handed batter pushes scoring toward the leg side, over the wicket toward the off side", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var service = new DeliveryEffectService();
    var overTheWicket = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);
    var roundTheWicket = overTheWicket with { Variation = DeliveryVariation.RoundTheWicket };

    var rightArmQuick = MatchTestData.MakePlayer("Quick", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    rightArmQuick.BowlingStyle = BowlingStyle.RightArmFast;
    var leftHander = MatchTestData.MakePlayer("LHB", 12);
    leftHander.BattingHand = BattingHand.Left;

    var overEffect = service.Calculate(overTheWicket, leftHander, rightArmQuick, pitch);
    var roundEffect = service.Calculate(roundTheWicket, leftHander, rightArmQuick, pitch);

    TestRunner.IsTrue(roundEffect.ZoneBias[ShotZone.SquareLeg] > overEffect.ZoneBias[ShotZone.SquareLeg],
        "Round the wicket to an opposite-handed batter should bias scoring toward the leg side more than over the wicket");
    TestRunner.IsTrue(overEffect.ZoneBias[ShotZone.Cover] > roundEffect.ZoneBias[ShotZone.Cover] || overEffect.ZoneBias[ShotZone.Point] > roundEffect.ZoneBias[ShotZone.Point],
        "Over the wicket to an opposite-handed batter should bias scoring toward the off side more than round the wicket");
});

TestRunner.Run("PlanFitService rewards AngleTheCrease against an opposite-handed batter and not a same-handed one - Sections 8/9", () =>
{
    var fit = new PlanFitService();
    var pitch = new PitchConditions(50, 50, 50, 50);

    var rightArmQuick = MatchTestData.MakePlayer("Quick", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    rightArmQuick.BowlingStyle = BowlingStyle.RightArmFast;

    var leftHander = MatchTestData.MakePlayer("LHB", 12);
    leftHander.BattingHand = BattingHand.Left;
    var rightHander = MatchTestData.MakePlayer("RHB", 12);
    rightHander.BattingHand = BattingHand.Right;

    var weaknessVsLefty = fit.ExploitsWeakness(leftHander, rightArmQuick, BowlingApproach.AngleTheCrease, pitch);
    var weaknessVsRighty = fit.ExploitsWeakness(rightHander, rightArmQuick, BowlingApproach.AngleTheCrease, pitch);

    TestRunner.IsTrue(weaknessVsLefty > weaknessVsRighty,
        $"AngleTheCrease should score as a materially better plan against an opposite-handed batter ({weaknessVsLefty:F2}) than a same-handed one ({weaknessVsRighty:F2})");

    // And it genuinely reaches RankPlans, not just the raw ExploitsWeakness helper.
    var ranked = fit.RankPlans(rightArmQuick, leftHander, pitch, MatchPhase.MiddleOvers, MatchFormat.Test);
    TestRunner.IsTrue(ranked.Any(r => r.Approach.Variation == DeliveryVariation.RoundTheWicket),
        "AngleTheCrease should appear among the candidate plans a pace bowler is offered");
});

TestRunner.Run("DeliveryEffectService: SwingHandling and SeamHandling - dead-attribute fix, Section Y/Z", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var service = new DeliveryEffectService();
    var ball = new ExecutedDelivery(BowlingLine.FourthStump, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);

    var swingBowler = MatchTestData.MakePlayer("SwingBowler", 16, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    swingBowler.Bowling.Swing = 18;
    swingBowler.Bowling.Seam = 4;

    var poorHandler = MatchTestData.MakePlayer("PoorHandler", 10);
    poorHandler.Batting.SwingHandling = 1;
    var goodHandler = MatchTestData.MakePlayer("GoodHandler", 10);
    goodHandler.Batting.SwingHandling = 20;

    var poorEffect = service.Calculate(ball, poorHandler, swingBowler, pitch, ballAge: 0);
    var goodEffect = service.Calculate(ball, goodHandler, swingBowler, pitch, ballAge: 0);
    TestRunner.IsTrue(poorEffect.WicketScale > goodEffect.WicketScale,
        $"Against a genuine new-ball swing bowler, poor SwingHandling ({poorEffect.WicketScale:F2}) should carry more wicket risk than good SwingHandling ({goodEffect.WicketScale:F2})");

    // The threat fades as the ball wears - by 300 legal balls swing is long gone.
    var poorEffectOldBall = service.Calculate(ball, poorHandler, swingBowler, pitch, ballAge: 300);
    double newBallGap = poorEffect.WicketScale - goodEffect.WicketScale;
    double oldBallGap = poorEffectOldBall.WicketScale - service.Calculate(ball, goodHandler, swingBowler, pitch, ballAge: 300).WicketScale;
    TestRunner.IsTrue(oldBallGap < newBallGap,
        "An old, worn ball offers far less swing, so the SwingHandling gap should shrink towards nothing");

    var seamBowler = MatchTestData.MakePlayer("SeamBowler", 16, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    seamBowler.Bowling.Swing = 4;
    seamBowler.Bowling.Seam = 18;

    var poorSeamHandler = MatchTestData.MakePlayer("PoorSeamHandler", 10);
    poorSeamHandler.Batting.SeamHandling = 1;
    var goodSeamHandler = MatchTestData.MakePlayer("GoodSeamHandler", 10);
    goodSeamHandler.Batting.SeamHandling = 20;

    var poorSeamEffect = service.Calculate(ball, poorSeamHandler, seamBowler, pitch, ballAge: 0);
    var goodSeamEffect = service.Calculate(ball, goodSeamHandler, seamBowler, pitch, ballAge: 0);
    TestRunner.IsTrue(poorSeamEffect.WicketScale > goodSeamEffect.WicketScale,
        $"Against genuine seam movement, poor SeamHandling ({poorSeamEffect.WicketScale:F2}) should carry more wicket risk than good SeamHandling ({goodSeamEffect.WicketScale:F2})");

    // A spinner creates neither kind of threat - the swing/seam machinery must be a no-op for one.
    var spinner = MatchTestData.MakePlayer("SomeSpinner", 16, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    var spinPoorHandler = MatchTestData.MakePlayer("SpinPoorSwing", 10);
    spinPoorHandler.Batting.SwingHandling = 1;
    var spinGoodHandler = MatchTestData.MakePlayer("SpinGoodSwing", 10);
    spinGoodHandler.Batting.SwingHandling = 20;
    TestRunner.AreEqual(
        service.Calculate(ball, spinGoodHandler, spinner, pitch, ballAge: 0).WicketScale,
        service.Calculate(ball, spinPoorHandler, spinner, pitch, ballAge: 0).WicketScale,
        "SwingHandling should have no effect at all against a genuine spinner");
});

TestRunner.Run("BowlerExecutionService: a bowler who has built real pressure sometimes escalates to a deliberate trap ball shaped by what he has actually just bowled", () =>
{
    var execution = new BowlerExecutionService();
    var bowler = MatchTestData.MakePlayer("SmartBowler", 16, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    bowler.Mental.GameAwareness = 19; bowler.Mental.DecisionMaking = 19;
    for (int i = 0; i < 100; i++) bowler.Experience.RecordAppearance(MatchFormat.T20, new DateOnly(2020, 1, 1));

    var approach = new BowlingApproach();
    // Contained on a full-ish length, consistently on one line - the textbook "died for the yorker" setup.
    var readout = new SpellReadout(8, 0, 0, 0, ConsecutiveDots: 4,
        RecentDeliveries: new[] { (BowlingLine.FourthStump, BowlingLength.Good), (BowlingLine.FourthStump, BowlingLength.Good), (BowlingLine.FourthStump, BowlingLength.Good) });

    int trapCount = 0;
    ExecutedDelivery? firstTrap = null;
    for (int i = 0; i < 500; i++)
    {
        var executed = execution.Execute(bowler, approach, readout, null, new Random(i));
        bool isTrap = executed.Deviation == PlanDeviationReason.ReadTheBatter && executed.Note is not null && executed.Note.Contains("built the pressure");
        if (isTrap) { trapCount++; firstTrap ??= executed; }
    }

    TestRunner.IsTrue(trapCount > 25, $"A sharp bowler should go for the kill a meaningful fraction of the time once real pressure is built, got {trapCount}/500");
    TestRunner.IsTrue(firstTrap is not null, "At least one trap ball should have fired across 500 tries");
    TestRunner.AreEqual(BowlingLength.Yorker, firstTrap!.Length, "Contained on a full-ish length - the trap is the yorker, not a random wicket-ball");

    // No pressure built (fewer consecutive dots) - the branch should never fire at all.
    var noPressureReadout = new SpellReadout(8, 0, 0, 0, ConsecutiveDots: 1, RecentDeliveries: readout.RecentDeliveries);
    int falseTraps = 0;
    for (int i = 0; i < 200; i++)
    {
        var executed = execution.Execute(bowler, approach, noPressureReadout, null, new Random(i));
        if (executed.Deviation == PlanDeviationReason.ReadTheBatter && executed.Note is not null && executed.Note.Contains("built the pressure"))
            falseTraps++;
    }
    TestRunner.AreEqual(0, falseTraps, "Without a real dot-ball streak, the trap-ball branch must never fire");
});

await TestRunner.RunAsync("A real simulated T20 innings actually produces trap-ball deviations when a sharp attack contains a batter - the mechanism reaches the live engine, not just the unit", async () =>
{
    var (batting, _) = MatchTestData.MakeEleven("PatternBat", 8, 8);
    var (fielding, bowlers) = MatchTestData.MakeEleven("PatternBowl", 8, 16);
    foreach (var b in bowlers) { b.Mental.GameAwareness = 19; b.Mental.DecisionMaking = 19; }
    var setup = new InningsSetup(batting, fielding, bowlers);
    var simulator = new InningsSimulator();

    int trapBallsAcrossInnings = 0;
    for (int seed = 0; seed < 20; seed++)
    {
        var innings = simulator.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "PatternBat", Guid.NewGuid(), "PatternBowl", new Random(seed));
        trapBallsAcrossInnings += innings.Deliveries.Count(d => d.Line == BowlingLine.AtTheStumps && d.Length == BowlingLength.Yorker);
    }

    TestRunner.IsTrue(trapBallsAcrossInnings > 0, "Across 20 innings against a weak, containable batting side, a sharp attack should genuinely reach for the trap yorker at least once");
    await Task.CompletedTask;
});

// ---------------------------------------------------------------------------
// Post-Phase-4 planning brief, Section R: fielding as a bait-and-trap sequence.
// A captain reacting to what a batter has ACTUALLY been attacking this innings,
// not just his a-priori BattingZoneStrengths profile.
// ---------------------------------------------------------------------------

TestRunner.Run("BatterMatchState.DominantAttackZone reads a genuine, recent, repeated pattern - not a single big shot, and not a stale one", () =>
{
    var state = new BatterMatchState();
    TestRunner.IsTrue(state.DominantAttackZone is null, "No shots at all - no pattern");

    state.RecordZoneAttack(ShotZone.Cover);
    state.RecordZoneAttack(ShotZone.MidWicket);
    TestRunner.IsTrue(state.DominantAttackZone is null, "Two different zones is not a pattern yet");

    state.RecordZoneAttack(ShotZone.Cover);
    TestRunner.IsTrue(state.DominantAttackZone is null, "Only two of three shots share a zone - not established enough yet");

    state.RecordZoneAttack(ShotZone.Cover);
    TestRunner.AreEqual(ShotZone.Cover, state.DominantAttackZone, "Three of four shots to Cover is a genuine, noticeable pattern");

    // The window is short and rolls - an old pattern that has genuinely stopped should not still read as live.
    state.RecordZoneAttack(ShotZone.FineLeg);
    state.RecordZoneAttack(ShotZone.FineLeg);
    state.RecordZoneAttack(ShotZone.FineLeg);
    // Window now holds: Cover, FineLeg, FineLeg, FineLeg (the two oldest Cover entries rolled off a 6-entry window).
    TestRunner.AreEqual(ShotZone.FineLeg, state.DominantAttackZone, "A fresh, more recent pattern should be read over a stale one that has rolled out of the window");
});

TestRunner.Run("AutoFieldSetter.BuildField commits real coverage to a zone the batter has actually been attacking this innings, beyond what his static ability profile alone would justify", () =>
{
    var setter = new AutoFieldSetter();
    var (fieldingSide, _) = MatchTestData.MakeEleven("Trap", 12, 12);
    var bowler = fieldingSide.First(p => p.BowlingRole == BowlingRoleType.OpeningBowler);

    // A batter whose STATIC profile does not favour ThirdMan at all - so any coverage there has
    // to come from the live signal, not the a-priori read.
    var flatProfile = new BattingZoneStrengths();
    foreach (var zone in Enum.GetValues<ShotZone>()) flatProfile[zone] = 50;
    flatProfile[ShotZone.ThirdMan] = 20;

    var withoutTrap = setter.BuildField(fieldingSide, bowler, MatchFormat.Test, MatchPhase.MiddleOvers,
        newBall: false, batterZones: flatProfile, liveAttackZone: null);
    var withTrap = setter.BuildField(fieldingSide, bowler, MatchFormat.Test, MatchPhase.MiddleOvers,
        newBall: false, batterZones: flatProfile, liveAttackZone: ShotZone.ThirdMan);

    int coverageWithout = withoutTrap.FieldersInZone(ShotZone.ThirdMan, insideCircle: false);
    int coverageWith = withTrap.FieldersInZone(ShotZone.ThirdMan, insideCircle: false);

    TestRunner.IsTrue(coverageWith >= coverageWithout,
        $"A live attack pattern in ThirdMan should never REDUCE deep coverage there ({coverageWith} vs {coverageWithout})");
    TestRunner.IsTrue(coverageWith > 0,
        "A batter's static profile rated ThirdMan his weakest zone, so only the live trap signal can explain a deep fielder actually being placed there");

    // Both fields must still be legal - the trap is a priority nudge inside the existing rules, never a way around them.
    var rules = new FieldSettingRules();
    TestRunner.IsTrue(rules.Validate(withTrap, MatchFormat.Test, MatchPhase.MiddleOvers).IsLegal, "A field built with a live trap zone must still be a legal field");
});

TestRunner.Run("A real simulated innings actually populates DominantAttackZone from live play, and the field visibly reacts to it once the pattern is established", () =>
{
    var simulator = new InningsSimulator();
    var (batting, _) = MatchTestData.MakeEleven("ZoneBat", 15, 8);
    var (fielding, bowlers) = MatchTestData.MakeEleven("ZoneField", 8, 10);

    // Force the opener to target one specific zone relentlessly, so a real pattern is
    // guaranteed to emerge rather than merely possible.
    var plan = new TacticalPlan();
    plan.BatterInstructions.Add(BatterInstruction.TargetTheGap(batting[0].Id, ShotZone.MidWicket));
    var setup = new InningsSetup(batting, fielding, bowlers);

    bool everSawDominantZone = false;
    for (int seed = 0; seed < 15 && !everSawDominantZone; seed++)
    {
        var innings = simulator.Simulate(setup, MatchFormat.T20, 20,
            Guid.NewGuid(), "ZoneBat", Guid.NewGuid(), "ZoneField", new Random(seed),
            battingPlan: plan);

        // The opener needs to have actually reached the crease and hit fours to MidWicket enough
        // times to establish the pattern - not guaranteed on every seed, so this is checked as
        // "does it ever happen", the same style every other statistical claim in this suite uses.
        int midWicketFours = innings.Deliveries.Count(d =>
            d.Outcome.Zone == ShotZone.MidWicket && d.Outcome.RunsOffBat == 4 && d.StrikerId == batting[0].Id);
        if (midWicketFours >= 3) everSawDominantZone = true;
    }

    TestRunner.IsTrue(everSawDominantZone,
        "Across 15 seeded innings with a batter instructed to target one zone, a genuine live attacking pattern (3+ fours to the same zone) should emerge at least once");
});

TestRunner.Run("AutoFieldSetter.BuildField automatically contains a batter who is genuinely dominating the strike rate - fewer slips, more boundary riders - independent of any coach instruction", () =>
{
    var setter = new AutoFieldSetter();
    var (fieldingSide, _) = MatchTestData.MakeEleven("Contain", 12, 12);
    var newBallBowler = fieldingSide.First(p => p.BowlingRole == BowlingRoleType.OpeningBowler);

    // T20 middle overs baseline is 122 - 90 balls at nearly two-a-ball is a genuine, unmistakable
    // strike-rate explosion, not a marginal case.
    var flying = setter.BuildField(fieldingSide, newBallBowler, MatchFormat.T20, MatchPhase.MiddleOvers,
        newBall: true, strikerBallsFaced: 20, strikerStrikeRate: 190);
    var ordinary = setter.BuildField(fieldingSide, newBallBowler, MatchFormat.T20, MatchPhase.MiddleOvers,
        newBall: true, strikerBallsFaced: 20, strikerStrikeRate: 110);

    TestRunner.IsTrue(flying.FieldersOutsideCircle > ordinary.FieldersOutsideCircle,
        $"A batter flying at nearly a run a ball above baseline should draw more boundary riders ({flying.FieldersOutsideCircle}) than an ordinary strike rate ({ordinary.FieldersOutsideCircle})");
    TestRunner.IsTrue(flying.CatchersBehindWicket <= ordinary.CatchersBehindWicket,
        "Containing a rampant batter should never call for MORE slips than the ordinary case");

    // A tiny sample must not trigger containment off one fluky big hit.
    var earlyFlurry = setter.BuildField(fieldingSide, newBallBowler, MatchFormat.T20, MatchPhase.MiddleOvers,
        newBall: true, strikerBallsFaced: 3, strikerStrikeRate: 400);
    var neutralStart = setter.BuildField(fieldingSide, newBallBowler, MatchFormat.T20, MatchPhase.MiddleOvers,
        newBall: true, strikerBallsFaced: 3, strikerStrikeRate: 0);
    TestRunner.AreEqual(neutralStart.FieldersOutsideCircle, earlyFlurry.FieldersOutsideCircle,
        "Three balls faced is far too small a sample to trust - containment must not fire off it, however extreme the number looks");

    // Every containment field must still be legal.
    var rules = new FieldSettingRules();
    TestRunner.IsTrue(rules.Validate(flying, MatchFormat.T20, MatchPhase.MiddleOvers).IsLegal, "A containment field must still be a legal field");
});

TestRunner.Run("The containment response applies just as much in multi-day cricket as limited overs - a batter smashing a Test attack draws the same automatic protection", () =>
{
    var setter = new AutoFieldSetter();
    var (fieldingSide, _) = MatchTestData.MakeEleven("TestContain", 12, 12);
    var bowler = fieldingSide.First(p => p.BowlingRole == BowlingRoleType.OpeningBowler);

    // Test baseline is 52 - a strike rate of 110 (double the baseline) over a real sample is a
    // genuine "he is taking this attack apart" innings by first-class standards.
    var smashing = setter.BuildField(fieldingSide, bowler, MatchFormat.Test, MatchPhase.MiddleOvers,
        newBall: false, strikerBallsFaced: 40, strikerStrikeRate: 110);
    var settled = setter.BuildField(fieldingSide, bowler, MatchFormat.Test, MatchPhase.MiddleOvers,
        newBall: false, strikerBallsFaced: 40, strikerStrikeRate: 48);

    TestRunner.IsTrue(smashing.FieldersOutsideCircle > settled.FieldersOutsideCircle,
        $"A Test batter scoring at more than double the format's baseline should draw real boundary protection ({smashing.FieldersOutsideCircle}) over a batter playing at a normal tempo ({settled.FieldersOutsideCircle})");
});

