TestRunner.Run("Issue 4: a T20 innings bowls its full 20 overs (barring being bowled out), not truncated early by a bowler-selection dead end", () =>
{
    var simulator = new InningsSimulator();
    int shortfalls = 0;
    for (int seed = 0; seed < 30; seed++)
    {
        var (batting, _) = MatchTestData.MakeEleven("Bat", 12, 12);
        var (fielding, bowlers) = MatchTestData.MakeEleven("Field", 10, 12);
        var setup = new InningsSetup(batting, fielding, bowlers);
        var innings = simulator.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "Bat", Guid.NewGuid(), "Field", new Random(seed));

        if (!innings.IsAllOut && innings.LegalBalls < 120) shortfalls++;
    }
    TestRunner.AreEqual(0, shortfalls, "No T20 innings should end early with overs unbowled unless the batting side was genuinely all out");
});

TestRunner.Run("ScorecardFormatter produces correct real-world dismissal notation for every dismissal type - Issue 3", () =>
{
    var bowler = MatchTestData.MakePlayer("X", 12, PlayerRole.Bowler, BowlingRoleType.FirstChange);
    bowler.LastName = "Smith";
    var fielder = MatchTestData.MakePlayer("Y", 12);
    fielder.LastName = "Jones";
    var keeper = MatchTestData.MakePlayer("Z", 12, PlayerRole.WicketKeeper);
    keeper.LastName = "Brown";
    var players = new[] { bowler, fielder, keeper }.ToDictionary(p => p.Id);

    TestRunner.AreEqual("b Smith", ScorecardFormatter.DescribeDismissal(DismissalType.Bowled, bowler.Id, null, players));
    TestRunner.AreEqual("lbw b Smith", ScorecardFormatter.DescribeDismissal(DismissalType.LBW, bowler.Id, null, players));
    TestRunner.AreEqual("c & b Smith", ScorecardFormatter.DescribeDismissal(DismissalType.CaughtAndBowled, bowler.Id, null, players));
    TestRunner.AreEqual("c Jones b Smith", ScorecardFormatter.DescribeDismissal(DismissalType.Caught, bowler.Id, fielder.Id, players));
    TestRunner.AreEqual("c Brown b Smith", ScorecardFormatter.DescribeDismissal(DismissalType.CaughtBehind, bowler.Id, keeper.Id, players));
    TestRunner.AreEqual("st Brown b Smith", ScorecardFormatter.DescribeDismissal(DismissalType.Stumped, bowler.Id, keeper.Id, players));
    TestRunner.AreEqual("run out (Jones)", ScorecardFormatter.DescribeDismissal(DismissalType.RunOut, null, fielder.Id, players));
    TestRunner.AreEqual("not out", ScorecardFormatter.DescribeDismissal(DismissalType.NotOut, null, null, players));
});

TestRunner.Run("MatchTimeline advances days correctly and never exceeds the match's own scheduled length - Issues 1/6/7", () =>
{
    var overRates = new OverRateService();
    var clearWeather = new MatchWeather { CloudCover = 0 };
    var timeline = new MatchTimeline(1, 3, 90, overRates, clearWeather, month: 6);

    TestRunner.AreEqual(LightVerdict.Clear, timeline.AssessLight(nextBowlerIsSpinner: false), "Mid-morning under clear skies should read as clear light");
    TestRunner.AreEqual(1, timeline.Day);

    TestRunner.IsTrue(timeline.TryAdvanceDay(), "Day 1 of 3 should be able to advance to day 2");
    TestRunner.AreEqual(2, timeline.Day);
    TestRunner.IsTrue(timeline.TryAdvanceDay(), "Day 2 of 3 should be able to advance to day 3");
    TestRunner.AreEqual(3, timeline.Day);
    TestRunner.IsTrue(!timeline.TryAdvanceDay(), "A 3-day match must not be able to advance past its own scheduled length");
    TestRunner.AreEqual(3, timeline.Day);
});

TestRunner.Run("A real simulated multi-day match tags its own deliveries with a real day number, closing the '[Day ?]' gap - Issue 1", () =>
{
    var simulator = new MultiDayMatchSimulator();
    var setup = MultiDaySetup(5);
    var result = simulator.Simulate(setup, new Random(11));

    var taggedDays = result.Innings.SelectMany(i => i.Deliveries).Where(d => d.Day is not null).Select(d => d.Day!.Value).ToList();
    TestRunner.IsTrue(taggedDays.Count > 0, "A real multi-day match should tag at least some deliveries with a real Day number");
    TestRunner.IsTrue(taggedDays.All(d => d >= 1 && d <= setup.Days), "Every tagged day must be within the match's own scheduled range");
    TestRunner.IsTrue(taggedDays.SequenceEqual(taggedDays.OrderBy(d => d)), "Day numbers must never go backwards across the match");
});

TestRunner.Run("PostMatchAnalysisService.SessionSummaries breaks a multi-day match into real session-by-session figures, in chronological order - Issue 5", () =>
{
    var simulator = new MultiDayMatchSimulator();
    var analysis = new PostMatchAnalysisService();
    var setup = MultiDaySetup(5);
    var result = simulator.Simulate(setup, new Random(13));

    var summaries = analysis.SessionSummaries(result);
    TestRunner.IsTrue(summaries.Count > 0, "A real multi-day match should produce at least one session summary");

    for (int i = 1; i < summaries.Count; i++)
    {
        bool chronological = summaries[i].Day > summaries[i - 1].Day
            || (summaries[i].Day == summaries[i - 1].Day && summaries[i].Session >= summaries[i - 1].Session);
        TestRunner.IsTrue(chronological, "Session summaries should be in chronological order");
    }

    var current = PostMatchAnalysisService.CurrentDayAndSession(result);
    TestRunner.IsTrue(current is not null, "A completed multi-day match should report a current day/session for the header - Issue 7");
});

TestRunner.Run("PostMatchAnalysisService.PlayerOfTheMatch favours the winning side, and only overrides it for a genuinely extraordinary losing-side performance - Issue 10", () =>
{
    var analysis = new PostMatchAnalysisService();
    var winningTeamId = Guid.NewGuid();
    var losingTeamId = Guid.NewGuid();
    var winnerStarId = Guid.NewGuid();
    var loserStarId = Guid.NewGuid();

    InningsState BuildInnings(Guid battingTeam, Guid bowlingTeam, string battingName, string bowlingName, Guid starId, string starName, int starRuns, int starBalls)
    {
        var innings = new InningsState { BattingTeamId = battingTeam, BattingTeamName = battingName, BowlingTeamId = bowlingTeam, BowlingTeamName = bowlingName, Format = MatchFormat.T20 };
        innings.BatterCards.Add(new BatterCard { PlayerId = starId, PlayerName = starName, BattingPosition = 1, HasBatted = true, Runs = starRuns, BallsFaced = starBalls });
        for (int i = 0; i < 5; i++)
            innings.BatterCards.Add(new BatterCard { PlayerId = Guid.NewGuid(), PlayerName = $"Order{i}", BattingPosition = i + 2, HasBatted = true, Runs = 15, BallsFaced = 20 });
        return innings;
    }

    var setup = new MatchSetup
    {
        Home = new MatchSide(winningTeamId, "Winner", Array.Empty<Player>(), Array.Empty<Player>()),
        Away = new MatchSide(losingTeamId, "Loser", Array.Empty<Player>(), Array.Empty<Player>())
    };

    // Ordinary case: comparable, unremarkable performances on both sides - POTM should still
    // favour the winner.
    var ordinaryFirst = BuildInnings(winningTeamId, losingTeamId, "Winner", "Loser", winnerStarId, "WinnerStar", 55, 40);
    var ordinarySecond = BuildInnings(losingTeamId, winningTeamId, "Loser", "Winner", loserStarId, "LoserStar", 50, 38);
    var ordinaryResult = new MatchResult
    {
        MatchId = Guid.NewGuid(), Setup = setup, FirstInnings = ordinaryFirst, SecondInnings = ordinarySecond,
        WinningTeamId = winningTeamId, Summary = "Winner beat Loser"
    };
    var ordinaryReport = analysis.AnalyzeMatch(ordinaryResult);
    TestRunner.AreEqual(winnerStarId, ordinaryReport.PlayerOfTheMatch!.PlayerId,
        "With comparable performances on both sides, Player of the Match should come from the winning side");

    // Extraordinary case: the LOSING side's star has a genuinely huge knock, the winning side's
    // best is very ordinary - POTM should now override to the losing side.
    var winnerOrdinary = BuildInnings(winningTeamId, losingTeamId, "Winner", "Loser", winnerStarId, "WinnerStar", 18, 20);
    var loserHuge = BuildInnings(losingTeamId, winningTeamId, "Loser", "Winner", loserStarId, "LoserStar", 190, 95);
    var extraordinaryResult = ordinaryResult with { FirstInnings = winnerOrdinary, SecondInnings = loserHuge };
    var extraordinaryReport = analysis.AnalyzeMatch(extraordinaryResult);
    TestRunner.AreEqual(loserStarId, extraordinaryReport.PlayerOfTheMatch!.PlayerId,
        "A genuinely extraordinary losing-side performance should override the winning-side default");
});

TestRunner.Run("DetermineBattingIntent automatically softens a switched-on batter's intent after a genuine recent wicket cluster, but leaves a poor reader of the game unchanged - Issue 9", () =>
{
    var state = new InningsState { BattingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamId = Guid.NewGuid(), BowlingTeamName = "Bowl", Format = MatchFormat.T20, MaxLegalBalls = 120 };
    state.LegalBalls = 30;
    state.FallOfWickets.Add(new FallOfWicket(1, 20, 22, Guid.NewGuid()));
    state.FallOfWickets.Add(new FallOfWicket(2, 25, 28, Guid.NewGuid()));
    state.CurrentPartnershipBalls = 2;

    var newBatterCard = new BatterCard { PlayerId = Guid.NewGuid(), PlayerName = "New", BattingPosition = 5, BallsFaced = 2 };

    var sharpBatter = MatchTestData.MakePlayer("Sharp", 14);
    sharpBatter.Mental.GameAwareness = 18;
    var obliviousBatter = MatchTestData.MakePlayer("Oblivious", 14);
    obliviousBatter.Mental.GameAwareness = 2;

    var baseline = InningsSimulator.DetermineBattingIntent(state, newBatterCard, MatchPhase.MiddleOvers);
    var oblivious = InningsSimulator.DetermineBattingIntent(state, newBatterCard, MatchPhase.MiddleOvers, obliviousBatter);
    var sharp = InningsSimulator.DetermineBattingIntent(state, newBatterCard, MatchPhase.MiddleOvers, sharpBatter);

    TestRunner.AreEqual(baseline, oblivious, "A batter with poor GameAwareness should not automatically soften - he plays on as before");
    TestRunner.IsTrue(sharp != baseline, "A switched-on batter facing a genuine recent cluster should actually soften from the baseline");
});

TestRunner.Run("BatterMatchState.BowlerFamiliarity rises only when the batter is genuinely coping against a specific bowler, and falls when he is beaten - Issue 11", () =>
{
    var state = new BatterMatchState();
    double baseline = state.GetBowlerFamiliarityMultiplier(Guid.NewGuid()); // an untouched bowler - the neutral starting point

    var copedWellId = Guid.NewGuid();
    for (int i = 0; i < 10; i++) state.RecordBowlerFamiliarity(copedWellId, 4, beatenOrThreatened: false);
    TestRunner.IsTrue(state.GetBowlerFamiliarityMultiplier(copedWellId) > baseline,
        "Genuinely coping against a specific bowler should raise his familiarity multiplier above the neutral start");

    var struggledId = Guid.NewGuid();
    for (int i = 0; i < 10; i++) state.RecordBowlerFamiliarity(struggledId, 0, beatenOrThreatened: true);
    TestRunner.IsTrue(state.GetBowlerFamiliarityMultiplier(struggledId) < baseline,
        "Being repeatedly beaten by a specific bowler should lower his familiarity multiplier below the neutral start");
});

TestRunner.Run("Mystery spinner: BallOutcomeModel.IsMysterySpinner classifies a genuine wide-repertoire spinner, and a batter builds real familiarity against him more slowly than against an honest bowler for the same outcomes", () =>
{
    var mysterySpinner = MatchTestData.MakePlayer("Mystery", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    mysterySpinner.Bowling.Variation = 18;
    TestRunner.IsTrue(BallOutcomeModel.IsMysterySpinner(mysterySpinner), "A spinner with a genuinely wide, disguised repertoire should classify as a mystery spinner");

    var honestSpinner = MatchTestData.MakePlayer("Honest", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    honestSpinner.Bowling.Variation = 6;
    TestRunner.IsTrue(!BallOutcomeModel.IsMysterySpinner(honestSpinner), "A spinner with little variation is not a mystery threat, whatever else he can do");

    var pace = MatchTestData.MakePlayer("Pace", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    pace.Bowling.Variation = 18;
    TestRunner.IsTrue(!BallOutcomeModel.IsMysterySpinner(pace), "Variation alone does not make a mystery spinner - he has to actually be a spinner");

    var stateA = new BatterMatchState();
    for (int i = 0; i < 8; i++) stateA.RecordBowlerFamiliarity(mysterySpinner.Id, 4, beatenOrThreatened: false, mysterious: true);
    double mysteryFamiliarity = stateA.GetBowlerFamiliarityMultiplier(mysterySpinner.Id, mysterious: true);

    var stateB = new BatterMatchState();
    for (int i = 0; i < 8; i++) stateB.RecordBowlerFamiliarity(honestSpinner.Id, 4, beatenOrThreatened: false, mysterious: false);
    double honestFamiliarity = stateB.GetBowlerFamiliarityMultiplier(honestSpinner.Id, mysterious: false);

    TestRunner.IsTrue(honestFamiliarity > mysteryFamiliarity,
        "The same run of positive outcomes should build LESS real familiarity against a genuine mystery bowler than against an honest one");
});

TestRunner.Run("Mystery spinner: a batter's line/length pattern-reading tells him much less against a genuine mystery bowler than an honest one", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var established = new[] { (BowlingLine.FourthStump, BowlingLength.Good), (BowlingLine.FourthStump, BowlingLength.Good), (BowlingLine.FourthStump, BowlingLength.Good) };
    var changeUp = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Yorker, DeliveryVariation.None, 1.0, PlanDeviationReason.ReadTheBatter);

    var sharpBatter = MatchTestData.MakePlayer("Sharp", 14);
    sharpBatter.Mental.GameAwareness = 20;

    var mysterySpinner = MatchTestData.MakePlayer("Mystery", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    mysterySpinner.Bowling.Variation = 18;
    var honestBowler = MatchTestData.MakePlayer("Honest", 14, PlayerRole.Bowler, BowlingRoleType.FirstChange);

    var service = new DeliveryEffectService();
    var vsMystery = service.Calculate(changeUp, sharpBatter, mysterySpinner, pitch, established);
    var vsHonest = service.Calculate(changeUp, sharpBatter, honestBowler, pitch, established);

    TestRunner.IsTrue(vsMystery.WicketScale > vsHonest.WicketScale,
        "The same sharp batter should read an honest bowler's change-up better than a genuine mystery spinner's - his pattern-reading carries much less weight against real deception");
});

