TestRunner.Run("BowlingPairSynergyService rewards a genuinely economical new-ball pairing and penalises a leaky one, staying neutral with no shared history", () =>
{
    var synergy = new BowlingPairSynergyService();
    var bowlerA = MatchTestData.MakePlayer("PairA", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var bowlerB = MatchTestData.MakePlayer("PairB", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);

    TestRunner.AreEqual(1.0, synergy.GetSynergyMultiplier(bowlerA, bowlerB.Id), "No shared history at all should read as neutral");

    for (int i = 0; i < 5; i++) synergy.RecordNewBallPairing(bowlerA, bowlerB, combinedEconomy: 3.5, MatchFormat.T20, wicketsTakenTogether: 2);
    TestRunner.IsTrue(synergy.GetSynergyMultiplier(bowlerA, bowlerB.Id) > 1.0,
        "A pairing that has repeatedly contained the new ball together should read as a genuine positive");
    TestRunner.IsTrue(synergy.GetSynergyMultiplier(bowlerB, bowlerA.Id) > 1.0, "The lift is mutual - it belongs to the pairing, not one side of it");

    var bowlerC = MatchTestData.MakePlayer("PairC", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var bowlerD = MatchTestData.MakePlayer("PairD", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    for (int i = 0; i < 5; i++) synergy.RecordNewBallPairing(bowlerC, bowlerD, combinedEconomy: 14.0, MatchFormat.T20, wicketsTakenTogether: 0);
    TestRunner.IsTrue(synergy.GetSynergyMultiplier(bowlerC, bowlerD.Id) < 1.0,
        "A pairing that has repeatedly leaked runs together should read as a genuine drag");
});

TestRunner.Run("CaptaincyService situational pattern memory nudges TacticalJudgement for a recurring situation, and stays neutral for a different one", () =>
{
    var service = new CaptaincyService();
    var captain = MatchTestData.MakePlayer("Recaller", 14);

    string tightChase = CaptaincyService.BuildSituationKey(MatchFormat.T20, MatchPhase.DeathOvers, chasing: true, pressureLevel: 85);
    string calmPowerplay = CaptaincyService.BuildSituationKey(MatchFormat.T20, MatchPhase.Powerplay, chasing: false, pressureLevel: 20);

    TestRunner.AreEqual(1.0, service.SituationConfidenceMultiplier(captain, tightChase), "No history in this situation yet should be neutral");

    for (int i = 0; i < 6; i++) service.RecordSituationOutcome(captain, tightChase, outcomeRating: 80);
    double afterGoodHistory = service.SituationConfidenceMultiplier(captain, tightChase);
    double unrelatedSituation = service.SituationConfidenceMultiplier(captain, calmPowerplay);

    TestRunner.IsTrue(afterGoodHistory > 1.0, "A captain with a genuinely good record in this exact recurring situation should read it with a touch more conviction");
    TestRunner.AreEqual(1.0, unrelatedSituation, "The memory is specific to the situation it was built from, not a general confidence boost");

    // Bounded, per the brief's own "must never escape a ceiling" instruction - much smaller than
    // an ordinary matchup swing (MatchupConfidenceService's own 0.85-1.15).
    TestRunner.IsTrue(afterGoodHistory < 1.06, $"The swing should stay small and bounded, got {afterGoodHistory:F3}");
});

TestRunner.Run("A real MatchSimulator match records captaincy match-count/situational outcomes for both captains - closing CaptaincyProfile.RecordMatch's dead-code gap", () =>
{
    var simulator = new MatchSimulator();
    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("RmHome", 13, 13);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("RmAway", 13, 13);

    var homeCaptain = MatchTestData.MakePlayer("HomeCap", 14);
    var awayCaptain = MatchTestData.MakePlayer("AwayCap", 14);
    var homeLeadership = new MatchLeadership { Captain = homeCaptain, Profile = new CaptaincyProfile { PlayerId = homeCaptain.Id } };
    var awayLeadership = new MatchLeadership { Captain = awayCaptain, Profile = new CaptaincyProfile { PlayerId = awayCaptain.Id } };

    var setup = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "RmHome", homeOrder, homeBowlers),
        Away = new MatchSide(Guid.NewGuid(), "RmAway", awayOrder, awayBowlers),
        Format = MatchFormat.T20,
        OversPerInnings = 20,
        HomeLeadership = homeLeadership,
        AwayLeadership = awayLeadership
    };

    simulator.Simulate(setup, new Random(21));

    TestRunner.AreEqual(1, homeLeadership.Profile.MatchesCaptained, "A completed match should credit the home captain via CaptaincyProfile.RecordMatch");
    TestRunner.AreEqual(1, awayLeadership.Profile.MatchesCaptained, "...and the away captain too");
    TestRunner.IsTrue(homeCaptain.Matchups.Keys.Any(k => k.StartsWith("situation:")),
        "The match's outcome should have been recorded into the home captain's own situational memory");
    TestRunner.IsTrue(awayCaptain.Matchups.Keys.Any(k => k.StartsWith("situation:")),
        "...and the away captain's too");
});

TestRunner.Run("CoachCareerService.EvaluateSatisfaction builds ambition pressure for genuine overachievement at a small club, but not at a big one", () =>
{
    var career = new CoachCareerService();

    var smallClub = new Team { Name = "Small Club", Strength = 35, Reputation = new Reputation(domestic: 30) };
    var bigClub = new Team { Name = "Big Club", Strength = 90, Reputation = new Reputation(domestic: 90) };

    var coachAtSmallClub = new Coach { FirstName = "Rising", LastName = "Star", CareerSatisfaction = 70 };
    var coachAtBigClub = new Coach { FirstName = "Settled", LastName = "Star", CareerSatisfaction = 70 };

    for (int year = 0; year < 5; year++)
    {
        career.EvaluateSatisfaction(coachAtSmallClub, smallClub, performanceScore: 0.7, seasonsAtClub: year);
        career.EvaluateSatisfaction(coachAtBigClub, bigClub, performanceScore: 0.7, seasonsAtClub: year);
    }

    TestRunner.IsTrue(coachAtSmallClub.CareerSatisfaction < coachAtBigClub.CareerSatisfaction,
        $"Repeated genuine overachievement at a small club ({coachAtSmallClub.CareerSatisfaction:F1}) should build real ambition pressure that a big-club coach ({coachAtBigClub.CareerSatisfaction:F1}) doing the same never accumulates");
});

TestRunner.Run("CoachCareerService.TryResign fires a real, probabilistic resignation once satisfaction has genuinely collapsed, and never for a content coach", () =>
{
    var career = new CoachCareerService();
    var random = new Random(9);

    bool everResigned = false;
    Coach? resignedCoach = null;
    CoachingContract? resignedContract = null;
    for (int trial = 0; trial < 40 && !everResigned; trial++)
    {
        var coach = new Coach { FirstName = "Unhappy", LastName = trial.ToString(), CareerSatisfaction = 5, CurrentTeamId = Guid.NewGuid() };
        var contract = new CoachingContract();
        coach.CurrentContractId = contract.Id;
        var team = new Team { Name = "Restless FC" };

        if (career.TryResign(coach, contract, team, random, out _))
        {
            everResigned = true;
            resignedCoach = coach;
            resignedContract = contract;
        }
    }

    TestRunner.IsTrue(everResigned, "A coach whose satisfaction has genuinely collapsed should, across enough trials, actually resign");
    TestRunner.AreEqual(ContractStatus.Resigned, resignedContract!.Status, "Resignation should set the contract's own status");
    TestRunner.IsTrue(resignedCoach!.CurrentTeamId is null && resignedCoach.CurrentContractId is null, "A resigned coach is no longer attached to the team or its contract");

    var contentCoach = new Coach { FirstName = "Content", LastName = "Coach", CareerSatisfaction = 80, CurrentTeamId = Guid.NewGuid() };
    var contentContract = new CoachingContract();
    bool contentEverResigned = false;
    for (int trial = 0; trial < 30; trial++)
        if (career.TryResign(contentCoach, contentContract, new Team(), random, out _)) contentEverResigned = true;

    TestRunner.IsTrue(!contentEverResigned, "A genuinely content coach should never resign");
});

TestRunner.Run("DeliveryEffectService.DismissalWeightsFor scales the stumping weight by the actual keeper's aptitude - an elite gloveman converts more than a poor stand-in", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var delivery = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);
    var striker = MatchTestData.MakePlayer("Striker", 12);
    var spinner = MatchTestData.MakePlayer("Spinner", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);

    var eliteKeeper = MatchTestData.MakePlayer("EliteKeeper", 18, PlayerRole.WicketKeeper);
    var poorKeeper = MatchTestData.MakePlayer("PoorKeeper", 4, PlayerRole.WicketKeeper);

    var noKeeperWeights = DeliveryEffectService.DismissalWeightsFor(delivery, striker, spinner, pitch);
    var eliteWeights = DeliveryEffectService.DismissalWeightsFor(delivery, striker, spinner, pitch, eliteKeeper);
    var poorWeights = DeliveryEffectService.DismissalWeightsFor(delivery, striker, spinner, pitch, poorKeeper);

    TestRunner.IsTrue(eliteWeights[DismissalType.Stumped] > noKeeperWeights[DismissalType.Stumped],
        "An elite keeper standing up should convert MORE stumping chances than the keeper-agnostic baseline");
    TestRunner.IsTrue(poorWeights[DismissalType.Stumped] < noKeeperWeights[DismissalType.Stumped],
        "A poor stand-in keeper should convert FEWER than the keeper-agnostic baseline");
    TestRunner.IsTrue(eliteWeights[DismissalType.Stumped] > poorWeights[DismissalType.Stumped],
        "An elite keeper should clearly out-convert a poor one");
});

TestRunner.Run("DeliveryEffectService's swing/seam batter response: a sharp reader partially compensates poor swing handling with a guard change, but only when both are genuinely true", () =>
{
    var pitch = new PitchConditions(50, 50, 50, 50);
    var swingBowler = MatchTestData.MakePlayer("Swinger", 16, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    swingBowler.Bowling.Swing = 18;
    var delivery = new ExecutedDelivery(BowlingLine.FourthStump, BowlingLength.Good, DeliveryVariation.None, 1.0, PlanDeviationReason.Followed);

    var poorHandlingSharpReader = MatchTestData.MakePlayer("Sharp", 10);
    poorHandlingSharpReader.Batting.SwingHandling = 3;
    poorHandlingSharpReader.Mental.GameAwareness = 19;

    var poorHandlingOblivious = MatchTestData.MakePlayer("Oblivious", 10);
    poorHandlingOblivious.Batting.SwingHandling = 3;
    poorHandlingOblivious.Mental.GameAwareness = 2;

    var service = new DeliveryEffectService();
    var sharpResult = service.Calculate(delivery, poorHandlingSharpReader, swingBowler, pitch, ballAge: 5);
    var obliviousResult = service.Calculate(delivery, poorHandlingOblivious, swingBowler, pitch, ballAge: 5);

    TestRunner.IsTrue(sharpResult.WicketScale < obliviousResult.WicketScale,
        "Identical poor swing handling, but the sharp reader adjusts his guard and carries measurably less wicket risk than the oblivious batter");
