TestRunner.Run("MultiDayMatchSimulator.BuildPitch dampens spin and lifts seam on a day genuinely affected by rain, versus an identical dry day", () =>
{
    var ground = new Ground { Name = "Damp Oval", PitchSpinRating = 55, PitchPaceRating = 50, PitchBounceRating = 50, PitchBattingFriendliness = 55, PitchWearRate = 50 };
    var setup = new MultiDayMatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "Home", new List<Player>(), new List<Player>()),
        Away = new MatchSide(Guid.NewGuid(), "Away", new List<Player>(), new List<Player>()),
        Ground = ground,
        Days = 5,
        OversPerDay = 90
    };
    var simulator = new MultiDayMatchSimulator();

    var dryDay = simulator.BuildPitch(setup, day: 2, oversLostByDay: new[] { 0, 0 });
    var wetDay = simulator.BuildPitch(setup, day: 2, oversLostByDay: new[] { 0, 90 }); // day 2 entirely rain-affected

    TestRunner.IsTrue(wetDay.Spin < dryDay.Spin, $"A rain-affected day should grip less for spin than an identical dry day (wet {wetDay.Spin:F1} vs dry {dryDay.Spin:F1})");
    TestRunner.IsTrue(wetDay.Pace > dryDay.Pace, $"A rain-affected day should offer a shade more seam than an identical dry day (wet {wetDay.Pace:F1} vs dry {dryDay.Pace:F1})");

    // No rain information at all (the pre-existing 2-argument call shape) must behave exactly as
    // it always did - every caller before this slice never passed oversLostByDay at all.
    var noInfo = simulator.BuildPitch(setup, day: 2);
    TestRunner.AreEqual(dryDay.Spin, noInfo.Spin, "Omitting rain information should reproduce the original, unaffected pitch exactly");
});

