            $"A pure batsman should never be suggested a bowling focus, got {focus}");
    }

    var pureBowler = MatchTestData.MakePlayer("PureBowl", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    for (int i = 0; i < 20; i++)
    {
        var focus = service.SuggestFocus(pureBowler, Array.Empty<StaffMember>(), random);
        TestRunner.IsTrue(focus.ToString().StartsWith("Bowling") || focus is TrainingFocus.Fielding or TrainingFocus.Physical or TrainingFocus.Mental,
            $"A pure bowler should never be suggested a batting focus, got {focus}");
    }
});

TestRunner.Run("TrainingService.SuggestFocus reliably names the player's actual weakest cluster when the coach is strong", () =>
{
    var service = new TrainingService();
    var random = new Random(2);

    var player = MatchTestData.MakePlayer("Lopsided", 14, PlayerRole.Batsman);
    player.Batting.AgainstSpin = 3;
