});

TestRunner.Run("TrainingService.ApplyAnnualTraining grows the targeted cluster over repeated years, and blocks entirely for a player in rehab", () =>
{
    var service = new TrainingService();
    var random = new Random(3);

    var young = MatchTestData.MakePlayer("Prospect", 8, PlayerRole.Batsman);
    young.DateOfBirth = new DateOnly(2008, 1, 1);
    young.PotentialAbility = 190; // huge headroom
    young.TrainingPlan.Focus = TrainingFocus.BattingAgainstSpin;
    young.TrainingPlan.Intensity = TrainingIntensity.Intensive;

    int startingSpin = young.Batting.AgainstSpin;
    var eliteCoach = new StaffMember { Role = StaffRole.BattingCoach, TechnicalKnowledge = 19, Communication = 18, Analysis = 17, Diligence = 17, YearsExperience = 10 };

    for (int year = 2026; year < 2046; year++)
        service.ApplyAnnualTraining(young, teamTrainingQuality: 80, new[] { eliteCoach }, random, new DateOnly(year, 1, 1));

    TestRunner.IsTrue(young.Batting.AgainstSpin > startingSpin,
        $"Twenty years of directed, well-coached training on a young player with real headroom should raise the targeted cluster (started {startingSpin}, now {young.Batting.AgainstSpin})");
    TestRunner.IsTrue(young.Batting.PowerHitting == 8, "An untargeted cluster should not move from directed training alone");

    var injured = MatchTestData.MakePlayer("Crocked", 14, PlayerRole.Batsman);
    injured.CurrentInjury = new Injury(InjuryType.Hamstring, InjurySeverity.Serious, new DateOnly(2026, 1, 1), 90);
    injured.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
    int techniqueBefore = injured.Batting.Technique;

    var result = service.ApplyAnnualTraining(injured, 80, Array.Empty<StaffMember>(), random, new DateOnly(2026, 1, 1));
    TestRunner.AreEqual(TrainingFocus.None, result.Focus, "A player in rehab from a serious injury cannot train this year");
    TestRunner.AreEqual(techniqueBefore, injured.Batting.Technique, "His attributes must not move while in rehab");
});

TestRunner.Run("All-round development is real but capped - a specialist never becomes a complete second-discipline player, unlike a genuine allrounder", () =>
{
    var service = new TrainingService();
    var random = new Random(4);
    var eliteCoach = new StaffMember { Role = StaffRole.BowlingCoach, TechnicalKnowledge = 19, Communication = 18, Analysis = 17, Diligence = 17, YearsExperience = 12 };

    var specialistBatter = MatchTestData.MakePlayer("Specialist", 10, PlayerRole.Batsman);
    specialistBatter.DateOfBirth = new DateOnly(2005, 1, 1);
    specialistBatter.PotentialAbility = 190;
    specialistBatter.TrainingPlan.Focus = TrainingFocus.AllroundBowling;
    specialistBatter.TrainingPlan.Intensity = TrainingIntensity.Intensive;

    var genuineAllrounder = MatchTestData.MakePlayer("Genuine", 10, PlayerRole.BattingAllrounder, BowlingRoleType.FirstChange);
    genuineAllrounder.DateOfBirth = new DateOnly(2005, 1, 1);
    genuineAllrounder.PotentialAbility = 190;
    genuineAllrounder.TrainingPlan.Focus = TrainingFocus.AllroundBowling;
    genuineAllrounder.TrainingPlan.Intensity = TrainingIntensity.Intensive;

    for (int year = 2026; year < 2066; year++)
    {
        service.ApplyAnnualTraining(specialistBatter, 80, new[] { eliteCoach }, random, new DateOnly(year, 1, 1));
        service.ApplyAnnualTraining(genuineAllrounder, 80, new[] { eliteCoach }, random, new DateOnly(year, 1, 1));
    }

    TestRunner.InRange(specialistBatter.Bowling.Accuracy, 1, 13, "A pure batter's bowling, however much he trains it, should never pass the part-timer ceiling");
    TestRunner.IsTrue(genuineAllrounder.Bowling.Accuracy > 13,
        $"A genuine allrounder training the same discipline for the same forty years should be able to pass that ceiling (got {genuineAllrounder.Bowling.Accuracy})");
});

TestRunner.Run("Role conversion training reshapes the relevant attributes and RoleTraitDeriver eventually re-derives BattingRole to match - no staleness left behind", () =>
{
    var service = new TrainingService();
    var random = new Random(5);
    var roles = new RoleTraitDeriver();

    // Deliberately a NARROW starting gap (topOrderScore just clears finisherScore by a small
    // margin) rather than an extreme "textbook opener" profile - NudgeTowardBattingRole moves all
    // three finisher attributes together by 1 per successful year, so the gap decides how many
    // successful years the conversion needs, and a wide gap made this test's single seed a coin
    // flip on whether forty simulated years (many of them past the prime-development age, where
    // growth chance is deliberately much lower) was actually enough. A narrow, realistic gap
    // needs only a handful of genuine successes, which is comfortably likely well inside the
    // budget below.
    var opener = MatchTestData.MakePlayer("Opener", 10, PlayerRole.Batsman);
    opener.DateOfBirth = new DateOnly(2003, 1, 1);
    opener.PotentialAbility = 180;
    opener.Batting.Technique = 13; opener.Batting.DefensiveAbility = 13; opener.Batting.AgainstPace = 12; opener.Batting.RiskManagement = 13;
    opener.Batting.PowerHitting = 8; opener.Batting.DeathOverBatting = 8; opener.Batting.BoundaryHitting = 8;
    roles.ApplyTo(opener);
    TestRunner.AreEqual(BattingRole.Opener, opener.BattingRole, "Sanity check on the seeded profile before training starts");

    opener.TrainingPlan.Focus = TrainingFocus.RoleConversion;
    opener.TrainingPlan.TargetBattingRole = BattingRole.LowerOrder;
    opener.TrainingPlan.Intensity = TrainingIntensity.Intensive;

    for (int year = 2026; year < 2066 && opener.BattingRole != BattingRole.LowerOrder; year++)
        service.ApplyAnnualTraining(opener, 80, Array.Empty<StaffMember>(), random, new DateOnly(year, 1, 1));

    TestRunner.AreEqual(BattingRole.LowerOrder, opener.BattingRole,
        "Sustained role-conversion training should eventually reshape the player's attributes enough that RoleTraitDeriver derives the new role on its own - the exact staleness gap this phase closes");
});

TestRunner.Run("CurrentAbility never exceeds PotentialAbility except through the rare, bounded breakthrough case, which is gated to young players on an Intensive programme", () =>
{
    var service = new TrainingService();

    var nearCeiling = MatchTestData.MakePlayer("NearCeiling", 15, PlayerRole.Batsman);
    nearCeiling.DateOfBirth = new DateOnly(2004, 1, 1);
    nearCeiling.PotentialAbility = nearCeiling.CurrentAbility + 2;
    nearCeiling.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
    nearCeiling.TrainingPlan.Intensity = TrainingIntensity.Intensive;
    var random = new Random(6);

    for (int year = 2026; year < 2066; year++)
    {
        service.ApplyAnnualTraining(nearCeiling, 80, Array.Empty<StaffMember>(), random, new DateOnly(year, 1, 1));
        TestRunner.IsTrue(nearCeiling.CurrentAbility <= nearCeiling.PotentialAbility,
            $"CurrentAbility ({nearCeiling.CurrentAbility}) must never exceed PotentialAbility ({nearCeiling.PotentialAbility}), year {year}");
    }

    int youngBreakthroughs = 0, oldBreakthroughs = 0;
    // 800 trials rather than a rounder, smaller number - the breakthrough itself is deliberately
    // rare (a real, bounded exception, not a routine outcome), so a small trial count leaves a
    // non-negligible chance of a false failure purely from bad luck rather than the mechanism
    // being broken. 800 pushes that below a fraction of a percent.
    for (int trial = 0; trial < 800; trial++)
    {
        var youngRandom = new Random(1000 + trial);
        var young = MatchTestData.MakePlayer("Young", 15, PlayerRole.Batsman);
        young.DateOfBirth = new DateOnly(2004, 1, 1);
        young.PotentialAbility = young.CurrentAbility + 1;
        young.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
        young.TrainingPlan.Intensity = TrainingIntensity.Intensive;
        int before = young.PotentialAbility;
        service.ApplyAnnualTraining(young, 90, Array.Empty<StaffMember>(), youngRandom, new DateOnly(2026, 1, 1));
        if (young.PotentialAbility > before) youngBreakthroughs++;

        var oldRandom = new Random(2000 + trial);
        var old = MatchTestData.MakePlayer("Old", 15, PlayerRole.Batsman);
        old.DateOfBirth = new DateOnly(1985, 1, 1);
        old.PotentialAbility = old.CurrentAbility + 1;
        old.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
        old.TrainingPlan.Intensity = TrainingIntensity.Intensive;
        int oldBefore = old.PotentialAbility;
        service.ApplyAnnualTraining(old, 90, Array.Empty<StaffMember>(), oldRandom, new DateOnly(2026, 1, 1));
        if (old.PotentialAbility > oldBefore) oldBreakthroughs++;
    }

    TestRunner.IsTrue(youngBreakthroughs > 0, "Across 800 trials, a young player right at his ceiling on an Intensive programme should genuinely break through at least once");
    TestRunner.AreEqual(0, oldBreakthroughs, "A player past the prime development age should never get the breakthrough, however many trials");
});

TestRunner.Run("Intensive training carries a real overtraining injury risk that Light/Normal training does not", () =>
{
    var service = new TrainingService();

    int intensiveInjuries = 0;
    for (int trial = 0; trial < 200; trial++)
    {
        var random = new Random(trial);
        var player = MatchTestData.MakePlayer("Grinder", 13, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        player.Bowling.Pace = 16;
        player.Physical.InjuryProneness = 15;
        player.TrainingPlan.Focus = TrainingFocus.BowlingPaceDevelopment;
        player.TrainingPlan.Intensity = TrainingIntensity.Intensive;

        var result = service.ApplyAnnualTraining(player, 60, Array.Empty<StaffMember>(), random, new DateOnly(2026, 1, 1));
        if (result.OvertrainingInjury is not null) intensiveInjuries++;
    }
    TestRunner.IsTrue(intensiveInjuries > 0, $"Across 200 trials of Intensive training on an injury-prone fast bowler, at least one overtraining injury should occur ({intensiveInjuries} did)");

    int lightInjuries = 0;
    for (int trial = 0; trial < 200; trial++)
    {
        var random = new Random(trial);
        var player = MatchTestData.MakePlayer("Careful", 13, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        player.Bowling.Pace = 16;
        player.Physical.InjuryProneness = 15;
        player.TrainingPlan.Focus = TrainingFocus.BowlingPaceDevelopment;
        player.TrainingPlan.Intensity = TrainingIntensity.Light;

        var result = service.ApplyAnnualTraining(player, 60, Array.Empty<StaffMember>(), random, new DateOnly(2026, 1, 1));
        if (result.OvertrainingInjury is not null) lightInjuries++;
    }
    TestRunner.AreEqual(0, lightInjuries, "Light training should never carry an overtraining injury risk, however many trials");
});

TestRunner.Run("WorldClockService's MONTHLY tick runs training (Wave 2 - moved off the annual rollover), and a hired specialist coach develops a player measurably faster than facility quality alone", () =>
{
    // Wave 2 moved training off the once-a-year annual rollover onto the monthly tick, in twelve
    // small increments. This test's window is deliberately short (four years) and its intensity
    // Normal, so NEITHER path fully caps the targeted cluster - the coach's edge shows as a real
    // gap rather than both hitting the ceiling. (The original fourteen-year / Intensive version
    // let both paths reach the 20-per-attribute ceiling under the finer cadence, which made the
    // comparison meaningless - a legitimate test-premise change, not a production bug.)
    var clock = new WorldClockService();

    int WithCoach(bool hireCoach, int seed)
    {
        var world = EmptyWorld();
        var team = new Team { Name = "Academy FC", Facilities = new TeamFacilities { TrainingQuality = 40 } };
        world.Teams[team.Id] = team;

        var player = MatchTestData.MakePlayer("Trainee", 8, PlayerRole.Batsman);
        player.DateOfBirth = new DateOnly(2010, 1, 1);
        player.PotentialAbility = 190;
        player.CurrentTeamId = team.Id;
        player.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
        player.TrainingPlan.Intensity = TrainingIntensity.Normal;
        world.Players.Add(player);

        if (hireCoach)
        {
            var coach = new StaffMember { Role = StaffRole.BattingCoach, TechnicalKnowledge = 19, Communication = 18, Analysis = 17, Diligence = 17, YearsExperience = 12 };
            world.Staff.Add(coach);
            team.StaffIds.Add(coach.Id);
        }

        var calendar = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: seed);
        clock.AdvanceTo(calendar, world, new DateOnly(2030, 2, 1));

        return player.Batting.Technique + player.Batting.Timing + player.Batting.ShotSelection + player.Batting.DefensiveAbility;
    }

    int totalWithCoach = 0, totalWithoutCoach = 0;
    for (int seed = 0; seed < 8; seed++)
    {
        totalWithCoach += WithCoach(true, seed);
        totalWithoutCoach += WithCoach(false, seed + 100);
    }

    TestRunner.IsTrue(totalWithCoach > totalWithoutCoach,
        $"Over eight seeded four-year careers, a hired specialist batting coach should develop the targeted cluster measurably further than facility quality alone (with coach {totalWithCoach}, without {totalWithoutCoach})");
});

