TestRunner.Run("StaffCareerService.GrowFromTenure grows a fresh appointment's attributes faster than a long-tenured one's, and always advances YearsExperience", () =>
{
    var career = new StaffCareerService();

    int CountGrowth(int startingYears, int trials)
    {
        int totalGrowth = 0;
        var random = new Random(5);
        for (int i = 0; i < trials; i++)
        {
            var staff = new StaffMember { FirstName = "Grow", LastName = i.ToString(), Role = StaffRole.Analyst, YearsExperience = startingYears };
            int before = staff.Analysis + staff.TechnicalKnowledge + staff.Communication;
            career.GrowFromTenure(staff, random);
            int after = staff.Analysis + staff.TechnicalKnowledge + staff.Communication;
            totalGrowth += after - before;
        }
        return totalGrowth;
    }

    int freshGrowth = CountGrowth(startingYears: 0, trials: 400);
    int veteranGrowth = CountGrowth(startingYears: 20, trials: 400);

    TestRunner.IsTrue(freshGrowth > veteranGrowth,
        $"A fresh appointment ({freshGrowth} growth events over 400 trials) should develop faster than a long-tenured one ({veteranGrowth})");

    var single = new StaffMember { Role = StaffRole.Analyst, YearsExperience = 3 };
    career.GrowFromTenure(single, new Random(2));
    TestRunner.AreEqual(4, single.YearsExperience, "YearsExperience should always advance by one, whether or not any attribute happened to grow this year");
});

TestRunner.Run("WorldClockService's annual rollover grows employed staff over tenure, and leaves an unemployed free agent untouched", () =>
{
    // A real bug in an earlier draft of this test, not in the production code: the contract's own
    // EndDate was set to expire after the FIRST simulated year, which correctly detached the staff
    // member per ProcessContractExpiry - but that meant the later years' rollovers correctly saw
    // no employed staff member left to grow, and the "three years of growth" assertion was really
    // asserting against a scenario the test's own setup had already ended after one year. Split
    // into two tests so each asserts against a scenario that actually happens: growth over a
    // contract that comfortably outlasts the whole advance, and expiry checked on its own terms below.
    var clock = new WorldClockService();
    var world = EmptyWorld();
    var team = new Team { Name = "Rollover Staff FC" };
    world.Teams[team.Id] = team;

    var employed = new StaffMember { FirstName = "Employed", LastName = "Coach", Role = StaffRole.BattingCoach, YearsExperience = 0, TeamId = team.Id };
    team.StaffIds.Add(employed.Id);
    world.Staff.Add(employed);

    var unemployed = new StaffMember { FirstName = "FreeAgent", LastName = "Coach", Role = StaffRole.BattingCoach, YearsExperience = 0 };
    world.Staff.Add(unemployed);

    world.StaffContracts.Add(new StaffContract
    {
        StaffId = employed.Id,
        TeamId = team.Id,
        StartDate = new DateOnly(2020, 1, 1),
        EndDate = new DateOnly(2050, 1, 1), // comfortably outlasts the advance below
        Status = ContractStatus.Active
    });

    var calendar = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: 3);
    clock.AdvanceTo(calendar, world, new DateOnly(2029, 1, 2));

    TestRunner.IsTrue(employed.YearsExperience >= 3, $"Three annual rollovers should have advanced the employed staff member's experience by at least 3 (got {employed.YearsExperience})");
    TestRunner.AreEqual(0, unemployed.YearsExperience, "An unemployed free agent should not accrue tenure - there is no job to be growing in");
});

TestRunner.Run("WorldClockService properly expires and detaches a staff contract that has run its course, unlike the pre-existing coach expiry path", () =>
{
    var clock = new WorldClockService();
    var world = EmptyWorld();
    var team = new Team { Name = "Expiry Staff FC" };
    world.Teams[team.Id] = team;

    var employed = new StaffMember { FirstName = "Expiring", LastName = "Coach", Role = StaffRole.BattingCoach, TeamId = team.Id };
    team.StaffIds.Add(employed.Id);
    world.Staff.Add(employed);

    // EndDate deliberately close to the calendar's own start date - Part 3 added a renewal
    // decision 90 days ahead of EndDate, and the ORIGINAL version of this test (EndDate six
    // months out) had that renewal window land squarely inside the advance below, so the
    // contract was legitimately renewed before it ever reached its own expiry - working exactly
    // as designed, but not what this test means to exercise. Placing EndDate here puts the
    // renewal trigger (EndDate - 90 days) before the calendar even starts, so the daily tick
    // never visits it and only the expiry path this test is actually about gets exercised.
    var expiringContract = new StaffContract
    {
        StaffId = employed.Id,
        TeamId = team.Id,
        StartDate = new DateOnly(2020, 1, 1),
        EndDate = new DateOnly(2026, 1, 15),
        Status = ContractStatus.Active
    };
    world.StaffContracts.Add(expiringContract);

    var calendar = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: 4);
    var events = clock.AdvanceTo(calendar, world, new DateOnly(2026, 6, 5));

    TestRunner.AreEqual(ContractStatus.Expired, expiringContract.Status, "The contract's own end date should have been reached and processed");
    TestRunner.IsTrue(employed.TeamId is null, "Unlike the pre-existing coach expiry path, a staff member should be properly detached once his contract expires");
    TestRunner.IsTrue(!team.StaffIds.Contains(employed.Id), "...and removed from the team's own StaffIds");
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.ContractExpired && e.SubjectId == employed.Id), "A ContractExpired event should be raised for the staff contract");
});

