TestRunner.Run("GameCalendar.RandomForDay gives independent streams across different days, unlike RandomForYear reused within the same year", () =>
{
    var calendar = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 99);

    // RandomForYear's own documented shape: called twice for the same year, it re-seeds
    // identically both times - by design for a single year-long processing pass, but exactly
    // the property that would have made a day-keyed renewal roll silently correlated if reused.
    var yearA = calendar.RandomForYear(2027).NextDouble();
    var yearB = calendar.RandomForYear(2027).NextDouble();
    TestRunner.AreEqual(yearA, yearB, "RandomForYear called twice for the same year should reproduce the identical first draw - this is the exact property RandomForDay exists to avoid for daily processing");

    var day1 = calendar.RandomForDay(new DateOnly(2027, 3, 1)).NextDouble();
    var day2 = calendar.RandomForDay(new DateOnly(2027, 9, 15)).NextDouble();
    TestRunner.IsTrue(day1 != day2, "Two different days within the same year should draw independent, non-correlated streams");
});

