TestRunner.Run("CoachCareerService.EvaluateRenewal is driven by BoardTrust - the board's own accumulated read of tenure performance - and rewards genuine trust with a real pay rise", () =>
{
    var career = new CoachCareerService();

    int RenewalsAt(double boardTrust, int trials)
    {
        int renewed = 0;
        var random = new Random(3);
        for (int i = 0; i < trials; i++)
        {
            var coach = new Coach { BoardTrust = boardTrust, Reputation = new Reputation(domestic: 50) };
            var contract = new CoachingContract { EndDate = new DateOnly(2028, 1, 1), AnnualSalary = 100_000 };
            if (career.EvaluateRenewal(coach, contract, new Team(), random).Renewed) renewed++;
        }
        return renewed;
    }

    // BoardTrust=100 (the true maximum, clamping the renewal chance at its own 0.92 ceiling) -
    // an earlier draft used 85, which genuinely only computes to a ~79% chance under the actual
    // formula (Math.Clamp((85-30)/70.0, ...) = 0.786), not the "almost every time" this
    // assertion's own wording claims. 240/300 (the real observed rate at 85) was the formula
    // working correctly; the test's OWN expectation was miscalibrated against arithmetic nobody
    // had actually worked through, not a production bug - fixed by testing the genuinely
    // near-certain case the assertion's wording actually describes.
    int trustedRenewals = RenewalsAt(100, 300);
    int distrustedRenewals = RenewalsAt(15, 300);

    TestRunner.IsTrue(trustedRenewals > 250, $"A coach the board genuinely trusts should be renewed almost every time ({trustedRenewals}/300)");
    TestRunner.IsTrue(distrustedRenewals < 50, $"A coach the board has lost faith in should almost never be renewed ({distrustedRenewals}/300)");

    var highTrustCoach = new Coach { BoardTrust = 100, Reputation = new Reputation(domestic: 50) };
    var highTrustContract = new CoachingContract { EndDate = new DateOnly(2028, 1, 1), AnnualSalary = 100_000 };
    var decision = career.EvaluateRenewal(highTrustCoach, highTrustContract, new Team(), new Random(7));
    if (decision.Renewed)
    {
        TestRunner.IsTrue(highTrustContract.AnnualSalary > 100_000, "Genuine, high trust should be rewarded with a real pay rise on renewal");
        TestRunner.AreEqual(new DateOnly(2030, 1, 1), highTrustContract.EndDate, "A renewal should extend the contract by the requested term");
    }
});

TestRunner.Run("Both the dismissal and resignation paths now clear Team.CurrentCoachId too, closing the gap the job market's own hiring flow depends on", () =>
{
    var career = new CoachCareerService();
