// -------------------- WAVE 2: player development realism --------------------

TestRunner.Run("Wave 2: monthly (periodFraction) training moves the targeted cluster gradually, and re-derives the staff suggestion each period for an unset focus", () =>
{
    var service = new TrainingService();
    var random = new Random(7);

    var young = MatchTestData.MakePlayer("MonthlyDev", 8, PlayerRole.Batsman);
    young.DateOfBirth = new DateOnly(2008, 1, 1);
    young.PotentialAbility = 190;
    young.TrainingPlan.Focus = TrainingFocus.BattingAgainstSpin;
    young.TrainingPlan.Intensity = TrainingIntensity.Intensive;
    int startSpin = young.Batting.AgainstSpin;

    // three simulated years of MONTHLY ticks
    for (int y = 2026; y < 2029; y++)
        for (int m = 1; m <= 12; m++)
            service.ApplyPeriodicTraining(young, 80, Array.Empty<StaffMember>(), random, new DateOnly(y, m, 1),
                periodFraction: 1.0 / 12.0, reassessFocus: true);

    TestRunner.IsTrue(young.Batting.AgainstSpin > startSpin,
        $"Monthly training over three years should raise the targeted cluster (started {startSpin}, now {young.Batting.AgainstSpin})");

    // dynamic focus: an unset plan gets a suggestion re-derived each period
    var drifter = MatchTestData.MakePlayer("Drifter", 10, PlayerRole.Batsman);
    drifter.DateOfBirth = new DateOnly(2006, 1, 1);
    drifter.Batting.AgainstSpin = 3; // clearly his weakest applicable cluster
    service.ApplyPeriodicTraining(drifter, 70, Array.Empty<StaffMember>(), new Random(1), new DateOnly(2026, 2, 1),
        periodFraction: 1.0 / 12.0, reassessFocus: true);
    TestRunner.IsTrue(drifter.TrainingPlan.StaffSuggestion is not null,
        "An unset plan should have a staff suggestion filled in on a periodic tick");
});

TestRunner.Run("Wave 2: rehab blocks training early in a serious injury but allows LIGHT physical work in the final phase; a career-threatening injury is always blocked", () =>
{
    var service = new TrainingService();

    var early = MatchTestData.MakePlayer("RehabEarly", 14, PlayerRole.Batsman);
    early.CurrentInjury = new Injury(InjuryType.KneeInjury, InjurySeverity.Serious, new DateOnly(2026, 1, 1), 200);
    early.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
    int techBefore = early.Batting.Technique;
    var earlyResult = service.ApplyPeriodicTraining(early, 80, Array.Empty<StaffMember>(), new Random(1), new DateOnly(2026, 2, 1),
        periodFraction: 1.0, reassessFocus: true);
    TestRunner.AreEqual(TrainingFocus.None, earlyResult.Focus, "No directed training in the early phase of a serious injury");
    TestRunner.AreEqual(techBefore, early.Batting.Technique, "...and no attribute movement");

    var late = MatchTestData.MakePlayer("RehabLate", 14, PlayerRole.Batsman);
    late.PotentialAbility = 190;
    late.CurrentInjury = new Injury(InjuryType.KneeInjury, InjurySeverity.Serious, new DateOnly(2026, 1, 1), 100);
    late.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
    int fitBefore = late.Physical.Fitness;
    int lateTech = late.Batting.Technique;
    // 85% through the layoff = final phase
    int fitMoved = 0;
    for (int i = 0; i < 40; i++)
    {
        var r = service.ApplyPeriodicTraining(late, 80, Array.Empty<StaffMember>(), new Random(100 + i), new DateOnly(2026, 3, 20),
            periodFraction: 1.0, reassessFocus: true);
        if (r.Focus == TrainingFocus.Physical) fitMoved++;
    }
    TestRunner.IsTrue(fitMoved > 0, "Final-phase rehab should run as a light PHYSICAL programme");
    TestRunner.AreEqual(lateTech, late.Batting.Technique, "...and never touches his batting technique - it is physical rehab only");
    TestRunner.IsTrue(late.Physical.Fitness >= fitBefore, "Physical fitness can only go up (or hold) from light rehab work");

    var crocked = MatchTestData.MakePlayer("CareerThreat", 14, PlayerRole.Batsman);
    crocked.CurrentInjury = new Injury(InjuryType.BackInjury, InjurySeverity.CareerThreatening, new DateOnly(2026, 1, 1), 400);
    var ctResult = service.ApplyPeriodicTraining(crocked, 80, Array.Empty<StaffMember>(), new Random(1), new DateOnly(2026, 12, 1),
        periodFraction: 1.0, reassessFocus: true);
    TestRunner.AreEqual(TrainingFocus.None, ctResult.Focus, "A career-threatening injury blocks all training regardless of phase");
});

TestRunner.Run("Wave 2: MatchDevelopmentService.ApplyMatchExperience develops a young player with headroom from playing well, format-aware, but barely touches a veteran at his ceiling", () =>
{
    var service = new MatchDevelopmentService();

    var youngGrew = 0;
    for (int trial = 0; trial < 20; trial++)
    {
        var young = MatchTestData.MakePlayer("Learner", 9, PlayerRole.Batsman);
        young.DateOfBirth = new DateOnly(2007, 1, 1); // ~19
        young.PotentialAbility = 170; // real headroom
        int powerBefore = young.Batting.PowerHitting + young.Batting.DeathOverBatting + young.Batting.BoundaryHitting;
        var rng = new Random(trial);
        for (int i = 0; i < 15; i++)
            service.ApplyMatchExperience(young, MatchFormat.T20, bowling: false, valuedRating: 45, matchImportance: 50, rng, new DateOnly(2026, 6, 1));
        if (young.Batting.PowerHitting + young.Batting.DeathOverBatting + young.Batting.BoundaryHitting > powerBefore) youngGrew++;
    }
    TestRunner.IsTrue(youngGrew >= 12, $"A young T20 batter with headroom, playing well, should develop his T20 cluster in most of 20 trials (got {youngGrew})");

    var vetGrew = 0;
    for (int trial = 0; trial < 20; trial++)
    {
        var vet = MatchTestData.MakePlayer("Veteran", 14, PlayerRole.Batsman);
        vet.DateOfBirth = new DateOnly(1988, 1, 1); // ~38
        int before = vet.Batting.PowerHitting + vet.Batting.Technique + vet.Batting.DefensiveAbility;
        var rng = new Random(trial);
        for (int i = 0; i < 15; i++)
            service.ApplyMatchExperience(vet, MatchFormat.T20, bowling: false, valuedRating: 45, matchImportance: 50, rng, new DateOnly(2026, 6, 1));
        if (vet.Batting.PowerHitting + vet.Batting.Technique + vet.Batting.DefensiveAbility > before) vetGrew++;
    }
    TestRunner.IsTrue(vetGrew <= 4, $"A 38-year-old should hardly ever 'develop' from playing (got {vetGrew} of 20)");
});

TestRunner.Run("Wave 2: the pressure moment - a big failure in a high-importance match sets an unresolved moment, and redemption clears it with a real lift; a resilient temperament redeems more reliably than a fragile one", () =>
{
    var service = new MatchDevelopmentService();

    // sets on a big failure
    var p = MatchTestData.MakePlayer("Stokes", 14, PlayerRole.BattingAllrounder, BowlingRoleType.FirstChange);
    service.ApplyMatchExperience(p, MatchFormat.T20, bowling: true, valuedRating: -60, matchImportance: 90, new Random(1), new DateOnly(2026, 4, 1));
    TestRunner.IsTrue(p.PendingPressureMoment is not null, "A big failure in a final should leave an unresolved pressure moment");
    double confAfterFail = p.Form.Confidence;

    // redemption in the next final clears it and lifts confidence
    service.ApplyMatchExperience(p, MatchFormat.T20, bowling: true, valuedRating: 55, matchImportance: 92, new Random(2), new DateOnly(2027, 6, 1));
    TestRunner.IsTrue(p.PendingPressureMoment is null, "A strong showing in the next big match clears the moment");
    TestRunner.IsTrue(p.Form.Confidence > confAfterFail, "...and lifts his confidence");

    // resilient vs fragile redemption reliability
    int resilientRedeemed = 0, fragileRedeemed = 0;
    for (int trial = 0; trial < 60; trial++)
    {
        var tough = MatchTestData.MakePlayer("Tough", 14);
        tough.Personality = PersonalityTrait.BigMatchPlayer | PersonalityTrait.Professional;
        var timid = MatchTestData.MakePlayer("Timid", 14);
        timid.Personality = PersonalityTrait.Inconsistent;

        service.ApplyMatchExperience(tough, MatchFormat.T20, false, -40, 90, new Random(trial), new DateOnly(2026, 4, 1));
        service.ApplyMatchExperience(timid, MatchFormat.T20, false, -40, 90, new Random(trial), new DateOnly(2026, 4, 1));

        int toughPh = tough.Mental.PressureHandling, timidPh = timid.Mental.PressureHandling;
        service.ApplyMatchExperience(tough, MatchFormat.T20, false, 40, 90, new Random(1000 + trial), new DateOnly(2027, 4, 1));
        service.ApplyMatchExperience(timid, MatchFormat.T20, false, 40, 90, new Random(1000 + trial), new DateOnly(2027, 4, 1));
        if (tough.Mental.PressureHandling > toughPh) resilientRedeemed++;
        if (timid.Mental.PressureHandling > timidPh) fragileRedeemed++;
    }
    TestRunner.IsTrue(resilientRedeemed > fragileRedeemed,
        $"A resilient player should learn from the redemption more often ({resilientRedeemed}) than a fragile one ({fragileRedeemed})");
});

TestRunner.Run("Wave 2: SituationalPerformanceModifier reads an unresolved pressure moment - a player carrying one is worse off under pressure than an identical player without", () =>
{
    var mod = new SituationalPerformanceModifier();

    var carrying = MatchTestData.MakePlayer("Carrying", 14);
    var clear = MatchTestData.MakePlayer("Clear", 14);
    carrying.PendingPressureMoment = new PressureMoment(new DateOnly(2026, 4, 1), Severity: 60, SubsequentAttempts: 2);

    double withMoment = mod.PressureAdjustment(carrying, pressureLevel: 90);
    double without = mod.PressureAdjustment(clear, pressureLevel: 90);
    TestRunner.IsTrue(withMoment < without, $"Carrying an unresolved big-match failure should drag a player down under pressure ({withMoment:F3} vs {without:F3})");

    // at ordinary pressure it does nothing
    TestRunner.AreEqual(mod.PressureAdjustment(carrying, 50), mod.PressureAdjustment(clear, 50),
        "At neutral pressure the moment has no effect - it is a big-occasion weight");
});

TestRunner.Run("Wave 2: WorldClockService's monthly tick now develops a player DURING a season, and a hired specialist coach out-develops facility quality alone", () =>
{
    var clock = new WorldClockService();

    double DevAdvantage(bool withCoach)
    {
        double totalDelta = 0;
        for (int trial = 0; trial < 6; trial++)
        {
            var world = EmptyWorld();
            var team = new Team { Name = "Dev FC" };
            team.Facilities.TrainingQuality = 45;
            world.Teams[team.Id] = team;

            if (withCoach)
            {
                var bc = new StaffMember { FirstName = "Batting", LastName = "Guru", Role = StaffRole.BattingCoach, TechnicalKnowledge = 19, Communication = 18, YearsExperience = 12 };
                world.Staff.Add(bc);
                team.StaffIds.Add(bc.Id);
            }

            var player = MatchTestData.MakePlayer("Pupil" + trial, 8, PlayerRole.Batsman);
            player.DateOfBirth = new DateOnly(2008, 1, 1);
            player.PotentialAbility = 180;
            player.CurrentTeamId = team.Id;
            player.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
            player.TrainingPlan.Intensity = TrainingIntensity.Normal;
            int before = player.Batting.Technique + player.Batting.Timing + player.Batting.ShotSelection + player.Batting.DefensiveAbility;
            world.Players.Add(player);

            var cal = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: trial);
            clock.AdvanceTo(cal, world, new DateOnly(2029, 6, 1));
            totalDelta += (player.Batting.Technique + player.Batting.Timing + player.Batting.ShotSelection + player.Batting.DefensiveAbility) - before;
        }
        return totalDelta;
    }

    double withCoachDev = DevAdvantage(true);
    double facilityOnlyDev = DevAdvantage(false);
    TestRunner.IsTrue(withCoachDev > 0, "Monthly training over three years should visibly develop a young player mid-career, not only at annual rollover");
    TestRunner.IsTrue(withCoachDev > facilityOnlyDev, $"A hired specialist batting coach should out-develop facility quality alone ({withCoachDev} vs {facilityOnlyDev})");
});

// -------------------- WAVE 3: continuous decay & relationship memory --------------------

TestRunner.Run("Wave 3: FormState.DecayConfidenceTowardNeutral moves confidence toward 50 from both directions and never overshoots", () =>
{
    var high = new FormState();
    high.RecordPerformance(100); // confidence up to ~60
    for (int i = 0; i < 100; i++) high.DecayConfidenceTowardNeutral(5);
    TestRunner.AreEqual(50.0, Math.Round(high.Confidence, 3), "Decays down to exactly 50, no lower");

    var low = new FormState();
    low.RecordPerformance(-100); // confidence down to ~40
    for (int i = 0; i < 100; i++) low.DecayConfidenceTowardNeutral(5);
    TestRunner.AreEqual(50.0, Math.Round(low.Confidence, 3), "Decays up to exactly 50, no higher");
});

TestRunner.Run("Wave 3: the monthly tick freezes form/morale decay for a genuinely unavailable player while an available one keeps decaying", () =>
{
