TestRunner.Run("Wave 3: MatchupConfidence blends a fast recent average with the slow career one - a reversal shows up in the blend before the career figure catches up", () =>
{
    var mc = new MatchupConfidence();
    for (int i = 0; i < 10; i++) mc.RecordOutcome(70); // long strong history
    double careerAfterGood = mc.Confidence;
    for (int i = 0; i < 3; i++) mc.RecordOutcome(-80); // a sharp recent reversal

    TestRunner.IsTrue(mc.RecentConfidence < mc.Confidence, "The recent average reacts faster to the reversal than the career one");
    TestRunner.IsTrue(mc.BlendedConfidence < careerAfterGood, "The blend consumers read is already reflecting the reversal");

    for (int i = 0; i < 40; i++) mc.DecayTowardNeutral(10);
    TestRunner.AreEqual(0.0, Math.Round(mc.RecentConfidence, 3), "The recent average decays too, not just the career one");
});

TestRunner.Run("Wave 3: GetMatchupMultiplier has a real minimum-sample threshold, and a known edge bites harder under pressure", () =>
{
    var svc = new MatchupConfidenceService();
    var p = MatchTestData.MakePlayer("Faced", 13);
    var key = MatchupKey.ForBowler(Guid.NewGuid());

    svc.RecordOutcome(p, key, -80);
    svc.RecordOutcome(p, key, -80);
    TestRunner.AreEqual(1.0, svc.GetMatchupMultiplier(p, key), "Two outcomes is a coincidence, not a matchup - exactly 1.0");

    svc.RecordOutcome(p, key, -80);
    double calm = svc.GetMatchupMultiplier(p, key, pressureLevel: 50);
    double knockout = svc.GetMatchupMultiplier(p, key, pressureLevel: 95);
    TestRunner.IsTrue(calm < 1.0, "Three genuine failures against a bowler now bite");
    TestRunner.IsTrue(knockout < calm, $"...and bite harder in a knockout ({knockout:F3}) than a dead rubber ({calm:F3})");
});

TestRunner.Run("Wave 3: returning from a real layoff, confidence is read back from the pre-injury level - a Professional recovers more of it than an Inconsistent player, and a Niggle leaves it untouched", () =>
{
    var avail = new PlayerAvailabilityService();

    double Recovered(PersonalityTrait personality, InjurySeverity severity)
    {
        var p = MatchTestData.MakePlayer("Returner", 13);
        p.Personality = personality;
        p.Form.RecordPerformance(100); // riding high - confidence ~60
        double preInjury = p.Form.Confidence;
        avail.ApplyInjury(p, InjuryType.Hamstring, severity, new DateOnly(2026, 1, 1), random: new Random(3));
        // drag his confidence to rock bottom while he is out, to prove it is READ BACK, not left as-is
        p.Form.AdjustConfidence(-40);
        avail.MarkRecovered(p, new DateOnly(2026, 6, 1));
        return p.Form.Confidence;
    }

    double pro = Recovered(PersonalityTrait.Professional | PersonalityTrait.Consistent, InjurySeverity.Serious);
    double flaky = Recovered(PersonalityTrait.Inconsistent, InjurySeverity.Serious);
    TestRunner.IsTrue(pro > 50 && flaky > 50, "Both recover SOME belief back toward their pre-injury level");
    TestRunner.IsTrue(pro > flaky, $"A professional comes back with more of his belief intact ({pro:F1}) than a flaky one ({flaky:F1})");

    // a niggle is not a "layoff" - confidence is left exactly where it was
    var n = MatchTestData.MakePlayer("Niggler", 13);
    n.Form.RecordPerformance(100);
    avail.ApplyInjury(n, InjuryType.Hamstring, InjurySeverity.Niggle, new DateOnly(2026, 1, 1), random: new Random(3));
    n.Form.AdjustConfidence(-20);
    double beforeReturn = n.Form.Confidence;
    avail.MarkRecovered(n, new DateOnly(2026, 1, 10));
    TestRunner.AreEqual(Math.Round(beforeReturn, 3), Math.Round(n.Form.Confidence, 3), "A niggle does not trigger the return-from-layoff confidence read");
});

TestRunner.Run("Wave 3: partnership chemistry decays on its own faster cadence, frozen when the partner is unavailable and decaying when both are available", () =>
{
    var chem = new PartnershipChemistryService();
    var a = MatchTestData.MakePlayer("PartA", 13);
    var b = MatchTestData.MakePlayer("PartB", 13);
    var c = MatchTestData.MakePlayer("PartC", 13);

    // A dominant partnership rating, so the faster decay is visible before it bottoms out at neutral.
    for (int i = 0; i < 5; i++)
    {
        chem.RecordPartnership(a, b, runs: 220, balls: 60, MatchFormat.T20, endedInRunOut: false);
        chem.RecordPartnership(a, c, runs: 220, balls: 60, MatchFormat.T20, endedInRunOut: false);
    }

    double abBefore = a.Matchups[MatchupKey.ForPartner(b.Id)].Confidence;
    double acBefore = a.Matchups[MatchupKey.ForPartner(c.Id)].Confidence;

    // b is genuinely unavailable; c is fit but just not being paired with a
    var unavailable = new HashSet<Guid> { b.Id };
    for (int month = 0; month < 12; month++)
        chem.DecayPartnerships(a, unavailable, periodFraction: 1.0 / 12.0);

    TestRunner.AreEqual(Math.Round(abBefore, 3), Math.Round(a.Matchups[MatchupKey.ForPartner(b.Id)].Confidence, 3),
        "Chemistry with an unavailable partner is frozen - no opportunity, no penalty");
    TestRunner.IsTrue(a.Matchups[MatchupKey.ForPartner(c.Id)].Confidence < acBefore,
        "Chemistry with an available partner they simply haven't batted with fades");

    // and it fades faster than a general matchup edge
    var opp = MatchupKey.ForOpponent(Guid.NewGuid());
    for (int i = 0; i < 5; i++) new MatchupConfidenceService().RecordOutcome(a, opp, 90);
    double oppBefore = a.Matchups[opp].Confidence;
    var mcSvc = new MatchupConfidenceService();
    for (int month = 0; month < 12; month++) mcSvc.DecayAll(a, 5.0 / 12.0, decayPartnerKeys: false);
    double oppFade = oppBefore - a.Matchups[opp].Confidence;
    double partnerFade = acBefore - a.Matchups[MatchupKey.ForPartner(c.Id)].Confidence;
    TestRunner.IsTrue(partnerFade > oppFade, $"Partnership chemistry ({partnerFade:F1}) fades faster than a general opponent edge ({oppFade:F1})");
});

TestRunner.Run("Wave 3: DecayAll(decayPartnerKeys: false) leaves partner keys alone while still decaying opponent keys", () =>
{
    var svc = new MatchupConfidenceService();
    var p = MatchTestData.MakePlayer("Mixed", 13);
    var opp = MatchupKey.ForOpponent(Guid.NewGuid());
    var partner = MatchupKey.ForPartner(Guid.NewGuid());
    for (int i = 0; i < 5; i++) { svc.RecordOutcome(p, opp, 80); svc.RecordOutcome(p, partner, 80); }

    double partnerBefore = p.Matchups[partner].Confidence;
    for (int i = 0; i < 5; i++) svc.DecayAll(p, amount: 10, decayPartnerKeys: false);

    TestRunner.IsTrue(p.Matchups[opp].Confidence < 80, "Opponent edge still decays");
    TestRunner.AreEqual(Math.Round(partnerBefore, 3), Math.Round(p.Matchups[partner].Confidence, 3), "Partner edge is left for PartnershipChemistryService to handle");
});

// -------------------- WAVE 4: coaching / staff realism --------------------

TestRunner.Run("Wave 4: the captain accumulator crystallises into real Leadership/DecisionMaking movement - fast for a young captain, negligible for a veteran, and a vice-captain banks a smaller share", () =>
{
    var growth = new CaptaincyGrowthService();

    int YoungGained(int matchesCaptained, double perMatchRating, int trials)
    {
        int gained = 0;
        for (int t = 0; t < trials; t++)
        {
            var cap = MatchTestData.MakePlayer("Cap" + t, 12);
            var profile = new CaptaincyProfile { PlayerId = cap.Id, MatchesCaptained = matchesCaptained };
            for (int m = 0; m < 4; m++) profile.AccumulateDecisionQuality(perMatchRating);
            int before = cap.Mental.Leadership + cap.Mental.DecisionMaking;
            growth.Crystallise(cap, profile, new Random(t));
            if (cap.Mental.Leadership + cap.Mental.DecisionMaking > before) gained++;
        }
        return gained;
    }

    int freshGood = YoungGained(matchesCaptained: 3, perMatchRating: 60, trials: 200);
    int veteranGood = YoungGained(matchesCaptained: 220, perMatchRating: 60, trials: 200);
    TestRunner.IsTrue(freshGood > veteranGood * 2, $"A new captain learns from good calls far faster ({freshGood}) than a 220-match veteran ({veteranGood})");

    // poor calls can erode decision-making
    var poorCap = MatchTestData.MakePlayer("PoorCap", 14);
    var poorProfile = new CaptaincyProfile { PlayerId = poorCap.Id, MatchesCaptained = 10 };
    int dmBefore = poorCap.Mental.DecisionMaking;
    int eroded = 0;
    for (int t = 0; t < 200; t++)
    {
        var c = MatchTestData.MakePlayer("PC" + t, 14);
        var pr = new CaptaincyProfile { PlayerId = c.Id, MatchesCaptained = 10 };
        for (int m = 0; m < 4; m++) pr.AccumulateDecisionQuality(-60);
        int b = c.Mental.DecisionMaking;
        growth.Crystallise(c, pr, new Random(t));
        if (c.Mental.DecisionMaking < b) eroded++;
    }
    TestRunner.IsTrue(eroded > 10, $"A sustained run of poor decision-quality should erode DecisionMaking sometimes ({eroded} of 200)");

    // vice-captain banks a smaller share
    var vc = new CaptaincyProfile { PlayerId = Guid.NewGuid() };
    var full = new CaptaincyProfile { PlayerId = Guid.NewGuid() };
    for (int m = 0; m < 5; m++) { full.AccumulateDecisionQuality(50); vc.AccumulateDecisionQuality(50, weight: 0.35); }
    TestRunner.IsTrue(vc.DecisionQualityAccumulator < full.DecisionQualityAccumulator, "A vice-captain banks a smaller fraction of the same signal");
});

TestRunner.Run("Wave 4: a real MatchSimulator match banks a decision-quality reading for both captains and (smaller) for a vice-captain", () =>
{
    var simulator = new MatchSimulator();
    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("W4Home", 14, 13);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("W4Away", 12, 12);

    var homeCaptain = MatchTestData.MakePlayer("W4HCap", 14);
    var homeVice = MatchTestData.MakePlayer("W4HVice", 14);
    var awayCaptain = MatchTestData.MakePlayer("W4ACap", 14);
    var homeVp = new CaptaincyProfile { PlayerId = homeVice.Id };
    var homeLeadership = new MatchLeadership { Captain = homeCaptain, Profile = new CaptaincyProfile { PlayerId = homeCaptain.Id }, ViceCaptain = homeVice, ViceCaptainProfile = homeVp };
    var awayLeadership = new MatchLeadership { Captain = awayCaptain, Profile = new CaptaincyProfile { PlayerId = awayCaptain.Id } };

    var setup = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "W4Home", homeOrder, homeBowlers),
        Away = new MatchSide(Guid.NewGuid(), "W4Away", awayOrder, awayBowlers),
        Format = MatchFormat.T20, OversPerInnings = 20,
        HomeLeadership = homeLeadership, AwayLeadership = awayLeadership
    };
    simulator.Simulate(setup, new Random(31));

    TestRunner.AreEqual(1, homeLeadership.Profile.AccumulatedMatches, "The home captain banked one match");
    TestRunner.AreEqual(1, awayLeadership.Profile.AccumulatedMatches, "The away captain banked one match");
    TestRunner.AreEqual(1, homeVp.AccumulatedMatches, "The vice-captain banked the match too");
    TestRunner.IsTrue(Math.Abs(homeVp.DecisionQualityAccumulator) < Math.Abs(homeLeadership.Profile.DecisionQualityAccumulator),
        "...but a smaller fraction of the signal than the captain");
});

TestRunner.Run("Wave 4: CoachCareerService.GrowFromMilestone scales with job context, and drifts a coach's profile toward his philosophy", () =>
{
    var career = new CoachCareerService();

    int MilestoneGrowth(double teamStrength, double competitionPrestige, int trials)
    {
        int total = 0;
        for (int t = 0; t < trials; t++)
        {
            var coach = new Coach { FirstName = "M", LastName = t.ToString(), Philosophy = CoachingPhilosophy.PerformanceFocused };
            var team = new Team { Strength = teamStrength, Reputation = new Reputation(domestic: teamStrength) };
            int before = coach.Attributes.TacticalKnowledge + coach.Attributes.MatchReading + coach.Attributes.DecisionMaking + coach.Attributes.Adaptability;
            career.GrowFromMilestone(coach, team, competitionPrestige, seasonsAtClub: 1, performanceScore: 0.4, new Random(t));
            total += coach.Attributes.TacticalKnowledge + coach.Attributes.MatchReading + coach.Attributes.DecisionMaking + coach.Attributes.Adaptability - before;
        }
        return total;
    }

    int bigJob = MilestoneGrowth(88, 85, 400);
    int smallJob = MilestoneGrowth(30, 25, 400);
    TestRunner.IsTrue(bigJob > smallJob, $"A coach at a big club in a prestigious competition learns faster ({bigJob}) than one at a small job ({smallJob})");

    // specialisation drift for an analytics coach
    int analysisDrift = 0;
    for (int t = 0; t < 400; t++)
    {
        var coach = new Coach { FirstName = "A", LastName = t.ToString(), Philosophy = CoachingPhilosophy.AnalyticsDriven };
        var team = new Team { Strength = 60, Reputation = new Reputation(domestic: 60) };
        int before = coach.Attributes.TacticalAnalysis + coach.Attributes.OppositionAnalysis + coach.Attributes.Statistics;
        career.GrowFromMilestone(coach, team, 60, 1, 0.5, new Random(t));
        analysisDrift += coach.Attributes.TacticalAnalysis + coach.Attributes.OppositionAnalysis + coach.Attributes.Statistics - before;
    }
    TestRunner.IsTrue(analysisDrift > 0, "An analytics-driven coach sharpens his analytical attributes on milestones, not only the in-match reads");
});

TestRunner.Run("Wave 4: ScrutinyFactor amplifies a marquee coach's board-trust swings at a big club versus a low-profile coach", () =>
{
    var career = new CoachCareerService();

    double TrustDropAfterBadSeason(double coachRep, double teamStanding)
    {
        var coach = new Coach { FirstName = "S", LastName = "C", Reputation = new Reputation(domestic: coachRep), BoardTrust = 60 };
        var team = new Team { Strength = teamStanding, Reputation = new Reputation(domestic: teamStanding) };
        var contract = new CoachingContract { CoachId = coach.Id, TeamId = team.Id, StartDate = new DateOnly(2024, 1, 1) };
        coach.CurrentContractId = contract.Id; coach.CurrentTeamId = team.Id; team.CurrentCoachId = coach.Id;
        double before = coach.BoardTrust;
        career.EvaluateSeason(coach, contract, team, performanceScore: -0.6, seasonsAtClub: 2, new Random(1));
        return before - coach.BoardTrust;
    }

    double marquee = TrustDropAfterBadSeason(coachRep: 85, teamStanding: 88);
    double lowProfile = TrustDropAfterBadSeason(coachRep: 25, teamStanding: 30);
    TestRunner.IsTrue(marquee > lowProfile, $"A bad season costs a marquee coach at a big club more trust ({marquee:F1}) than a low-profile one ({lowProfile:F1})");
});

TestRunner.Run("Wave 4: Type B - an ambitious coach overachieving at a small club draws rival interest, and the board either retains him on improved terms or he walks", () =>
{
    var career = new CoachCareerService();

    int interested = 0;
    for (int t = 0; t < 400; t++)
    {
        var coach = new Coach { FirstName = "Amb", LastName = t.ToString(), Reputation = new Reputation(domestic: 70), CareerSatisfaction = 60, BoardTrust = 65 };
        coach.Attributes.Ambition = 18;
        var team = new Team { Strength = 35, Reputation = new Reputation(domestic: 30) };
        if (career.EvaluateRivalInterest(coach, team, lastPerformanceScore: 0.7, new Random(t))) interested++;
    }
    TestRunner.IsTrue(interested > 10, $"An ambitious coach who has outgrown a small job should draw rival interest across trials (got {interested})");

    // trusting board retains
    var trusting = new Coach { FirstName = "T", LastName = "C", BoardTrust = 85, Reputation = new Reputation(domestic: 70) };
    var teamT = new Team { Name = "Trusting FC" };
    var contractT = new CoachingContract { CoachId = trusting.Id, TeamId = teamT.Id, EndDate = new DateOnly(2028, 1, 1), AnnualSalary = 100000 };
    trusting.CurrentContractId = contractT.Id; trusting.CurrentTeamId = teamT.Id; teamT.CurrentCoachId = trusting.Id;
    int retainedCount = 0;
    for (int t = 0; t < 100; t++)
    {
        var c = new Coach { FirstName = "T", LastName = t.ToString(), BoardTrust = 85 };
        var tm = new Team { Name = "TF" };
        var ct = new CoachingContract { CoachId = c.Id, TeamId = tm.Id, EndDate = new DateOnly(2028, 1, 1), AnnualSalary = 100000 };
        c.CurrentContractId = ct.Id; c.CurrentTeamId = tm.Id; tm.CurrentCoachId = c.Id;
        var (retained, _) = career.OfferRetention(c, ct, tm, new Random(t));
        if (retained) { retainedCount++; TestRunner.IsTrue(ct.AnnualSalary > 100000 && ct.Status == ContractStatus.Active, "A retention is a real pay rise on an active contract"); }
        else TestRunner.IsTrue(ct.Status == ContractStatus.Resigned && c.CurrentTeamId is null && tm.CurrentCoachId is null, "A failed retention detaches both sides");
    }
    TestRunner.IsTrue(retainedCount > 60, $"A high-trust board usually fights off a rival ({retainedCount} of 100)");
});

TestRunner.Run("Wave 4: StaffCareerService.GrowFromDevelopmentSignal rewards a specialist whose own cluster is outdeveloping the team, and penalises one whose cluster stagnates", () =>
{
    var career = new StaffCareerService();

    var battingCoach = new StaffMember { FirstName = "BC", LastName = "Good", Role = StaffRole.BattingCoach, Reputation = 40, TechnicalKnowledge = 12, Communication = 12 };
    var bowler1 = MatchTestData.MakePlayer("B1", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var bat1 = MatchTestData.MakePlayer("Ba1", 12, PlayerRole.Batsman);
    var bat2 = MatchTestData.MakePlayer("Ba2", 12, PlayerRole.Batsman);
    var players = new List<Player> { bowler1, bat1, bat2 };
    var dev = new Dictionary<Guid, double> { [bat1.Id] = 4, [bat2.Id] = 3, [bowler1.Id] = 0 }; // batters way ahead

    double repBefore = battingCoach.Reputation;
    career.GrowFromDevelopmentSignal(battingCoach, players, dev, new Random(1));
    TestRunner.IsTrue(battingCoach.Reputation > repBefore, "A batting coach whose batters are pulling ahead gains reputation");

    var stagnant = new StaffMember { FirstName = "BC", LastName = "Poor", Role = StaffRole.BattingCoach, Reputation = 60 };
    var devDown = new Dictionary<Guid, double> { [bat1.Id] = 0, [bat2.Id] = 0, [bowler1.Id] = 5 }; // his batters going nowhere, the bowler flying
    double stagRepBefore = stagnant.Reputation;
    career.GrowFromDevelopmentSignal(stagnant, players, devDown, new Random(1));
    TestRunner.IsTrue(stagnant.Reputation < stagRepBefore, "A batting coach whose batters stagnate while others improve loses reputation");

    // an analyst is skipped entirely - not judged on player development
    var analyst = new StaffMember { Role = StaffRole.Analyst, Reputation = 50 };
    career.GrowFromDevelopmentSignal(analyst, players, dev, new Random(1));
    TestRunner.AreEqual(50.0, analyst.Reputation, "An analyst's value is not player development, so this signal does not touch him");
});

TestRunner.Run("Wave 4: staff build their own reputation over tenure, IsHeadCoachCandidate is a high bar, and staff retention is coach-mediated (a good man-manager fights harder)", () =>
{
    var career = new StaffCareerService();

    var staff = new StaffMember { Role = StaffRole.AssistantCoach, Analysis = 13, TechnicalKnowledge = 13, Communication = 13, Diligence = 12, YearsExperience = 2, Reputation = 30 };
    double repBefore = staff.Reputation;
    for (int i = 0; i < 10; i++) career.GrowFromTenure(staff, new Random(i));
    TestRunner.IsTrue(staff.Reputation > repBefore, "A specialist's reputation drifts up toward his real quality over tenure");

    var notReady = new StaffMember { Role = StaffRole.AssistantCoach, Analysis = 10, Communication = 10, TechnicalKnowledge = 10, YearsExperience = 2, Reputation = 30 };
    TestRunner.IsTrue(!career.IsHeadCoachCandidate(notReady), "A middling, inexperienced assistant is not a head-coach candidate");
    var ready = new StaffMember { Role = StaffRole.AssistantCoach, Analysis = 17, Communication = 17, TechnicalKnowledge = 16, Diligence = 15, YearsExperience = 9, Reputation = 65 };
    TestRunner.IsTrue(career.IsHeadCoachCandidate(ready), "An experienced, well-regarded, genuinely effective assistant is");

    int fightGood = 0, fightPoor = 0;
    for (int t = 0; t < 200; t++)
    {
        var s1 = new StaffMember { Role = StaffRole.Analyst, CareerSatisfaction = 40 };
        var s2 = new StaffMember { Role = StaffRole.Analyst, CareerSatisfaction = 40 };
