        var c2 = new StaffContract { StaffId = s2.Id, TeamId = tm.Id, EndDate = new DateOnly(2028, 1, 1), AnnualSalary = 50000 };
        var goodManager = new Coach { Attributes = new CoachAttributes { ManManagement = 18 } };
        var poorManager = new Coach { Attributes = new CoachAttributes { ManManagement = 4 } };
        if (career.OfferRetention(s1, c1, tm, goodManager, new Random(t)).Retained) fightGood++;
        if (career.OfferRetention(s2, c2, tm, poorManager, new Random(t)).Retained) fightPoor++;
    }
