});

TestRunner.Run("Wave 4: InterimCoachService installs the assistant on a vacancy, does nothing without one, and can make a successful interim permanent", () =>
{
    var interim = new InterimCoachService();
    var world = EmptyWorld();

    var team = new Team { Name = "Vacant FC", Strength = 60, Reputation = new Reputation(domestic: 55) };
    world.Teams[team.Id] = team;

    // no assistant -> nothing happens
    TestRunner.IsTrue(interim.AppointInterim(team, world, new DateOnly(2026, 1, 1)) is null, "No assistant coach means no interim can be installed");

    var assistant = new StaffMember { FirstName = "Assistant", LastName = "Coach", Role = StaffRole.AssistantCoach, TeamId = team.Id, Analysis = 14, Communication = 14, TechnicalKnowledge = 13, Reputation = 55, YearsExperience = 7 };
    team.StaffIds.Add(assistant.Id);
    world.Staff.Add(assistant);

    var ev = interim.AppointInterim(team, world, new DateOnly(2026, 1, 1));
    TestRunner.IsTrue(ev is not null && ev.Type == GameEventType.CoachAppointedInterim, "The assistant steps up on a vacancy");
    TestRunner.AreEqual(assistant.Id, team.InterimCoachStaffId);

    // a genuine run + good results -> can be made permanent
    bool everPromoted = false;
    for (int t = 0; t < 40 && !everPromoted; t++)
    {
        var w = EmptyWorld();
        var tm = new Team { Name = "Promote FC", Strength = 60, Reputation = new Reputation(domestic: 55) };
        w.Teams[tm.Id] = tm;
        var asst = new StaffMember { FirstName = "A", LastName = t.ToString(), Role = StaffRole.AssistantCoach, TeamId = tm.Id, Reputation = 65, Analysis = 15, Communication = 15, TechnicalKnowledge = 14 };
        tm.StaffIds.Add(asst.Id); w.Staff.Add(asst);
        tm.InterimCoachStaffId = asst.Id;
        tm.InterimSince = new DateOnly(2025, 1, 1);
        var promo = interim.ConsiderPermanentPromotion(tm, w, new DateOnly(2026, 6, 1), lastPerformanceScore: 0.7, new Random(t));
        if (promo is not null)
        {
            everPromoted = true;
            TestRunner.IsTrue(promo.Type == GameEventType.CoachPromotedToPermanent, "The promotion event has the right type");
            TestRunner.IsTrue(tm.CurrentCoachId is not null && tm.InterimCoachStaffId is null, "He is a real head coach now, not the interim");
            TestRunner.IsTrue(w.Coaches.Count == 1 && w.CoachingContracts.Count == 1, "...with a Coach entity and a contract");
            TestRunner.IsTrue(asst.TeamId is null && !tm.StaffIds.Contains(asst.Id), "...and no longer the assistant");
        }
    }
    TestRunner.IsTrue(everPromoted, "A well-regarded interim with a real run and good results should sometimes be made permanent");
});

TestRunner.Run("Wave 4: the world clock installs an interim on a coach departure, and runs squad management on a quarterly cadence", () =>
{
    var clock = new WorldClockService();
    var world = EmptyWorld();

    var team = new Team { Name = "Clock W4 FC" };
    world.Teams[team.Id] = team;

    var assistant = new StaffMember { FirstName = "Interim", LastName = "Ready", Role = StaffRole.AssistantCoach, TeamId = team.Id };
    team.StaffIds.Add(assistant.Id);
    world.Staff.Add(assistant);

    // a coach whose contract expires quickly -> vacancy -> interim
    var coach = new Coach { FirstName = "Leaving", LastName = "Soon", CurrentTeamId = team.Id };
    var contract = new CoachingContract { CoachId = coach.Id, TeamId = team.Id, StartDate = new DateOnly(2020, 1, 1), EndDate = new DateOnly(2026, 1, 10) };
    coach.CurrentContractId = contract.Id;
    team.CurrentCoachId = coach.Id;
    world.Coaches.Add(coach);
    world.CoachingContracts.Add(contract);

    var cal = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: 9);
    var events = clock.AdvanceTo(cal, world, new DateOnly(2026, 3, 1));

    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.CoachAppointedInterim), "The assistant is installed as interim once the head coach's contract lapses");
    TestRunner.AreEqual(assistant.Id, team.InterimCoachStaffId);

    // squad management now runs quarterly: a Rest ends within a quarter, not a year
    var world2 = EmptyWorld();
    var restedPlayer = new Player
    {
        FirstName = "Rested", LastName = "Star",
        DateOfBirth = new DateOnly(1992, 1, 1),
        CurrentAbility = 150, PotentialAbility = 150,
        SquadStatus = SquadStatus.FirstChoice,
        CurrentSquadDecision = new SquadDecision { Type = SquadDecisionType.Rest, DecidedDate = new DateOnly(2026, 1, 1), ReviewDate = new DateOnly(2026, 3, 1) },
        NonInjuryUnavailability = UnavailabilityReason.Resting
    };
    world2.Players.Add(restedPlayer);
    var cal2 = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: 9);
    clock.AdvanceTo(cal2, world2, new DateOnly(2026, 5, 1)); // crosses the Apr 1 quarter tick
    TestRunner.IsTrue(restedPlayer.CurrentSquadDecision is null && restedPlayer.NonInjuryUnavailability == UnavailabilityReason.Available,
        "A two-month Rest is reviewed on the quarterly tick, not left running until the next annual rollover");
});

TestRunner.Run("Wave 4: a concluded competition grows the competing team's head coach (milestone cadence), across trial seeds", () =>
{
    var clock = new WorldClockService();
