        coach.CurrentContractId = contract.Id;
        team.CurrentCoachId = coach.Id;
        world.Coaches.Add(coach);
        world.CoachingContracts.Add(contract);

        var comp = new Competition { Name = "Campaign Cup", Prestige = 80, Window = CompetitionWindow.Annual(3, 1, 5, 30) };
        world.Competitions.Add(comp);
        for (int year = 2026; year <= 2030; year++)
