            var season = new CompetitionSeason { CompetitionId = comp.Id, Year = year };
            var standing = season.GetOrCreateStanding(team.Id);
            for (int i = 0; i < 6; i++) standing.RecordResult(MatchOutcome.Win, CompetitionPointsSystem.LimitedOvers);
            for (int i = 0; i < 2; i++) standing.RecordResult(MatchOutcome.Loss, CompetitionPointsSystem.LimitedOvers);
            world.CompetitionSeasons.Add(season);
        }

        int before = coach.Attributes.TacticalKnowledge + coach.Attributes.MatchReading + coach.Attributes.DecisionMaking + coach.Attributes.Adaptability;
        var cal = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: trial);
        clock.AdvanceTo(cal, world, new DateOnly(2031, 1, 2));
        int after = coach.Attributes.TacticalKnowledge + coach.Attributes.MatchReading + coach.Attributes.DecisionMaking + coach.Attributes.Adaptability;
        if (after > before) everGrew = true;
    }
    TestRunner.IsTrue(everGrew, "Across 25 trial worlds, a coach whose team plays several completed campaigns should grow tactically on the milestone cadence");
});

TestRunner.Run("Wave 4: GameCalendar.RandomForQuarter is deterministic and independent of the month/day/week/year streams", () =>
{
    var cal = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 4242);

    double q1a = cal.RandomForQuarter(2026, 1).NextDouble();
    double q1b = cal.RandomForQuarter(2026, 1).NextDouble();
    TestRunner.AreEqual(Math.Round(q1a, 10), Math.Round(q1b, 10), "Same quarter draws the identical stream twice");

    double q1 = cal.RandomForQuarter(2026, 1).NextDouble();
    double q2 = cal.RandomForQuarter(2026, 2).NextDouble();
    double m = cal.RandomForMonth(2026, 4).NextDouble();
    double d = cal.RandomForDay(new DateOnly(2026, 4, 1)).NextDouble();
    double w = cal.RandomForWeek(new DateOnly(2026, 4, 1)).NextDouble();
    TestRunner.IsTrue(q1 != q2 && q1 != m && q1 != d && q1 != w, "The quarterly stream is its own thing, not shared with any other cadence");
});

TestRunner.Run("Wave 4: Team.DelegatedResponsibilities.TrainingFocus makes a delegated specialist read the weakness more reliably", () =>
{
    var service = new TrainingService();

    var weakCoach = new StaffMember { Role = StaffRole.BattingCoach, TechnicalKnowledge = 5, Communication = 5, Analysis = 5, YearsExperience = 1 };

    int RightCalls(bool delegated, int trials)
    {
        int correct = 0;
        for (int t = 0; t < trials; t++)
        {
            var p = MatchTestData.MakePlayer("Weak" + t, 12, PlayerRole.Batsman);
            p.Batting.AgainstSpin = 2; p.Batting.SpinHandling = 2; // unambiguously his weakest cluster
            var f = service.SuggestFocus(p, new[] { weakCoach }, new Random(t), delegatedToStaff: delegated);
            if (f == TrainingFocus.BattingAgainstSpin) correct++;
        }
        return correct;
    }

    int notDelegated = RightCalls(false, 300);
    int delegatedCalls = RightCalls(true, 300);
    TestRunner.IsTrue(delegatedCalls >= notDelegated, $"A delegated specialist misreads less often ({delegatedCalls} correct vs {notDelegated})");
});



