TestRunner.Run("Wave 5: the senior consensus on the coach is standing-weighted - a disaffected senior star drags it further than a happy junior lifts it, and there is no consensus without seniors", () =>
{
    var room = new DressingRoomService();
    var asOf = new DateOnly(2026, 6, 1);

    Player Senior(string n, double trust)
    {
        var p = MatchTestData.MakePlayer(n, 15);
        p.DateOfBirth = new DateOnly(1992, 1, 1);
        p.Reputation = new Reputation(domestic: 80);
        p.Mental.Leadership = 16;
        p.Experience = PlayerExperience.FromExistingCareer(new Dictionary<MatchFormat, int> { [MatchFormat.Test] = 80 }, internationalMatches: 80, bigMatchAppearances: 15);
        p.CoachTrust = trust;
        return p;
    }
    Player Junior(string n, double trust)
    {
        var p = MatchTestData.MakePlayer(n, 9);
        p.DateOfBirth = new DateOnly(2006, 1, 1);
        p.Reputation = new Reputation(domestic: 5);
        p.CoachTrust = trust;
        return p;
    }

    var happy = new List<Player> { Senior("S1", 70), Senior("S2", 70), Junior("J1", 90), Junior("J2", 90) };
    var disaffected = new List<Player> { Senior("S3", 30), Senior("S4", 70), Junior("J3", 90), Junior("J4", 90) };

    double happyC = room.SeniorConsensusCoachTrust(happy, asOf)!.Value;
    double disC = room.SeniorConsensusCoachTrust(disaffected, asOf)!.Value;
    TestRunner.IsTrue(Math.Abs(happyC - 70) < 5, "With both seniors happy, the consensus is close to their view regardless of the ecstatic juniors");
    TestRunner.IsTrue(disC < 55, "One disaffected senior pulls the consensus down materially");

    var noSeniors = new List<Player> { Junior("J5", 80), Junior("J6", 20) };
    TestRunner.IsTrue(room.SeniorConsensusCoachTrust(noSeniors, asOf) is null, "No senior voice means no established view, not a negative one");
});

TestRunner.Run("Wave 5: room dynamics pull the juniors' trust toward the senior consensus over time, and harmony reflects how united AND how positive the seniors are", () =>
{
    var room = new DressingRoomService();
    var asOf = new DateOnly(2026, 6, 1);
    var team = new Team { Name = "Culture FC", CurrentStreak = 2 };

    Player Senior(string n, double trust) { var p = MatchTestData.MakePlayer(n, 15); p.DateOfBirth = new DateOnly(1992, 1, 1); p.Reputation = new Reputation(domestic: 80); p.Mental.Leadership = 16; p.Experience = PlayerExperience.FromExistingCareer(new Dictionary<MatchFormat, int>{[MatchFormat.Test]=80}, 80, 15); p.CoachTrust = trust; p.CurrentTeamId = team.Id; return p; }
    Player Junior(string n) { var p = MatchTestData.MakePlayer(n, 9); p.DateOfBirth = new DateOnly(2006, 1, 1); p.Reputation = new Reputation(domestic: 5); p.CoachTrust = 50; p.CurrentTeamId = team.Id; return p; }

    var united = new List<Player> { Senior("US1", 78), Senior("US2", 76), Junior("UJ1"), Junior("UJ2") };
    for (int m = 0; m < 12; m++) room.ApplyRoomDynamics(team, united, asOf, 1.0 / 12.0);
    TestRunner.IsTrue(united.First(p => p.FirstName == "UJ1").CoachTrust > 55, "Juniors' trust has drifted up toward the positive senior consensus");
    TestRunner.IsTrue(team.DressingRoomHarmony > 60, $"A united, positive senior group and a winning streak makes for a harmonious room ({team.DressingRoomHarmony:F0})");

    var splitTeam = new Team { Name = "Split FC", CurrentStreak = 0, DressingRoomHarmony = 60 };
