    Player Sr(PersonalityTrait pt) { var p = MatchTestData.MakePlayer("Sr", 15); p.DateOfBirth = new DateOnly(1992, 1, 1); p.Reputation = new Reputation(domestic: 80); p.Mental.Leadership = 16; p.Experience = PlayerExperience.FromExistingCareer(new Dictionary<MatchFormat, int>{[MatchFormat.Test]=80}, 80, 15); p.Personality = pt; return p; }
    Player Jr(PersonalityTrait pt) { var p = MatchTestData.MakePlayer("Jr", 8); p.DateOfBirth = new DateOnly(2006, 1, 1); p.Reputation = new Reputation(domestic: 5); p.Personality = pt; return p; }

    double good = mentoring.Compatibility(Sr(PersonalityTrait.Professional | PersonalityTrait.TeamOriented), Jr(PersonalityTrait.FastLearner | PersonalityTrait.Professional), asOf);
    double poor = mentoring.Compatibility(Sr(PersonalityTrait.Lazy), Jr(PersonalityTrait.Lazy | PersonalityTrait.MoneyFocused), asOf);
