});

TestRunner.Run("Wave 5: MentoringService.ReviewGroups pairs unmentored juniors with the best compatible senior, caps a senior at two mentees, and dissolves a group when the mentee graduates", () =>
{
    var mentoring = new MentoringService();
    var date = new DateOnly(2026, 6, 1);
    var team = new Team { Name = "Mentor FC" };

    Player Sr(string n, PersonalityTrait pt = PersonalityTrait.Professional | PersonalityTrait.TeamOriented)
    { var p = MatchTestData.MakePlayer(n, 15, PlayerRole.Batsman); p.DateOfBirth = new DateOnly(1992, 1, 1); p.Reputation = new Reputation(domestic: 82); p.Mental.Leadership = 17; p.Experience = PlayerExperience.FromExistingCareer(new Dictionary<MatchFormat, int>{[MatchFormat.Test]=80}, 80, 15); p.Personality = pt; p.CurrentTeamId = team.Id; return p; }
    Player Jr(string n)
    { var p = MatchTestData.MakePlayer(n, 8, PlayerRole.Batsman); p.DateOfBirth = new DateOnly(2006, 1, 1); p.Reputation = new Reputation(domestic: 5); p.Personality = PersonalityTrait.FastLearner; p.PotentialAbility = 170; p.CurrentTeamId = team.Id; return p; }

    var s1 = Sr("MSr1");
    var j1 = Jr("MJr1"); var j2 = Jr("MJr2"); var j3 = Jr("MJr3");
    var squad = new List<Player> { s1, j1, j2, j3 };
    var groups = new List<MentoringGroup>();

    mentoring.ReviewGroups(team, squad, groups, date);
    TestRunner.AreEqual(2, groups.Count, "One senior can mentor at most two juniors, so the third stays unmentored");

    var s2 = Sr("MSr2");
