    TestRunner.IsTrue(decoratedFloor >= 8, "...but never untouchable");
});

TestRunner.Run("Wave 7: success is team-appropriate - a developing side's coach who overachieves gains far more reputation than a powerhouse's coach for the same score", () =>
{
    var career = new CoachCareerService();

    var developingCoach = new Coach { FirstName = "Dev", LastName = "Coach" };
    var developingTeam = new Team { Strength = 30, Reputation = new Reputation(domestic: 25) };
    double devGain = career.UpdateCareerRecord(developingCoach, developingTeam, performanceScore: 0.6, wonTitle: false, wonMajorTitle: false, reachedMajorFinal: false);

    var eliteCoach = new Coach { FirstName = "Elite", LastName = "Coach" };
    var eliteTeam = new Team { Strength = 88, Reputation = new Reputation(domestic: 85, continental: 60) };
    double eliteGain = career.UpdateCareerRecord(eliteCoach, eliteTeam, performanceScore: 0.6, wonTitle: false, wonMajorTitle: false, reachedMajorFinal: false);

    TestRunner.IsTrue(devGain > eliteGain, $"Overachieving with a modest side is a bigger reputational story ({devGain:F1}) than the same score with a powerhouse ({eliteGain:F1})");

    TestRunner.AreEqual(CoachCareerService.TeamAmbitionTier.Elite, career.AmbitionTier(eliteTeam));
    TestRunner.AreEqual(CoachCareerService.TeamAmbitionTier.Developing, career.AmbitionTier(developingTeam));
});

TestRunner.Run("Wave 7: an elite club's coach who goes a whole tenure without a trophy comes under real board pressure, and the world clock records majors won into his track record", () =>
{
    var clock = new WorldClockService();
    var world = EmptyWorld();

    var eliteTeam = new Team { Name = "Powerhouse", Strength = 90, Reputation = new Reputation(domestic: 88, continental: 70) };
    world.Teams[eliteTeam.Id] = eliteTeam;

    var coach = new Coach { FirstName = "No", LastName = "Silverware", CurrentTeamId = eliteTeam.Id, BoardTrust = 55 };
    var contract = new CoachingContract { CoachId = coach.Id, TeamId = eliteTeam.Id, StartDate = new DateOnly(2020, 1, 1), EndDate = new DateOnly(2040, 1, 1) };
    coach.CurrentContractId = contract.Id;
    eliteTeam.CurrentCoachId = coach.Id;
    world.Coaches.Add(coach);
    world.CoachingContracts.Add(contract);

    var league = new Competition { Name = "Elite League", Prestige = 60 };
    var worldCup = new Competition { Name = "The World Cup", Scope = CompetitionScope.International, Prestige = 90 };
    world.Competitions.Add(league);
    world.Competitions.Add(worldCup);

    var rival = new Team { Name = "Rival", Strength = 80 };
    world.Teams[rival.Id] = rival;

    for (int year = 2026; year <= 2033; year++)
    {
        // respectable domestic seasons - always second, never champions
        var s = new CompetitionSeason { CompetitionId = league.Id, Year = year };
        var st = s.GetOrCreateStanding(eliteTeam.Id);
        for (int i = 0; i < 7; i++) st.RecordResult(MatchOutcome.Win);
        for (int i = 0; i < 3; i++) st.RecordResult(MatchOutcome.Loss);
        var rt = s.GetOrCreateStanding(rival.Id);
        for (int i = 0; i < 9; i++) rt.RecordResult(MatchOutcome.Win);
        s.Complete(rival.Id);
        world.CompetitionSeasons.Add(s);

        if (year == 2027)
        {
            var wc = new CompetitionSeason { CompetitionId = worldCup.Id, Year = year };
            wc.GetOrCreateStanding(eliteTeam.Id).RecordResult(MatchOutcome.Win);
            wc.PlayoffQualifiedTeamIds.Add(eliteTeam.Id);
            wc.Complete(eliteTeam.Id); // won the World Cup once
            world.CompetitionSeasons.Add(wc);
        }
    }

    double trustBefore = coach.BoardTrust;
    var cal = GameCalendar.Restore(new DateOnly(2026, 1, 1), new DateOnly(2026, 1, 1), worldSeed: 7);
    clock.AdvanceTo(cal, world, new DateOnly(2034, 1, 2));

    TestRunner.AreEqual(1, coach.CareerRecord.MajorTitlesWon, "The World Cup win is recorded as a major title");
    TestRunner.IsTrue(coach.CareerRecord.SeasonsCoached >= 7, "Every completed season is folded into his record");
    TestRunner.IsTrue(coach.CareerRecord.SeasonsSinceLastTitle >= 4, "The trophy drought since the World Cup is being tracked");
    TestRunner.IsTrue(coach.BoardTrust < trustBefore, "A long trophyless run at a powerhouse erodes board trust despite respectable finishes");
});

