TestRunner.Run("Wave 8: RankingService moves points opposition-adjusted - beating a stronger, higher-rated side is worth far more than beating a weaker one, and a real climb lifts reputation", () =>
{
    var svc = new RankingService();
    var rankings = new List<TeamRanking>();

    var minnow = new Team { Name = "Minnow", Strength = 35 };
    var giant = new Team { Name = "Giant", Strength = 90 };
    var mid = new Team { Name = "Mid", Strength = 60 };

    // seed the giant high, the minnow low
    svc.GetOrCreate(rankings, giant, MatchFormat.T20);
    svc.GetOrCreate(rankings, minnow, MatchFormat.T20);
    svc.GetOrCreate(rankings, mid, MatchFormat.T20);

    double minnowBefore = rankings.First(r => r.TeamId == minnow.Id).Points;

    svc.RecordMatch(rankings, minnow, giant, MatchFormat.T20, winnerId: minnow.Id, homeStrength: 35, awayStrength: 90);
    double afterUpset = rankings.First(r => r.TeamId == minnow.Id).Points;

    svc.RecordMatch(rankings, minnow, mid, MatchFormat.T20, winnerId: minnow.Id, homeStrength: 35, awayStrength: 60);
    double afterOrdinaryWin = rankings.First(r => r.TeamId == minnow.Id).Points;

    TestRunner.IsTrue(afterUpset - minnowBefore > afterOrdinaryWin - afterUpset,
        "Beating the top-ranked giant is worth far more ranking points than a subsequent win over a mid side");

    // reputation effect
    var climbingTeam = new Team { Name = "Climber", Reputation = new Reputation(domestic: 30) };
    var topRanking = new TeamRanking { TeamId = climbingTeam.Id, Format = MatchFormat.T20, Points = 120, Position = 1 };
    double repBefore = climbingTeam.Reputation.Domestic;
    for (int m = 0; m < 6; m++) svc.ApplyReputationEffect(climbingTeam, topRanking, fieldSize: 10);
    TestRunner.IsTrue(climbingTeam.Reputation.Domestic > repBefore + 3, "Sitting at the top of a format's rankings lifts a team's standing over time");
});

TestRunner.Run("Wave 8: MatchRecorder updates rankings only when the caller supplies a rankings list, and leaves them untouched otherwise", () =>
{
    var (homeOrder, homeBowlers) = MatchTestData.MakeEleven("RkHome", 14, 13);
    var (awayOrder, awayBowlers) = MatchTestData.MakeEleven("RkAway", 12, 12);
    var homeId = Guid.NewGuid(); var awayId = Guid.NewGuid();
    var setup = new MatchSetup
    {
        Home = new MatchSide(homeId, "RkHome", homeOrder, homeBowlers),
        Away = new MatchSide(awayId, "RkAway", awayOrder, awayBowlers),
        Format = MatchFormat.T20, OversPerInnings = 20, MatchDate = new DateOnly(2026, 6, 1)
    };
    var result = new MatchSimulator().Simulate(setup, new Random(3));

    var home = new Team { Id = homeId, Name = "RkHome", Strength = 65 };
    var away = new Team { Id = awayId, Name = "RkAway", Strength = 55 };
    var teams = new Dictionary<Guid, Team> { [homeId] = home, [awayId] = away };
    var players = homeOrder.Concat(homeBowlers).Concat(awayOrder).Concat(awayBowlers).GroupBy(p => p.Id).ToDictionary(g => g.Key, g => g.First());

    var recorder = new MatchRecorder();
    recorder.Record(result, players, teams: teams); // no rankings list
    // (no ranking list to inspect - just proving it does not throw)

    var rankings = new List<TeamRanking>();
    recorder.Record(result, players, teams: teams, rankings: rankings);
    TestRunner.AreEqual(2, rankings.Count, "Supplying a rankings list creates and updates a row for each side");
    TestRunner.IsTrue(rankings.All(r => r.MatchesRated == 1 && r.Position >= 1), "Both rows absorbed the match and got a table position");
});

