        int before = asst.Analysis + asst.Communication + asst.TechnicalKnowledge;
        interim.GrowInterimFromMilestone(asst, team, competitionPrestige: 80, new Random(t));
        totalGrowth += asst.Analysis + asst.Communication + asst.TechnicalKnowledge - before;
