TestRunner.Run("Inconsistency fix: partnership chemistry with an unavailable partner is frozen, while a pairing that simply hasn't batted together decays - one flat call would treat both the same", () =>
{
    // This is the CLAUDE.md review-pass inconsistency: point 8's flat monthly decay vs point 6's
    // injury-freeze. DecayPartnerships must branch on WHY the pair hasn't played together.
    var chem = new PartnershipChemistryService();
    var star = MatchTestData.MakePlayer("Star", 15);
    var injuredPartner = MatchTestData.MakePlayer("Injured", 15);
    var fitPartner = MatchTestData.MakePlayer("Fit", 15);

    for (int i = 0; i < 5; i++)
    {
        chem.RecordPartnership(star, injuredPartner, 200, 60, MatchFormat.T20, false);
        chem.RecordPartnership(star, fitPartner, 200, 60, MatchFormat.T20, false);
    }
    double injuredBefore = star.Matchups[MatchupKey.ForPartner(injuredPartner.Id)].Confidence;
    double fitBefore = star.Matchups[MatchupKey.ForPartner(fitPartner.Id)].Confidence;

    var unavailable = new HashSet<Guid> { injuredPartner.Id };
    for (int m = 0; m < 10; m++) chem.DecayPartnerships(star, unavailable, 1.0 / 12.0);

    TestRunner.AreEqual(Math.Round(injuredBefore, 3), Math.Round(star.Matchups[MatchupKey.ForPartner(injuredPartner.Id)].Confidence, 3),
        "Chemistry with the injured partner is frozen - he had no opportunity");
    TestRunner.IsTrue(star.Matchups[MatchupKey.ForPartner(fitPartner.Id)].Confidence < fitBefore,
        "Chemistry with the fit partner they haven't batted with decays - the opportunity was there");
});


