    for (int s = 0; s < 40; s++)
    {
        julyTemp += svc.Generate(lahore, new DateOnly(2026, 7, 15), new Random(s)).TemperatureC;
        janTemp += svc.Generate(lahore, new DateOnly(2026, 1, 15), new Random(s)).TemperatureC;
    }
