TestRunner.Run("6.1: MatchSetup.HomeAdvantage defaults neutral (existing sims unchanged) and a real edge shifts results toward the home side", () =>
{
    var sim = new MatchSimulator();
    var homeId = Guid.NewGuid();
    var awayId = Guid.NewGuid();

    MatchSetup Build(double edge)
    {
        var (ho, hb) = MatchTestData.MakeEleven("Home", 13, 13);
        var (ao, ab) = MatchTestData.MakeEleven("Away", 13, 13);
        return new MatchSetup
        {
            Home = new MatchSide(homeId, "Home", ho, hb),
            Away = new MatchSide(awayId, "Away", ao, ab),
            Format = MatchFormat.T20, OversPerInnings = 20,
            HomeAdvantage = edge
        };
    }

    // Neutral edge == not setting it at all: identical result for a given seed.
    var neutral = sim.Simulate(Build(0), new Random(123));
    var unset = sim.Simulate(new MatchSetup
    {
        Home = Build(0).Home, Away = Build(0).Away, Format = MatchFormat.T20, OversPerInnings = 20
    }, new Random(123));
    TestRunner.AreEqual(neutral.FirstInnings.Runs, unset.FirstInnings.Runs, "HomeAdvantage 0 is byte-identical to never setting it");

    int homeWinsNeutral = 0, homeWinsEdge = 0;
    for (int s = 0; s < 60; s++)
    {
        if (sim.Simulate(Build(0), new Random(s)).WinningTeamId == homeId) homeWinsNeutral++;
        if (sim.Simulate(Build(0.05), new Random(s)).WinningTeamId == homeId) homeWinsEdge++;
    }
    TestRunner.IsTrue(homeWinsEdge > homeWinsNeutral, $"A 5% home edge wins more often ({homeWinsEdge} vs {homeWinsNeutral} of 60)");
});

TestRunner.Run("6.1: Rivalry reinforces on a meeting that mattered and an emergent one fades when dormant; geographic never fades", () =>
{
    var a = Guid.NewGuid();
    var b = Guid.NewGuid();

    var emergent = new Rivalry { TeamAId = a, TeamBId = b, Source = RivalrySource.Emergent };
    emergent.SetIntensity(40);
    emergent.Reinforce(new DateOnly(2026, 5, 1), 8);
    TestRunner.IsTrue(emergent.Intensity > 40, "A final between the two cranks the rivalry up");
    double afterReinforce = emergent.Intensity;
    for (int y = 0; y < 5; y++) emergent.Fade(3);
    TestRunner.IsTrue(emergent.Intensity < afterReinforce, "Left dormant, an emergent rivalry cools off");

    var derby = new Rivalry { TeamAId = a, TeamBId = b, Source = RivalrySource.Geographic };
    derby.SetIntensity(82);
    for (int y = 0; y < 10; y++) derby.Fade(3);
    TestRunner.AreEqual(82.0, derby.Intensity, "A derby does not fade - Fade is a no-op for a geographic rivalry");
    TestRunner.IsTrue(derby.Match(b, a) && derby.Involves(a), "The pair is order-independent");
});

TestRunner.Run("6.1: FixturePlayService plays a scheduled fixture - it completes, updates the table, logs appearances, and is deterministic", () =>
{
    (WorldState World, GameCalendar Calendar, CompetitionSeason Season, List<Team> Teams) Fresh()
    {
        var seeder = new WorldSeeder(seed: 55, worldStartDate: new DateOnly(2026, 6, 1));
        var (teams, players) = seeder.GenerateStarterWorld(teamCount: 2, squadSize: 14);
        var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
        var world = new WorldState
        {
            Teams = teams.ToDictionary(t => t.Id),
            Grounds = grounds.ToDictionary(g => g.Id),
            Players = players.ToList(),
            Projects = new List<InfrastructureProject>(),
            Competitions = { comp }
        };
        world.CompetitionSeasons.Add(season);
        var fixture = new Fixture
        {
            CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Round 1", RoundNumber = 1,
            HomeTeamId = teams[0].Id, AwayTeamId = teams[1].Id,
            ScheduledDate = new DateOnly(2026, 9, 20), GroundId = teams[0].HomeGroundId
        };
        world.Fixtures.Add(fixture);
        return (world, new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 55), season, teams);
    }

    var (w1, c1, s1, teams1) = Fresh();
    var report = new FixturePlayService().PlayDueFixtures(w1, c1, new DateOnly(2026, 9, 20));

    TestRunner.AreEqual(1, report.FixturesPlayed, "The one fixture due today was played");
    TestRunner.AreEqual(FixtureStatus.Completed, w1.Fixtures[0].Status, "...and marked completed");
    TestRunner.IsTrue(w1.Fixtures[0].ResultingMatchId is not null, "...with a real match id");
    TestRunner.IsTrue(s1.Standings.Sum(st => st.Played) == 2, "Both sides' standings rows show a game played");
    // Appearance logging follows batting/bowling participation (the recorder's existing behaviour):
    // a pure fielder who neither batted nor bowled is not counted. See CLAUDE.md tech-debt note.
    TestRunner.IsTrue(w1.MatchesThisSeason.Count >= 12, $"The players who batted or bowled were logged as having appeared ({w1.MatchesThisSeason.Count})");
    TestRunner.IsTrue(report.Events.Any(e => e.Type == GameEventType.MatchCompleted), "A MatchCompleted event was raised");

    string WinnerName(WorldState w, List<Team> ts) =>
        w.Fixtures[0].WinningTeamId is { } id ? ts.First(t => t.Id == id).Name : "(no result)";

    var (w2, c2, _, teams2) = Fresh();
    new FixturePlayService().PlayDueFixtures(w2, c2, new DateOnly(2026, 9, 20));
    TestRunner.AreEqual(WinnerName(w1, teams1), WinnerName(w2, teams2), "Same seed -> same winner (deterministic, by team name)");
});

TestRunner.Run("6.1: the world clock plays a competition's fixtures as its window passes, and fills the table reproducibly", () =>
{
    // Compares by TEAM NAME, not TeamId - two seeder runs build structurally identical worlds
    // but with fresh Guids, so a Guid-ordered comparison would be meaningless. The point of the
    // test is that the SIMULATION is Guid-independent and reproducible from the seed.
    string Run(int seed)
    {
        var seeder = new WorldSeeder(seed: seed, worldStartDate: new DateOnly(2026, 6, 1));
        var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);
        var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
        var (fixtures, rivalries) = seeder.GenerateFixturesAndRivalries(comp, season, teams, grounds);
        var world = new WorldState
        {
            Teams = teams.ToDictionary(t => t.Id),
            Grounds = grounds.ToDictionary(g => g.Id),
            Players = players.ToList(),
            Projects = new List<InfrastructureProject>(),
            Competitions = { comp }
        };
        world.CompetitionSeasons.Add(season);
        foreach (var f in fixtures) world.Fixtures.Add(f);
        foreach (var r in rivalries) world.Rivalries.Add(r);
        new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: seed), world, new DateOnly(2027, 4, 1));

        int played = world.Fixtures.Count(f => f.Status == FixtureStatus.Completed);
        TestRunner.IsTrue(played >= 10, $"Most of the double round-robin was played as the window passed ({played} of {world.Fixtures.Count})");
        TestRunner.AreEqual(played * 2, season.Standings.Sum(st => st.Played), "The table's games-played total matches the fixtures completed");
        TestRunner.IsTrue(season.Standings.Any(st => st.Points > 0), "Somebody has points on the board");

        var nameById = teams.ToDictionary(t => t.Id, t => t.Name);
        return string.Join(";", season.Standings
            .Select(st => (Name: nameById[st.TeamId], st.Points, st.Played))
            .OrderBy(x => x.Name)
            .Select(x => $"{x.Name}={x.Points}/{x.Played}"));
    }

    TestRunner.AreEqual(Run(808), Run(808), "The same seed produces the same final table (by team name)");
});

TestRunner.Run("6.1: FixturePlayService advances a knockout bracket - a semi-final winner propagates into the final", () =>
{
    var seeder = new WorldSeeder(seed: 71, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);
