TestRunner.Run("6.1: playing a fixture between rivals renews the rivalry and swings the two sides' morale further apart", () =>
{
    var seeder = new WorldSeeder(seed: 91, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 2, squadSize: 14);
    var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);

    var rivalry = new Rivalry { TeamAId = teams[0].Id, TeamBId = teams[1].Id, Source = RivalrySource.Historical };
    rivalry.SetIntensity(70);
    world.Rivalries.Add(rivalry);
    double intensityBefore = rivalry.Intensity;

    int seq = 0;
    int decisiveMeetings = 0;
    bool sawRealGap = false;
    for (int s = 0; s < 8; s++)
    {
        var f = new Fixture
        {
            CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Final", RoundNumber = 0, SequenceNumber = seq++,
            HomeTeamId = teams[0].Id, AwayTeamId = teams[1].Id,
            ScheduledDate = new DateOnly(2026, 11, 1).AddDays(s * 7), GroundId = teams[0].HomeGroundId
        };
        world.Fixtures.Add(f);
        double gapBefore = Math.Abs(teams[0].Morale.Level - teams[1].Morale.Level);
        new FixturePlayService().PlayDueFixtures(world, new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 91 + s), f.ScheduledDate);
        if (f.WinningTeamId is not null)
        {
            decisiveMeetings++;
            if (Math.Abs(teams[0].Morale.Level - teams[1].Morale.Level) - gapBefore > 3) sawRealGap = true;
        }
    }

    TestRunner.IsTrue(rivalry.LastReinforced is not null && rivalry.Intensity > intensityBefore, "Meetings renew and crank up the rivalry");
    TestRunner.IsTrue(decisiveMeetings >= 4, $"Most rival meetings produce a result ({decisiveMeetings} of 8)");
    TestRunner.IsTrue(sawRealGap, "Beating your rival swings the two sides' morale further apart than an ordinary win");
});

