TestRunner.Run("6.2: a human club's ManagerPreferences are respected - delegation off means no auto squad; AlwaysInclude / NeverSelect are honoured when on", () =>
{
    var seeder = new WorldSeeder(seed: 202, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 16);
    var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);

    var humanTeam = teams[0];
    var humanCoach = new Coach { FirstName = "The", LastName = "Player", IsHumanControlled = true };
    humanCoach.CurrentTeamId = humanTeam.Id;
    humanTeam.CurrentCoachId = humanCoach.Id;
    world.Coaches.Add(humanCoach);
    humanTeam.ManagerPreferences.DelegateSquadSelection = false;

    var ai = new AiClubManagementService();
    var rng = new Random(1);
    foreach (var _ in ai.RunMonthly(world, new GameCalendar(new DateOnly(2026, 9, 1), worldSeed: 202), new DateOnly(2026, 9, 1), rng)) { }

    TestRunner.IsTrue(!world.SquadAnnouncements.Any(a => a.TeamId == humanTeam.Id),
        "Delegation off -> the sim does not name the human's squad for him");
    TestRunner.IsTrue(world.SquadAnnouncements.Any(a => a.TeamId == teams[1].Id),
        "...but the AI clubs still get their squads named");

    // Now turn delegation on, with explicit honoured/blocked players.
    humanTeam.ManagerPreferences.DelegateSquadSelection = true;
    var roster = world.Players.Where(p => humanTeam.SquadPlayerIds.Contains(p.Id)).ToList();
    var star = roster.OrderByDescending(p => p.CurrentAbility).First();
    var fringe = roster.OrderBy(p => p.CurrentAbility).First();
    humanTeam.ManagerPreferences.NeverSelect.Add(star.Id);
    humanTeam.ManagerPreferences.AlwaysInclude.Add(fringe.Id);

    var squad = ai.PickSquad(world, humanTeam, MatchFormat.T20, new DateOnly(2026, 9, 1), humanCoach);
    TestRunner.IsTrue(!squad.Contains(star.Id), "NeverSelect keeps the star out even though he is the best player");
    TestRunner.IsTrue(squad.Contains(fringe.Id), "AlwaysInclude keeps the fringe player in");
});

