TestRunner.Run("6.2: a full seeded world advanced through a season twice produces the same fixtures, table and squads", () =>
{
    // Guid-independent projection: everything keyed by NAME, since two seeder runs get fresh Guids.
    string Run(int seed)
    {
        var seeder = new WorldSeeder(seed: seed, worldStartDate: new DateOnly(2026, 6, 1));
        var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);
        var (grounds, comp, s) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
        var (fixtures, rivalries) = seeder.GenerateFixturesAndRivalries(comp, s, teams, grounds);
        var world = new WorldState
        {
            Teams = teams.ToDictionary(t => t.Id),
            Grounds = grounds.ToDictionary(g => g.Id),
            Players = players.ToList(),
            Projects = new List<InfrastructureProject>(),
            Competitions = { comp }
        };
        world.CompetitionSeasons.Add(s);
        foreach (var f in fixtures) world.Fixtures.Add(f);
        foreach (var r in rivalries) world.Rivalries.Add(r);
        new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: seed), world, new DateOnly(2027, 4, 1));

        var teamName = teams.ToDictionary(t => t.Id, t => t.Name);
        var playerName = players.ToDictionary(p => p.Id, p => p.FullName);
        int played = world.Fixtures.Count(f => f.Status == FixtureStatus.Completed);

        string table = string.Join(",", s.Standings
            .Select(st => (Name: teamName[st.TeamId], st.Points, st.NetRunRate))
            .OrderBy(x => x.Name)
            .Select(x => $"{x.Name}={x.Points}/{x.NetRunRate:0.00}"));

        string squads = string.Join(";", world.SquadAnnouncements
            .Select(a => (Team: teamName[a.TeamId], Players: string.Join(",", a.PlayerIds.Select(id => playerName[id]).OrderBy(n => n))))
            .OrderBy(x => x.Team)
            .Select(x => $"{x.Team}:{x.Players}"));

        return $"played={played}|{table}|{squads}";
    }

    TestRunner.AreEqual(Run(1234), Run(1234), "The same seed reproduces the whole season - fixtures, table and squads");
});


