TestRunner.Run("6.3: finishing a season pays prize money into budgets and names a player of the series", () =>
{
    var seeder = new WorldSeeder(seed: 62, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);
    var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
    var (fixtures, rivalries) = seeder.GenerateFixturesAndRivalries(comp, season, teams, grounds);
    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);
    foreach (var f in fixtures) world.Fixtures.Add(f);
    foreach (var r in rivalries) world.Rivalries.Add(r);

    var budgetsBefore = teams.ToDictionary(t => t.Id, t => t.Finances.Budget);

    var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 62), world, new DateOnly(2027, 4, 1));

    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.SeasonCompleted), "A SeasonCompleted event fired");
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.PlayerOfTheSeriesAwarded), "A player of the series was named");
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.BroadcastRevenuePaid), "Phase 7: broadcast money was distributed on season completion");
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.TeamFinancesSettled), "Phase 7: the season's finances were settled (sponsorship, matchday, upkeep, wages)");
    // NOTE: with Phase 7's real (stub) wage bill, a completed season no longer guarantees every
    // club's budget GREW - a small club can spend more on wages than it earns, which is a
    // legitimate finance-loop outcome. What is guaranteed is that the competition money landed:
    // the total prize + broadcast money paid across the four clubs is a large positive figure.
    double totalCompetitionMoney = new CricketManager.Domain.Services.CompetitionRevenueService()
        .DistributeSeasonRevenue(comp, world.CompetitionSeasons.First(s => s.CompetitionId == comp.Id && s.IsCompleted))
        .Sum(e => e.Total);
    TestRunner.IsTrue(totalCompetitionMoney > 100_000, $"Real competition prize/participation money was distributed ({totalCompetitionMoney:N0})");
    TestRunner.IsTrue(!world.SeasonContributions.ContainsKey(season.Id), "The season's contribution accumulator was cleared once the award was made");

    // §10.6 (Follow-up Pass 3, register correction - already built, not new logic this pass):
    // domestic prize money is surfaced as its own news line naming the biggest cheques, not just
    // banked silently into a budget - the same treatment a franchise-league title already got.
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.FranchisePrizeMoney && e.Headline.Contains("prize money is paid out")),
        "§10.6: the domestic prize money is surfaced as its own news line naming the biggest cheques");
});

