TestRunner.Run("Phase 10: a THREE-tier domestic pyramid cascades promotion/relegation along the whole chain", () =>
{
    var seeder = new WorldSeeder(seed: 71, worldStartDate: new DateOnly(2026, 3, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 9, squadSize: 12);
