    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var d in divisions) world.Competitions.Add(d);
    foreach (var s in seasons) world.CompetitionSeasons.Add(s);
    foreach (var f in fixtures) world.Fixtures.Add(f);
    foreach (var r in rivalries) world.Rivalries.Add(r);

    var midTeams2026 = seasons.First(s => s.CompetitionId == divisions[1].Id).ParticipatingTeamIds.ToHashSet();
    var d3Teams2026 = seasons.First(s => s.CompetitionId == divisions[2].Id).ParticipatingTeamIds.ToHashSet();

