    TestRunner.IsTrue(promoted >= 2, $"promotions happened at more than one level of the pyramid ({promoted})");
    TestRunner.IsTrue(relegated >= 2, $"relegations happened at more than one level ({relegated})");

    var mid2027 = world.CompetitionSeasons.First(s => s.CompetitionId == divisions[1].Id && s.Year == 2027).ParticipatingTeamIds.ToHashSet();
    TestRunner.AreEqual(midTeams2026.Count, mid2027.Count, "the middle division keeps its size - it swaps with both neighbours");
    TestRunner.IsTrue(!midTeams2026.SetEquals(mid2027), "...but its membership changed on both sides");
});

TestRunner.Run("Phase 10: the seeded world has three domestic formats per country plus associate national teams and a qualifier", () =>
{
    var seeder = new WorldSeeder(seed: 88, worldStartDate: new DateOnly(2026, 6, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "England", "Australia", "India" }, teamsPerCountry: 4, squadSize: 14, seasonYear: 2026);

    foreach (var c in new[] { "England", "Australia", "India" })
    {
        TestRunner.IsTrue(iw.Competitions.Any(x => x.Country == c && x.Scope == CricketManager.Domain.Enums.CompetitionScope.DomesticFirstClass), $"{c} has a First-Class Championship");
        TestRunner.IsTrue(iw.Competitions.Any(x => x.Country == c && x.Scope == CricketManager.Domain.Enums.CompetitionScope.DomesticListA), $"{c} has a One-Day Cup");
        TestRunner.IsTrue(iw.Competitions.Any(x => x.Country == c && x.Scope == CricketManager.Domain.Enums.CompetitionScope.DomesticT20), $"{c} has a T20 cup");
    }

    // Northern (England) vs southern (Australia) FC windows are 6 months apart.
    var engFc = iw.Competitions.First(x => x.Country == "England" && x.Scope == CricketManager.Domain.Enums.CompetitionScope.DomesticFirstClass);
    var ausFc = iw.Competitions.First(x => x.Country == "Australia" && x.Scope == CricketManager.Domain.Enums.CompetitionScope.DomesticFirstClass);
    TestRunner.IsTrue(engFc.Window.StartMonth != ausFc.Window.StartMonth, "the hemispheres schedule their domestic seasons in different halves of the year");

    var associateTeams = iw.Teams.Where(t => t.IsNational && WorldSeeder.AssociateNations.Contains(t.Country)).ToList();
    TestRunner.AreEqual(4, associateTeams.Count, "the four associate nations are real national teams");
    TestRunner.IsTrue(iw.Competitions.Any(x => x.Name == "ICC Associate Qualifier"), "there is an Associate Qualifier");
});

TestRunner.Run("Phase 10: a domestic competition on a sustained reputation high expands; WC-qualification points accrue from internationals", () =>
{
    var world = EmptyWorld();
    var top = new Competition { Name = "Big League", Scope = CompetitionScope.DomesticT20, Format = MatchFormat.T20, Reputation = 82, Prestige = 60, PromotionRelegationCount = 1 };
    var bottom = new Competition { Name = "Feeder League", Scope = CompetitionScope.DomesticT20, Format = MatchFormat.T20, Reputation = 40, Prestige = 32 };
    top.SecondTierCompetitionId = bottom.Id;
    world.Competitions.Add(top); world.Competitions.Add(bottom);
    for (int i = 0; i < 12; i++) world.Teams[Guid.NewGuid()] = new Team { Name = $"C{i}" };
    var ids = world.Teams.Keys.ToList();
    var ts = new CompetitionSeason { CompetitionId = top.Id, Year = 2026 };
    var bs = new CompetitionSeason { CompetitionId = bottom.Id, Year = 2026 };
    for (int i = 0; i < 6; i++) { ts.ParticipatingTeamIds.Add(ids[i]); ts.GetOrCreateStanding(ids[i]); }
    for (int i = 6; i < 12; i++) { bs.ParticipatingTeamIds.Add(ids[i]); bs.GetOrCreateStanding(ids[i]); }
    ts.Complete(ids[0]); bs.Complete(ids[6]);
    world.CompetitionSeasons.Add(ts); world.CompetitionSeasons.Add(bs);

    var lifecycle = new CompetitionLifecycleService();
    GameEvent? expandEvent = null;
    for (int y = 0; y < 5; y++)
        foreach (var e in lifecycle.ReviewAnnually(world, new DateOnly(2027 + y, 1, 1), 2026 + y))
            if (e.Headline.Contains("expands")) expandEvent = e;
    TestRunner.IsTrue(expandEvent is not null, "three straight strong years expand the league");
    TestRunner.IsTrue(top.PendingExpansion > 0, "and a pending expansion is queued for the P/R machinery");
});

