        MatchTestData.MakePlayer("Anchor5", 11), MatchTestData.MakePlayer("Anchor6", 10),
        MatchTestData.MakePlayer("Slogger", 12), MatchTestData.MakePlayer("Tail1", 6),
        MatchTestData.MakePlayer("Tail2", 5), MatchTestData.MakePlayer("Tail3", 4), MatchTestData.MakePlayer("Tail4", 3)
    };
    var slogger = order[6];
    slogger.Batting.PowerHitting = 20; slogger.Batting.DeathOverBatting = 20; slogger.Batting.BoundaryHitting = 20;
    slogger.BattingTraits.PowerHitter = 90; slogger.BattingTraits.Finisher = 85;

    void AddCards(InningsState st, int batted)
    {
        for (int i = 0; i < order.Count; i++)
            st.BatterCards.Add(new BatterCard { PlayerId = order[i].Id, PlayerName = order[i].FullName, BattingPosition = i + 1, HasBatted = i < batted });
    }

    // Death of a T20 innings, 4 down, next man is an anchor - the AI should look to promote the slogger.
    var deathState = new InningsState { BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl", Format = MatchFormat.T20, Runs = 130, Wickets = 4, LegalBalls = 102, MaxLegalBalls = 120 };
    AddCards(deathState, 4);

    int promotions = 0;
    for (int s = 0; s < 200; s++)
        if (ai.ChoosePinchHitter(deathState, order, 4, MatchFormat.T20, null, TacticalPlan.None, new Random(s)) == 6) promotions++;
    TestRunner.IsTrue(promotions > 40, $"In the death overs the slogger is often promoted ({promotions}/200)");

    // Calm first-innings start, 1 down, 15 overs left - no reason to shuffle.
    var calmState = new InningsState { BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl", Format = MatchFormat.T20, Runs = 35, Wickets = 1, LegalBalls = 30, MaxLegalBalls = 120 };
    AddCards(calmState, 2);

    int calmPromotions = 0;
    for (int s = 0; s < 200; s++)
        if (ai.ChoosePinchHitter(calmState, order, 2, MatchFormat.T20, null, TacticalPlan.None, new Random(s)) is not null) calmPromotions++;
    TestRunner.IsTrue(calmPromotions == 0, $"No promotion when the situation is calm ({calmPromotions}/200)");

    // Test cricket never triggers it (the nightwatchman is a separate mechanism).
    var testState = new InningsState { BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl", Format = MatchFormat.Test, Runs = 130, Wickets = 4, LegalBalls = 300 };
    AddCards(testState, 4);
    TestRunner.IsTrue(ai.ChoosePinchHitter(testState, order, 4, MatchFormat.Test, null, TacticalPlan.None, new Random(1)) is null,
        "Test cricket is left to the nightwatchman");
});

TestRunner.Run("6.4: a coach who keeps the final say on the batting order is never overridden", () =>
{
    var ai = new InMatchTacticalAI();
