// ==================== PHASE 6 - Slice 6.5 (human coach season loop / board relationship) ====================

(Coach Coach, CoachingContract Contract, Team Team, WorldState World) BoardScenario(double teamStrength, params MatchOutcome[] results)
{
    var team = new Team { Name = "Testers", Strength = teamStrength, Reputation = new Reputation(domestic: teamStrength) };
    var coach = new Coach { FirstName = "Head", LastName = "Coach" };
    coach.CurrentTeamId = team.Id;
    var contract = new CoachingContract
    {
        CoachId = coach.Id, TeamId = team.Id, StartDate = new DateOnly(2026, 1, 1), EndDate = new DateOnly(2029, 1, 1),
        Status = ContractStatus.Active, AnnualSalary = 200_000, CompensationIfTerminated = 150_000
    };
    coach.CurrentContractId = contract.Id;
    team.CurrentCoachId = coach.Id;

    var comp = new Competition { Name = "League", Window = CompetitionWindow.Annual(1, 1, 12, 31) };
    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
    season.ParticipatingTeamIds.Add(team.Id);
    var standing = season.GetOrCreateStanding(team.Id);
    foreach (var r in results) standing.RecordResult(r, CompetitionPointsSystem.LimitedOvers);

    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team> { [team.Id] = team },
        Grounds = new Dictionary<Guid, Ground>(),
        Players = new List<Player>(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.Coaches.Add(coach);
    world.CoachingContracts.Add(contract);
    world.CompetitionSeasons.Add(season);
    return (coach, contract, team, world);
}

TestRunner.Run("6.5: BoardConfidence tracks the current season - up for an overperforming club, down for an underperforming one", () =>
{
    var W = MatchOutcome.Win;
    var L = MatchOutcome.Loss;

    var (_, _, overTeam, overWorld) = BoardScenario(45, W, W, W, W, W, W, L, W);   // a modest side winning nearly everything
    var (_, _, underTeam, underWorld) = BoardScenario(80, L, L, L, L, L, W, L, L); // a strong side losing nearly everything

    overTeam.BoardConfidence = 50;
    underTeam.BoardConfidence = 50;

    var board = new BoardRelationshipService();
    for (int m = 0; m < 4; m++)
    {
        board.ReviewMonthly(overWorld, new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 1), new DateOnly(2026, 6 + m, 1), new Random(m));
        board.ReviewMonthly(underWorld, new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 1), new DateOnly(2026, 6 + m, 1), new Random(m));
    }

    TestRunner.IsTrue(overTeam.BoardConfidence > 60, $"An overperforming club's board grows confident ({overTeam.BoardConfidence:0})");
    TestRunner.IsTrue(underTeam.BoardConfidence < 35, $"An underperforming strong club's board loses confidence ({underTeam.BoardConfidence:0})");
});

TestRunner.Run("6.5: a club whose board confidence collapses sacks its coach mid-season, pays compensation, and vacates the chair", () =>
{
    var L = MatchOutcome.Loss;
    var board = new BoardRelationshipService();

    int sacked = 0;
    for (int trial = 0; trial < 60; trial++)
    {
        var (coach, contract, team, world) = BoardScenario(85, L, L, L, L, L, L, L, L, L, L);
        team.BoardConfidence = 12; // already on the brink
        double budgetBefore = team.Finances.Budget;

        for (int m = 0; m < 6 && contract.Status == ContractStatus.Active; m++)
            board.ReviewMonthly(world, new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 1), new DateOnly(2026, 6 + m, 1), new Random(trial * 10 + m));

        if (contract.Status == ContractStatus.Terminated)
        {
            sacked++;
            TestRunner.IsTrue(coach.CurrentTeamId is null && team.CurrentCoachId is null, "A sacked coach is detached on both sides");
            TestRunner.IsTrue(team.Finances.Budget < budgetBefore, "Compensation was paid out of the budget");
        }
    }
    TestRunner.IsTrue(sacked >= 20, $"A club losing every game with the board already on the brink usually sacks the coach ({sacked}/60)");
});

TestRunner.Run("6.5: a job offer reaches an unemployed human coach and he takes a vacant club that fits", () =>
