});

TestRunner.Run("6.5: a full multi-year seeded-world run is deterministic and produces real board/coaching history", () =>
{
    string Run(int seed)
    {
        var seeder = new WorldSeeder(seed: seed, worldStartDate: new DateOnly(2026, 6, 1));
        var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);
        var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
        var (fixtures, rivalries) = seeder.GenerateFixturesAndRivalries(comp, season, teams, grounds);
        var world = new WorldState
        {
            Teams = teams.ToDictionary(t => t.Id),
            Grounds = grounds.ToDictionary(g => g.Id),
            Players = players.ToList(),
            Projects = new List<InfrastructureProject>(),
            Competitions = { comp }
        };
        world.CompetitionSeasons.Add(season);
        foreach (var f in fixtures) world.Fixtures.Add(f);
        foreach (var r in rivalries) world.Rivalries.Add(r);

        var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: seed), world, new DateOnly(2031, 6, 1));

        var teamName = teams.ToDictionary(t => t.Id, t => t.Name);
        var champions = world.CompetitionSeasons.Where(s => s.IsCompleted)
            .OrderBy(s => s.Year)
            .Select(s => $"{s.Year}:{(s.ChampionTeamId is { } c && teamName.TryGetValue(c, out var n) ? n : "?")}");
        return string.Join(",", champions) + $"|coaches={world.Coaches.Count}|pots={events.Count(e => e.Type == GameEventType.PlayerOfTheSeriesAwarded)}";
    }

    var a = Run(4321);
    var b = Run(4321);
    TestRunner.AreEqual(a, b, "Five years of a full world - fixtures, seasons, board decisions - reproduce exactly from the seed");
    TestRunner.IsTrue(a.Contains("2026:") && a.Contains("2029:"), "Multiple seasons were completed with champions");
    TestRunner.IsTrue(a.Contains("pots=") && !a.Contains("pots=0"), "Players of the series were named across the run");
});


// ==================== PHASE 6 - Slice 6.6 (fixture disruption, dead rubbers) ====================

TestRunner.Run("6.6: Fixture.Reschedule moves an unplayed fixture and refuses a completed one", () =>
{
    var f = new Fixture { Stage = "Round 1", HomeTeamId = Guid.NewGuid(), AwayTeamId = Guid.NewGuid(), ScheduledDate = new DateOnly(2026, 5, 1) };
    f.Reschedule(new DateOnly(2026, 5, 8));
    TestRunner.AreEqual(new DateOnly(2026, 5, 8), f.ScheduledDate, "The date moved");
    TestRunner.AreEqual(FixtureStatus.Scheduled, f.Status, "It is still scheduled");
    TestRunner.AreEqual(1, f.RescheduleCount, "The attempt was counted");

    f.Complete(Guid.NewGuid(), f.HomeTeamId!.Value);
    bool threw = false;
    try { f.Reschedule(new DateOnly(2026, 6, 1)); } catch (InvalidOperationException) { threw = true; }
    TestRunner.IsTrue(threw, "A completed fixture cannot be rescheduled");
});

TestRunner.Run("6.6: the season runner re-fixtures a match that was missed on its scheduled day", () =>
{
    var seeder = new WorldSeeder(seed: 66, worldStartDate: new DateOnly(2026, 3, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 2, squadSize: 14);
    var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);

    // A fixture dated in the past relative to the clock start - it can never be "due" and would
    // otherwise sit Scheduled forever, blocking the season from ever completing.
    var stranded = new Fixture
    {
        CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Round 1", RoundNumber = 1, SequenceNumber = 0,
        HomeTeamId = teams[0].Id, AwayTeamId = teams[1].Id, ScheduledDate = new DateOnly(2026, 2, 1),
        GroundId = teams[0].HomeGroundId
    };
    world.Fixtures.Add(stranded);

    var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 3, 1), worldSeed: 66), world, new DateOnly(2026, 4, 1));

    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.FixturePostponed), "The missed fixture was re-fixtured");
    TestRunner.IsTrue(stranded.Status == FixtureStatus.Completed || stranded.ScheduledDate > new DateOnly(2026, 3, 1),
        "It was either played after being moved forward, or is now scheduled for a future date");
});

TestRunner.Run("6.6: a dead rubber is played with lower stakes and a rotated side", () =>
{
    var svc = new FixturePlayService();

    var seeder = new WorldSeeder(seed: 67, worldStartDate: new DateOnly(2026, 3, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 5, squadSize: 18);
    var (grounds, _, _) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);

    var comp = new Competition
    {
        Name = "Playoff League", StructureType = CompetitionStructureType.LeagueWithPlayoffs,
        Scope = CompetitionScope.DomesticT20, Format = MatchFormat.T20, PlayoffQualifierCount = 2,
        Window = CompetitionWindow.Annual(4, 1, 8, 31), Prestige = 50
    };
    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
    foreach (var t in teams) { season.ParticipatingTeamIds.Add(t.Id); season.GetOrCreateStanding(t.Id); }

    // Build a table where the top 2 are runaway clear and the bottom 3 are mathematically out,
    // with almost every game already played (so "clinched"/"eliminated" is real).
    var ranked = season.Standings.ToList();
    for (int i = 0; i < 7; i++) { ranked[0].RecordResult(MatchOutcome.Win); ranked[1].RecordResult(MatchOutcome.Win); }
    for (int i = 0; i < 7; i++) { ranked[2].RecordResult(MatchOutcome.Loss); ranked[3].RecordResult(MatchOutcome.Loss); ranked[4].RecordResult(MatchOutcome.Loss); }

    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);

    // Give team 3's first-teamers a real season's workload so rotation has something to bite on
    // (WorkloadRotationService rests on genuine load/condition, not the dead-rubber flag alone).
    foreach (var id in new PlayerSelectionEvaluator()
                 .RankAvailable(players.Where(p => teams[3].SquadPlayerIds.Contains(p.Id)), MatchFormat.T20, new DateOnly(2026, 8, 20))
                 .Take(7).Select(s => s.PlayerId))
        world.MatchesThisSeason[id] = 14;

    // One remaining fixture between two eliminated sides - a dead rubber for both.
    var deadRubber = new Fixture
    {
        CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Round 8", RoundNumber = 8, SequenceNumber = 100,
        HomeTeamId = teams[3].Id, AwayTeamId = teams[4].Id, ScheduledDate = new DateOnly(2026, 8, 20),
        GroundId = teams[3].HomeGroundId
    };
    world.Fixtures.Add(deadRubber);

    // Its two clubs rotate in dead rubbers by default (ManagerPreferences.RotateInDeadRubbers) -
    // WorkloadRotationService rests players in a dead rubber, and a genuine top-7 name is among
    // those rested. Assert the MECHANISM directly (deterministic) rather than inferring it from
    // which lower-order batter happened to face a ball, which shifts with any XI-selection change.
    var team3Roster = players.Where(p => teams[3].SquadPlayerIds.Contains(p.Id)).ToList();
    var rested = new WorkloadRotationService().PlayersToRest(world, teams[3], MatchFormat.T20, new DateOnly(2026, 8, 20),
        isDeadRubber: true, matchImportance: 50 * 0.55);
    var team3Top7 = new PlayerSelectionEvaluator()
        .RankAvailable(team3Roster, MatchFormat.T20, new DateOnly(2026, 8, 20))
        .Take(7).Select(s => s.PlayerId).ToHashSet();
    TestRunner.IsTrue(rested.Count > 0, "The dead rubber triggers rotation");
    TestRunner.IsTrue(rested.Any(id => team3Top7.Contains(id)), "At least one genuine first-teamer is rested for the dead rubber");

    var report = svc.PlayDueFixtures(world, new GameCalendar(new DateOnly(2026, 3, 1), worldSeed: 67), new DateOnly(2026, 8, 20));
    TestRunner.AreEqual(1, report.FixturesPlayed, "The dead rubber was still played");
    TestRunner.AreEqual(FixtureStatus.Completed, deadRubber.Status, "...and completed");
});

