TestRunner.Run("6.7: NationalSelectionService builds a country's pool from its own players, capped, no retirees", () =>
{
    var seeder = new WorldSeeder(seed: 71, worldStartDate: new DateOnly(2026, 6, 1));
    var (paks, pakPlayers) = seeder.GenerateStarterWorld("Pakistan", teamCount: 5, squadSize: 16);
    var (auss, ausPlayers) = seeder.GenerateStarterWorld("Australia", teamCount: 5, squadSize: 16);
    var all = pakPlayers.Concat(ausPlayers).ToList();

    // Retire a couple of good Pakistan players.
    foreach (var p in pakPlayers.OrderByDescending(p => p.CurrentAbility).Take(2)) p.IsRetired = true;

    var national = new Team { Name = "Pakistan", Country = "Pakistan", IsNational = true };
    new NationalSelectionService().RefreshPool(national, all, new DateOnly(2026, 6, 1));

    TestRunner.IsTrue(national.SquadPlayerIds.Count <= NationalSelectionService.PoolSize && national.SquadPlayerIds.Count >= 11,
        $"The pool is a sensible size ({national.SquadPlayerIds.Count})");
    TestRunner.IsTrue(national.SquadPlayerIds.All(id => pakPlayers.Any(p => p.Id == id)), "Every pool player is Pakistani");
    TestRunner.IsTrue(national.SquadPlayerIds.All(id => !all.First(p => p.Id == id).IsRetired), "No retired players in the pool");
    TestRunner.IsTrue(national.GetCaptain(MatchFormat.T20) is { } cap && national.SquadPlayerIds.Contains(cap), "A captain from within the pool was set");
});

TestRunner.Run("6.7: an international window puts national-squad players on international duty and frees them when it closes", () =>
{
    var seeder = new WorldSeeder(seed: 72, worldStartDate: new DateOnly(2026, 3, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England" }, teamsPerCountry: 3, squadSize: 14, seasonYear: 2026);

    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
    foreach (var r in iw.Rivalries) world.Rivalries.Add(r);

    var clock = new WorldClockService();
    var cal = new GameCalendar(new DateOnly(2026, 3, 1), worldSeed: 72);

    // Into the middle of the June-July international window.
    clock.AdvanceTo(cal, world, new DateOnly(2026, 6, 20));
    int onDuty = world.Players.Count(p => p.NonInjuryUnavailability == UnavailabilityReason.InternationalDuty);
    TestRunner.IsTrue(onDuty >= 20, $"National-squad players across the three teams are on international duty ({onDuty})");

    var pavail = new PlayerAvailabilityService();
    var onDutyPlayer = world.Players.First(p => p.NonInjuryUnavailability == UnavailabilityReason.InternationalDuty);
    TestRunner.IsTrue(!pavail.GetAvailability(onDutyPlayer, new DateOnly(2026, 6, 20), MatchFormat.T20).IsAvailable,
        "A player on international duty is unavailable for his club");

    // Past the World T20 window close, into the early-August gap between international windows
    // (Phase 10 added year-round international cricket, so the old "September = quiet" assumption
    // no longer holds - the ODI Championship window opens on 1 September).
    clock.AdvanceTo(cal, world, new DateOnly(2026, 8, 5));
    TestRunner.AreEqual(0, world.Players.Count(p => p.NonInjuryUnavailability == UnavailabilityReason.InternationalDuty),
        "Between international windows everyone is released back to their clubs");
});

