TestRunner.Run("Pass1 bug1: EnsureIncluded inserts a forced player at a role-appropriate slot and never strands the attack", () =>
{
    // A settled XI: 2 openers, 3 middle, a keeper, 5 bowlers.
    var order = new List<Player>();
    var op1 = MatchTestData.MakePlayer("Op1", 13); op1.BattingRole = BattingRole.Opener;
    var op2 = MatchTestData.MakePlayer("Op2", 13); op2.BattingRole = BattingRole.Opener;
    var m1 = MatchTestData.MakePlayer("Mid1", 12); m1.BattingRole = BattingRole.MiddleOrder;
    var m2 = MatchTestData.MakePlayer("Mid2", 11); m2.BattingRole = BattingRole.MiddleOrder;
    var m3 = MatchTestData.MakePlayer("Mid3", 8);  m3.BattingRole = BattingRole.MiddleOrder; // weakest bat - the sacrifice
    var kp = MatchTestData.MakePlayer("Keep", 11, PlayerRole.WicketKeeper); kp.BattingRole = BattingRole.MiddleOrder;
    order.AddRange(new[] { op1, op2, m1, m2, m3, kp });
    for (int i = 1; i <= 5; i++)
    {
        var b = MatchTestData.MakePlayer($"Bowl{i}", 10, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        b.BattingRole = BattingRole.Tailender;
        order.Add(b);
    }
    var bowlers = order.Where(p => p.BowlingRole != BowlingRoleType.NotABowler).ToList();
    var xi = new XiSelectionResult(order, bowlers, kp, true, Array.Empty<string>());

    // Force in a genuine middle-order batsman who was left out.
    var forcedCaptain = MatchTestData.MakePlayer("Skipper", 13); forcedCaptain.BattingRole = BattingRole.MiddleOrder;
    var squad = order.Concat(new[] { forcedCaptain }).ToList();

    var result = FixturePlayService.EnsureIncluded(xi, squad, Array.Empty<Guid>(), forcedCaptain.Id, MatchFormat.T20);

    int skipperPos = result.BattingOrder.ToList().FindIndex(p => p.Id == forcedCaptain.Id);
    TestRunner.IsTrue(skipperPos >= 0, "The captain is in the XI");
    TestRunner.IsTrue(skipperPos >= 2 && skipperPos <= 6, $"...at a middle-order slot, not tail-end ({skipperPos})");
    TestRunner.AreEqual(11, result.BattingOrder.Count, "Still eleven");
    int bowlersAfter = result.BattingOrder.Count(p => p.BowlingRole != BowlingRoleType.NotABowler);
    TestRunner.IsTrue(bowlersAfter >= XiSelectionService.BowlingFloor(MatchFormat.T20),
        $"The attack still has legal depth ({bowlersAfter}) - a batter was dropped, not a bowler");
    TestRunner.IsTrue(!result.BattingOrder.Any(p => p.Id == m3.Id), "The weakest pure batsman made way");
});

TestRunner.Run("Pass1 bug2: a knockout fixture awaiting a slow feeder is never abandoned", () =>
{
    var seeder = new WorldSeeder(seed: 991, worldStartDate: new DateOnly(2026, 3, 1));
    var (teams, players) = seeder.GenerateStarterWorld(teamCount: 4, squadSize: 14);
    var (grounds, comp, season) = seeder.GenerateGroundsAndCompetition(teams, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = teams.ToDictionary(t => t.Id),
        Grounds = grounds.ToDictionary(g => g.Id),
        Players = players.ToList(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);

    // A deliberately awkward hand-built bracket: the final is dated BEFORE its own semis, so it
    // sits "past due" with unresolved feeders for a long time.
    var semi1 = new Fixture { CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Semi-Final", SequenceNumber = 1000,
        HomeTeamId = teams[0].Id, AwayTeamId = teams[1].Id, ScheduledDate = new DateOnly(2026, 5, 1), GroundId = teams[0].HomeGroundId };
    var semi2 = new Fixture { CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Semi-Final", SequenceNumber = 1001,
        HomeTeamId = teams[2].Id, AwayTeamId = teams[3].Id, ScheduledDate = new DateOnly(2026, 5, 1), GroundId = teams[2].HomeGroundId };
    var final = new Fixture { CompetitionId = comp.Id, SeasonId = season.Id, Stage = "Final", SequenceNumber = 1002,
        ScheduledDate = new DateOnly(2026, 3, 20),
        HomeFeederFixtureId = semi1.Id, AwayFeederFixtureId = semi2.Id,
        HomeTeamPlaceholder = "Winner SF1", AwayTeamPlaceholder = "Winner SF2" };
    world.Fixtures.Add(semi1); world.Fixtures.Add(semi2); world.Fixtures.Add(final);

    var runner = new CompetitionSeasonRunner();
    var cal = new GameCalendar(new DateOnly(2026, 3, 1), worldSeed: 991);
    // Tick the runner's own reschedule pass over ~40 days while the final's feeders are unplayed.
    for (int d = 1; d <= 40; d++)
    {
        foreach (var _ in runner.Advance(world, cal, new DateOnly(2026, 3, 1).AddDays(d))) { }
        TestRunner.IsTrue(final.Status != FixtureStatus.Cancelled, $"Day {d}: the final has NOT been abandoned");
    }
    TestRunner.AreEqual(0, final.RescheduleCount, "Waiting on a feeder never counts against the abandon threshold");
    TestRunner.IsTrue(final.ScheduledDate > new DateOnly(2026, 4, 1), "The final's date was pushed forward while it waited");
});

TestRunner.Run("Pass1 bug3: GameCalendar.NewRandomCareer is the named unpredictable-seed path; an explicit seed still reproduces", () =>
{
    var a = GameCalendar.NewRandomCareer(new DateOnly(2026, 6, 1));
    var b = GameCalendar.NewRandomCareer(new DateOnly(2026, 6, 1));
    TestRunner.IsTrue(a.WorldSeed != b.WorldSeed, "Two new random careers get different master seeds");

    var pinned1 = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 4242);
    var pinned2 = new GameCalendar(new DateOnly(2026, 6, 1), worldSeed: 4242);
    TestRunner.AreEqual(pinned1.WorldSeed, pinned2.WorldSeed, "An explicit seed is reproducible");
    TestRunner.AreEqual(pinned1.RandomForYear(2030).Next(), pinned2.RandomForYear(2030).Next(), "...right down to the RNG stream");
});


// ==================== POST-PHASE-6 RECTIFICATIONS - Pass 2 (carry-forwards + sections A-G) ====================

// ---- carry-forward (a): an individual honour -> bounded morale + reputation (which feeds dressing-room standing) ----
TestRunner.Run("Pass2 (a): player-of-the-match lifts morale and nudges reputation, weight-scaled and bounded", () =>
{
    var svc = new PlayerMoraleService();
    var room = new DressingRoomService();
    var asOf = new DateOnly(2026, 6, 1);

    var p = MatchTestData.MakePlayer("Honoured", 12);
    p.DateOfBirth = new DateOnly(1994, 1, 1);
    double morale0 = p.Morale.Level, rep0 = p.Reputation.Domestic, standing0 = room.Standing(p, asOf);

    svc.AdjustForIndividualHonour(p, weight: 1.0);
    TestRunner.IsTrue(p.Morale.Level > morale0, "morale rose after a match award");
    TestRunner.IsTrue(p.Reputation.Domestic > rep0, "reputation nudged up");
    TestRunner.IsTrue(room.Standing(p, asOf) >= standing0, "...which can only help his standing in the room, never hurt it");

    var q = MatchTestData.MakePlayer("SeriesHero", 12);
    double qRep0 = q.Reputation.Domestic;
    svc.AdjustForIndividualHonour(q, weight: 3.0);
    TestRunner.IsTrue(q.Reputation.Domestic - qRep0 > p.Reputation.Domestic - rep0, "a series award weighs more than a single match");

    for (int i = 0; i < 300; i++) svc.AdjustForIndividualHonour(p, weight: 3.0);
    TestRunner.IsTrue(p.Morale.Level <= 100 && p.Reputation.Domestic <= 100, "still bounded after a career of awards");
});

// ---- carry-forward (b): quarterly development snapshots + a period-over-period progress report ----
TestRunner.Run("Pass2 (b): a development snapshot captures attribute clusters, and the report shows the biggest mover", () =>
{
    var reportSvc = new PlayerDevelopmentReportService();
    var p = MatchTestData.MakePlayer("Prospect", 9);
    p.PotentialAbility = 180;

    var snap1 = PlayerDevelopmentSnapshot.Of(p, new DateOnly(2026, 1, 1));
    TestRunner.IsTrue(reportSvc.Progress(new List<PlayerDevelopmentSnapshot> { snap1 }) is null, "one snapshot is not enough for a progress read");

    // A year of genuine batting improvement.
    p.Batting.Technique = Math.Min(20, p.Batting.Technique + 6);
    p.Batting.Timing = Math.Min(20, p.Batting.Timing + 6);
    p.Batting.ShotSelection = Math.Min(20, p.Batting.ShotSelection + 6);
    p.CurrentAbility += 12;
    p.RecalculateFormatSuitability();
    var snap2 = PlayerDevelopmentSnapshot.Of(p, new DateOnly(2027, 1, 1));

    var progress = reportSvc.Progress(new List<PlayerDevelopmentSnapshot> { snap1, snap2 });
    TestRunner.IsTrue(progress is not null, "two snapshots give a progress read");
    TestRunner.IsTrue(progress!.BattingDelta > 3, $"the batting cluster moved up ({progress.BattingDelta:F1})");
    TestRunner.IsTrue(progress.CurrentAbilityDelta == 12, "current ability delta is exact");
    TestRunner.AreEqual("batting", progress.BiggestMover().Cluster, "batting is correctly the headline mover");
});

// ---- carry-forward (c): matchup recency-weighting gets personality moderation on top of the pressure factor ----
TestRunner.Run("Pass2 (c): a fragile temperament lives closer to his recent matchup record than a settled one", () =>
{
    var svc = new MatchupConfidenceService();
    var opponent = Guid.NewGuid();
    var key = MatchupKey.ForBowler(opponent);

    var fragile = MatchTestData.MakePlayer("Fragile", 10);
    fragile.Personality = PersonalityTrait.Inconsistent;
    var settled = MatchTestData.MakePlayer("Settled", 10);
    settled.Personality = PersonalityTrait.Consistent;

    // Identical history: a long poor run, then a recent turnaround.
    foreach (var pl in new[] { fragile, settled })
    {
        for (int i = 0; i < 6; i++) svc.RecordOutcome(pl, key, -30);
        for (int i = 0; i < 3; i++) svc.RecordOutcome(pl, key, 60);
    }

    double fragileMult = svc.GetMatchupMultiplier(fragile, key);
    double settledMult = svc.GetMatchupMultiplier(settled, key);
    TestRunner.IsTrue(fragileMult > settledMult + 0.01,
        $"the inconsistent player rides the recent good form more ({fragileMult:F3} vs {settledMult:F3})");
});

// ---- carry-forward (d) + section C: RandomForWeek has a real consumer - weekly individual coaching ----
TestRunner.Run("Pass2 (d/C): a specialist coach assigned to a young player develops him week by week", () =>
{
    var svc = new SpecialistStaffService();
    var team = new Team { Name = "Academy FC" };
