    var battingCoach = new StaffMember
    {
        FirstName = "Bat", LastName = "Guru", Role = StaffRole.BattingCoach,
        TechnicalKnowledge = 18, Communication = 17, Analysis = 14, Diligence = 16, YearsExperience = 10
    };
    team.StaffIds.Add(battingCoach.Id);

    svc.AssignIndividualWork(team, new[] { young }, new[] { battingCoach });
    TestRunner.AreEqual(battingCoach.Id, young.AssignedSpecialistCoachId, "the young player with real headroom is assigned the batting coach");

    var world = new WorldState { Teams = new Dictionary<Guid, Team> { [team.Id] = team }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player> { young }, Projects = new List<InfrastructureProject>() };
