// ---- carry-forward (e): trust in the captain, distinct from trust in the coach ----
TestRunner.Run("Pass2 (e): captain trust moves on how his calls went and the result, and is bounded", () =>
{
    var side = Enumerable.Range(0, 11).Select(i => MatchTestData.MakePlayer($"P{i}", 12)).ToList();
