    double afterGood = CaptaincyService.SquadCaptainTrust(side);

    CaptaincyService.ApplyCaptainTrust(side, matchDecisionRating: -60, won: false);
    TestRunner.IsTrue(CaptaincyService.SquadCaptainTrust(side) < afterGood, "a badly-led defeat erodes it");

    for (int i = 0; i < 100; i++) CaptaincyService.ApplyCaptainTrust(side, -70, false);
    TestRunner.IsTrue(side.All(p => p.CaptainTrust >= 0), "bounded at zero");
    for (int i = 0; i < 200; i++) CaptaincyService.ApplyCaptainTrust(side, 70, true);
    TestRunner.IsTrue(side.All(p => p.CaptainTrust <= 100), "bounded at 100");
});

