// ---- carry-forward (h) + section F: rotation is driven by workload, never the dead-rubber flag alone ----
TestRunner.Run("Pass2 (h/F): a dead rubber alone doesn't rest a fresh young side; a tired old one gets managed", () =>
{
    var svc = new WorkloadRotationService();

    var freshPlayers = new List<Player>();
    var fresh = new Team { Name = "Fresh XI" };
    for (int i = 0; i < 18; i++)
    {
        var p = MatchTestData.MakePlayer($"Fresh{i}", 12);
        p.DateOfBirth = new DateOnly(2002, 1, 1);
        p.CurrentTeamId = fresh.Id; fresh.SquadPlayerIds.Add(p.Id); freshPlayers.Add(p);
    }

    var tiredPlayers = new List<Player>();
    var tired = new Team { Name = "Tired XI" };
    for (int i = 0; i < 18; i++)
    {
        var p = MatchTestData.MakePlayer($"Tired{i}", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        p.DateOfBirth = new DateOnly(1990, 1, 1);
        p.Bowling.Pace = 16; p.Physical.Fitness = 8; p.Physical.InjuryProneness = 16;
        p.CurrentTeamId = tired.Id; tired.SquadPlayerIds.Add(p.Id); tiredPlayers.Add(p);
    }

    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team> { [fresh.Id] = fresh, [tired.Id] = tired },
        Grounds = new Dictionary<Guid, Ground>(),
        Players = freshPlayers.Concat(tiredPlayers).ToList(),
        Projects = new List<InfrastructureProject>()
    };
    // Tired side has played a heavy recent block.
    foreach (var p in tiredPlayers) world.MatchesThisSeason[p.Id] = 18;

    var d = new DateOnly(2026, 8, 1);
    var freshRest = svc.PlayersToRest(world, fresh, MatchFormat.T20, d, isDeadRubber: true, matchImportance: 30);
    var tiredRest = svc.PlayersToRest(world, tired, MatchFormat.T20, d, isDeadRubber: true, matchImportance: 30);

    TestRunner.IsTrue(freshRest.Count <= 1, $"a fresh young side is barely rotated even in a dead rubber ({freshRest.Count})");
    TestRunner.IsTrue(tiredRest.Count > freshRest.Count, $"a tired, ageing, brittle side is managed more ({tiredRest.Count})");

    // A genuine big match overrides the dead-rubber appetite.
    var bigMatchRest = svc.PlayersToRest(world, tired, MatchFormat.T20, d, isDeadRubber: false, matchImportance: 95);
    TestRunner.IsTrue(bigMatchRest.Count <= tiredRest.Count, "when it matters, you play your best");
});

