    foreach (var p in squad) p.CurrentTeamId = national.Id;
    var natChoices = svc.AppointAll(national, squad, new DateOnly(2026, 6, 1), null, new Dictionary<Guid, CaptaincyProfile>(), new Random(9));

    TestRunner.IsTrue(domChoices.Count == 3, "a domestic side finds a captain from modest leaders");
    TestRunner.IsTrue(natChoices.Count == 0, "no one clears the stricter national bar, so no appointment is forced");
});

// ---- section E: national pool built for coverage, squads drawn from it ----
TestRunner.Run("Pass2 (E): a national pool is coverage-built, correctly nationalitied, and squads are drawn from it", () =>
{
    var seeder = new WorldSeeder(seed: 501, worldStartDate: new DateOnly(2026, 6, 1));
    var (teams, players) = seeder.GenerateStarterWorld("Pakistan", teamCount: 9, squadSize: 16);
    var national = new Team { Name = "Pakistan", Country = "Pakistan", IsNational = true };

    var poolSvc = new NationalPoolService();
    var pool = poolSvc.BuildPool(national, players, MatchFormat.T20, new DateOnly(2026, 6, 1), coach: null);

    TestRunner.IsTrue(pool.Entries.Count >= 28 && pool.Entries.Count <= NationalPoolService.TargetSize + 2,
        $"the pool is a real, deep squad ({pool.Entries.Count})");
    TestRunner.IsTrue(pool.Entries.All(e => players.First(p => p.Id == e.PlayerId).Nationality == "Pakistan"), "every pool member is Pakistani");
    TestRunner.IsTrue(pool.Entries.All(e => !players.First(p => p.Id == e.PlayerId).IsRetired), "no retirees");

    Player P(Guid id) => players.First(p => p.Id == id);
    TestRunner.IsTrue(pool.Entries.Any(e => P(e.PlayerId).PrimaryRole == PlayerRole.WicketKeeper), "the keeper battle is covered");
    TestRunner.IsTrue(pool.Entries.Count(e => P(e.PlayerId).BowlingStyle is BowlingStyle.RightArmOffSpin or BowlingStyle.RightArmLegSpin or BowlingStyle.LeftArmOrthodox or BowlingStyle.LeftArmChinaman) >= 2, "spin variety is covered");
    TestRunner.IsTrue(pool.Entries.Count(e => { var pl = P(e.PlayerId); return pl.BowlingRole != BowlingRoleType.NotABowler && pl.Bowling.Pace >= 12; }) >= 3, "pace depth is covered");

    var squad = poolSvc.DrawSquad(pool, players, MatchFormat.T20, new DateOnly(2026, 6, 1), size: 15);
    TestRunner.AreEqual(15, squad.Count, "a 15-man squad is drawn");
    TestRunner.IsTrue(squad.All(id => pool.Contains(id)), "every squad member comes FROM the pool");
    TestRunner.IsTrue(P(squad[0]).PrimaryRole == PlayerRole.WicketKeeper, "a keeper is secured first");

    // An outside pick must go through the pool first, as a watchlist entry.
    var outsider = players.First(p => !pool.Contains(p.Id));
    TestRunner.IsTrue(poolSvc.AddException(pool, outsider, new DateOnly(2026, 6, 1), "franchise form"), "an exceptional outsider can be added");
    TestRunner.IsTrue(pool.EntryFor(outsider.Id)!.Watchlist, "...but only to the watchlist, not straight into a squad");

    // ReviewPool drops a retired member.
    var victim = P(pool.Entries.First(e => !P(e.PlayerId).Equals(outsider)).PlayerId);
    victim.IsRetired = true;
    poolSvc.ReviewPool(pool, national, players, new DateOnly(2026, 12, 1), coach: null);
    TestRunner.IsTrue(!pool.Contains(victim.Id), "a retired player is reviewed out of the pool");
});

// ---- sections A/B/D/E integration: a multi-year seeded world stays coherent and deterministic ----
TestRunner.Run("Pass2 integration: a multi-year world advertises and fills jobs, snapshots development, and stays deterministic", () =>
{
    (int fixturesDone, int devHistories, int coachingEvents, string champs) RunWorld(int seed)
    {
        var seeder = new WorldSeeder(seed: seed, worldStartDate: new DateOnly(2026, 1, 1));
        var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
        var world = new WorldState
        {
            Teams = iw.Teams.ToDictionary(t => t.Id),
            Grounds = iw.Grounds.ToDictionary(g => g.Id),
            Players = iw.Players.ToList(),
            Projects = new List<InfrastructureProject>(),
        };
        foreach (var c in iw.Competitions) world.Competitions.Add(c);
        foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
        foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
        foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
        foreach (var p in iw.NationalPools) world.NationalPools.Add(p);

        // Vacate a couple of head-coach chairs so the job market has something to do.
        foreach (var t in world.Teams.Values.Where(t => !t.IsNational).Take(2)) t.CurrentCoachId = null;

        var clock = new WorldClockService();
        var cal = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: seed);
        var events = clock.AdvanceTo(cal, world, new DateOnly(2028, 6, 1));

        int fixturesDone = world.Fixtures.Count(f => f.Status == FixtureStatus.Completed);
        int devHistories = world.DevelopmentHistory.Count(kv => kv.Value.Count >= 2);
        int coachingEvents = events.Count(e => e.Type is GameEventType.CoachAppointed or GameEventType.StaffAppointed
            or GameEventType.CoachDismissed or GameEventType.CoachResigned or GameEventType.CoachJobOffer
            or GameEventType.StaffPromotedToHeadCoach or GameEventType.CoachAppointedInterim);
        string champs = string.Join(",", world.CompetitionSeasons.Where(s => s.IsCompleted && s.ChampionTeamId is { } cid)
            .OrderBy(s => s.Year).ThenBy(s => world.Teams[s.ChampionTeamId!.Value].Name)
            .Select(s => $"{s.Year}:{world.Teams[s.ChampionTeamId!.Value].Name}"));
        return (fixturesDone, devHistories, coachingEvents, champs);
    }

    var a = RunWorld(4242);
    TestRunner.IsTrue(a.fixturesDone > 30, $"a real amount of cricket was played ({a.fixturesDone} fixtures)");
    TestRunner.IsTrue(a.devHistories > 20, $"quarterly development snapshots accumulated for many players ({a.devHistories})");
    TestRunner.IsTrue(a.coachingEvents > 0, "the coaching/job market moved over the run (appointments, offers, departures)");

    var b = RunWorld(4242);
    TestRunner.AreEqual(a.fixturesDone, b.fixturesDone, "same seed -> same fixtures played");
    TestRunner.AreEqual(a.champs, b.champs, "same seed -> same champions");
    TestRunner.AreEqual(a.devHistories, b.devHistories, "same seed -> same development history");
    TestRunner.AreEqual(a.coachingEvents, b.coachingEvents, "same seed -> same coaching-market activity");
});


