TestRunner.Run("7.2: a competition's reputation rises on full grounds and a tight table, falls on empty grounds and a procession (tech-debt item 7)", () =>
{
    var svc = new CompetitionReputationService();
    var teams = Enumerable.Range(0, 6).Select(i => { var t = new Team { Name = $"C{i}" }; t.Reputation.Adjust(55); return t; }).ToList();
    var byId = teams.ToDictionary(t => t.Id);

    Competition Run(double startRep, IReadOnlyList<double> fills, int[] points)
    {
        var comp = new Competition { Name = "League", Prestige = 55, Reputation = startRep };
        var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
        for (int i = 0; i < teams.Count; i++)
        {
            season.ParticipatingTeamIds.Add(teams[i].Id);
            var st = season.GetOrCreateStanding(teams[i].Id);
            for (int w = 0; w < points[i]; w++) st.RecordResult(MatchOutcome.Win);
        }
        svc.ReviewSeason(comp, season, fills, byId);
        return comp;
    }

    var thriving = Run(50, Enumerable.Repeat(0.85, 15).ToList(), new[] { 10, 9, 9, 8, 8, 7 });   // full houses, tight table
    var dying = Run(50, Enumerable.Repeat(0.08, 15).ToList(), new[] { 16, 12, 6, 4, 2, 0 });      // empty grounds, runaway

    TestRunner.IsTrue(thriving.Reputation > 50, $"a thriving competition gains standing ({thriving.Reputation:F1})");
    TestRunner.IsTrue(dying.Reputation < 50, $"a dying one loses it ({dying.Reputation:F1})");
    TestRunner.IsTrue(thriving.Reputation - 50 <= 4.01 && 50 - dying.Reputation <= 4.01, "the move is bounded to a few points a season");
});


