TestRunner.Run("7.3: the board sets a season budget from wealth and last year's books, and a takeover reshapes it", () =>
{
    var svc = new BoardService();
    var rich = new Team { Name = "Rich" }; rich.Board.Wealth = 90; rich.Finances.Budget = 2_000_000;
    var poor = new Team { Name = "Poor" }; poor.Board.Wealth = 20; poor.Finances.Budget = 100_000;
    svc.SetSeasonBudget(rich, 2_000_000, 400_000);
    svc.SetSeasonBudget(poor, 100_000, -300_000);
    TestRunner.IsTrue(rich.Board.SeasonBudget > poor.Board.SeasonBudget * 3, "the wealthy, profitable club gets a far bigger budget");

    // Fan sentiment: overachieving + a title lifts it; a loss-making underachiever sours it.
    var team = new Team { Name = "T" };
    double before = team.Board.FanSentiment;
    svc.ReviewFanSentiment(team, performanceScore: 0.8, wonTitle: true, netResult: 200_000);
    TestRunner.IsTrue(team.Board.FanSentiment > before, "a title-winning overachievement lifts the fans");
    svc.ReviewFanSentiment(team, performanceScore: -0.9, wonTitle: false, netResult: -600_000);
    TestRunner.IsTrue(team.Board.FanSentiment < before + 8, "a loss-making collapse sours them again");

    // Takeover: never for a member-owned club; realistic for a big-market struggling private club.
    var protected1 = new Team { Name = "Trust FC" };
    protected1.Board.Ownership = OwnershipModel.MemberOwned;
    protected1.Reputation.Adjust(80); protected1.BoardConfidence = 10; protected1.Board.FanSentiment = 15;
    bool anyMemberTakeover = false;
    for (int i = 0; i < 200; i++) if (svc.ConsiderTakeover(protected1, new DateOnly(2027, 1, 1), new Random(i)) is not null) anyMemberTakeover = true;
    TestRunner.IsTrue(!anyMemberTakeover, "a supporters' trust is never taken over");

    int takeovers = 0;
    for (int i = 0; i < 300; i++)
    {
        var target = new Team { Name = "Target" };
        target.Board.Ownership = OwnershipModel.PrivateOwner;
        target.Reputation.Adjust(85); target.BoardConfidence = 12; target.Board.FanSentiment = 20;
        double wealthBefore = target.Board.Wealth, ambitionBefore = target.Board.Ambition;
        var ev = svc.ConsiderTakeover(target, new DateOnly(2027, 1, 1), new Random(i));
        if (ev is not null)
        {
            takeovers++;
            TestRunner.IsTrue(target.Board.Wealth > wealthBefore && target.Board.Ambition > ambitionBefore, "the new owner is wealthier and more ambitious");
            TestRunner.AreEqual(GameEventType.ClubTakeover, ev.Type, "a ClubTakeover event fired");
        }
    }
    TestRunner.IsTrue(takeovers is > 5 and < 200, $"a struggling big-market club changes hands sometimes, not always ({takeovers}/300)");
});

