// ---- 7.4: media & press ----
TestRunner.Run("7.4: a losing run raises a press storyline, and how the conference lands depends on MediaHandling", () =>
{
    Coach MakeCoach(int media, bool human = false)
    {
        var c = new Coach { FirstName = "C", LastName = media.ToString(), IsHumanControlled = human };
        c.SeedAttributesFromHistory();
        c.Attributes.MediaHandling = media;
        c.Attributes.PressureHandling = 12;
        return c;
    }

    (double confidenceDelta, int conferences) Trial(int media, int seed)
    {
        var team = new Team { Name = "Strugglers" };
        team.CurrentStreak = -6;
        team.BoardConfidence = 55;
        var coach = MakeCoach(media);
        coach.CurrentTeamId = team.Id;
        team.CurrentCoachId = coach.Id;
        var world = new WorldState
        {
            Teams = new Dictionary<Guid, Team> { [team.Id] = team },
            Grounds = new Dictionary<Guid, Ground>(),
            Players = new List<Player>(),
            Projects = new List<InfrastructureProject>(),
            Coaches = { coach }
        };
        var svc = new PressConferenceService();
        svc.RaiseStorylines(world, new DateOnly(2027, 5, 1), Array.Empty<GameEvent>());
        double before = team.BoardConfidence;
        var evs = svc.HoldPendingConferences(world, new DateOnly(2027, 5, 1), new Random(seed)).ToList();
        return (team.BoardConfidence - before, evs.Count);
    }

    // Averaged over trials since the tone is rolled.
    double sharpSum = 0, poorSum = 0;
    int held = 0;
    for (int i = 0; i < 120; i++) { var s = Trial(19, i); var p = Trial(4, i); sharpSum += s.confidenceDelta; poorSum += p.confidenceDelta; held += s.conferences; }
    TestRunner.IsTrue(held > 100, "the storyline was raised and the conference held nearly every trial");
    TestRunner.IsTrue(sharpSum > poorSum, $"a strong media operator comes out of it better than a poor one on average ({sharpSum:F0} vs {poorSum:F0})");
});

