TestRunner.Run("7.5: CareerStatsService folds a match into the cache and MilestoneService catches the crossings", () =>
{
    var stats = new CareerStatsService();
    var milestones = new MilestoneService();

    var player = MatchTestData.MakePlayer("Veteran", 15);
    player.DateOfBirth = new DateOnly(1994, 1, 1);
    // A career already close to two landmarks.
    for (int i = 0; i < 99; i++) player.Experience.RecordAppearance(MatchFormat.Test, new DateOnly(2020, 1, 1)); // his 100th cap comes THIS match
    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team>(),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = new List<Player> { player },
        Projects = new List<InfrastructureProject>()
    };
    world.CareerStats[CareerStatsService.Key(player.Id, MatchFormat.Test)] = new PlayerCareerStats
    {
        PlayerId = player.Id, Format = MatchFormat.Test, Matches = 99, Innings = 150, Runs = 4_960, Hundreds = 12
    };

    var records = new MatchRecords();
    records.Batting.Add(new BattingInningsRecord { PlayerId = player.Id, Runs = 105, BallsFaced = 180, NotOut = false, Fours = 10, Sixes = 1 });
    player.Experience.RecordAppearance(MatchFormat.Test, new DateOnly(2027, 6, 1)); // the 100th cap

    var before = stats.Snapshot(world, new[] { player.Id }, MatchFormat.Test);
    stats.ApplyMatch(world, records, MatchFormat.Test, new HashSet<Guid> { player.Id });
    var found = milestones.Detect(world, records, world.Players.ToDictionary(p => p.Id), MatchFormat.Test, new DateOnly(2027, 6, 1), before);

    TestRunner.IsTrue(found.Any(e => e.Headline.Contains("100th") && e.Headline.Contains("cap")), "the cap landmark was caught");
    TestRunner.IsTrue(found.Any(e => e.Headline.Contains("5,000 career Test runs")), "the 5,000-run landmark was caught (4,960 -> 5,065)");
    TestRunner.AreEqual(5_065, stats.For(world, player.Id, MatchFormat.Test)!.Runs, "the cache was updated");
});

