// ---- 7.6: discipline & conduct ----
TestRunner.Run("7.6: a seam-heavy attack draws over-rate fines far more than a spin-inclusive one", () =>
{
    var svc = new DisciplineService();
    var world = new WorldState { Teams = new Dictionary<Guid, Team>(), Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };

    List<Player> Attack(bool allSeam)
    {
        var list = new List<Player>();
        for (int i = 0; i < 5; i++)
        {
            var p = MatchTestData.MakePlayer($"Bowl{i}", 13, PlayerRole.Bowler, allSeam || i < 3 ? BowlingRoleType.OpeningBowler : BowlingRoleType.SpecialistSpinner);
            p.Bowling.Pace = allSeam || i < 3 ? 16 : 4;
            list.Add(p);
        }
        return list;
    }

    int seamFines = 0, mixedFines = 0;
    for (int i = 0; i < 120; i++)
    {
        var home = new Team { Name = "Home" }; var away = new Team { Name = "Away" };
        var seamAttack = Attack(true); var mixedAttack = Attack(false);
        var xi = seamAttack.Concat(mixedAttack).Take(11).ToList();
        var evs = svc.ReviewMatch(world, new DateOnly(2027, 6, 1), MatchFormat.Test, home, away,
            homeBowlers: seamAttack, awayBowlers: mixedAttack, homeXi: xi, awayXi: xi,
            homeCaptainId: null, awayCaptainId: null, importance: 50, random: new Random(i));
        seamFines += evs.Count(e => e.SubjectId == home.Id && e.Headline.Contains("over-rate"));
        mixedFines += evs.Count(e => e.SubjectId == away.Id && e.Headline.Contains("over-rate"));
    }
    TestRunner.IsTrue(seamFines > mixedFines + 5, $"the four-seam attack is fined much more often ({seamFines} vs {mixedFines})");
});

TestRunner.Run("7.6: a ban is a real unavailability, cleared on expiry, and demerit points age out of the rolling 24-month window", () =>
{
    var svc = new DisciplineService();
    var avail = new PlayerAvailabilityService();
    var player = MatchTestData.MakePlayer("Hothead", 12);
    player.SuspendedUntil = new DateOnly(2027, 7, 1);
    player.NonInjuryUnavailability = UnavailabilityReason.Suspended;

    TestRunner.IsTrue(!avail.GetAvailability(player, new DateOnly(2027, 6, 15)).IsAvailable, "a suspended player cannot be picked");

    var world = new WorldState { Teams = new Dictionary<Guid, Team>(), Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player> { player }, Projects = new List<InfrastructureProject>() };
    svc.ReviewSuspensions(world, new DateOnly(2027, 6, 1)); // before expiry
    TestRunner.AreEqual(UnavailabilityReason.Suspended, player.NonInjuryUnavailability, "still banned before the date");
    var evs = svc.ReviewSuspensions(world, new DateOnly(2027, 7, 2)); // after
    TestRunner.AreEqual(UnavailabilityReason.Available, player.NonInjuryUnavailability, "available again once served");
    TestRunner.IsTrue(evs.Any(e => e.Headline.Contains("available again")), "an event announced the return");

    // Section A: demerit points age out of a rolling 24-month window, not a "lose one every 6 months" timer.
    player.DemeritLog.Add(new DemeritEntry(new DateOnly(2025, 1, 1), 3, 2, "old charge"));
    player.DemeritLog.Add(new DemeritEntry(new DateOnly(2027, 3, 1), 2, 1, "recent charge"));
    svc.ReviewSuspensions(world, new DateOnly(2027, 7, 2));
    TestRunner.AreEqual(2, player.DemeritPoints, "the charge over 24 months old has aged out; only the recent one still counts");
    TestRunner.IsTrue(player.DemeritLog.Count == 1, "the expired log entry was pruned");
});


// ---- 7.7: records database + hall of fame ----
TestRunner.Run("7.7: a record is established silently, then a broken record produces a 'stood for N' story with a holder chain", () =>
{
    var svc = new RecordProgressionService();
    var world = new WorldState { Teams = new Dictionary<Guid, Team>(), Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };
    var teamA = Guid.NewGuid(); var teamB = Guid.NewGuid();

    MatchRecords TeamTotal(int runs, Guid teamId, string name)
    {
        var r = new MatchRecords();
        r.TeamInnings.Add(new TeamInningsRecord { BattingTeamId = teamId, BattingTeamName = name, Runs = runs, Wickets = 6, Format = MatchFormat.T20 });
        return r;
    }

    var first = svc.ReviewMatch(world, TeamTotal(210, teamA, "Alpha"), new DateOnly(2026, 6, 1));
    TestRunner.IsTrue(!first.Any(e => e.Type == GameEventType.RecordBroken), "establishing the first record is not 'breaking' one");

    var beaten = svc.ReviewMatch(world, TeamTotal(255, teamB, "Beta"), new DateOnly(2028, 6, 1));
    TestRunner.IsTrue(beaten.Any(e => e.Type == GameEventType.RecordBroken && e.Headline.Contains("stood for 2 year")),
        "the new record names how long the old one stood");

    var entry = world.RecordBook["HighestTeamTotal|"];
    TestRunner.AreEqual(255d, entry.Value, "the book holds the new mark");
    TestRunner.AreEqual(1, entry.PreviousHolders.Count, "and the previous holder is in the chain");
    TestRunner.AreEqual("Alpha", entry.PreviousHolders[0].HolderName, "with the right name");
});

TestRunner.Run("7.7: the Hall of Fame inducts genuine greats and leaves out ordinary long careers", () =>
{
