TestRunner.Run("7.8: a weak, political selection panel meddles with the pool - a strong one gets out of the way", () =>
{
    var seeder = new WorldSeeder(seed: 780, worldStartDate: new DateOnly(2026, 6, 1));
    var (_, players) = seeder.GenerateStarterWorld("Pakistan", teamCount: 10, squadSize: 16);
    var svc = new SelectionPanelService();
    var poolSvc = new NationalPoolService();

    int Meddles(double chairmanQuality, double politicisation, int seed)
    {
        var national = new Team { Name = "Pakistan", Country = "Pakistan", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = chairmanQuality, Politicisation = politicisation } };
        var pool = poolSvc.BuildPool(national, players, MatchFormat.T20, new DateOnly(2026, 6, 1), null);
        // A well-known name who has been DROPPED (out of the pool) and is out of form and older -
        // exactly the "recall on reputation" a weak, political panel reaches for.
        var fading = players.OrderByDescending(p => p.Reputation.Domestic).First(p => pool.Contains(p.Id));
        pool.Remove(fading.Id);
        fading.Reputation = new Reputation(68);
        fading.Form.RecordPerformance(-60); fading.Form.RecordPerformance(-60); fading.Form.RecordPerformance(-60);
        fading.DateOfBirth = new DateOnly(1992, 1, 1);
        var pools = new List<NationalPool> { pool };
        var evs = svc.ApplyPanelInfluence(national, pools, players.ToList(), new DateOnly(2026, 6, 1), new Random(seed));
        return evs.Count;
    }

    int weakTotal = 0, strongTotal = 0;
    for (int i = 0; i < 60; i++) { weakTotal += Meddles(42, 82, i); strongTotal += Meddles(88, 25, i); }
    TestRunner.IsTrue(weakTotal > strongTotal + 5, $"the weak political panel leaves far more fingerprints ({weakTotal} vs {strongTotal})");
});

// ---- 7.9: umpiring (no DRS) ----
TestRunner.Run("7.9: umpire judgement folds attributes and experience; a null panel is a byte-identical no-op in the ball model", () =>
{
    var elite = new Umpire { Accuracy = 19, Consistency = 18, Composure = 18, LbwJudgement = 19, MatchesOfficiated = 250 };
    var rookie = new Umpire { Accuracy = 9, Consistency = 8, Composure = 8, LbwJudgement = 9, MatchesOfficiated = 4 };
    TestRunner.IsTrue(elite.EffectiveJudgement > rookie.EffectiveJudgement + 0.3, "an elite official reads the game far better");

    var svc = new UmpireService();
    TestRunner.AreEqual(1.0, svc.OutBiasFor(null, 90, 0.05), "no panel = a neutral 1.0 bias");
    TestRunner.IsTrue(svc.OutBiasFor(new[] { rookie, rookie }, 95, 0.05) is > 1.0 and <= 1.22, "a rookie panel under a loud crowd leans toward more decisions, bounded");

    // Byte-identical: an innings with bias 1.0 replays exactly as one with no umpire influence.
    var sim = new InningsSimulator();
    var batting = MatchTestData.Setup(12, 4, "A"); var bowling = MatchTestData.Setup(4, 12, "B");
    var setup = new InningsSetup(batting.BattingOrder, bowling.FieldingSide, bowling.AvailableBowlers);
    var plain = sim.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "A", Guid.NewGuid(), "B", new Random(99));
    var neutral = sim.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "A", Guid.NewGuid(), "B", new Random(99), umpireOutBias: 1.0);
    TestRunner.AreEqual(plain.Runs, neutral.Runs, "bias 1.0 changes nothing");
    TestRunner.AreEqual(plain.Deliveries.Count, neutral.Deliveries.Count, "...not one delivery");
});

TestRunner.Run("7.9: a leaning panel gives more of the marginal LBWs and caught-behinds", () =>
{
    var sim = new InningsSimulator();
    int neutralOut = 0, leaningOut = 0;
    for (int i = 0; i < 120; i++)
    {
        var batting = MatchTestData.Setup(11, 4, "A"); var bowling = MatchTestData.Setup(4, 13, "B");
        var setup = new InningsSetup(batting.BattingOrder, bowling.FieldingSide, bowling.AvailableBowlers);
        var n = sim.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "A", Guid.NewGuid(), "B", new Random(i + 3000), umpireOutBias: 1.0);
        var l = sim.Simulate(setup, MatchFormat.T20, 20, Guid.NewGuid(), "A", Guid.NewGuid(), "B", new Random(i + 3000), umpireOutBias: 1.18);
        neutralOut += n.BatterCards.Count(c => c.Dismissal is DismissalType.LBW or DismissalType.CaughtBehind);
        leaningOut += l.BatterCards.Count(c => c.Dismissal is DismissalType.LBW or DismissalType.CaughtBehind);
    }
    TestRunner.IsTrue(leaningOut > neutralOut, $"the leaning panel produces more LBW/caught-behind wickets ({leaningOut} vs {neutralOut})");
});

TestRunner.Run("7.9: UmpireService assigns the right tier, prefers neutral officials, and moves careers", () =>
{
    var panel = new WorldSeeder(seed: 79).GenerateUmpirePanel(new[] { "Pakistan", "Australia", "England" }, 24);
    var svc = new UmpireService();

    var assigned = svc.AssignPanel(panel, isInternational: true, isKnockout: true, importance: 90,
        homeNationality: "Pakistan", awayNationality: "Australia", random: new Random(1));
    TestRunner.IsTrue(assigned.Count is >= 2 and <= 3, "two on-field plus a reserve");
    TestRunner.IsTrue(assigned.Take(2).All(u => u.Panel is UmpirePanel.Elite or UmpirePanel.International), "a big international knockout gets the top tiers");
    TestRunner.IsTrue(assigned.Take(2).All(u => u.Nationality is not ("Pakistan" or "Australia")) || panel.Count(u => u.Nationality is not ("Pakistan" or "Australia")) < 2,
        "neutral officials are preferred where available");

    var onField = assigned.Take(2).ToList();
    double repBefore = onField.Average(u => u.Reputation);
    var howlerProne = onField.Select(u => { u.Accuracy = 5; u.LbwJudgement = 5; u.Consistency = 5; return u; }).ToList();
    int totalHowlers = 0;
    for (int i = 0; i < 40; i++)
    {
        var report = svc.ReviewMatch(howlerProne, new Dictionary<DismissalType, int> { [DismissalType.LBW] = 6, [DismissalType.CaughtBehind] = 4 }, tightFinish: true, importance: 85, new Random(i));
        totalHowlers += report.Howlers;
    }
    TestRunner.IsTrue(totalHowlers > 0, "a poor panel produces real errors over a run of matches");
    TestRunner.IsTrue(onField.All(u => u.MatchesOfficiated > 0), "officiating a match counts toward experience");
});


// ---- Phase 7 integration: a multi-year world exercises every slice and stays deterministic ----
TestRunner.Run("Phase 7 integration: finance, news, awards, records, discipline and umpiring all run over a multi-year world, deterministically", () =>
{
    (int financeEvents, int awardEvents, int newsItems, int digests, int careerStatRows, int umpMatches, string champs) Run(int seed)
    {
        var seeder = new WorldSeeder(seed: seed, worldStartDate: new DateOnly(2026, 1, 1));
        var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
        var world = new WorldState
        {
            Teams = iw.Teams.ToDictionary(t => t.Id),
            Grounds = iw.Grounds.ToDictionary(g => g.Id),
            Players = iw.Players.ToList(),
            Projects = new List<InfrastructureProject>(),
        };
        foreach (var c in iw.Competitions) world.Competitions.Add(c);
        foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
        foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
        foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
        foreach (var p in iw.NationalPools) world.NationalPools.Add(p);
        foreach (var u in iw.Umpires) world.Umpires.Add(u);

        var clock = new WorldClockService();
        var cal = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: seed);
        var events = clock.AdvanceTo(cal, world, new DateOnly(2029, 3, 1));

        int financeEvents = events.Count(e => e.Type is GameEventType.TeamFinancesSettled or GameEventType.BroadcastRevenuePaid or GameEventType.SeasonBudgetSet);
        int awardEvents = events.Count(e => e.Type == GameEventType.SeasonAward);
        int careerStatRows = world.CareerStats.Count;
        int umpMatches = world.Umpires.Sum(u => u.MatchesOfficiated);
        string champs = string.Join(",", world.CompetitionSeasons.Where(s => s.IsCompleted && s.ChampionTeamId is { } cid)
            .OrderBy(s => s.Year).ThenBy(s => world.Teams[s.ChampionTeamId!.Value].Name)
            .Select(s => $"{s.Year}:{world.Teams[s.ChampionTeamId!.Value].Name}"));
        return (financeEvents, awardEvents, world.NewsArchive.Count, world.Digests.Count, careerStatRows, umpMatches, champs);
    }

    var a = Run(7007);
    TestRunner.IsTrue(a.financeEvents > 0, "the finance loop ran (settlements, broadcast money, budgets)");
    TestRunner.IsTrue(a.awardEvents > 0, "awards were handed out");
    TestRunner.IsTrue(a.newsItems > 50, $"the news archive filled up ({a.newsItems})");
    TestRunner.IsTrue(a.digests > 20, $"weekly digests were produced ({a.digests})");
    TestRunner.IsTrue(a.careerStatRows > 100, $"the career-stats cache was populated by real matches ({a.careerStatRows})");
    TestRunner.IsTrue(a.umpMatches > 30, $"umpires officiated real matches ({a.umpMatches})");

    var b = Run(7007);
    TestRunner.AreEqual(a.champs, b.champs, "same seed -> same champions");
    TestRunner.AreEqual(a.careerStatRows, b.careerStatRows, "same seed -> same career-stats cache");
    TestRunner.AreEqual(a.umpMatches, b.umpMatches, "same seed -> same umpiring workload");
    TestRunner.AreEqual(a.financeEvents, b.financeEvents, "same seed -> same finance activity");
});


// ---- Phase 7 follow-up: financial fair play, fan sentiment -> attendance, a competitive-world acceptance test ----
TestRunner.Run("7 follow-up: a club running a sustained deficit gets a points deduction and a spending embargo, lifted on recovery", () =>
{
    var svc = new FinancialFairPlayService();
    var comp = new Competition { Name = "Domestic League", Scope = CompetitionScope.DomesticT20 };
    var teamOk = new Team { Name = "Solvent" }; teamOk.Finances.Budget = 500_000;
    var teamBroke = new Team { Name = "Overspent" }; teamBroke.Finances.Budget = -5_000_000;

    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2027 };
    foreach (var t in new[] { teamOk, teamBroke })
    {
        season.ParticipatingTeamIds.Add(t.Id);
        var st = season.GetOrCreateStanding(t.Id);
        for (int i = 0; i < 10; i++) st.RecordResult(MatchOutcome.Win); // 20 points each
    }

    var world = new WorldState
    {
        Teams = new[] { teamOk, teamBroke }.ToDictionary(t => t.Id),
        Grounds = new Dictionary<Guid, Ground>(),
        Players = new List<Player>(),
        Projects = new List<InfrastructureProject>(),
        Competitions = { comp }
    };
    world.CompetitionSeasons.Add(season);

    var evs = svc.Review(world, new DateOnly(2028, 1, 1), 2027);
    TestRunner.IsTrue(evs.Any(e => e.SubjectId == teamBroke.Id && e.Headline.Contains("financial fair play")), "the overspent club is charged");
    TestRunner.IsTrue(!evs.Any(e => e.SubjectId == teamOk.Id), "the solvent club is not");
    TestRunner.IsTrue(teamBroke.Board.UnderTransferEmbargo, "and placed under a spending embargo");
    var brokeRow = season.Standings.First(s => s.TeamId == teamBroke.Id);
    TestRunner.IsTrue(brokeRow.PointsPenalty >= 4 && brokeRow.Points < 20, $"a real points deduction was applied ({brokeRow.Points}, -{brokeRow.PointsPenalty})");

    // Recovery: books back in the black, embargo lifted.
    teamBroke.Finances.Budget = 300_000;
    teamBroke.Board.EmbargoUntil = new DateOnly(2028, 6, 1);
    var lift = svc.Review(world, new DateOnly(2029, 1, 1), 2028);
    TestRunner.IsTrue(!teamBroke.Board.UnderTransferEmbargo, "the embargo is lifted once the accounts recover");
    TestRunner.IsTrue(lift.Any(e => e.SubjectId == teamBroke.Id && e.Headline.Contains("lifted")), "and the lift is announced");
});

TestRunner.Run("7 follow-up: an angry fanbase stays away, a buzzing one fills the ground - the board -> fans -> gate loop closes", () =>
{
    var svc = new MatchdayRevenueService();
    var ground = new Ground { Name = "The Oval", Capacity = 25_000 };
