TestRunner.Run("8.1: an academy intake is genuine teenagers - low current ability, wide potential, attached to the club but not the senior squad", () =>
{
    var team = new Team { Name = "Academy FC", Country = "Australia", Strength = 55 };
    team.Facilities.YouthDevelopmentQuality = 70;
    team.Reputation.Adjust(30); // domestic ~35
    var ground = new Ground { Name = "Nets", Capacity = 20000 };
    ground.Facilities.YouthFacilities = 65;

    var cohort = new AcademyService().GenerateIntake(team, ground, new DateOnly(2026, 6, 1), new Random(4), scoutingQuality: 60);

    TestRunner.IsTrue(cohort.Count is >= 2 and <= 8, $"a real cohort size ({cohort.Count})");
    foreach (var p in cohort)
    {
        int age = p.Age(new DateOnly(2026, 6, 1));
        TestRunner.IsTrue(age is >= AcademyService.IntakeMinAge and <= AcademyService.IntakeMaxAge, $"a teenager ({age})");
        TestRunner.IsTrue(p.CurrentAbility < p.PotentialAbility, "he has genuine headroom");
        TestRunner.AreEqual(team.Id, p.AcademyTeamId, "attached to the academy");
        TestRunner.AreEqual(team.Id, p.CurrentTeamId, "and a player of the club");
        TestRunner.IsTrue(team.AcademyPlayerIds.Contains(p.Id), "and in the academy list");
        TestRunner.IsTrue(!team.SquadPlayerIds.Contains(p.Id), "but NOT in the senior squad");
        TestRunner.AreEqual("Australia", p.Nationality, "nationality follows the club");
    }

    // A poorly resourced academy produces a smaller cohort, averaged over seeds.
    var poor = new Team { Name = "Poor", Country = "Australia", Strength = 40 };
    poor.Facilities.YouthDevelopmentQuality = 15;
    int poorTotal = 0, richTotal = 0;
    for (int s = 0; s < 30; s++)
    {
        poorTotal += new AcademyService().GenerateIntake(poor, null, new DateOnly(2026, 6, 1), new Random(s), 20).Count;
        richTotal += new AcademyService().GenerateIntake(team, ground, new DateOnly(2026, 6, 1), new Random(s), 60).Count;
    }
    TestRunner.IsTrue(richTotal > poorTotal, $"a better academy takes in more prospects ({richTotal} vs {poorTotal})");
});

TestRunner.Run("8.2: the annual review promotes a ready graduate into the senior squad and leaves a 15-year-old alone", () =>
{
    var team = new Team { Name = "Grad", Country = "England", Strength = 50 };
    var academy = new AcademyService();

    // A ready graduate: 19, ability well above the club's bar.
