    TestRunner.IsTrue(team.AcademyPlayerIds.Contains(kid.Id) && kid.AcademyTeamId == team.Id, "the 15-year-old is untouched");
});

TestRunner.Run("8.2: a plateaued prospect is released to the free-agent pool", () =>
{
    var team = new Team { Name = "Cut", Country = "England", Strength = 55 };
    var stuck = MatchTestData.MakePlayer("Stuck", 5);
    stuck.DateOfBirth = new DateOnly(2005, 3, 1); // 21
    stuck.CurrentAbility = 45; stuck.PotentialAbility = 62; // a low ceiling, not much headroom
    stuck.AcademyTeamId = team.Id; stuck.CurrentTeamId = team.Id;
    team.AcademyPlayerIds.Add(stuck.Id);

    var review = new AcademyService().ReviewAcademy(new[] { stuck }, team, new DateOnly(2026, 6, 1), new Random(2), scoutingQuality: 85, applyChanges: true);

    TestRunner.IsTrue(review.Released >= 1, "he was released");
    TestRunner.IsTrue(!team.AcademyPlayerIds.Contains(stuck.Id) && stuck.AcademyTeamId is null, "out of the academy");
    TestRunner.IsTrue(stuck.CurrentTeamId is null, "and a free agent");
});

TestRunner.Run("8.3: the review acts on a SCOUTED estimate - a weak scouting department misjudges a borderline prospect where a strong one keeps him", () =>
{
    // A low-current prospect whose TRUE ceiling sits just above the release bar. Strong scouting
    // reads that correctly and keeps him; weak scouting frequently reads him as done and lets him go.
    int ReleasedOverTrials(int scoutingQuality)
    {
        int released = 0;
        for (int t = 0; t < 120; t++)
        {
            var team = new Team { Name = "S", Country = "England", Strength = 50 };
            var p = MatchTestData.MakePlayer("Borderline", 4);
            p.DateOfBirth = new DateOnly(2005, 3, 1); // 21
            p.CurrentAbility = 36; p.PotentialAbility = 86; // true ceiling ~43, just above the release bar
            p.AcademyTeamId = team.Id; p.CurrentTeamId = team.Id;
            team.AcademyPlayerIds.Add(p.Id);
            var r = new AcademyService().ReviewAcademy(new[] { p }, team, new DateOnly(2026, 6, 1), new Random(t), scoutingQuality, applyChanges: true);
            released += r.Released;
        }
        return released;
    }

    int strong = ReleasedOverTrials(100);
    int weak = ReleasedOverTrials(15);
    TestRunner.IsTrue(strong == 0, $"a strong scouting department never wrongly releases him ({strong})");
    TestRunner.IsTrue(weak > 15, $"a weak one lets him go a real fraction of the time ({weak}/120)");
});

TestRunner.Run("8.4: individual peak timing - a late developer declines physically years after his identical-attribute twin", () =>
{
    var ageing = new PlayerAgeingService();
    int LateSum(int offset)
    {
        int total = 0;
        for (int seed = 0; seed < 25; seed++)
        {
            var p = MatchTestData.MakePlayer("P", 15, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
            p.DateOfBirth = new DateOnly(1994, 1, 1); // 32 at the start
            p.PeakAgeOffset = offset;
            var rng = new Random(seed);
            for (int y = 0; y < 6; y++) ageing.ApplyAnnualAgeing(p, new DateOnly(2026 + y, 6, 1), rng);
            total += p.Physical.Speed + p.Physical.Stamina + p.Bowling.Pace;
        }
        return total;
    }

    int early = LateSum(-3);
    int average = LateSum(0);
    int late = LateSum(4);
    TestRunner.IsTrue(late > average && average > early,
        $"the later the peak, the more he has kept into his late 30s (early {early} < avg {average} < late {late})");
});

TestRunner.Run("8.4: a career-threatening injury leaves a permanent mark on pace and mobility when it resolves", () =>
{
    var svc = new PlayerAvailabilityService();
    var p = MatchTestData.MakePlayer("Crock", 15, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    int paceBefore = p.Bowling.Pace, speedBefore = p.Physical.Speed;

    svc.ApplyInjury(p, InjuryType.KneeInjury, InjurySeverity.CareerThreatening, new DateOnly(2026, 1, 1), teamMedicalQuality: 60);
    svc.MarkRecovered(p, p.CurrentInjury!.ExpectedReturnDate);

    TestRunner.IsTrue(p.Bowling.Pace < paceBefore, $"a yard of pace gone for good ({p.Bowling.Pace} < {paceBefore})");
    TestRunner.IsTrue(p.Physical.Speed < speedBefore, "a step slower in the field, permanently");

    // A Minor injury leaves no such mark.
    var q = MatchTestData.MakePlayer("Fine", 15, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    int qPace = q.Bowling.Pace;
    svc.ApplyInjury(q, InjuryType.MuscleStrain, InjurySeverity.Minor, new DateOnly(2026, 1, 1));
    svc.MarkRecovered(q, q.CurrentInjury?.ExpectedReturnDate ?? new DateOnly(2026, 2, 1));
    TestRunner.AreEqual(qPace, q.Bowling.Pace, "a minor knock costs nothing lasting");
});

TestRunner.Run("8.1/8.2: a genuine teenager develops faster than a mid-career player on the identical training programme", () =>
{
    int Gains(int age)
    {
        int total = 0;
        for (int seed = 0; seed < 25; seed++)
        {
            var p = MatchTestData.MakePlayer("Dev", 6);
            p.DateOfBirth = new DateOnly(2026 - age, 6, 2);
            p.CurrentAbility = 60; p.PotentialAbility = 180;
            p.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
            p.TrainingPlan.Intensity = TrainingIntensity.Normal;
            var rng = new Random(seed);
            for (int m = 0; m < 24; m++)
                new TrainingService().ApplyPeriodicTraining(p, 60, Array.Empty<StaffMember>(), rng, new DateOnly(2026, 1, 1).AddMonths(m), 1.0 / 12, true);
            total += p.Batting.Technique;
        }
        return total;
    }

    int teen = Gains(16);
    int midCareer = Gains(27);
    TestRunner.IsTrue(teen > midCareer, $"the 16-year-old improves more over two years ({teen} vs {midCareer})");
});

TestRunner.Run("8.5: the training week is classified from the fixture calendar, and only a preparation/off-season week develops a young player", () =>
{
    var svc = new TrainingWeekService();
    var team = new Team { Name = "TW", Country = "England" };
    var world = new WorldState { Teams = new Dictionary<Guid, Team> { [team.Id] = team }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };

    // No fixtures, no competitions -> off-season.
    TestRunner.AreEqual(TrainingWeekType.OffSeason, svc.ClassifyWeek(team, world, new DateOnly(2026, 6, 15)), "no cricket on the horizon");

    world.Fixtures.Add(new Fixture { HomeTeamId = team.Id, AwayTeamId = Guid.NewGuid(), ScheduledDate = new DateOnly(2026, 6, 16) });
    TestRunner.AreEqual(TrainingWeekType.MatchWeek, svc.ClassifyWeek(team, world, new DateOnly(2026, 6, 15)), "a fixture the day after");

    var young = MatchTestData.MakePlayer("Y", 6);
    young.DateOfBirth = new DateOnly(2008, 1, 1); young.CurrentAbility = 60; young.PotentialAbility = 170;
    int offSeasonHits = 0, matchWeekHits = 0;
    for (int t = 0; t < 400; t++)
    {
        var a = MatchTestData.MakePlayer("A", 6); a.DateOfBirth = young.DateOfBirth; a.CurrentAbility = 60; a.PotentialAbility = 170;
        if (svc.ApplyTrainingWeek(a, TrainingWeekType.OffSeason, new Random(t), new DateOnly(2026, 6, 15))) offSeasonHits++;
        var b = MatchTestData.MakePlayer("B", 6); b.DateOfBirth = young.DateOfBirth; b.CurrentAbility = 60; b.PotentialAbility = 170;
        if (svc.ApplyTrainingWeek(b, TrainingWeekType.MatchWeek, new Random(t), new DateOnly(2026, 6, 15))) matchWeekHits++;
    }
    TestRunner.IsTrue(offSeasonHits > 0, $"off-season weeks develop a young player ({offSeasonHits}/400)");
    TestRunner.AreEqual(0, matchWeekHits, "a match week never does");
});

TestRunner.Run("8.6: a retiring international becomes a rookie coach - same person, real playing pedigree, a starting badge, his cricket brain intact", () =>
{
    var player = MatchTestData.MakePlayer("Wasim", 17, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    player.FirstName = "Wasim"; player.LastName = "Great";
    player.Nationality = "Pakistan";
    player.DateOfBirth = new DateOnly(1988, 6, 3);
    player.Reputation.Adjust(domesticDelta: 90, continentalDelta: 80, worldwideDelta: 55);
    player.Personality = PersonalityTrait.Leader;
    player.Mental.Leadership = 18; player.Mental.GameAwareness = 18; player.Mental.DecisionMaking = 17;
    for (int i = 0; i < 120; i++) player.Experience.RecordAppearance(MatchFormat.Test, new DateOnly(2010, 1, 1), isInternational: true);

    var coach = new CoachRecruitmentService().CreateFromRetiredPlayer(player, new DateOnly(2027, 1, 1));

    TestRunner.AreEqual("Wasim", coach.FirstName, "same first name");
    TestRunner.AreEqual("Great", coach.LastName, "same surname");
    TestRunner.AreEqual(player.DateOfBirth, coach.DateOfBirth, "same date of birth - he is the same person");
    TestRunner.AreEqual("Pakistan", coach.Nationality, "same nationality");
    TestRunner.IsTrue(coach.PlayingExperience is PlayingExperience.InternationalStar or PlayingExperience.FormerCaptain, "a heavy-cap international pedigree");
    TestRunner.AreEqual(CoachingLicense.Basic, coach.License, "he is only starting out as a coach");
    TestRunner.IsTrue(coach.Attributes.TacticalKnowledge > 10, "the cricket brain he had as a player carries in");
});

TestRunner.Run("8.6: coaching-badge progression advances a coach over a career and caps at the top", () =>
{
    var coach = new Coach { FirstName = "Learner", LastName = "C", License = CoachingLicense.Basic };
    coach.SeedAttributesFromHistory();
    var svc = new CoachCareerService();

    var progressions = new List<CoachingLicense>();
    for (int season = 1; season <= 55; season++)
    {
        coach.CareerRecord.RecordSeason(0.15, wonTitle: false, wonMajorTitle: false, reachedMajorFinal: false, sameClubAsLastSeason: true);
        var moved = svc.ProgressLicence(coach, coach.CareerRecord.SeasonsCoached, new Random(season * 13));
        if (moved is { } m) progressions.Add(m);
    }

    TestRunner.IsTrue(progressions.Count >= 3, $"the badge moves up several rungs over a career ({string.Join(" -> ", progressions)})");
    TestRunner.AreEqual(CoachingLicense.InternationalElite, coach.License, "and tops out at the elite badge");
    TestRunner.IsTrue(svc.ProgressLicence(coach, 80, new Random(1)) is null, "which cannot be exceeded");
});

TestRunner.Run("8.7: a buried youngster is loaned out to a weaker club and comes back a better player for the game time", () =>
{
    var big = new Team { Name = "Big", Country = "England", Strength = 80 };
    var small = new Team { Name = "Small", Country = "England", Strength = 40 };
    var world = new WorldState
    {
        Teams = new Dictionary<Guid, Team> { [big.Id] = big, [small.Id] = small },
        Grounds = new Dictionary<Guid, Ground>(),
        Players = new List<Player>(),
        Projects = new List<InfrastructureProject>()
    };

    for (int i = 0; i < 18; i++)
    {
        var p = MatchTestData.MakePlayer($"Big{i}", 15);
        p.CurrentTeamId = big.Id; big.SquadPlayerIds.Add(p.Id); world.Players.Add(p);
    }
    for (int i = 0; i < 12; i++)
    {
        var p = MatchTestData.MakePlayer($"Sm{i}", 8);
        p.CurrentTeamId = small.Id; small.SquadPlayerIds.Add(p.Id); world.Players.Add(p);
    }

    var kid = MatchTestData.MakePlayer("Kid", 9, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    kid.DateOfBirth = new DateOnly(2007, 1, 1); // 19
    kid.CurrentAbility = 90; kid.PotentialAbility = 165;
    kid.SquadStatus = SquadStatus.DevelopmentProspect;
    kid.CurrentTeamId = big.Id; big.SquadPlayerIds.Add(kid.Id); world.Players.Add(kid);

    var loans = new LoanService();
    var outEvents = loans.ConsiderLoans(world, big, new DateOnly(2026, 6, 1), new Random(3)).ToList();

    TestRunner.IsTrue(kid.LoanReturnDate is not null && kid.ParentClubId == big.Id, "he is out on loan");
    TestRunner.AreEqual(small.Id, kid.CurrentTeamId, "playing for the smaller club");
    TestRunner.IsTrue(small.SquadPlayerIds.Contains(kid.Id) && !big.SquadPlayerIds.Contains(kid.Id), "in their squad, out of his parent club's");

    // He plays some games, then the loan ends.
    world.RecordAppearance(kid.Id); world.RecordAppearance(kid.Id); world.RecordAppearance(kid.Id);
    world.RecordAppearance(kid.Id); world.RecordAppearance(kid.Id); world.RecordAppearance(kid.Id);
    int abilityBefore = kid.CurrentAbility;
    var backEvents = loans.ProcessReturns(world, kid.LoanReturnDate!.Value).ToList();

    TestRunner.IsTrue(kid.LoanReturnDate is null && kid.ParentClubId is null, "the loan is over");
    TestRunner.AreEqual(big.Id, kid.CurrentTeamId, "back at his parent club");
    TestRunner.IsTrue(big.SquadPlayerIds.Contains(kid.Id) && !small.SquadPlayerIds.Contains(kid.Id), "in their squad again");
    TestRunner.IsTrue(kid.CurrentAbility > abilityBefore, $"a better player for the games ({kid.CurrentAbility} > {abilityBefore})");
    TestRunner.IsTrue(backEvents.Count > 0, "and it is reported");
});

await TestRunner.RunAsync("Phase 8 integration: a seeded world runs its youth pipeline over a decade - academies take in, graduate and release, the world grows, and retiring players become coaches", async () =>
{
    await Task.CompletedTask;
    var seeder = new WorldSeeder(seed: 88088, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "India" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
    foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
    foreach (var p in iw.NationalPools) world.NationalPools.Add(p);
    foreach (var u in iw.Umpires) world.Umpires.Add(u);

    // Well-run academies, so the pipeline actually produces graduates over the decade.
    foreach (var t in world.Teams.Values) { t.Facilities.YouthDevelopmentQuality = 70; t.Facilities.ScoutingQuality = 60; }

    int seniorAtStart = world.Players.Count(p => p.AcademyTeamId is null);
    int academyAtStart = world.Players.Count(p => p.AcademyTeamId is not null);
    TestRunner.IsTrue(academyAtStart > 0, $"the seeded world starts with an academy pipeline ({academyAtStart} prospects)");
    var initialAcademyIds = world.Players.Where(p => p.AcademyTeamId is not null).Select(p => p.Id).ToHashSet();

    var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 88088), world, new DateOnly(2036, 3, 1));

    int intakeEvents = events.Count(e => e.Headline.Contains("academy takes in"));
    TestRunner.IsTrue(intakeEvents >= 10, $"academies take in new cohorts year after year ({intakeEvents})");

    int promotionEvents = events.Count(e => e.Headline.Contains("from the academy"));
    int releaseEvents = events.Count(e => e.Headline.Contains("release") && e.Headline.Contains("the academy has taken him"));
    TestRunner.IsTrue(promotionEvents >= 3, $"prospects graduate into senior squads over the decade ({promotionEvents})");
    TestRunner.IsTrue(releaseEvents >= 1, $"and the ones who plateau are let go ({releaseEvents})");

    int stillAccountedFor = initialAcademyIds.Count(id =>
    {
        var p = world.Players.FirstOrDefault(x => x.Id == id);
        return p is null // released and dropped from tracking, or
            || p.AcademyTeamId is not null // still in an academy, or
            || world.Teams.Values.Any(t => t.SquadPlayerIds.Contains(id)) // promoted, or
            || p.CurrentTeamId is null; // released to free agency
    });
    TestRunner.AreEqual(initialAcademyIds.Count, stillAccountedFor, "every original prospect is accounted for - promoted, still developing, or released");

    TestRunner.IsTrue(world.Players.Count > seniorAtStart, "the world's player base has grown, not just aged");
    int active = world.Players.Count(p => !p.IsRetired);
    TestRunner.IsTrue(active > world.Players.Count / 3, $"and it has not stagnated - {active}/{world.Players.Count} active");

    // NEW-C: a retiree's second career - head coach / specialist / scout / selector / mentor.
    int newFromRetirees = world.Coaches.Count(c => c.FromPlayerId is not null) + world.Staff.Count(s => s.FromPlayerId is not null);
    TestRunner.IsTrue(newFromRetirees >= 1, $"the world generates its own coaches and staff from retiring players ({newFromRetirees})");
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.PlayerCareerAfterCricket), "retirements produce 'life after cricket' news");
});

await TestRunner.RunAsync("Phase 8: the youth pipeline is deterministic - the same seed produces the same world twice", async () =>
{
    await Task.CompletedTask;
    (int Players, int Retired, int Academy, int Events) Run()
    {
        var seeder = new WorldSeeder(seed: 20260901, worldStartDate: new DateOnly(2026, 1, 1));
        var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia" }, teamsPerCountry: 3, squadSize: 14, seasonYear: 2026);
        var world = new WorldState
        {
            Teams = iw.Teams.ToDictionary(t => t.Id),
            Grounds = iw.Grounds.ToDictionary(g => g.Id),
            Players = iw.Players.ToList(),
            Projects = new List<InfrastructureProject>(),
        };
        foreach (var c in iw.Competitions) world.Competitions.Add(c);
        foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
        foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
        foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
        foreach (var p in iw.NationalPools) world.NationalPools.Add(p);
        foreach (var u in iw.Umpires) world.Umpires.Add(u);
        var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 20260901), world, new DateOnly(2033, 3, 1));
        return (world.Players.Count, world.Players.Count(p => p.IsRetired), world.Players.Count(p => p.AcademyTeamId is not null), events.Count);
    }

    var a = Run();
    var b = Run();
    TestRunner.AreEqual(a.Players, b.Players, "same total player count");
    TestRunner.AreEqual(a.Retired, b.Retired, "same number retired");
    TestRunner.AreEqual(a.Academy, b.Academy, "same academy population");
    TestRunner.AreEqual(a.Events, b.Events, "same event stream length");
});

