// PHASE 9 - Auction / Contracts / Market
// ============================================================================================

TestRunner.Run("9.0: every seeded player gets a real contract, and the finance loop sums the real wages instead of the stub", () =>
{
    var seeder = new WorldSeeder(seed: 909, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia" }, teamsPerCountry: 3, squadSize: 14, seasonYear: 2026);

    var domesticSquadPlayers = iw.Teams.Where(t => !t.IsNational && !t.IsFranchise)
        .SelectMany(t => t.SquadPlayerIds).ToHashSet();
    var contracted = iw.PlayerContracts.Where(c => c.Kind == CricketManager.Domain.Enums.ContractKind.Domestic).Select(c => c.PlayerId).ToHashSet();

    TestRunner.IsTrue(iw.PlayerContracts.Count > 50, $"contracts were generated ({iw.PlayerContracts.Count})");
    int uncontracted = domesticSquadPlayers.Count(id => !contracted.Contains(id)
        && iw.Players.First(p => p.Id == id).AcademyTeamId is null);
    TestRunner.AreEqual(0, uncontracted, "every senior domestic player has a contract");
    TestRunner.IsTrue(iw.PlayerContracts.All(c => c.AnnualWage >= 12_000 && c.EndDate > c.StartDate), "contracts are sane");

    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);

    var club = iw.Teams.First(t => !t.IsNational && !t.IsFranchise);
    double real = CricketManager.Domain.Services.PlayerContractService.RealWageBill(world, club)!.Value;
    double stub = new CricketManager.Domain.Services.WageBillService().EstimateAnnualWageBill(club, world.Players, world.StaffContracts);
    TestRunner.IsTrue(real > 0 && Math.Abs(real - stub) > 1, $"real wage bill ({real:N0}) is its own figure, not the stub ({stub:N0})");
});

TestRunner.Run("9.1: contract renewal keeps a valued young first-choice and lets an ageing fringe player run down", () =>
{
    var svc = new CricketManager.Domain.Services.PlayerContractService();
    int RenewRate(SquadStatus status, int age, PersonalityTrait personality = PersonalityTrait.None)
    {
        int renewed = 0;
        for (int t = 0; t < 200; t++)
        {
            var p = MatchTestData.MakePlayer("P", 14);
            p.DateOfBirth = new DateOnly(2026 - age, 6, 1);
            p.SquadStatus = status;
            p.Personality = personality;
            var team = new Team { Name = "C", Country = "England", Strength = 55 };
            team.Board.SeasonBudget = 8_000_000;
            var world = new WorldState { Teams = new Dictionary<Guid, Team> { [team.Id] = team }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player> { p }, Projects = new List<InfrastructureProject>() };
            double currentWage = new CricketManager.Domain.Services.PlayerValuationService().MarketWage(p) * 0.9; // on a slightly-below-market deal, so a renewal at market is a small raise
            var c = new CricketManager.Domain.Entities.PlayerContract { PlayerId = p.Id, TeamId = team.Id, StartDate = new DateOnly(2023, 1, 1), EndDate = new DateOnly(2026, 6, 1), AnnualWage = currentWage, Status = ContractStatus.Active };
            if (svc.EvaluateRenewal(c, p, team, new DateOnly(2026, 3, 1), new Random(t)).Renewed) renewed++;
        }
        return renewed;
    }

    int youngStar = RenewRate(SquadStatus.FirstChoice, 25);
    int oldFringe = RenewRate(SquadStatus.Fringe, 34);
    TestRunner.IsTrue(youngStar > 130, $"a 25-year-old first-choice is usually kept ({youngStar}/200)");
    TestRunner.IsTrue(oldFringe < 40, $"a 34-year-old fringe player is usually let go ({oldFringe}/200)");
});

TestRunner.Run("9.1: an expired contract makes the player a free agent - fully detached (Bosman)", () =>
