TestRunner.Run("9.2: the free-agent market signs an available player who fits a club's gap and accepts", () =>
{
    var svc = new CricketManager.Domain.Services.FreeAgentMarketService();
    var club = new Team { Name = "Buyers", Country = "England", Strength = 55 };
    club.Board.SeasonBudget = 10_000_000;
    club.Finances.Budget = 3_000_000;
    var world = new WorldState { Teams = new Dictionary<Guid, Team> { [club.Id] = club }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };
    var comp = new Competition { Name = "L", Format = MatchFormat.T20 };
    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
    season.ParticipatingTeamIds.Add(club.Id);
    world.Competitions.Add(comp); world.CompetitionSeasons.Add(season);
    world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract { PlayerId = Guid.NewGuid(), TeamId = club.Id, StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2028, 1, 1), AnnualWage = 100_000 });

    // A thin squad plus some good free-agent bowlers.
    for (int i = 0; i < 9; i++) { var b = MatchTestData.MakePlayer($"Bat{i}", 12); b.CurrentTeamId = club.Id; club.SquadPlayerIds.Add(b.Id); world.Players.Add(b); }
    for (int i = 0; i < 4; i++)
    {
        var fa = MatchTestData.MakePlayer($"FA{i}", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        fa.CurrentTeamId = null; fa.Nationality = "England";
        world.Players.Add(fa);
    }

    var events = svc.RunMonthly(world, new DateOnly(2026, 7, 1), new Random(2)).ToList();

    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.PlayerSigned), "a free agent was signed");
    TestRunner.IsTrue(club.SquadPlayerIds.Count(id => world.Players.First(p => p.Id == id).CurrentTeamId == club.Id) > 9, "the squad grew");
    TestRunner.IsTrue(world.PlayerContracts.Count(c => c.TeamId == club.Id) >= 2, "a new contract was created");
});

TestRunner.Run("9.3: player valuation - contract length remaining is the dominant lever, and a release clause is a hard ceiling", () =>
{
    var svc = new CricketManager.Domain.Services.PlayerValuationService();
    var p = MatchTestData.MakePlayer("Star", 17);
    p.DateOfBirth = new DateOnly(1999, 1, 1); // 27
    p.Reputation.Adjust(50, 30, 10);
    var asOf = new DateOnly(2026, 6, 1);

    var longDeal = new CricketManager.Domain.Entities.PlayerContract { PlayerId = p.Id, TeamId = Guid.NewGuid(), StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2030, 6, 1) };
    var shortDeal = new CricketManager.Domain.Entities.PlayerContract { PlayerId = p.Id, TeamId = Guid.NewGuid(), StartDate = new DateOnly(2023, 1, 1), EndDate = new DateOnly(2027, 3, 1) };

    double onLong = svc.EstimateValue(p, longDeal, asOf);
    double onShort = svc.EstimateValue(p, shortDeal, asOf);
    TestRunner.IsTrue(onLong > onShort * 1.6, $"the same player is worth far more on a long deal ({onLong:N0}) than a short one ({onShort:N0})");

    var withClause = new CricketManager.Domain.Entities.PlayerContract { PlayerId = p.Id, TeamId = Guid.NewGuid(), StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2030, 6, 1), ReleaseClauseValue = onLong * 0.4 };
    double capped = svc.EstimateValue(p, withClause, asOf);
    TestRunner.IsTrue(capped <= onLong * 0.4 + 1, $"the release clause caps the value ({capped:N0} <= {onLong * 0.4:N0})");
});

TestRunner.Run("9.3: a transfer moves a fee from buyer to seller, the player switches squads, and nothing happens outside a window", () =>
{
    CricketManager.Domain.Services.TransferMarketService Svc() => new();

    (WorldState World, Team Buyer, Team Seller, Player Target) Setup()
    {
        var buyer = new Team { Name = "Rich", Country = "England", Strength = 78 };
        buyer.Reputation.Adjust(45); buyer.Board.SeasonBudget = 20_000_000; buyer.Board.Ambition = 90; buyer.Finances.Budget = 15_000_000;
        var seller = new Team { Name = "Selling", Country = "England", Strength = 48 };
        var world = new WorldState { Teams = new Dictionary<Guid, Team> { [buyer.Id] = buyer, [seller.Id] = seller }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };
        var comp = new Competition { Name = "L", Format = MatchFormat.T20 };
        var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
        season.ParticipatingTeamIds.Add(buyer.Id); season.ParticipatingTeamIds.Add(seller.Id);
        world.Competitions.Add(comp); world.CompetitionSeasons.Add(season);

        for (int i = 0; i < 12; i++) { var b = MatchTestData.MakePlayer($"B{i}", 12); b.CurrentTeamId = buyer.Id; buyer.SquadPlayerIds.Add(b.Id); world.Players.Add(b);
            world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract { PlayerId = b.Id, TeamId = buyer.Id, StartDate = new DateOnly(2025,1,1), EndDate = new DateOnly(2028,1,1), AnnualWage = 120_000 }); }
        for (int i = 0; i < 14; i++) { var s = MatchTestData.MakePlayer($"S{i}", 11, PlayerRole.Bowler, BowlingRoleType.OpeningBowler); s.CurrentTeamId = seller.Id; seller.SquadPlayerIds.Add(s.Id); world.Players.Add(s);
            world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract { PlayerId = s.Id, TeamId = seller.Id, StartDate = new DateOnly(2025,1,1), EndDate = new DateOnly(2028,1,1), AnnualWage = 90_000 }); }

        // A clear upgrade target at the selling club, and he wants to go.
        var target = MatchTestData.MakePlayer("Wanted", 17, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
        target.CurrentTeamId = seller.Id; seller.SquadPlayerIds.Add(target.Id); world.Players.Add(target);
        target.SquadStatus = SquadStatus.Fringe; target.TransferRequested = true;
        world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract { PlayerId = target.Id, TeamId = seller.Id, StartDate = new DateOnly(2025,1,1), EndDate = new DateOnly(2029,1,1), AnnualWage = 150_000 });
        return (world, buyer, seller, target);
    }

    // Outside a window: nothing.
    var s1 = Setup();
    var outside = Svc().RunWindow(s1.World, new DateOnly(2026, 3, 1), new Random(1)).ToList();
    TestRunner.AreEqual(0, outside.Count(e => e.Type == GameEventType.PlayerTransferred), "no transfers outside a window");

    // Inside a window: the deal goes through, money moves.
    var s2 = Setup();
    double buyerBefore = s2.Buyer.Finances.Budget, sellerBefore = s2.Seller.Finances.Budget;
    var inside = Svc().RunWindow(s2.World, new DateOnly(2026, 7, 1), new Random(5)).ToList();
    TestRunner.IsTrue(inside.Any(e => e.Type == GameEventType.PlayerTransferred && e.SubjectId == s2.Target.Id)
        || s2.Target.CurrentTeamId == s2.Buyer.Id, "the wanted player moved");
    if (s2.Target.CurrentTeamId == s2.Buyer.Id)
    {
        TestRunner.IsTrue(s2.Buyer.Finances.Budget < buyerBefore, "the buyer paid a fee");
        TestRunner.IsTrue(s2.Seller.Finances.Budget > sellerBefore, "the seller banked it");
        TestRunner.IsTrue(s2.Buyer.SquadPlayerIds.Contains(s2.Target.Id) && !s2.Seller.SquadPlayerIds.Contains(s2.Target.Id), "he switched squads");
    }
});

TestRunner.Run("9.3: a release clause lets a buyer force a deal the selling club would have refused", () =>
{
    int Moved(bool withClause)
    {
        int moved = 0;
        for (int t = 0; t < 60; t++)
        {
            var buyer = new Team { Name = "Rich", Country = "England", Strength = 80 };
            buyer.Reputation.Adjust(50); buyer.Board.SeasonBudget = 40_000_000; buyer.Board.Ambition = 95; buyer.Finances.Budget = 30_000_000; buyer.Board.TransferBudgetShare = 0.6;
            var seller = new Team { Name = "Sell", Country = "England", Strength = 60 };
            var world = new WorldState { Teams = new Dictionary<Guid, Team> { [buyer.Id] = buyer, [seller.Id] = seller }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };
            var comp = new Competition { Name = "L", Format = MatchFormat.T20 };
            var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
            season.ParticipatingTeamIds.Add(buyer.Id); season.ParticipatingTeamIds.Add(seller.Id);
            world.Competitions.Add(comp); world.CompetitionSeasons.Add(season);
            // The buyer has a full batting line-up but no front-line seam - a genuine gap the star fills.
            for (int i = 0; i < 12; i++) { var b = MatchTestData.MakePlayer($"B{i}", 12); b.CurrentTeamId = buyer.Id; buyer.SquadPlayerIds.Add(b.Id); world.Players.Add(b); }

            var star = MatchTestData.MakePlayer("Star", 18, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
            star.CurrentTeamId = seller.Id; seller.SquadPlayerIds.Add(star.Id); world.Players.Add(star);
            star.SquadStatus = SquadStatus.FirstChoice; // the club would NOT normally sell
            for (int i = 0; i < 14; i++) { var s = MatchTestData.MakePlayer($"S{i}", 12); s.CurrentTeamId = seller.Id; seller.SquadPlayerIds.Add(s.Id); world.Players.Add(s); }
            var c = new CricketManager.Domain.Entities.PlayerContract { PlayerId = star.Id, TeamId = seller.Id, StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2030, 1, 1), AnnualWage = 400_000 };
            if (withClause) c.ReleaseClauseValue = 3_000_000;
            world.PlayerContracts.Add(c);

            new CricketManager.Domain.Services.TransferMarketService().RunWindow(world, new DateOnly(2026, 7, 1), new Random(t)).ToList();
            if (star.CurrentTeamId == buyer.Id) moved++;
        }
        return moved;
    }

    int noClause = Moved(false);
    int clause = Moved(true);
    TestRunner.IsTrue(clause > noClause + 10, $"the release clause forces far more deals through ({clause} vs {noClause} of 60)");
});

TestRunner.Run("9.4: a buried, ambitious fringe player hands in a transfer request; a settled first-choice does not", () =>
{
    var svc = new CricketManager.Domain.Services.TransferRequestService();
    int Requests(SquadStatus status, PersonalityTrait personality)
    {
        int filed = 0;
        for (int t = 0; t < 120; t++)
        {
            var team = new Team { Name = "C", Country = "England" };
            var p = MatchTestData.MakePlayer("P", 13);
            p.DateOfBirth = new DateOnly(2001, 1, 1); // 25
            p.SquadStatus = status; p.Personality = personality;
            p.CurrentTeamId = team.Id; team.SquadPlayerIds.Add(p.Id);
            var world = new WorldState { Teams = new Dictionary<Guid, Team> { [team.Id] = team }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player> { p }, Projects = new List<InfrastructureProject>() };
            world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract { PlayerId = p.Id, TeamId = team.Id, StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2028, 1, 1), AnnualWage = 100_000 });
            world.RecordAppearance(Guid.NewGuid()); // populate the tracker so "0 games" reads as real
            for (int y = 0; y < 4; y++)
            {
                foreach (var ev in svc.RunQuarterly(world, new DateOnly(2026, 1 + y * 3, 1), new Random(t * 10 + y)))
                    if (ev.Type == GameEventType.TransferRequestFiled) filed++;
            }
        }
        return filed;
    }

    int buriedAmbitious = Requests(SquadStatus.Fringe, PersonalityTrait.Ambitious);
    int happyStar = Requests(SquadStatus.FirstChoice, PersonalityTrait.Loyal);
    TestRunner.IsTrue(buriedAmbitious > 10, $"the buried ambitious fringe player agitates to leave ({buriedAmbitious})");
    TestRunner.AreEqual(0, happyStar, "a settled first-choice never does");
});

TestRunner.Run("9.5: the franchise auction fills squads within a purse, respects the overseas roster cap, and produces marquee-buy news", () =>
{
    var seeder = new WorldSeeder(seed: 951, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "India" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);

    var franchiseComp = world.Competitions.First(c => c.IsFranchiseAuctionLeague);
    var franchiseSeason = world.CompetitionSeasons.First(s => s.CompetitionId == franchiseComp.Id);
    var events = new CricketManager.Domain.Services.FranchiseAuctionService()
        .RunAuction(world, franchiseComp, franchiseSeason, new DateOnly(2026, 3, 20), new Random(3)).ToList();

    var franchiseIds = franchiseSeason.ParticipatingTeamIds.ToHashSet();
    var franchises = iw.FranchiseTeams.Where(f => franchiseIds.Contains(f.Id)).ToList();
    TestRunner.IsTrue(franchises.All(f => f.SquadPlayerIds.Count >= 11), $"every franchise has a playable squad ({string.Join(",", franchises.Select(f => f.SquadPlayerIds.Count))})");
    double purse = 14_000_000 * Math.Clamp(world.MarketIndex, 0.5, 6.0);
    foreach (var f in franchises)
    {
        int overseas = f.SquadPlayerIds.Count(id => !string.Equals(world.Players.First(p => p.Id == id).Nationality, franchiseComp.Country, StringComparison.OrdinalIgnoreCase));
        TestRunner.IsTrue(overseas <= franchiseComp.OverseasSquadLimit + 1, $"{f.Name} is within the overseas roster cap ({overseas})");
        double spend = world.PlayerContracts.Where(c => c.Kind == CricketManager.Domain.Enums.ContractKind.Franchise && c.TeamId == f.Id).Sum(c => c.AnnualWage);
        TestRunner.IsTrue(spend <= purse * 1.25, $"{f.Name} broadly stayed within its purse ({spend:N0} vs {purse:N0})");
    }
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.PlayerAuctioned), "marquee-buy news was produced");
    // Every auctioned player has a franchise contract but keeps his domestic registration.
    var anySold = franchises.SelectMany(f => f.SquadPlayerIds).First();
    TestRunner.IsTrue(world.Players.First(p => p.Id == anySold).CurrentTeamId is not null
        && !franchises.Any(f => f.Id == world.Players.First(p => p.Id == anySold).CurrentTeamId),
        "an auctioned player keeps his domestic club as his registration");
});

TestRunner.Run("9.5: OverseasRegistrationService trims an XI to the overseas cap and flags the bumped players", () =>
{
    var svc = new CricketManager.Domain.Services.OverseasRegistrationService();
    var order = new List<Player>();
    for (int i = 0; i < 6; i++) { var p = MatchTestData.MakePlayer($"OS{i}", 14); p.Nationality = "Overseas"; order.Add(p); }
    for (int i = 0; i < 5; i++) { var p = MatchTestData.MakePlayer($"H{i}", 13); p.Nationality = "Host"; order.Add(p); }
    var squad = order.ToList();
    for (int i = 0; i < 4; i++) { var p = MatchTestData.MakePlayer($"HBench{i}", 12); p.Nationality = "Host"; squad.Add(p); }

    var xi = new CricketManager.Domain.Services.XiSelectionResult(order, order.Where(p => p.BowlingRole != BowlingRoleType.NotABowler).ToList(), null, false, new List<string>());
    var corrected = svc.EnforceLimit(xi, squad, "Host", 4, MatchFormat.T20);

    int overseasNow = corrected.BattingOrder.Count(p => p.Nationality == "Overseas");
    TestRunner.IsTrue(overseasNow <= 4, $"the XI is within the 4-overseas cap ({overseasNow})");
    TestRunner.AreEqual(11, corrected.BattingOrder.Count, "still eleven");
    TestRunner.IsTrue(squad.Count(p => p.NonInjuryUnavailability == UnavailabilityReason.Unregistered) >= 2, "the bumped players are flagged Unregistered");
    CricketManager.Domain.Services.OverseasRegistrationService.ClearFixtureFlags(squad);
    TestRunner.AreEqual(0, squad.Count(p => p.NonInjuryUnavailability == UnavailabilityReason.Unregistered), "and the flags clear afterwards");
});

TestRunner.Run("9.6: a loan now carries real terms - a fee and wage split move money - and an obligation to buy completes a permanent transfer", () =>
{
    var loans = new CricketManager.Domain.Services.LoanService();
    var big = new Team { Name = "Big", Country = "England", Strength = 82 };
    var small = new Team { Name = "Small", Country = "England", Strength = 42 };
    small.Board.SeasonBudget = 8_000_000; small.Finances.Budget = 4_000_000;
    var world = new WorldState { Teams = new Dictionary<Guid, Team> { [big.Id] = big, [small.Id] = small }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player>(), Projects = new List<InfrastructureProject>() };

    for (int i = 0; i < 17; i++) { var p = MatchTestData.MakePlayer($"Big{i}", 15); p.CurrentTeamId = big.Id; big.SquadPlayerIds.Add(p.Id); world.Players.Add(p); }
    for (int i = 0; i < 12; i++) { var p = MatchTestData.MakePlayer($"Sm{i}", 8); p.CurrentTeamId = small.Id; small.SquadPlayerIds.Add(p.Id); world.Players.Add(p); }
    var kid = MatchTestData.MakePlayer("Kid", 10, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    kid.DateOfBirth = new DateOnly(2007, 1, 1); kid.CurrentAbility = 95; kid.PotentialAbility = 170;
    kid.SquadStatus = SquadStatus.DevelopmentProspect;
    kid.CurrentTeamId = big.Id; big.SquadPlayerIds.Add(kid.Id); world.Players.Add(kid);
    world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract { PlayerId = kid.Id, TeamId = big.Id, StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2029, 1, 1), AnnualWage = 60_000 });

    double smallBefore = small.Finances.Budget, bigBefore = big.Finances.Budget;
    loans.ConsiderLoans(world, big, new DateOnly(2026, 6, 1), new Random(3)).ToList();

    TestRunner.IsTrue(kid.CurrentLoan is not null, "a loan agreement with terms exists");
    TestRunner.IsTrue(small.Finances.Budget < smallBefore && big.Finances.Budget > bigBefore, "the loan fee + wage lump moved from the borrower to the parent");

    // Force an obligation to buy and run the return.
    kid.CurrentLoan!.BuyFee = 1_500_000; kid.CurrentLoan.IsObligationToBuy = true;
    for (int i = 0; i < 8; i++) world.RecordAppearance(kid.Id);
    var back = loans.ProcessReturns(world, kid.LoanReturnDate!.Value).ToList();

    TestRunner.IsTrue(back.Any(e => e.Type == GameEventType.PlayerTransferred), "the obligation triggered a permanent transfer");
    TestRunner.AreEqual(small.Id, kid.CurrentTeamId, "he now belongs to the loan club");
    TestRunner.IsTrue(kid.CurrentLoan is null && kid.ParentClubId is null, "the loan is fully closed out");
});

TestRunner.Run("9.7: a one-club servant gets a loyalty bonus at ten years and a testimonial near the end of his career", () =>
{
    var svc = new CricketManager.Domain.Services.PlayerContractService();
    var team = new Team { Name = "Home", Country = "England" };
    team.Reputation.Adjust(30);
    var servant = MatchTestData.MakePlayer("Loyal", 15);
    servant.DateOfBirth = new DateOnly(1990, 1, 1); // 36
    servant.CurrentTeamId = team.Id; team.SquadPlayerIds.Add(servant.Id);
    var world = new WorldState { Teams = new Dictionary<Guid, Team> { [team.Id] = team }, Grounds = new Dictionary<Guid, Ground>(), Players = new List<Player> { servant }, Projects = new List<InfrastructureProject>() };
    var c = new CricketManager.Domain.Entities.PlayerContract { PlayerId = servant.Id, TeamId = team.Id, StartDate = new DateOnly(2011, 1, 1), EndDate = new DateOnly(2028, 1, 1), AnnualWage = 300_000, IsHomegrown = true, Status = ContractStatus.Active };
    world.PlayerContracts.Add(c);

    double budgetBefore = team.Finances.Budget;
    var events = svc.ProcessLoyaltyRewards(world, new DateOnly(2026, 1, 1)).ToList();

