TestRunner.Run("9.8: a training camp develops a young player and lifts squad cohesion; a franchise-committed player is excused from the national camp", () =>
{
    var seeder = new WorldSeeder(seed: 981, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "India" }, teamsPerCountry: 3, squadSize: 14, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);
    foreach (var np in iw.NationalPools) world.NationalPools.Add(np);

    // Give a national-pool player a franchise contract for the franchise league whose window
    // overlaps the club/international pre-season.
    var franchiseComp = world.Competitions.First(c => c.IsFranchiseAuctionLeague);
    var natTeam = world.Teams.Values.First(t => t.IsNational);
    var poolPlayer = world.Players.First(p => natTeam.SquadPlayerIds.Contains(p.Id));
    world.PlayerContracts.Add(new CricketManager.Domain.Entities.PlayerContract
    {
        PlayerId = poolPlayer.Id, TeamId = iw.FranchiseTeams[0].Id, Kind = CricketManager.Domain.Enums.ContractKind.Franchise,
        CompetitionId = franchiseComp.Id, StartDate = new DateOnly(2026, 3, 1), EndDate = new DateOnly(2026, 5, 20), Status = ContractStatus.Active
    });

    var camps = new CricketManager.Domain.Services.TrainingCampService();
    var events = new List<GameEvent>();
    // Run across the pre-season months so every camp window is hit.
    for (int m = 1; m <= 6; m++)
        events.AddRange(camps.RunCamps(world, new DateOnly(2026, m, 10), new Random(m)));

    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.TrainingCampCallUp), "camps ran");
    // The franchise-committed player was excused from at least one national/club camp.
    TestRunner.IsTrue(events.Any(e => e.Headline.Contains("excused on franchise duty")),
        $"a franchise commitment excuses a player from an overlapping national camp");
});

await TestRunner.RunAsync("Phase 9 integration: a seeded world runs a real market over six years - contracts renew and lapse, free agents and transfers move players and money, the franchise auction runs yearly, and the market inflates", async () =>
{
    await Task.CompletedTask;
    var seeder = new WorldSeeder(seed: 99123, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
    foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
    foreach (var p in iw.NationalPools) world.NationalPools.Add(p);
    foreach (var u in iw.Umpires) world.Umpires.Add(u);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);

    double indexStart = world.MarketIndex;
    var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 99123), world, new DateOnly(2032, 3, 1));

    TestRunner.IsTrue(events.Count(e => e.Type == GameEventType.PlayerContractRenewed) >= 5, "contracts were renewed");
    TestRunner.IsTrue(events.Count(e => e.Type == GameEventType.PlayerBecameFreeAgent) >= 3, "some contracts lapsed to free agency");
    TestRunner.IsTrue(events.Count(e => e.Type == GameEventType.PlayerSigned) >= 2, "free agents were signed");
    int market = events.Count(e => e.Type is GameEventType.PlayerTransferred or GameEventType.PlayerAuctioned);
    TestRunner.IsTrue(market >= 5, $"the market moved players ({market} transfers/auctions)");
    TestRunner.IsTrue(events.Count(e => e.Headline.Contains("auction is complete")) >= 4, "the franchise auction ran most years");
    TestRunner.IsTrue(world.MarketIndex > indexStart * 1.08, $"the market has inflated ({indexStart:F2} -> {world.MarketIndex:F2})");

    var franchiseSeasonsDone = world.CompetitionSeasons.Count(s => s.IsCompleted
        && world.Competitions.First(c => c.Id == s.CompetitionId).IsFranchiseAuctionLeague);
    TestRunner.IsTrue(franchiseSeasonsDone >= 3, $"franchise seasons were played to a finish ({franchiseSeasonsDone})");

    int active = world.Players.Count(p => !p.IsRetired);
    TestRunner.IsTrue(active > world.Players.Count / 3, $"the world is still healthy ({active}/{world.Players.Count})");
    // Every active senior squad player has a contract.
    int missing = world.Teams.Values.Where(t => !t.IsNational && !t.IsFranchise)
        .SelectMany(t => t.SquadPlayerIds)
        .Count(id => world.Players.FirstOrDefault(p => p.Id == id) is { IsRetired: false, AcademyTeamId: null }
                     && CricketManager.Domain.Services.PlayerContractService.ActiveDomesticContract(world, id) is null);
    TestRunner.IsTrue(missing <= 5, $"almost every senior squad player is under contract ({missing} gaps)");
});

await TestRunner.RunAsync("Phase 9: the market is deterministic - the same seed produces the same world twice", async () =>
{
    await Task.CompletedTask;
    (int Players, int Contracts, int FreeAgents, double Index, int Events) Run()
    {
        var seeder = new WorldSeeder(seed: 20261101, worldStartDate: new DateOnly(2026, 1, 1));
        var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia" }, teamsPerCountry: 3, squadSize: 14, seasonYear: 2026);
        var world = new WorldState
        {
            Teams = iw.Teams.ToDictionary(t => t.Id),
            Grounds = iw.Grounds.ToDictionary(g => g.Id),
            Players = iw.Players.ToList(),
            Projects = new List<InfrastructureProject>(),
        };
        foreach (var c in iw.Competitions) world.Competitions.Add(c);
        foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
        foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
        foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
        foreach (var p in iw.NationalPools) world.NationalPools.Add(p);
        foreach (var u in iw.Umpires) world.Umpires.Add(u);
        foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);
        var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 20261101), world, new DateOnly(2031, 3, 1));
        return (world.Players.Count, world.PlayerContracts.Count(c => c.Status == ContractStatus.Active),
                world.Players.Count(p => p.CurrentTeamId is null && !p.IsRetired), Math.Round(world.MarketIndex, 4), events.Count);
    }

    var a = Run();
    var b = Run();
    TestRunner.AreEqual(a.Players, b.Players, "same player count");
    TestRunner.AreEqual(a.Contracts, b.Contracts, "same active-contract count");
    TestRunner.AreEqual(a.FreeAgents, b.FreeAgents, "same free-agent count");
    TestRunner.AreEqual(a.Index, b.Index, "same market index");
    TestRunner.AreEqual(a.Events, b.Events, "same event stream length");
});

