TestRunner.Run("Rectification A: the code of conduct is four levels, fines are a % of the match fee, and 4 demerit points in 24 months triggers a suspension", () =>
{
    var svc = new DisciplineService();
    var world = EmptyWorld();
    var player = MatchTestData.MakePlayer("Hothead", 12);
    player.Mental.Professionalism = 3;
    player.Personality = PersonalityTrait.Aggressive | PersonalityTrait.RiskTaker;
    world.Players.Add(player);
    var team = new Team { Name = "Rovers" }; team.Finances.Budget = 5_000_000;
    world.Teams[team.Id] = team;

    // Feed the four-level roller many matches; count what comes out.
    var levels = new List<int>();
    for (int i = 0; i < 4000; i++)
    {
        var before = player.DemeritLog.Count;
        foreach (var e in svc.ReviewMatch(world, new DateOnly(2026, 6, 1).AddDays(i / 20), MatchFormat.T20,
            team, team, new List<Player>(), new List<Player>(), new List<Player> { player }, new List<Player>(),
            null, null, 60, new Random(i)))
        {
            if (e.Type == GameEventType.DisciplinaryAction && e.Headline.Contains("Level "))
                levels.Add(int.Parse(e.Headline.Split("Level ")[1][0].ToString()));
        }
    }
    TestRunner.IsTrue(levels.Count(l => l == 1) > levels.Count(l => l == 2), "Level 1 is the most common charge");
    TestRunner.IsTrue(levels.Contains(3) && levels.Contains(4), "Level 3 and Level 4 charges both occur, rarely");
    TestRunner.IsTrue(player.DemeritLog.Count > 0 && player.SuspendedUntil is not null, "enough charges eventually produce a real suspension");
    TestRunner.AreEqual(4, DisciplineService.SuspensionThreshold, "the suspension threshold is 4 (the real ICC value), not 8");
});

TestRunner.Run("Rectification A: demerit points age out of a rolling 24-month window", () =>
{
    var p = MatchTestData.MakePlayer("X", 10);
    p.DemeritLog.Add(new DemeritEntry(new DateOnly(2026, 1, 1), 3, 2, "old"));
    p.DemeritLog.Add(new DemeritEntry(new DateOnly(2028, 6, 1), 2, 1, "recent"));
    TestRunner.AreEqual(2, p.DemeritPointsIn(new DateOnly(2028, 7, 1)), "a charge more than 24 months old no longer counts");
    TestRunner.AreEqual(5, p.DemeritPointsIn(new DateOnly(2027, 1, 1)), "inside the window, all charges count");
});

TestRunner.Run("Rectification A: a head coach can be charged at a press conference for a badly-handled confrontational answer", () =>
{
