});

TestRunner.Run("Rectification A: umpire career stats accumulate by format and a genuinely inaccurate umpire loses reputation", () =>
{
    var svc = new UmpireService();
    var weak = new Umpire { FirstName = "Weak", LastName = "Call", Accuracy = 5, Consistency = 5, LbwJudgement = 5, Composure = 5, Panel = UmpirePanel.International, MatchesOfficiated = 40, Reputation = 62, DateOfBirth = new DateOnly(1978, 1, 1) };

    double before = weak.Reputation;
    for (int i = 0; i < 80; i++)
        svc.ReviewMatch(new List<Umpire> { weak }, new Dictionary<DismissalType, int> { [DismissalType.LBW] = 4, [DismissalType.CaughtBehind] = 3 }, i % 3 == 0, 70, new Random(i), MatchFormat.Test);
    TestRunner.IsTrue(weak.MatchesByFormat.GetValueOrDefault(MatchFormat.Test) == 80, "matches-by-format is tracked");
    TestRunner.IsTrue(weak.CareerMarginalCalls > 20 && weak.CareerHowlers > 0, "marginal calls and howlers accumulate");
    TestRunner.IsTrue(weak.Reputation < before, $"an inaccurate umpire's reputation falls ({before:F0} -> {weak.Reputation:F0})");

    var panel = new List<Umpire> { weak };
    svc.SeasonReview(panel, new DateOnly(2027, 1, 1), new Random(1));
    TestRunner.IsTrue(weak.CareerAccuracy < 90, "career accuracy reflects the howler rate");
});

TestRunner.Run("Rectification G: franchise retention respects the caps (<=6, <=5 capped, <=2 uncapped) and unused slots become RTM cards", () =>
{
    var world = EmptyWorld();
    var comp = new Competition { Name = "Test League", Scope = CompetitionScope.FranchiseLeague };
    var franchise = new Team { Name = "Riders", IsFranchise = true };
    franchise.Board.Ambition = 100;
    world.Teams[franchise.Id] = franchise;

    for (int i = 0; i < 12; i++)
    {
        var p = MatchTestData.MakePlayer($"Star{i}", 16);
        p.Nationality = "Testland";
        if (i < 8) for (int m = 0; m < 40; m++) p.Experience.RecordAppearance(MatchFormat.T20, new DateOnly(2024, 1, 1), isInternational: true);
        p.Reputation = new Reputation(domestic: 70, continental: 45, worldwide: 30);
        world.Players.Add(p);
        franchise.SquadPlayerIds.Add(p.Id);
    }

    var outcome = new FranchiseRetentionService().RunRetention(world, comp, franchise, new DateOnly(2026, 1, 1), croreEquiv: 100_000, startingPurse: 14_000_000, new Random(7));
    TestRunner.IsTrue(outcome.Retained.Count <= FranchiseRetentionService.MaxRetentions, $"at most 6 retained ({outcome.Retained.Count})");
    TestRunner.IsTrue(outcome.Retained.Count(id => FranchiseRetentionService.IsCapped(world.Players.First(p => p.Id == id))) <= FranchiseRetentionService.MaxCappedRetentions, "at most 5 capped");
    TestRunner.AreEqual(FranchiseRetentionService.MaxRetentions - outcome.Retained.Count, outcome.RtmCards, "unused retention slots become RTM cards");
    TestRunner.IsTrue(outcome.RtmEligible.Count == 12 - outcome.Retained.Count, "the non-retained former squad are RTM-eligible");
});

