    TestRunner.IsTrue(iw.CountryProfiles.Values.Any(p => p.DomesticStructure == DomesticStructureModel.BoardControlledRegions)
                      && iw.CountryProfiles.Values.Any(p => p.DomesticStructure == DomesticStructureModel.ClubMembership),
                      "both ownership models are represented");
