TestRunner.Run("Rectification F: a full mega auction fills every franchise to a playable squad, within purse, honouring the overseas squad cap, deterministically", () =>
{
    (List<int> Sizes, List<double> Spends, int Lots) Run(int seed)
    {
        var seeder = new WorldSeeder(seed: 700, worldStartDate: new DateOnly(2026, 1, 1));
        var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England", "India" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
        var world = new WorldState { Teams = iw.Teams.ToDictionary(t => t.Id), Grounds = iw.Grounds.ToDictionary(g => g.Id), Players = iw.Players.ToList(), Projects = new List<InfrastructureProject>(), CountryProfiles = iw.CountryProfiles };
        foreach (var c in iw.Competitions) world.Competitions.Add(c);
        foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
        foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);

        var comp = world.Competitions.First(c => c.IsFranchiseAuctionLeague);
        var season = world.CompetitionSeasons.First(s => s.CompetitionId == comp.Id);
        var summary = new FranchiseAuctionService().RunAuctionDetailed(world, comp, season, new DateOnly(2026, 3, 20), new Random(seed));

        var fIds = season.ParticipatingTeamIds.ToHashSet();
        var franchises = world.Teams.Values.Where(t => fIds.Contains(t.Id)).OrderBy(t => t.Name).ToList();
        double purse = 14_000_000 * Math.Clamp(world.MarketIndex, 0.5, 6.0) * world.ProfileFor(comp.Country).EconomicScale;
        foreach (var f in franchises)
        {
            TestRunner.IsTrue(f.SquadPlayerIds.Count >= 12, $"{f.Name} reached a playable squad ({f.SquadPlayerIds.Count})");
            int overseas = f.SquadPlayerIds.Count(id => !string.Equals(world.Players.First(p => p.Id == id).Nationality, comp.Country, StringComparison.OrdinalIgnoreCase));
            TestRunner.IsTrue(overseas <= comp.OverseasSquadLimit, $"{f.Name} within the overseas squad cap ({overseas})");
            double spend = world.PlayerContracts.Where(c => c.Kind == ContractKind.Franchise && c.TeamId == f.Id).Sum(c => c.AnnualWage);
            TestRunner.IsTrue(spend <= purse * 1.35, $"{f.Name} within purse ({spend:N0} / {purse:N0})");
        }
        TestRunner.AreEqual(AuctionMode.Mega, summary.Mode, "the first auction is a mega auction");
        TestRunner.IsTrue(summary.ShortlistPlayerIds.Count >= franchises.Count * 10, "the shortlist scales with the number of franchises");
        return (franchises.Select(f => f.SquadPlayerIds.Count).ToList(), franchises.Select(f => world.PlayerContracts.Where(c => c.Kind == ContractKind.Franchise && c.TeamId == f.Id).Sum(c => c.AnnualWage)).ToList(), summary.Lots.Count);
    }

    var a = Run(11);
    var b = Run(11);
    TestRunner.AreEqual(string.Join(",", a.Sizes), string.Join(",", b.Sizes), "same seed - identical squad sizes");
    TestRunner.AreEqual(string.Join(",", a.Spends.Select(x => Math.Round(x))), string.Join(",", b.Spends.Select(x => Math.Round(x))), "same seed - identical spend");
    TestRunner.AreEqual(a.Lots, b.Lots, "same seed - identical lot count");
});

TestRunner.Run("Rectification F: base prices come only from the fixed brackets, and a fading player self-selects a lower one", () =>
{
    var seeder = new WorldSeeder(seed: 88, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England", "India" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
    var world = new WorldState { Teams = iw.Teams.ToDictionary(t => t.Id), Grounds = iw.Grounds.ToDictionary(g => g.Id), Players = iw.Players.ToList(), Projects = new List<InfrastructureProject>(), CountryProfiles = iw.CountryProfiles };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);
    var comp = world.Competitions.First(c => c.IsFranchiseAuctionLeague);
    var season = world.CompetitionSeasons.First(s => s.CompetitionId == comp.Id);

    var summary = new FranchiseAuctionService().RunAuctionDetailed(world, comp, season, new DateOnly(2026, 3, 20), new Random(5));
    double cr = 14_000_000 * Math.Clamp(world.MarketIndex, 0.5, 6.0) * world.ProfileFor(comp.Country).EconomicScale / 120.0;
    var validBrackets = new[] { 0.30, 0.40, 0.50, 0.75, 1.0, 1.25, 1.5, 2.0 }.Select(x => Math.Round(x * cr)).ToHashSet();
    TestRunner.IsTrue(summary.Lots.All(l => validBrackets.Contains(Math.Round(l.BasePrice))), "every base price is one of the eight fixed brackets");
});

TestRunner.Run("Correction 3: a franchise coach is a year-round multi-year appointment - hired before the auction, kept through the off-season, a foreign national coach not taken", () =>
{
    var world = EmptyWorld();
    var franchiseComp = new Competition { Name = "FL", Scope = CompetitionScope.FranchiseLeague, IsFranchiseAuctionLeague = true, Country = "Hostland", Prestige = 60, Window = CompetitionWindow.Annual(4, 1, 5, 15) };
    var season = new CompetitionSeason { CompetitionId = franchiseComp.Id, Year = 2026 };
    var f1 = new Team { Name = "AF", IsFranchise = true, Finances = new TeamFinances { Budget = 50_000_000 } };
    world.Teams[f1.Id] = f1;
    season.ParticipatingTeamIds.Add(f1.Id);
    world.Competitions.Add(franchiseComp);
    world.CompetitionSeasons.Add(season);

    var natTeam = new Team { Name = "Nation", IsNational = true, Country = "Elsewhere" };
    world.Teams[natTeam.Id] = natTeam;
    var natCoach = new Coach { FirstName = "Nat", LastName = "Boss", CurrentTeamId = natTeam.Id };
    var freeCoach = new Coach { FirstName = "Free", LastName = "Lance" };
    world.Coaches.Add(natCoach);
    world.Coaches.Add(freeCoach);

    var svc = new FranchiseCoachService();
    svc.EnsureCoachInPost(world, franchiseComp, season, new DateOnly(2026, 3, 1), new Random(1)).ToList();
    TestRunner.IsTrue(f1.CurrentCoachId is not null, "the franchise got a head coach before the auction");
    TestRunner.IsTrue(f1.CurrentCoachId != natCoach.Id, "a foreign national-team coach was not taken");
    var hired = world.Coaches.First(c => c.Id == f1.CurrentCoachId);
    TestRunner.IsTrue(hired.FranchiseCoachingTeamId == f1.Id, "he is recorded as the franchise's coach");
    TestRunner.IsTrue(world.CoachingContracts.Any(k => k.CoachId == hired.Id && k.TeamId == f1.Id && k.Status == ContractStatus.Active && k.EndDate > new DateOnly(2027, 1, 1)),
        "on a real multi-year contract");

    // The end-of-campaign review keeps him in post (year-round) - not released.
    season.Complete(f1.Id); // champions - no sack risk
    svc.ReviewAfterCampaign(world, franchiseComp, new DateOnly(2026, 5, 15), new Random(2)).ToList();
    TestRunner.IsTrue(f1.CurrentCoachId == hired.Id, "the coach stays in post through the off-season");

    // A second call before the next auction keeps the incumbent - no needless re-hire.
    var before = f1.CurrentCoachId;
    svc.EnsureCoachInPost(world, franchiseComp, season, new DateOnly(2027, 3, 1), new Random(3)).ToList();
    TestRunner.AreEqual(before, f1.CurrentCoachId, "the incumbent is kept for the next auction");

    // A national coach of the HOST country can take the franchise job; a foreign one cannot.
    var hostNatTeam = new Team { Name = "Hosts", IsNational = true, Country = "Hostland" };
    world.Teams[hostNatTeam.Id] = hostNatTeam;
    var hostNatCoach = new Coach { FirstName = "Home", LastName = "Coach", CurrentTeamId = hostNatTeam.Id };
    TestRunner.IsTrue(svc.IsAvailableFor(world, hostNatCoach, franchiseComp), "a national coach of the host country IS available for that country's franchise league");
    TestRunner.IsTrue(!svc.IsAvailableFor(world, natCoach, franchiseComp), "a foreign national coach is not");
});

