await TestRunner.RunAsync("Rectification integration: a seeded world runs through a franchise window - the auction fills squads, year-round franchise coaches are in post, and the league plays out", async () =>
{
    await Task.CompletedTask;
    var seeder = new WorldSeeder(seed: 246810, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England", "India" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
