TestRunner.Run("Follow-up: no franchise ever closes a season at a loss - the central pool + floor guarantee it", () =>
{
    var (world, iw) = SeedFollowUpWorld();
    var comp = world.Competitions.First(c => c.IsFranchiseAuctionLeague);
    var season = world.CompetitionSeasons.First(s => s.CompetitionId == comp.Id);

    // Run the auction so purses are genuinely spent, then drive every franchise's budget deep negative.
    new FranchiseAuctionService().RunAuction(world, comp, season, new DateOnly(2026, 3, 20), new Random(4)).ToList();
    var franchises = world.Teams.Values.Where(t => season.ParticipatingTeamIds.Contains(t.Id)).ToList();
    foreach (var f in franchises) f.Finances.Budget = -25_000_000;
    // A finished season.
    season.Complete(franchises[0].Id, franchises[1].Id);

    var settlements = new FranchiseFinanceService().SettleSeason(world, comp, season, new DateOnly(2026, 5, 20));
    TestRunner.IsTrue(settlements.Count == franchises.Count, "a settlement per franchise");
    foreach (var f in franchises)
        TestRunner.IsTrue(f.Finances.Budget >= FranchiseFinanceService.ReserveFloor, $"{f.Name} closes above the reserve floor ({f.Finances.Budget:N0})");
    TestRunner.IsTrue(settlements.All(s => s.Event.Type == GameEventType.FranchiseFinancesSettled), "a settlement news item per franchise");
});

