TestRunner.Run("Follow-up: a transfer-listed player's agent turns interest into a bidding contest, and takes a cut", () =>
{
    var (world, iw) = SeedFollowUpWorld(seed: 771);
    var star = world.Players
        .Where(p => p.CurrentTeamId is not null && !p.IsRetired && p.PrimaryRole == PlayerRole.Batsman && !WorldSeeder.AssociateNations.Contains(p.Nationality))
        .OrderByDescending(SquadNeeds.OverallScore).Skip(3).First();
    star.TransferRequested = true;
    star.TransferListed = true;
    star.SquadStatus = SquadStatus.SecondChoice;
    star.Reputation = new Reputation(domestic: 70, continental: 48, worldwide: 30);
    var oldClub = world.Teams[star.CurrentTeamId!.Value];
    var group = SquadNeeds.Groups().First(g => g.Matches(star));

    // Open a genuine gap at his position at every OTHER domestic club, with deep pockets, so
    // there is a real contest.
    foreach (var club in world.Teams.Values.Where(t => !t.IsNational && !t.IsFranchise && t.Id != oldClub.Id).ToList())
    {
        club.Board.SeasonBudget = 300_000_000;
        club.Finances.Budget = 150_000_000;
        club.Board.Ambition = 90;
        club.SquadPlayerIds.RemoveAll(id => world.Players.First(p => p.Id == id) is { } p && group.Matches(p));
    }

    var events = new List<GameEvent>();
    for (int q = 0; q < 6; q++)
        events.AddRange(new TransferMarketService().RunAgentBiddingWars(world, new DateOnly(2026, 1, 15).AddMonths(q * 3), new Random(q + 5)));

    bool moved = events.Any(e => e.Type == GameEventType.AgentBiddingWar) || star.CurrentTeamId != oldClub.Id;
    TestRunner.IsTrue(moved, "an agent bidding war moved a listed star");
});

