    (int Players, int Contracts, double Index, int Events) Run()
    {
        var (world, _) = SeedFollowUpWorld(seed: 13579, teamsPerCountry: 3, squad: 14);
        var events = new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 13579), world, new DateOnly(2029, 3, 1));
        return (world.Players.Count, world.PlayerContracts.Count(c => c.Status == ContractStatus.Active), Math.Round(world.MarketIndex, 4), events.Count);
    }
