    var b = Run();
    TestRunner.AreEqual(a.Players, b.Players, "same player count");
    TestRunner.AreEqual(a.Contracts, b.Contracts, "same active-contract count");
    TestRunner.AreEqual(a.Index, b.Index, "same market index");
    TestRunner.AreEqual(a.Events, b.Events, "same event stream length");
});

