TestRunner.Run("Post-P9: a match-winning chase innings rates well above the same innings in a dead rubber (MatchSituation)", () =>
{
    var rec = new PerformanceRecordingService();
    var innings = new BattingInningsRecord { PlayerId = Guid.NewGuid(), Runs = 74, BallsFaced = 52, Fours = 7, Sixes = 3, NotOut = true };

    double dead = rec.RateBattingInnings(innings, MatchFormat.T20,
        new MatchSituation(BaseImportance: 22, WasChase: false, TeamTotal: 205, TeamWicketsInHand: 8, MomentumForTeam: 0, MatchDecided: true, TeamWon: null));
    double clutch = rec.RateBattingInnings(innings, MatchFormat.T20,
        new MatchSituation(BaseImportance: 92, WasChase: true, TeamTotal: 168, TeamWicketsInHand: 4, MomentumForTeam: 45, MatchDecided: true, TeamWon: true));
    double blunt = rec.RateBattingInnings(innings, MatchFormat.T20);

    TestRunner.IsTrue(clutch > dead + 8, $"A final-winning chase knock ({clutch:F1}) outranks the same runs in a dead game ({dead:F1})");
    TestRunner.IsTrue(blunt > 0 && Math.Abs(blunt - dead) < 25, "The no-situation fallback stays close to the ordinary reading");
});

TestRunner.Run("Post-P9: a spell that seals a low-total defence rates above the same figures in a dead rubber", () =>
{
    var rec = new PerformanceRecordingService();
    var spell = new BowlingSpellRecord { PlayerId = Guid.NewGuid(), OversBowled = 4, RunsConceded = 24, Wickets = 3 };

    double dead = rec.RateBowlingSpell(spell, MatchFormat.T20,
        new MatchSituation(BaseImportance: 20, WasChase: false, WicketsTakenByTeam: 6, MatchDecided: true, TeamWon: null));
    double decisive = rec.RateBowlingSpell(spell, MatchFormat.T20,
        new MatchSituation(BaseImportance: 88, WasChase: true, WicketsTakenByTeam: 8, MomentumForTeam: 30, MatchDecided: true, TeamWon: true));

    TestRunner.IsTrue(decisive > dead + 4, $"Winning a tense defence ({decisive:F1}) is worth more than the same 3-for in a dead game ({dead:F1})");
});

TestRunner.Run("Post-P9: AiTacticalPlanner - no plan for a threadbare side, a real delegated plan with an analyst", () =>
{
    var planner = new AiTacticalPlanner();
    var (ourXi, _) = MatchTestData.MakeEleven("Us", 12, 12);
    var (oppXi, _) = MatchTestData.MakeEleven("Them", 12, 12);

    // Threadbare: a weak-reading captain, no analyst.
    ourXi[0].Mental.DecisionMaking = 3; ourXi[0].Mental.GameAwareness = 3; ourXi[0].Mental.Composure = 3;
    var side = new Team { Name = "Us" };
    side.SetCaptain(MatchFormat.T20, ourXi[0].Id);
    var opp = new Team { Name = "Them" };
    var world = EmptyWorld();

    var noPlan = planner.BuildPlan(world, side, ourXi, opp, oppXi, null, MatchFormat.T20, importance: 50, new Random(1));
    TestRunner.IsTrue(noPlan is null, "A side with no analyst and a captain who cannot read a game gets no plan");

    // Same side, now with a strong analyst on the books.
    var analyst = new StaffMember { FirstName = "Sharp", LastName = "Eyes", Role = StaffRole.Analyst, Analysis = 18, Statistics = 18, TechnicalKnowledge = 17, Communication = 16, Diligence = 17, YearsExperience = 8 };
    world.Staff.Add(analyst);
    side.StaffIds.Add(analyst.Id);

    var plan = planner.BuildPlan(world, side, ourXi, opp, oppXi, null, MatchFormat.T20, importance: 80, new Random(1));
    TestRunner.IsTrue(plan is not null, "With an analyst there is a real plan");
    TestRunner.AreEqual(DecisionAuthority.Delegated, plan!.DefaultAuthority, "An AI plan leaves the calls with the captain");
    TestRunner.AreEqual(BowlingIntent.Attacking, plan.TeamBowlingIntent, "A big occasion sharpens the bowling intent");
});

