// ==================== PHASE 10 - WORLD SIMULATION & INTERNATIONAL CRICKET ====================

TestRunner.Run("Phase 10: country profiles carry a talent / home-conditions layer, and it shapes academy intake + pitches", () =>
{
    var seeder = new WorldSeeder(seed: 101, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "India", "Australia", "England" }, teamsPerCountry: 3, squadSize: 14, seasonYear: 2026);

    var india = iw.CountryProfiles["India"];
    var australia = iw.CountryProfiles["Australia"];
    TestRunner.IsTrue(india.TalentProduction > australia.TalentProduction, "India produces more cricketers");
    TestRunner.IsTrue(india.PaceVsSpinTalentBias < 45 && australia.PaceVsSpinTalentBias > 55, "India leans spin, Australia leans pace");
    TestRunner.IsTrue(india.HomePitchSpinBias > 5 && australia.HomePitchSpinBias <= 0, "India's spin bias is positive, Australia's is not");

    double indianSpin = iw.Grounds.Where(g => g.Country == "India").Average(g => g.PitchSpinRating);
    double aussieSpin = iw.Grounds.Where(g => g.Country == "Australia").Average(g => g.PitchSpinRating);
    TestRunner.IsTrue(indianSpin > aussieSpin + 8, $"Indian pitches turn more than Australian ones ({indianSpin:F0} vs {aussieSpin:F0})");

    // Cohort role mix: India's cohorts skew toward spin, Australia's toward pace.
    var acad = new AcademyService();
    int indSpin = 0, indPace = 0, ausSpin = 0, ausPace = 0;
    for (int i = 0; i < 40; i++)
    {
        foreach (var p in acad.GenerateIntake(iw.Teams.First(t => t.Country == "India" && !t.IsNational), null, new DateOnly(2026, 1, 1), new Random(i), 60, india))
            { if (p.BowlingStyle.ToString().Contains("Spin") || p.BowlingStyle.ToString().Contains("Orthodox") || p.BowlingStyle.ToString().Contains("Chinaman")) indSpin++; else if (p.PrimaryRole == PlayerRole.Bowler) indPace++; }
        foreach (var p in acad.GenerateIntake(iw.Teams.First(t => t.Country == "Australia" && !t.IsNational), null, new DateOnly(2026, 1, 1), new Random(i), 60, australia))
            { if (p.BowlingStyle.ToString().Contains("Spin") || p.BowlingStyle.ToString().Contains("Orthodox") || p.BowlingStyle.ToString().Contains("Chinaman")) ausSpin++; else if (p.PrimaryRole == PlayerRole.Bowler) ausPace++; }
    }
    TestRunner.IsTrue(indSpin > ausSpin, $"India's academies produce more spinners ({indSpin} vs {ausSpin})");
    TestRunner.IsTrue(ausPace > indPace, $"Australia's academies produce more quicks ({ausPace} vs {indPace})");
});

