TestRunner.Run("Phase 11: SelectionMeetingService - a weak political panel produces a thin rationale, a strong one does not", () =>
{
    var (squad, _) = MatchTestData.MakeEleven("S", 12, 12);
    var extra = new List<Player>();
    for (int i = 0; i < 6; i++) extra.Add(MatchTestData.MakePlayer($"Sub{i}", 8 + i % 3));
    var pool = squad.Concat(extra).ToList();
    var svc = new SelectionMeetingService();

    var weakBoard = new Team { Name = "Weakland", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 35, Politicisation = 80 } };
    var strongBoard = new Team { Name = "Sharpland", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 88, Politicisation = 20 } };

    // Chosen squad: the 11 plus 4 subs - and deliberately leave out the best-ranked sub while
    // including the weakest, to create a surprise/omission.
    var chosen = squad.Concat(extra.Take(4)).Select(p => p.Id).ToList();

    var weak = svc.Hold(weakBoard, MatchFormat.T20, chosen, pool, new DateOnly(2026, 6, 1));
    var strong = svc.Hold(strongBoard, MatchFormat.T20, chosen, pool, new DateOnly(2026, 6, 1));

    TestRunner.IsTrue(strong.MeetingQuality > weak.MeetingQuality + 15, $"the strong panel's meeting is more rigorous ({strong.MeetingQuality} vs {weak.MeetingQuality})");
    TestRunner.IsTrue(weak.DissentNote is not null, "the weak panel's rationale is flagged as thin");
    TestRunner.IsTrue(strong.SlotRationales.Count > 0 && strong.SlotRationales.All(r => !string.IsNullOrWhiteSpace(r.Rationale)), "the strong panel gives a real rationale per pick");
});

