TestRunner.Run("Phase 11: RunningCalling sets a floor under run-out risk", () =>
{
    var model = new BallOutcomeModel();
    Player Bat(int calling) { var p = MatchTestData.MakePlayer("B", 12); p.Mental.RunningCalling = calling; return p; }
    var bowler = MatchTestData.MakePlayer("Bowl", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);

    int RunOuts(int calling)
    {
        var s = Bat(calling); var ns = Bat(calling);
        var ctx = new BallContext { Striker = s, NonStriker = ns, Bowler = bowler, Format = MatchFormat.ODI, Phase = MatchPhase.MiddleOvers };
        var rng = new Random(7);
        int ro = 0;
        for (int i = 0; i < 40000; i++)
        {
            var o = model.SimulateBall(ctx, rng);
            if (o.IsWicket && o.Dismissal == DismissalType.RunOut) ro++;
        }
        return ro;
    }

    int good = RunOuts(18), poor = RunOuts(3);
    TestRunner.IsTrue(poor > good, $"two poor callers are run out more often than two sharp ones ({poor} vs {good})");
});

TestRunner.Run("Phase 11: AiTacticalPlanner - a stronger Test side leans to attack, a weaker one digs in", () =>
{
    var planner = new AiTacticalPlanner();
    var (strong, _) = MatchTestData.MakeEleven("Str", 17, 17);
    var (weak, _) = MatchTestData.MakeEleven("Wk", 8, 8);
    var world = EmptyWorld();
