    var strongTeam = new Team { Name = "Strong" }; strongTeam.SetCaptain(MatchFormat.Test, strong[0].Id); strongTeam.StaffIds.Add(analyst.Id);
    strong[0].Mental.DecisionMaking = 16; strong[0].Mental.GameAwareness = 16; strong[0].Mental.Composure = 16;
    var weakTeam = new Team { Name = "Weak" }; weakTeam.SetCaptain(MatchFormat.Test, weak[0].Id); weakTeam.StaffIds.Add(analyst.Id);
    weak[0].Mental.DecisionMaking = 16; weak[0].Mental.GameAwareness = 16; weak[0].Mental.Composure = 16;

    var strongPlan = planner.BuildPlan(world, strongTeam, strong, weakTeam, weak, null, MatchFormat.Test, importance: 80, new Random(1));
    var weakPlan = planner.BuildPlan(world, weakTeam, weak, strongTeam, strong, null, MatchFormat.Test, importance: 80, new Random(1));

    TestRunner.IsTrue(strongPlan is not null && weakPlan is not null, "both sides build a plan");
    TestRunner.AreEqual(BowlingIntent.Attacking, strongPlan!.TeamBowlingIntent, "the stronger side attacks with the ball to press for a win");
    TestRunner.AreEqual(BattingIntent.Anchoring, weakPlan!.TeamBattingIntent, "the weaker side digs in with the bat");
});

