await TestRunner.RunAsync("Phase 13: a sell-on clause pays a former club a share of a later fee, and player-trading P&L feeds the budget", async () =>
{
    await Task.CompletedTask;
    var w = EmptyWorld();
    var origin = new Team { Name = "Origin FC", Strength = 55 }; origin.Board.SeasonBudget = 5_000_000;
    var mid = new Team { Name = "Mid FC", Strength = 60 }; mid.Board.SeasonBudget = 20_000_000; mid.Finances.Budget = 20_000_000;
    var big = new Team { Name = "Big FC", Strength = 80 }; big.Board.SeasonBudget = 60_000_000; big.Finances.Budget = 80_000_000; big.Board.Ambition = 90;
    w.Teams[origin.Id] = origin; w.Teams[mid.Id] = mid; w.Teams[big.Id] = big;

    var star = MatchTestData.MakePlayer("Star", 16); star.CurrentTeamId = mid.Id; star.Reputation = new Reputation(72, 50, 40);
    star.TransferListed = true; star.TransferRequested = true; star.SquadStatus = SquadStatus.Backup;
    w.Players.Add(star); mid.SquadPlayerIds.Add(star.Id);
    // Big FC has a genuine batting gap - its squad is bowlers.
    for (int i = 0; i < 16; i++) { var p = MatchTestData.MakePlayer($"Big{i}", 7, i < 4 ? PlayerRole.Batsman : PlayerRole.Bowler, i < 4 ? BowlingRoleType.NotABowler : BowlingRoleType.OpeningBowler); p.CurrentTeamId = big.Id; w.Players.Add(p); big.SquadPlayerIds.Add(p.Id); }

    // Mid holds a contract with a sell-on owed to Origin.
    var contract = new PlayerContractService().Sign(w, star, mid, new DateOnly(2026, 1, 1), 400_000, years: 3);
    contract.SellOnPercentage = 20; contract.SellOnBeneficiaryTeamId = origin.Id;

    double originBefore = origin.Finances.Budget;
    var events = new List<GameEvent>();
    for (int m = 0; m < 4; m++)
        events.AddRange(new TransferMarketService().RunWindow(w, new DateOnly(2026, 6, 10).AddMonths(m), new Random(m + 3)));

    bool moved = star.CurrentTeamId != mid.Id;
    TestRunner.IsTrue(moved || events.Any(e => e.Type == GameEventType.PlayerTransferred), "the listed star was sold");
    if (moved)
    {
        TestRunner.IsTrue(origin.Finances.Budget > originBefore, "Origin FC banked a sell-on share");
        TestRunner.IsTrue(mid.PlayerTradingPnL > 0, "Mid FC's player-trading P&L is positive after the sale");
    }
});

