    var topAgent = world.Agents.OrderByDescending(a => a.Reputation).First();
    TestRunner.IsTrue(topAgent.WageDemandMultiplier > 1.1, $"a top agent pushes the wage demand up ({topAgent.WageDemandMultiplier:F2})");

    // Over a decade the market runs: agents pick up new clients as reputations rise, drop retirees,
    // and bank commission from the bidding wars they engineer.
    int clientsBefore = world.Agents.Sum(a => a.ClientPlayerIds.Count);
    new WorldClockService().AdvanceTo(new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 1301), world, new DateOnly(2036, 6, 1));
    int clientsAfter = world.Agents.Sum(a => a.ClientPlayerIds.Count);
    TestRunner.IsTrue(clientsAfter != clientsBefore || world.Agents.Any(a => a.CareerEarnings > 0),
        "agent rosters churn and/or agents earn commission as the market runs");
});

