// ==================== PHASE 15: Match Officiating, Conditions & Rare Events ====================

TestRunner.Run("Phase 15: DRS - a marginal given-out decision is reviewed, and a weak panel's ones come back", () =>
{
    var drs = new DecisionReviewService();
    var striker = MatchTestData.MakePlayer("Set", 14);   // ReviewJudgement 14 - a sharp reviewer
    var nonStriker = MatchTestData.MakePlayer("Partner", 13);

    int overturned = 0, struckDown = 0, notReviewed = 0, umpiresCall = 0;
    for (int seed = 0; seed < 400; seed++)
    {
        var state = new DrsInningsState { ReviewsLeft = 2 };
        var v = drs.ConsiderBattingReview(DismissalType.LBW, striker, nonStriker,
            wicketsFallen: 2, runsRequired: null, ballsRemaining: null, umpireOutBias: 1.18, state, new Random(seed));
        switch (v)
        {
            case ReviewVerdict.Overturned: overturned++; break;
            case ReviewVerdict.StruckDown: struckDown++; break;
            case ReviewVerdict.UmpiresCall: umpiresCall++; break;
            default: notReviewed++; break;
        }
    }
    TestRunner.IsTrue(overturned > 10, $"a weak panel's marginal calls come back on review ({overturned}/400)");
    TestRunner.IsTrue(struckDown > 10, $"and plenty of reviews are burned ({struckDown}/400)");
    TestRunner.IsTrue(notReviewed > 40, $"not every decision is reviewed ({notReviewed}/400)");

    // A run-out is never a DRS matter, and no reviews left = never reviewed.
    TestRunner.AreEqual(ReviewVerdict.NotReviewed,
        drs.ConsiderBattingReview(DismissalType.RunOut, striker, nonStriker, 2, null, null, 1.2, new DrsInningsState { ReviewsLeft = 2 }, new Random(1)));
    TestRunner.AreEqual(ReviewVerdict.NotReviewed,
        drs.ConsiderBattingReview(DismissalType.LBW, striker, nonStriker, 2, null, null, 1.2, new DrsInningsState { ReviewsLeft = 0 }, new Random(1)));
});

TestRunner.Run("Phase 15: DRS wired into an innings - counters move with reviews on, stay zero with reviews off", () =>
{
    var sim = new InningsSimulator();
    var idA = Guid.NewGuid(); var idB = Guid.NewGuid();

    InningsSetup MakeSetup(int batLevel, int bowlLevel, string tag)
    {
        var bat = MatchTestData.MakeEleven($"{tag}B", batLevel, 4);
        var field = MatchTestData.MakeEleven($"{tag}F", 4, bowlLevel);
        return new InningsSetup(bat.BattingOrder, field.BattingOrder, field.Bowlers);
    }

    // With DRS off, no review counter ever moves, on any seed.
    for (int seed = 0; seed < 8; seed++)
    {
        var st = sim.Simulate(MakeSetup(9, 14, "off"), MatchFormat.T20, 20, idA, "A", idB, "B", new Random(seed), umpireOutBias: 1.15, drsReviewsPerInnings: 0);
        TestRunner.AreEqual(0, st.DrsOverturns + st.DrsStruckDown + st.DrsUmpiresCall, "DRS off = no review activity");
    }

    // With DRS on and plenty of LBW/CB wickets (weak batting), reviews genuinely happen.
    int totalActivity = 0;
    for (int seed = 0; seed < 15; seed++)
    {
        var st = sim.Simulate(MakeSetup(8, 15, "on"), MatchFormat.T20, 20, idA, "A", idB, "B", new Random(seed), umpireOutBias: 1.2, drsReviewsPerInnings: 2);
        totalActivity += st.DrsOverturns + st.DrsStruckDown + st.DrsUmpiresCall;
    }
    TestRunner.IsTrue(totalActivity > 0, $"across 15 innings DRS was used at least once ({totalActivity})");

    // Deterministic.
    var a = sim.Simulate(MakeSetup(10, 13, "det"), MatchFormat.T20, 20, idA, "A", idB, "B", new Random(99), drsReviewsPerInnings: 2);
    var b = sim.Simulate(MakeSetup(10, 13, "det"), MatchFormat.T20, 20, idA, "A", idB, "B", new Random(99), drsReviewsPerInnings: 2);
    TestRunner.AreEqual(a.Runs, b.Runs, "same seed, same innings with DRS on");
    TestRunner.AreEqual(a.DrsOverturns, b.DrsOverturns, "same seed, same DRS outcomes");
});

TestRunner.Run("Phase 15: playing conditions default by scope, and a Super Over match still completes", () =>
{
    TestRunner.AreEqual(3, PlayingConditions.For(CompetitionScope.International, MatchFormat.Test).DrsReviewsPerInnings);
    TestRunner.AreEqual(2, PlayingConditions.For(CompetitionScope.International, MatchFormat.T20).DrsReviewsPerInnings);
    TestRunner.AreEqual(1, PlayingConditions.For(CompetitionScope.FranchiseLeague, MatchFormat.T20).DrsReviewsPerInnings);
    TestRunner.AreEqual(0, PlayingConditions.For(CompetitionScope.DomesticT20, MatchFormat.T20).DrsReviewsPerInnings);

    var sim = new MatchSimulator();
    int superOvers = 0, resolved = 0;
    for (int seed = 0; seed < 160; seed++)
    {
        var setup = new MatchSetup
        {
            Home = new MatchSide(Guid.NewGuid(), "H", MatchTestData.MakeEleven("H", 12, 12).BattingOrder, MatchTestData.MakeEleven("H", 12, 12).Bowlers),
            Away = new MatchSide(Guid.NewGuid(), "A", MatchTestData.MakeEleven("A", 12, 12).BattingOrder, MatchTestData.MakeEleven("A", 12, 12).Bowlers),
            Format = MatchFormat.T20, OversPerInnings = 20, MatchDate = new DateOnly(2026, 5, 1),
            ResolveTiesWithSuperOver = true
        };
        var m = sim.Simulate(setup, new Random(seed));
        if (m.SuperOverPlayed)
        {
            superOvers++;
            TestRunner.IsTrue(m.WinningTeamId is not null || m.Summary.Contains("also tied"), "a super over is resolved or explicitly still tied");
        }
        if (m.WinningTeamId is not null) resolved++;
    }
    TestRunner.IsTrue(resolved > 150, "the vast majority of matches have a winner");
    Console.WriteLine($"    (super overs played across 160 seeds: {superOvers})");
});

TestRunner.Run("Phase 15: umpire fatigue and a decider howler draw a board query", () =>
{
    var svc = new UmpireService();
    var tired = new Umpire { FirstName = "Weary", LastName = "One", Panel = UmpirePanel.International, Accuracy = 9, LbwJudgement = 8, Consistency = 8, Composure = 8, Reputation = 60, MatchesSinceBreak = 20 };
    var partner = new Umpire { FirstName = "Also", LastName = "Tired", Panel = UmpirePanel.International, Accuracy = 9, LbwJudgement = 8, Consistency = 8, Composure = 8, Reputation = 58, MatchesSinceBreak = 20 };
    var wickets = new Dictionary<DismissalType, int> { [DismissalType.LBW] = 6, [DismissalType.CaughtBehind] = 4 };

    int scrutinyCount = 0;
    for (int seed = 0; seed < 40; seed++)
    {
        var a = new Umpire { FirstName = "W", LastName = $"{seed}", Panel = UmpirePanel.International, Accuracy = 9, LbwJudgement = 8, Consistency = 8, Composure = 8, Reputation = 60, MatchesSinceBreak = 20 };
        var b = new Umpire { FirstName = "X", LastName = $"{seed}b", Panel = UmpirePanel.International, Accuracy = 9, LbwJudgement = 8, Consistency = 8, Composure = 8, Reputation = 58, MatchesSinceBreak = 20 };
        svc.ReviewMatch(new[] { a, b }, wickets, tightFinish: true, importance: 92, new Random(seed), MatchFormat.Test, new DateOnly(2026, 6, 1));
        if (a.UnderScrutinyUntil is not null || b.UnderScrutinyUntil is not null) scrutinyCount++;
        TestRunner.AreEqual(1, a.MatchesSinceBreak - 20, "MatchesSinceBreak ticks");
    }
    TestRunner.IsTrue(scrutinyCount > 0, $"a weak panel butchering a decider draws scrutiny ({scrutinyCount}/40)");

    // A scrutinised umpire is passed over for a big appointment when there is a clear alternative.
    var scrutinised = new Umpire { FirstName = "S", LastName = "Crut", Panel = UmpirePanel.Elite, Reputation = 90, UnderScrutinyUntil = new DateOnly(2026, 12, 1) };
    var clean1 = new Umpire { FirstName = "C1", LastName = "Lean", Panel = UmpirePanel.Elite, Reputation = 70 };
    var clean2 = new Umpire { FirstName = "C2", LastName = "Lean", Panel = UmpirePanel.Elite, Reputation = 68 };
    var clean3 = new Umpire { FirstName = "C3", LastName = "Lean", Panel = UmpirePanel.Elite, Reputation = 66 };
    var picked = svc.AssignPanel(new[] { scrutinised, clean1, clean2, clean3 }, isInternational: true, isKnockout: true, importance: 90, "X", "Y", new Random(3), new DateOnly(2026, 8, 1));
    TestRunner.IsTrue(!picked.Take(2).Any(u => u.Id == scrutinised.Id), "the scrutinised umpire is left off the final");

    // The off-season clears both the fatigue clock and an expired query.
    var panel = new List<Umpire> { scrutinised, clean1 };
    scrutinised.UnderScrutinyUntil = new DateOnly(2025, 1, 1); // already past
    scrutinised.MatchesSinceBreak = 15;
    svc.SeasonReview(panel, new DateOnly(2026, 11, 1), new Random(1));
    TestRunner.AreEqual(0, scrutinised.MatchesSinceBreak, "the off-season resets the fatigue clock");
    TestRunner.IsTrue(scrutinised.UnderScrutinyUntil is null, "an expired board query lifts");
});

TestRunner.Run("Phase 15: the concussion protocol enforces a minimum stand-down", () =>
{
    var svc = new PlayerAvailabilityService();
    var p = MatchTestData.MakePlayer("Hit", 12);
    var date = new DateOnly(2026, 6, 10);

    svc.ApplyInjury(p, InjuryType.Concussion, InjurySeverity.Minor, date);
