    svc.ApplyInjury(q, InjuryType.Hamstring, InjurySeverity.Minor, date);
    TestRunner.IsTrue(q.ConcussionStandDownUntil is null, "an ordinary strain is not a concussion");
});

TestRunner.Run("Phase 15: conditions - pitch doctoring, drop-in pitches, wind and heat", () =>
{
    // A spin-strong home side vs a pace-oriented away side leans toward preparing a turner.
    int dry = 0, neutral = 0;
    for (int seed = 0; seed < 200; seed++)
    {
        var home = new Team { Name = "Spinners" };
        var homeXi = new List<Player>();
        for (int i = 0; i < 6; i++) { var b = MatchTestData.MakePlayer($"HB{i}", 13); b.Batting.AgainstSpin = 18; b.Batting.AgainstPace = 9; homeXi.Add(b); }
        homeXi.Add(MatchTestData.MakePlayer("HS1", 15, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner));
        homeXi.Add(MatchTestData.MakePlayer("HS2", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner));
        for (int i = 0; i < 3; i++) homeXi.Add(MatchTestData.MakePlayer($"HFill{i}", 8));
        var awayXi = new List<Player>();
        for (int i = 0; i < 7; i++) { var b = MatchTestData.MakePlayer($"AB{i}", 13); b.Batting.AgainstPace = 17; b.Batting.AgainstSpin = 9; awayXi.Add(b); }
        for (int i = 0; i < 4; i++) awayXi.Add(MatchTestData.MakePlayer($"AP{i}", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler));
        var g = new Ground { Name = "G", PitchSpinRating = 55, PitchPaceRating = 45 };
        var d = new PitchDoctoringService().Decide(home, homeXi, awayXi, g, new Random(seed));
        if (d == PitchPreparation.Dry) dry++;
        if (d == PitchPreparation.Neutral) neutral++;
    }
    TestRunner.IsTrue(dry > 20, $"a spin-strong home side often prepares a turner ({dry}/200)");
    TestRunner.IsTrue(neutral > 20, $"but not always - most matches are not doctored ({neutral}/200)");

    // A drop-in pitch wears more evenly - less day-5 spin, more batting ease.
    var mds = new MultiDayMatchSimulator();
    var side = MatchTestData.MakeEleven("S", 12, 12);
    MatchSide MS(string n) => new(Guid.NewGuid(), n, side.BattingOrder, side.Bowlers);
    var native = new Ground { Name = "Native", PitchSpinRating = 55, PitchWearRate = 55, UsesDropInPitch = false };
    var dropIn = new Ground { Name = "DropIn", PitchSpinRating = 55, PitchWearRate = 55, UsesDropInPitch = true };
    var d5native = mds.BuildPitch(new MultiDayMatchSetup { Home = MS("H"), Away = MS("A"), Ground = native }, 5);
    var d5drop = mds.BuildPitch(new MultiDayMatchSetup { Home = MS("H"), Away = MS("A"), Ground = dropIn }, 5);
    TestRunner.IsTrue(d5drop.BattingFriendliness > d5native.BattingFriendliness, "a drop-in holds its batting ease longer");
    TestRunner.IsTrue(d5drop.Spin < d5native.Spin, "and turns less by day five");

    // Wind and heat.
    TestRunner.IsTrue(new MatchWeather { WindSpeedKph = 35, CloudCover = 30 }.SwingBonus
                      > new MatchWeather { WindSpeedKph = 5, CloudCover = 30 }.SwingBonus, "a stiff wind helps the ball swing");
    TestRunner.IsTrue(new MatchWeather { TemperatureC = 42, Humidity = 25 }.IsExtremeHeat, "42C and dry is extreme heat");
    TestRunner.IsTrue(!new MatchWeather { TemperatureC = 30, Humidity = 40 }.IsExtremeHeat, "30C is not");
});

TestRunner.Run("Phase 15: a re-used strip is worn from ball one; a TV umpire makes tight run-outs marginally rarer", () =>
{
    var mds = new MultiDayMatchSimulator();
    var side = MatchTestData.MakeEleven("R", 12, 12);
    MatchSide MS(string n) => new(Guid.NewGuid(), n, side.BattingOrder, side.Bowlers);
    var g = new Ground { Name = "Reuse", PitchSpinRating = 45, PitchWearRate = 50 };
    var fresh = mds.BuildPitch(new MultiDayMatchSetup { Home = MS("H"), Away = MS("A"), Ground = g, PitchIsReused = false }, 1);
    var used = mds.BuildPitch(new MultiDayMatchSetup { Home = MS("H"), Away = MS("A"), Ground = g, PitchIsReused = true }, 1);
    TestRunner.IsTrue(used.Spin > fresh.Spin, "a re-used strip turns more from day one");
    TestRunner.IsTrue(used.BattingFriendliness < fresh.BattingFriendliness, "and is harder to bat on");
    TestRunner.IsTrue(used.Pace < fresh.Pace, "and has less pace");

    // Third umpire: run outs are a touch rarer over a big sample.
    int roWith = 0, roWithout = 0;
    var (order, bowlers) = MatchTestData.MakeEleven("T", 12, 12);
    for (int s = 0; s < 60; s++)
    {
        foreach (var third in new[] { true, false })
        {
            var setup = new InningsSetup(order, order, bowlers);
            var st = new InningsSimulator().Simulate(setup, MatchFormat.T20, 20,
                Guid.NewGuid(), "B", Guid.NewGuid(), "F", new Random(s),
                hasThirdUmpire: third);
            int ro = st.Deliveries.Count(d => d.Outcome.Dismissal == DismissalType.RunOut);
            if (third) roWith += ro; else roWithout += ro;
        }
    }
    TestRunner.IsTrue(roWith <= roWithout, $"a TV umpire overturns a few tight run-outs ({roWith} vs {roWithout})");
});

TestRunner.Run("Match-Engine Tactical Pass: ODI middle-overs read, partnership style fit, keeper-up stumpings, flaw frequency", () =>
{
    // §2.3: a side behind the rate with wickets in hand attacks the ODI middle overs.
    var state = new InningsState { Format = MatchFormat.ODI, Runs = 55, LegalBalls = 90, Wickets = 2, BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "B", BowlingTeamName = "F" }; // 15 overs, well behind 5.0/over pace
    var card = new BatterCard { PlayerId = Guid.NewGuid(), PlayerName = "X", BattingPosition = 3, BallsFaced = 20 };
    var intent = InningsSimulator.DetermineBattingIntent(state, card, MatchPhase.MiddleOvers);
    TestRunner.AreEqual(BattingIntent.Attacking, intent, "behind the rate with wickets in hand -> push on, not sit back");

    // §2.9: a complementary pairing (anchor + finisher) scores a shade more than two aggressive sloggers.
    var anchor = MatchTestData.MakePlayer("Anchor", 13); anchor.BattingTraits.Anchor = 80;
    var finisher = MatchTestData.MakePlayer("Finisher", 13); finisher.BattingTraits.Finisher = 80; finisher.BattingTraits.PowerHitter = 80;
    var slogger1 = MatchTestData.MakePlayer("Slog1", 13); slogger1.BattingTraits.Slogger = 80; slogger1.BattingTraits.PowerHitter = 80;
    var slogger2 = MatchTestData.MakePlayer("Slog2", 13); slogger2.BattingTraits.Slogger = 80; slogger2.BattingTraits.PowerHitter = 80;
    var bowlerP = MatchTestData.MakePlayer("Bwl", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    BallContext Ctx(Player striker, Player nonStriker) => new()
    {
        Striker = striker, Bowler = bowlerP, NonStriker = nonStriker, Format = MatchFormat.T20,
        Phase = MatchPhase.MiddleOvers, BattingIntent = BattingIntent.Normal, BowlingIntent = BowlingIntent.Balanced,
        PitchPace = 50, PitchSpin = 50, PitchBounce = 50, PitchBattingFriendliness = 50
    };
    var model = new BallOutcomeModel();
    double complementarySkill = model.CalculateProbabilities(Ctx(anchor, finisher)).ExpectedRuns;
    double bothAggroSkill = model.CalculateProbabilities(Ctx(slogger1, slogger2)).ExpectedRuns;
    TestRunner.IsTrue(complementarySkill >= bothAggroSkill, $"a complementary pairing edges out two batters playing the identical high-risk game ({complementarySkill:F3} vs {bothAggroSkill:F3})");

    // §2.14: a slow medium-pacer on a low, slow pitch opens up a real stumping weight; a spinner's is untouched.
    var mediumPacer = MatchTestData.MakePlayer("Medium", 10, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    mediumPacer.Bowling.Pace = 8;
    var slowLowPitch = new PitchConditions(50, 30, 30, 50);
    var delivery = new ExecutedDelivery(BowlingLine.LegStump, BowlingLength.Good, DeliveryVariation.None, 0.8, PlanDeviationReason.Followed);
    var weights = DeliveryEffectService.DismissalWeightsFor(delivery, MatchTestData.MakePlayer("Bat", 10), mediumPacer, slowLowPitch);
    TestRunner.IsTrue(weights[DismissalType.Stumped] > 0, "the keeper standing up to a genuine medium-pacer on a slow, low pitch is a real dismissal path");

    // §6.3: a technical flaw is exploited more when the delivery matches its shape.
    var flawed = MatchTestData.MakePlayer("Flawed", 12);
    flawed.TechnicalFlaw = TechnicalFlaw.FrontFootLbwProne;
    var matchingDelivery = new ExecutedDelivery(BowlingLine.AtTheStumps, BowlingLength.Full, DeliveryVariation.None, 0.8, PlanDeviationReason.Followed);
    var mismatchDelivery = matchingDelivery with { Line = BowlingLine.WideOutsideOff, Length = BowlingLength.Short };
    double SkillWith(ExecutedDelivery d) => new BallOutcomeModel().CalculateProbabilities(new BallContext
    {
        Striker = flawed, Bowler = bowlerP, Delivery = d, Format = MatchFormat.T20, Phase = MatchPhase.MiddleOvers,
        BattingIntent = BattingIntent.Normal, BowlingIntent = BowlingIntent.Balanced,
        PitchPace = 50, PitchSpin = 50, PitchBounce = 50, PitchBattingFriendliness = 50
    }).Wicket;
    TestRunner.IsTrue(SkillWith(matchingDelivery) > SkillWith(mismatchDelivery),
        "a delivery that matches the batter's own flaw genuinely raises his wicket chance over one that doesn't");
});

TestRunner.Run("Match-Engine Tactical Pass: two new balls (ODI), within-innings dew, an opposition-aware XI nudge", () =>
{
    // §1.5: two new balls in an ODI means the ball is never effectively older than ~150 balls -
    // a delivery at 200 and one at 150 read identically (isolated by holding Format fixed, since
    // the base wicket rate also differs by format and would otherwise confound the comparison).
    var quick = MatchTestData.MakePlayer("Quick", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var odiAt200 = new BallContext { Striker = MatchTestData.MakePlayer("B", 12), Bowler = quick, Format = MatchFormat.ODI, BallAge = 200, PitchPace = 50, PitchSpin = 50, PitchBounce = 50, PitchBattingFriendliness = 50, BattingIntent = BattingIntent.Normal, BowlingIntent = BowlingIntent.Balanced, Phase = MatchPhase.DeathOvers };
    var odiAt150 = odiAt200 with { BallAge = 150 };
    var testAt200 = odiAt200 with { Format = MatchFormat.Test };
    var testAt120 = testAt200 with { BallAge = 120 };
    var p200 = new BallOutcomeModel().CalculateProbabilities(odiAt200);
    var p150 = new BallOutcomeModel().CalculateProbabilities(odiAt150);
    TestRunner.AreEqual(p150.Wicket, p200.Wicket, "an ODI ball at 200 legal balls reads exactly like one at 150 - the two-new-balls cap");
    var pTest200 = new BallOutcomeModel().CalculateProbabilities(testAt200);
    var pTest120 = new BallOutcomeModel().CalculateProbabilities(testAt120);
    TestRunner.IsTrue(pTest200.Wicket != pTest120.Wicket, "a Test ball genuinely keeps ageing past 120 balls - no such cap there");

    // §1.6: a dewy night chase gets progressively easier for spin to concede as the innings goes on.
    // Paired same-seed comparison, but not pinned to one arbitrary seed - the deterministic
    // per-over pitch shift (see the dewFactor block in Simulate) still routes through a
    // stochastic ball model downstream, so a single seed can coincidentally land on an identical
    // aggregate Runs/Wickets even though the underlying conditions genuinely differed ball to
    // ball. At least one of a real spread of seeds must show it.
    var (order, bowlers) = MatchTestData.MakeEleven("D", 12, 12);
    var setup = new InningsSetup(order, order, bowlers);
    bool dewMadeADifference = false;
    for (int seed = 0; seed < 25 && !dewMadeADifference; seed++)
    {
        var early = new InningsSimulator().Simulate(setup, MatchFormat.ODI, 50, Guid.NewGuid(), "B", Guid.NewGuid(), "F", new Random(seed), dewFactor: 0.8);
        var noDew = new InningsSimulator().Simulate(setup, MatchFormat.ODI, 50, Guid.NewGuid(), "B", Guid.NewGuid(), "F", new Random(seed), dewFactor: 0);
        if (early.Runs != noDew.Runs || early.Wickets != noDew.Wickets) dewMadeADifference = true;
    }
    TestRunner.IsTrue(dewMadeADifference, "a dewy chase plays out differently from a dry one, across a real spread of seeds");

    // §3.3: an opposition top order that is almost entirely right-handed pulls in a left-arm option.
    var squad = new List<Player>();
    for (int i = 0; i < 6; i++) squad.Add(MatchTestData.MakePlayer($"Bat{i}", 13));
    squad.Add(MatchTestData.MakePlayer("Keeper", 12, PlayerRole.WicketKeeper));
    var rightArmSpin = MatchTestData.MakePlayer("RASpin", 11, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    var leftArmSpin = MatchTestData.MakePlayer("LASpin", 10, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    leftArmSpin.BowlingStyle = BowlingStyle.LeftArmOrthodox;
    squad.Add(rightArmSpin); squad.Add(leftArmSpin);
    for (int i = 0; i < 3; i++) squad.Add(MatchTestData.MakePlayer($"Seam{i}", 12, PlayerRole.Bowler, BowlingRoleType.OpeningBowler));
    var oppositionOrder = Enumerable.Range(0, 6).Select(i => { var p = MatchTestData.MakePlayer($"Opp{i}", 12); p.BattingHand = BattingHand.Right; return p; }).ToList<Player>();
    var xiSvc = new XiSelectionService();
    var withOpp = xiSvc.SelectXi(squad, MatchFormat.T20, new DateOnly(2026, 1, 1), oppositionBattingOrder: oppositionOrder);
    TestRunner.IsTrue(withOpp.Bowlers.Any(b => BallOutcomeModel.IsLeftArm(b.BowlingStyle)) || withOpp.Reasoning.Any(r => r.Contains("left-arm")),
        "facing an almost entirely right-handed top order pulls in a left-arm option when one is close in the squad");
});

TestRunner.Run("Match-Engine Tactical Pass (§3.4): the whole attack is used, not the same five bowlers every time", () =>
{
    var (order, bowlers) = MatchTestData.MakeEleven("W", 13, 12);
    var setup = new InningsSetup(order, order, bowlers);
    var overCounts = new Dictionary<Guid, int>();
    for (int s = 0; s < 15; s++)
    {
        var st = new InningsSimulator().Simulate(setup, MatchFormat.Test, 0, Guid.NewGuid(), "B", Guid.NewGuid(), "F", new Random(s));
        foreach (var c in st.BowlerCards)
            overCounts[c.PlayerId] = overCounts.GetValueOrDefault(c.PlayerId) + c.LegalBallsBowled;
    }
    int bowlersUsed = overCounts.Count(kv => kv.Value > 0);
    TestRunner.IsTrue(bowlersUsed >= 4, $"a Test innings uses a genuinely varied attack, not one or two bowlers ({bowlersUsed} used across 15 seeds)");
});

TestRunner.Run("Match-Engine Tactical Pass (§2.15): a sustained leg-theory barrage carries a real, deterministic conduct cost", () =>
{
    var w = EmptyWorld();
    var team = new Team { Name = "Quicks" }; w.Teams[team.Id] = team;
    var bowler = MatchTestData.MakePlayer("Enforcer", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    w.Players.Add(bowler);
    var svc = new DisciplineService();

    var under = svc.ReviewIntimidatoryBowling(w, new DateOnly(2026, 6, 1), MatchFormat.Test, team, bowler, legTheoryDeliveries: 12);
    TestRunner.IsTrue(under is null, "a few short balls at the body is just a tactic, not a charge");

    double budgetBefore = team.Finances.Budget;
    var over = svc.ReviewIntimidatoryBowling(w, new DateOnly(2026, 6, 1), MatchFormat.Test, team, bowler, legTheoryDeliveries: 20);
    TestRunner.IsTrue(over is { Type: GameEventType.DisciplinaryAction }, "a genuine sustained barrage draws a real Level 2 charge");
    TestRunner.IsTrue(over!.Headline.Contains("Level 2") && over.Headline.Contains("into-the-body"), $"named as intimidatory bowling: {over.Headline}");
    TestRunner.IsTrue(team.Finances.Budget < budgetBefore, "and a real fine is paid");
    TestRunner.AreEqual(3, bowler.DemeritPointsIn(new DateOnly(2026, 6, 1)), "three demerit points, matching a genuine Level 2 offence");

    // Deterministic - the exact same charge every time, for the exact same inputs (never perturbs
    // the shared match RNG). Two genuinely independent bowlers/worlds, not one reused mutable
    // player - reusing one would already carry demerit points into the second call.
    var team2a = new Team { Name = "Quicks2a" };
    var bowler2a = MatchTestData.MakePlayer("Enforcer2", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var w2a = EmptyWorld(); w2a.Teams[team2a.Id] = team2a; w2a.Players.Add(bowler2a);
    var repeat1 = svc.ReviewIntimidatoryBowling(w2a, new DateOnly(2026, 6, 1), MatchFormat.Test, team2a, bowler2a, legTheoryDeliveries: 20);

    var team2b = new Team { Name = "Quicks2b" };
    var bowler2b = MatchTestData.MakePlayer("Enforcer2", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var w2b = EmptyWorld(); w2b.Teams[team2b.Id] = team2b; w2b.Players.Add(bowler2b);
    var repeat2 = svc.ReviewIntimidatoryBowling(w2b, new DateOnly(2026, 6, 1), MatchFormat.Test, team2b, bowler2b, legTheoryDeliveries: 20);

    TestRunner.AreEqual(repeat1!.Headline.Replace(team2a.Name, "X"), repeat2!.Headline.Replace(team2b.Name, "X"),
        "identical inputs produce an identical charge every time - no RNG involved");
});

TestRunner.Run("Match-Engine Tactical Pass (§2.2): a spinner turning away from the bat draws a real extra slip", () =>
{
    var setter = new AutoFieldSetter();
    var (side, _) = MatchTestData.MakeEleven("Field", 13, 13);
    var offSpinner = MatchTestData.MakePlayer("Off", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    offSpinner.Bowling.Spin = 16; offSpinner.Bowling.Pace = 5;
    offSpinner.BowlingStyle = BowlingStyle.RightArmOffSpin;

    // Turning AWAY from a left-hander (the real threat) vs turning INTO a right-hander (no such threat).
    var vsLeft = setter.BuildField(side, offSpinner, MatchFormat.T20, MatchPhase.MiddleOvers, strikerHand: BattingHand.Left);
    var vsRight = setter.BuildField(side, offSpinner, MatchFormat.T20, MatchPhase.MiddleOvers, strikerHand: BattingHand.Right);
    TestRunner.IsTrue(vsLeft.CatchersBehindWicket > vsRight.CatchersBehindWicket,
        $"an off-spinner turning away from a left-hander draws a real slip a right-hander does not ({vsLeft.CatchersBehindWicket} vs {vsRight.CatchersBehindWicket})");

    // The mirror: a leg-spinner turns away from a RIGHT-hander instead.
    var legSpinner = MatchTestData.MakePlayer("Leg", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner);
    legSpinner.Bowling.Spin = 16; legSpinner.Bowling.Pace = 5;
    legSpinner.BowlingStyle = BowlingStyle.RightArmLegSpin;
    var legVsRight = setter.BuildField(side, legSpinner, MatchFormat.T20, MatchPhase.MiddleOvers, strikerHand: BattingHand.Right);
    var legVsLeft = setter.BuildField(side, legSpinner, MatchFormat.T20, MatchPhase.MiddleOvers, strikerHand: BattingHand.Left);
    TestRunner.IsTrue(legVsRight.CatchersBehindWicket > legVsLeft.CatchersBehindWicket,
        "a leg-spinner's mirror threat is against a right-hander, not a left-hander");

    // No hand supplied at all (the captain not reading the game, or every pre-§2.2 caller) - unaffected.
    var noHand = setter.BuildField(side, offSpinner, MatchFormat.T20, MatchPhase.MiddleOvers);
    TestRunner.AreEqual(vsRight.CatchersBehindWicket, noHand.CatchersBehindWicket, "no hand supplied reads exactly like the neutral case");
});

TestRunner.Run("Match-Engine Tactical Pass (§2.4/§2.5): declaration and the follow-on are captaincy calls, not just arithmetic", () =>
{
    // §2.4: a sharp captain declares on a thinner cushion than a callow one needs, buying more
    // overs to force the win; both still respect the hard floors (wickets, minimum overs).
    var state = new InningsState { Format = MatchFormat.Test, BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "B", BowlingTeamName = "F", Runs = 260, Wickets = 5, LegalBalls = 0 };
    int ballsLeft = 70 * 6; // 70 overs left - genuinely marginal for a declaration
    bool declaresSharp = InningsSimulator.ShouldDeclare(state, existingLead: 0, ballsLeftInMatch: ballsLeft, overNumber: 60, MatchFormat.Test, captainQuality: 1.0);
    bool declaresPoor = InningsSimulator.ShouldDeclare(state, existingLead: 0, ballsLeftInMatch: ballsLeft, overNumber: 60, MatchFormat.Test, captainQuality: 0.0);
    TestRunner.IsTrue(declaresSharp && !declaresPoor, "a sharp captain trusts a marginal lead a callow one waits past");

    // The neutral default (no captainQuality argument) reproduces the ORIGINAL, unscaled formula
    // exactly - byte-identical for every caller that predates §2.4.
    bool declaresNeutralA = InningsSimulator.ShouldDeclare(state, 0, ballsLeft, 60, MatchFormat.Test);
    bool declaresNeutralB = InningsSimulator.ShouldDeclare(state, 0, ballsLeft, 60, MatchFormat.Test, captainQuality: 0.5);
    TestRunner.AreEqual(declaresNeutralA, declaresNeutralB, "the omitted-argument default matches captainQuality: 0.5 exactly");

    // §2.5: the same "sharper captain reads the real signal more fully" shape for the follow-on,
    // in a genuinely marginal case (some time pressure, a pitch that offers a little turn).
    var mds = new MultiDayMatchSimulator();
    var ground = new Ground { Name = "G", PitchSpinRating = 58 };
    var setup = new MultiDayMatchSetup { Home = new MatchSide(Guid.NewGuid(), "H", new List<Player>(), new List<Player>()), Away = new MatchSide(Guid.NewGuid(), "A", new List<Player>(), new List<Player>()), Ground = ground, Days = 5 };
    int enforcedSharp = 0, enforcedPoor = 0;
    const int trials = 300;
    for (int s = 0; s < trials; s++)
    {
        if (mds.ShouldEnforceFollowOn(setup, ballsBowled: (int)(0.62 * 2700), totalBalls: 2700, lead: 215, new Random(s), captainQuality: 1.0)) enforcedSharp++;
        if (mds.ShouldEnforceFollowOn(setup, ballsBowled: (int)(0.62 * 2700), totalBalls: 2700, lead: 215, new Random(s), captainQuality: 0.0)) enforcedPoor++;
    }
    TestRunner.IsTrue(Math.Abs(enforcedSharp - enforcedPoor) > 10,
        $"captain quality genuinely moves the follow-on call in a marginal case ({enforcedSharp} vs {enforcedPoor} of {trials})");
});

TestRunner.Run("Phase 15 (§1.8): retired hurt on a genuinely bouncy pitch is not a dismissal", () =>
{
    // A quick, bouncy pitch and a striker who cannot handle the short ball at all - the exact
    // combination §1.8's deterministic trigger reads.
    var pitch = new PitchConditions(70, 40, 70, 45);
    bool retiredEverFired = false;
    for (int seed = 0; seed < 400 && !retiredEverFired; seed++)
    {
        var (order, bowlers) = MatchTestData.MakeEleven("RH", 12, 12);
        order[0].Batting.ShortBallAbility = 2; // a genuine bunny against the short ball
        var setup = new InningsSetup(order, order, bowlers);
        var st = new InningsSimulator().Simulate(setup, MatchFormat.T20, 20,
            Guid.NewGuid(), "B", Guid.NewGuid(), "F", new Random(seed), pitch: pitch);

        if (st.BatterCards.Any(c => c.Dismissal == DismissalType.Retired))
        {
            retiredEverFired = true;
            // The invariant the doc comment itself claims: a retired-hurt card is NOT counted
            // toward Wickets - only a genuine dismissal is.
            int genuineDismissals = st.BatterCards.Count(c => c.Dismissal is not DismissalType.NotOut and not DismissalType.Retired);
            TestRunner.AreEqual(genuineDismissals, st.Wickets, "retiring hurt does not increment the wicket count");
        }
    }
    TestRunner.IsTrue(retiredEverFired, "across enough seeds on a genuinely hostile pitch, retired hurt actually fires");
});

// ==================== PHASE 16: Records, Awards & Historical Flavour ====================

TestRunner.Run("Phase 16: the new record categories are tracked and broken", () =>
{
    var w = EmptyWorld();
    var batA = MatchTestData.MakePlayer("Sixer", 15); w.Players.Add(batA);
    var bowlA = MatchTestData.MakePlayer("Miser", 15, PlayerRole.Bowler, BowlingRoleType.OpeningBowler); w.Players.Add(bowlA);
    var svc = new RecordProgressionService();

    MatchRecords Rec(int sixes, int spellRuns)
    {
        var r = new MatchRecords();
        r.Batting.Add(new BattingInningsRecord { PlayerId = batA.Id, Runs = 90, BallsFaced = 45, Sixes = sixes });
        r.Bowling.Add(new BowlingSpellRecord { PlayerId = bowlA.Id, OversBowled = 10, RunsConceded = spellRuns, Wickets = 1 });
        return r;
    }

    var e1 = svc.ReviewMatch(w, Rec(6, 30), new DateOnly(2026, 6, 1));
    TestRunner.IsTrue(!e1.Any(e => e.Type == GameEventType.RecordBroken), "establishing a record is not news");
    TestRunner.IsTrue(w.RecordBook.ContainsKey($"{RecordCategory.MostSixesInInnings}|"), "the six-hitting record is now in the book");
    TestRunner.IsTrue(w.RecordBook.ContainsKey($"{RecordCategory.BestEconomyInInnings}|"), "so is the economy record");
    TestRunner.AreEqual(6.0, w.RecordBook[$"{RecordCategory.MostSixesInInnings}|"].Value, "the six record holds the right value");

    // A routine improvement updates the book silently (no archive spam); a DRAMATIC one is news.
    var e2 = svc.ReviewMatch(w, Rec(7, 20), new DateOnly(2027, 6, 1));
    TestRunner.AreEqual(7.0, w.RecordBook[$"{RecordCategory.MostSixesInInnings}|"].Value, "a routine improvement still updates the book");
    var e3 = svc.ReviewMatch(w, Rec(11, 8), new DateOnly(2028, 6, 1));
    TestRunner.IsTrue(e3.Any(e => e.Type == GameEventType.RecordBroken), "an 11-six innings and a sub-1-an-over spell are genuinely dramatic news");
});

TestRunner.Run("Phase 16: a big cap landmark gets a ceremony and a lift", () =>
{
    var w = EmptyWorld();
    var team = new Team { Name = "England", DressingRoomHarmony = 50 }; w.Teams[team.Id] = team;
    var vet = MatchTestData.MakePlayer("Servant", 14); vet.CurrentTeamId = team.Id; w.Players.Add(vet);

    var milestone = new GameEvent(new DateOnly(2026, 7, 1), GameEventType.PlayerMilestone,
        $"{vet.FullName} wins his 100th Test cap for England.", vet.Id);
    var ceremonies = new CeremonyService().Process(w, new[] { milestone }, new DateOnly(2026, 7, 1));

    TestRunner.IsTrue(ceremonies.Any(c => c.Type == GameEventType.MilestoneCeremony && c.Headline.Contains("guard of honour")),
        "the 100th cap gets a guard-of-honour ceremony");
    TestRunner.IsTrue(ceremonies[0].SubjectId == vet.Id, "attributed to the right player");

    // An ordinary landmark (a 25th cap) does not get the full ceremony.
    var small = new GameEvent(new DateOnly(2026, 7, 1), GameEventType.PlayerMilestone, $"{vet.FullName} wins his 25th Test cap for England.", vet.Id);
    TestRunner.IsTrue(new CeremonyService().Process(w, new[] { small }, new DateOnly(2026, 7, 1)).Count == 0, "a 25th cap is not a ceremony");
