TestRunner.Run("Phase 16: the pre-match report names a genuine personal hoodoo", () =>
{
    var bat = MatchTestData.MakePlayer("Bunny", 13);
    var bowl = MatchTestData.MakePlayer("Nemesis", 13, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    var mc = new MatchupConfidence();
    for (int i = 0; i < 6; i++) mc.RecordOutcome(-55);
    bat.Matchups[$"bowler:{bowl.Id}"] = mc;

    var duels = PreMatchReportService.KeyDuels(new[] { bat }, new[] { bowl });
    TestRunner.IsTrue(duels.Count > 0 && duels[0].Contains("bogey"), "a real, sampled hoodoo is surfaced");

