TestRunner.Run("Phase 16: a Team of the Era is named, and the talent cycle oscillates", () =>
{
    var w = EmptyWorld();
    for (int i = 0; i < 16; i++)
    {
        var p = MatchTestData.MakePlayer($"Great{i}", 15, i < 5 ? PlayerRole.Bowler : (i == 15 ? PlayerRole.WicketKeeper : PlayerRole.Batsman),
            i < 5 ? BowlingRoleType.OpeningBowler : BowlingRoleType.NotABowler);
        w.Players.Add(p);
        w.CareerStats[$"{p.Id}|Test"] = new PlayerCareerStats
        {
            PlayerId = p.Id, Format = MatchFormat.Test,
            Runs = i < 5 ? 800 : 6000 - i * 100, Wickets = i < 5 ? 300 - i * 20 : 5,
            Catches = i == 15 ? 200 : 30, Hundreds = i < 5 ? 0 : 18, FiveWicketHauls = i < 5 ? 15 : 0
        };
    }
    var ev = new AllTimeXiService().NameTeamOfEra(w, new DateOnly(2035, 1, 1), 5);
    TestRunner.IsTrue(ev is { Type: GameEventType.AllTimeXiNamed }, "a team of the era is named");
    TestRunner.IsTrue(ev!.Headline.Split(',').Length >= 10, "and it names an XI");

    // Era cycle: deterministic, and it genuinely rises and falls over its period.
    var profile = new CountryProfile { Nationality = "Testland", GenerationCyclePhase = 0.2 };
    double hi = double.MinValue, lo = double.MaxValue;
    for (int y = 2026; y < 2026 + 15; y++)
    {
        double f = AcademyService.EraQualityFactor(profile, y);
        hi = Math.Max(hi, f); lo = Math.Min(lo, f);
        TestRunner.AreEqual(f, AcademyService.EraQualityFactor(profile, y), "deterministic per year");
    }
    TestRunner.IsTrue(hi > 1.1 && lo < 0.9, $"the cycle has real peaks and troughs ({lo:F2}..{hi:F2})");
    TestRunner.AreEqual(1.0, AcademyService.EraQualityFactor(null, 2030), "no profile = a flat 1.0");
});

TestRunner.Run("Phase 16 (§20.4): the Team of the Era names a dominant team, a defining storyline, a pundit's dissent, and persists", () =>
{
    var w = EmptyWorld();
    var teamA = new Team { Name = "Dominators" }; w.Teams[teamA.Id] = teamA;
    var teamB = new Team { Name = "AlsoRans" }; w.Teams[teamB.Id] = teamB;
    var comp = new Competition { Name = "Era Cup" };

    // Dominators win 3 of 4 titles across the era window (2026-2035) - a real, checkable margin.
    for (int y = 2026; y < 2030; y++)
    {
        var s = new CompetitionSeason { CompetitionId = comp.Id, Year = y };
        s.GetOrCreateStanding(teamA.Id); s.GetOrCreateStanding(teamB.Id);
        s.Complete(y == 2028 ? teamB.Id : teamA.Id, y == 2028 ? teamA.Id : teamB.Id);
        w.CompetitionSeasons.Add(s);
    }

    // A defining storyline that ran during the era, more intense than nothing else on record.
    w.Storylines.Add(new Storyline
    {
        Kind = StorylineKind.DominantRun, SubjectId = teamA.Id, TeamId = teamA.Id,
        Started = new DateOnly(2027, 3, 1), LastUpdated = new DateOnly(2027, 6, 1), Intensity = 80,
        Summary = "Dominators go the whole season unbeaten"
    });

    // 16 players, so the panel has a real runner-up to dissent toward.
    for (int i = 0; i < 16; i++)
    {
        var p = MatchTestData.MakePlayer($"Great{i}", 15, i < 5 ? PlayerRole.Bowler : (i == 15 ? PlayerRole.WicketKeeper : PlayerRole.Batsman),
            i < 5 ? BowlingRoleType.OpeningBowler : BowlingRoleType.NotABowler);
        w.Players.Add(p);
        w.CareerStats[$"{p.Id}|Test"] = new PlayerCareerStats
        {
            PlayerId = p.Id, Format = MatchFormat.Test,
            Runs = i < 5 ? 800 : 6000 - i * 100, Wickets = i < 5 ? 300 - i * 20 : 5,
            Catches = i == 15 ? 200 : 30, Hundreds = i < 5 ? 0 : 18, FiveWicketHauls = i < 5 ? 15 : 0
        };
    }
    w.Pundits.Add(new Pundit("Old Pro", teamB.Id, null, "England", 0.9));

    var ev = new AllTimeXiService().NameTeamOfEra(w, new DateOnly(2035, 1, 1), 9);
    TestRunner.IsTrue(ev is { Type: GameEventType.AllTimeXiNamed }, "a team of the era is named");
    TestRunner.IsTrue(ev!.Headline.Contains("Dominators were the team of the era"), $"the clearly dominant team is named: {ev.Headline}");
    TestRunner.IsTrue(ev.Headline.Contains("defining story") && ev.Headline.Contains("unbeaten"), $"the most intense storyline of the era is quoted: {ev.Headline}");
    TestRunner.IsTrue(ev.Headline.Contains("Old Pro") && ev.Headline.Contains("disagrees"), $"a pundit's own dissenting vote is surfaced: {ev.Headline}");

    // §15.5: persisted, not just a news line that scrolls past.
    TestRunner.AreEqual(1, w.EraTeams.Count, "the era XI is persisted");
    var record = w.EraTeams[0];
    TestRunner.AreEqual(11, record.PlayerIds.Count, "with all eleven names");
    TestRunner.AreEqual(teamA.Id, record.DominantTeamId, "and the dominant team on record");
    TestRunner.IsTrue(record.DefiningStoryline is not null && record.DefiningStoryline.Contains("unbeaten"), "and the defining storyline on record");

    // No pundits, no dissent line - and no storylines/titles, no dominant-team/defining-story clauses.
    var w2 = EmptyWorld();
    for (int i = 0; i < 16; i++)
    {
        var p = MatchTestData.MakePlayer($"Great{i}", 15, i < 5 ? PlayerRole.Bowler : (i == 15 ? PlayerRole.WicketKeeper : PlayerRole.Batsman),
            i < 5 ? BowlingRoleType.OpeningBowler : BowlingRoleType.NotABowler);
        w2.Players.Add(p);
        w2.CareerStats[$"{p.Id}|Test"] = new PlayerCareerStats
        {
            PlayerId = p.Id, Format = MatchFormat.Test,
            Runs = i < 5 ? 800 : 6000 - i * 100, Wickets = i < 5 ? 300 - i * 20 : 5,
            Catches = i == 15 ? 200 : 30, Hundreds = i < 5 ? 0 : 18, FiveWicketHauls = i < 5 ? 15 : 0
        };
    }
    var ev2 = new AllTimeXiService().NameTeamOfEra(w2, new DateOnly(2035, 1, 1), 9);
    TestRunner.IsTrue(ev2 is not null && !ev2.Headline.Contains("team of the era") && !ev2.Headline.Contains("defining story") && !ev2.Headline.Contains("disagrees"),
        "with no titles, no storylines and no pundits, the headline stays to the XI alone");
});

TestRunner.Run("Phase 12 (§18.7): a genuine ground hoodoo becomes a live narrative storyline ahead of the return fixture", () =>
{
    var w = EmptyWorld();
    var ground = new Ground { Name = "The Furnace" }; w.Grounds[ground.Id] = ground;
    var team = new Team { Name = "Tourists" }; w.Teams[team.Id] = team;
    var bunny = MatchTestData.MakePlayer("Bunny", 13); bunny.CurrentTeamId = team.Id;
    team.SquadPlayerIds.Add(bunny.Id);
    w.Players.Add(bunny);

    var mc = new MatchupConfidence();
    for (int i = 0; i < 6; i++) mc.RecordOutcome(-60);
    bunny.Matchups[$"ground:{ground.Id}"] = mc;

    var comp = new Competition { Name = "Series" };
    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
    var fixture = new Fixture
    {
        CompetitionId = comp.Id, SeasonId = season.Id, HomeTeamId = team.Id, AwayTeamId = Guid.NewGuid(),
        GroundId = ground.Id, ScheduledDate = new DateOnly(2026, 6, 15)
    };
    w.Fixtures.Add(fixture);

    var events = new NarrativeService().ReviewMonthly(w, new DateOnly(2026, 6, 1)).ToList();
    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.NarrativeUpdate && e.Headline.Contains("Furnace") && e.Headline.Contains("hoodoo")),
        "the hoodoo becomes a live storyline as the return fixture approaches");
    TestRunner.IsTrue(w.Storylines.Any(s => s.Kind == StorylineKind.GroundHoodoo && s.SubjectId == bunny.Id),
        "recorded as a real, tracked storyline, not just a one-off line");

    // Reviewing again the same month does not duplicate the same live storyline.
    var again = new NarrativeService().ReviewMonthly(w, new DateOnly(2026, 6, 2)).ToList();
    TestRunner.IsTrue(!again.Any(e => e.Headline.Contains("Furnace")), "an already-live hoodoo storyline is not raised twice");

    // A fixture too far out (beyond the 21-day window) raises nothing yet.
    var w2 = EmptyWorld();
    var ground2 = new Ground { Name = "Elsewhere" }; w2.Grounds[ground2.Id] = ground2;
    var team2 = new Team { Name = "Tourists2" }; w2.Teams[team2.Id] = team2;
    var bunny2 = MatchTestData.MakePlayer("Bunny2", 13); bunny2.CurrentTeamId = team2.Id;
    team2.SquadPlayerIds.Add(bunny2.Id);
    w2.Players.Add(bunny2);
    bunny2.Matchups[$"ground:{ground2.Id}"] = mc;
    w2.Fixtures.Add(new Fixture { CompetitionId = comp.Id, SeasonId = season.Id, HomeTeamId = team2.Id, AwayTeamId = Guid.NewGuid(), GroundId = ground2.Id, ScheduledDate = new DateOnly(2026, 9, 1) });
    var farEvents = new NarrativeService().ReviewMonthly(w2, new DateOnly(2026, 6, 1)).ToList();
    TestRunner.IsTrue(!farEvents.Any(e => e.Headline.Contains("Elsewhere")), "a fixture three months out is not yet a live talking point");
});

