TestRunner.Run("Completion W1: coach attribute clamp (explicit list), margin bonus, holdout, hoodoo", () =>
{
    // Coach clamp still bounds every attribute 1-20.
    var coach = new Coach { FirstName = "C", LastName = "Lamp" };
    coach.Attributes.TacticalKnowledge = 99; coach.Attributes.Loyalty = -5;
    coach.SeedAttributesFromHistory();
    TestRunner.InRange(coach.Attributes.TacticalKnowledge, 1, 20, "clamped high");
    TestRunner.InRange(coach.Attributes.Loyalty, 1, 20, "clamped low");

    // A competition that opts in awards a limited-overs margin bonus.
    var comp = new Competition { Name = "Bonus Cup", Format = MatchFormat.T20, UsesLimitedOversMarginBonus = true };
    var (ho, hb) = MatchTestData.MakeEleven("Big", 17, 17);
    var (ao, ab) = MatchTestData.MakeEleven("Small", 5, 5);
    var setup = new MatchSetup
    {
        Home = new MatchSide(Guid.NewGuid(), "Big", ho, hb),
        Away = new MatchSide(Guid.NewGuid(), "Small", ao, ab),
        Format = MatchFormat.T20, OversPerInnings = 20, Competition = comp, MatchDate = new DateOnly(2026, 6, 1)
    };
    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026 };
    season.GetOrCreateStanding(setup.Home.TeamId); season.GetOrCreateStanding(setup.Away.TeamId);
    var m = new MatchSimulator().Simulate(setup, new Random(3));
    new MatchRecorder().Record(m, ho.Concat(ao).ToDictionary(p => p.Id), season);
    var winStanding = season.Standings.OrderByDescending(s => s.Points).First();
    TestRunner.IsTrue(winStanding.Points >= 2, $"winner has points ({winStanding.Points})"); // 2 for a win, +1 if a big margin

    // A contract holdout blocks selection; a renewal clears it.
    var w = EmptyWorld();
    var team = new Team { Name = "T", Reputation = new Reputation(60) }; w.Teams[team.Id] = team;
    var star = MatchTestData.MakePlayer("Money", 15); star.CurrentTeamId = team.Id;
    star.Personality = PersonalityTrait.MoneyFocused; star.SquadStatus = SquadStatus.FirstChoice;
    star.Reputation = new Reputation(60);
    w.Players.Add(star);
    var contract = new PlayerContract { PlayerId = star.Id, TeamId = team.Id, AnnualWage = 50_000, StartDate = new DateOnly(2025, 1, 1), EndDate = new DateOnly(2027, 6, 1), Kind = ContractKind.Domestic, Status = ContractStatus.Active };
    w.PlayerContracts.Add(contract);
    int holdouts = 0;
    for (int q = 0; q < 30; q++)
        holdouts += new TransferRequestService().RunQuarterly(w, new DateOnly(2026, 3, 1).AddMonths(q * 3), new Random(q)).Count(e => e.Type == GameEventType.ContractHoldout);
    if (star.HoldingOut)
    {
        TestRunner.IsTrue(!new PlayerAvailabilityService().GetAvailability(star, new DateOnly(2026, 6, 1)).IsAvailable, "a holdout player cannot be picked");
        star.SquadStatus = SquadStatus.FirstChoice;
        for (int r = 0; r < 20 && star.HoldingOut; r++)
            new PlayerContractService().EvaluateRenewal(contract, star, team, new DateOnly(2027, 3, 5), new Random(r));
        TestRunner.IsTrue(!star.HoldingOut, "a renewal ends the holdout");
    }
    TestRunner.IsTrue(holdouts >= 0, "holdout mechanism ran without error");

    // Ground hoodoo surfaces in the pre-match report.
    var bunny = MatchTestData.MakePlayer("Bunny", 13);
    var gid = Guid.NewGuid();
    var mc = new MatchupConfidence();
    for (int i = 0; i < 6; i++) mc.RecordOutcome(-60);
    bunny.Matchups[$"ground:{gid}"] = mc;
    var hoodoos = PreMatchReportService.GroundHoodoos(new[] { bunny }, gid, "The Furnace");
    TestRunner.IsTrue(hoodoos.Count == 1 && hoodoos[0].Contains("Furnace"), "a real ground hoodoo is surfaced");
});

TestRunner.Run("Completion W2: national-board ambition, retainer paid, day-night pitch, neutral venue", () =>
{
