TestRunner.Run("Completion W3-W5: franchise reputation drain, broadcast deal, bench sharpness, squad culture, fan reaction", () =>
{
    // Bench match-sharpness: a benched player loses it, playing brings it back.
    var w = EmptyWorld();
    var team = new Team { Name = "T" }; w.Teams[team.Id] = team;
    var benched = MatchTestData.MakePlayer("Bench", 13); benched.CurrentTeamId = team.Id; benched.MatchSharpness = 100;
    w.Players.Add(benched);
    var cal = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 5);
    new WorldClockService().AdvanceTo(cal, w, new DateOnly(2026, 8, 1));
    TestRunner.IsTrue(benched.MatchSharpness < 90, $"an unplayed player goes rusty ({benched.MatchSharpness:F0})");
    TestRunner.InRange(benched.MatchSharpness, 60, 100, "but never below the floor");

    // Broadcast deal: signed, fixed, renegotiated on expiry.
    var comp = new Competition { Name = "TV League", Scope = CompetitionScope.DomesticT20, Format = MatchFormat.T20, Prestige = 60, Reputation = 60 };
    var teams2 = Enumerable.Range(0, 6).Select(i => new Team { Name = $"C{i}", Reputation = new Reputation(60) }).ToList();
    var ev = new BroadcastRevenueService().RenegotiateDeal(comp, teams2, 2026, new Random(1));
    TestRunner.IsTrue(ev is not null && comp.BroadcastDeal is { AnnualValue: > 0 }, "a deal is signed");
    double locked = comp.BroadcastDeal!.AnnualValue;
    comp.Reputation = 95; // the competition grows - but the deal is locked
    TestRunner.AreEqual(locked, new BroadcastRevenueService().CalculateBroadcastPool(comp, teams2), "the signed deal pays its fixed value");
    comp.BroadcastDeal.ExpiresYear = 2028;
    new BroadcastRevenueService().RenegotiateDeal(comp, teams2, 2028, new Random(2));
    TestRunner.IsTrue(comp.BroadcastDeal.AnnualValue > locked, "the grown competition lands a bigger renewal");

    // Fan reaction to a relegation moves sentiment down.
    var fw = EmptyWorld();
    var relTeam = new Team { Name = "Down" }; relTeam.Board.MoveFanSentiment(0); fw.Teams[relTeam.Id] = relTeam;
    double sentBefore = relTeam.Board.FanSentiment;
    var reactions = new FanReactionService().React(new[] { new GameEvent(new DateOnly(2026, 9, 1), GameEventType.TeamRelegated, "Down are relegated.", relTeam.Id) }, fw, new DateOnly(2026, 9, 1)).ToList();
    TestRunner.IsTrue(reactions.Any(r => r.Type == GameEventType.FanReaction), "the fans react");
    TestRunner.IsTrue(relTeam.Board.FanSentiment < sentBefore, "and sentiment drops");
});

TestRunner.Run("Completion W6-W7: format comeback, nationality switch, new records, referee, H2H commentary", () =>
{
    // Format-specific comeback from retirement.
    var p = MatchTestData.MakePlayer("Come Back", 15);
    p.Reputation = new Reputation(70, 78, 78);
    p.DateOfBirth = new DateOnly(1997, 1, 1);
    var rs = new RetirementService();
    rs.RetireFromFormat(p, MatchFormat.Test, new DateOnly(2030, 1, 1));
    TestRunner.IsTrue(p.RetiredFormats.Contains(MatchFormat.Test), "retired from Tests");
    bool cameBack = false;
    for (int i = 0; i < 400 && !cameBack; i++)
        cameBack = rs.TryComebackFromFormat(p, MatchFormat.Test, new DateOnly(2030, 6, 1), new Random(i));
    TestRunner.IsTrue(cameBack, "a Test comeback is possible");
    TestRunner.IsTrue(!p.RetiredFormats.Contains(MatchFormat.Test), "and it clears the retirement");

    // S6: an uncapped long-residency player good enough abroad switches allegiance (RepresentationDriftService).
    var w = EmptyWorld();
    var club = new Team { Name = "Adopted XI", Country = "England" }; w.Teams[club.Id] = club;
    var engNat = new Team { Name = "England", Country = "England", IsNational = true }; w.Teams[engNat.Id] = engNat;
    var nepNat = new Team { Name = "Nepal", Country = "Nepal", IsNational = true }; w.Teams[nepNat.Id] = nepNat;
    w.CountryProfiles["England"] = new CountryProfile { Nationality = "England", Membership = MembershipStatus.FullMember };
    w.CountryProfiles["Nepal"] = new CountryProfile { Nationality = "Nepal", Membership = MembershipStatus.Associate };
    var drift = new RepresentationDriftService();
    var migrants = new List<Player>();
    for (int i = 0; i < 20; i++)
    {
        var mig = MatchTestData.MakePlayer($"Mig{i}", 15);
        mig.CurrentTeamId = club.Id; mig.Nationality = "Nepal";
        mig.Reputation = new Reputation(domestic: 74, continental: 46);
        mig.Personality |= PersonalityTrait.Ambitious;
        mig.DateOfBirth = new DateOnly(1999, 1, 1).AddDays(i * 11);
        w.Players.Add(mig); migrants.Add(mig);
    }
    bool switched = false;
    for (int y = 2028; y <= 2032 && !switched; y++)
    {
        drift.ReviewAnnually(w, new DateOnly(y, 12, 1)).ToList();
        switched = migrants.Any(m => m.Nationality == "England");
    }
    TestRunner.IsTrue(switched, "a qualified uncapped migrant switches allegiance");

    // New record categories: most catches in a match, most ducks in an innings.
    var rw = EmptyWorld();
    var recs = new MatchRecords();
    var fielderId = Guid.NewGuid();
    recs.Fielding.Add(new FieldingRecord { PlayerId = fielderId, Catches = 5 });
    for (int i = 0; i < 5; i++) recs.Batting.Add(new BattingInningsRecord { PlayerId = Guid.NewGuid(), Runs = 0, NotOut = false, Dismissal = DismissalType.Bowled });
    rw.Players.Add(new Player { FirstName = "Safe", LastName = "Hands", Id = fielderId });
    new RecordProgressionService().ReviewMatch(rw, recs, new DateOnly(2027, 1, 1));
    new RecordProgressionService().ReviewMatch(rw, recs, new DateOnly(2027, 2, 1)); // establish then hold
    TestRunner.IsTrue(rw.RecordBook.Keys.Any(k => k.StartsWith("MostCatchesInMatch")), "most-catches record is kept");
    TestRunner.IsTrue(rw.RecordBook.Keys.Any(k => k.StartsWith("MostDucksInInnings")), "most-ducks record is kept");

    // Match referee assignment is RNG-free and picks a senior official clear of the on-field trio.
    var us = new UmpireService();
    var pool = Enumerable.Range(0, 6).Select(i => new Umpire
    {
        FirstName = "U", LastName = $"{i}", Reputation = 40 + i * 8, MatchesOfficiated = 60,
        Accuracy = 12 + i, Consistency = 12, Composure = 12, LbwJudgement = 12, Panel = UmpirePanel.International
    }).ToList();
    var onField = pool.Take(2).ToList();
    var (refName1, refConsistency1) = us.AssignReferee(pool, onField, isInternational: true);
    var (refName2, _) = us.AssignReferee(pool, onField, isInternational: true);
    TestRunner.AreEqual(refName1, refName2, "referee assignment is deterministic");
    TestRunner.IsTrue(!onField.Any(u => u.FullName == refName1), "the referee is not one of the on-field umpires");
    TestRunner.InRange(refConsistency1, 0.3, 0.95, "consistency is a real 0..1 figure");
});

TestRunner.Run("Completion W9: a feuding crease pair runs a higher run-out risk; a flaw shapes the dismissal", () =>
{
    int RunOuts(bool feud, int seed)
    {
        var (order, _) = MatchTestData.MakeEleven("F", 12, 11);
        var (_, bowlers) = MatchTestData.MakeEleven("G", 11, 13);
        var setup = new InningsSetup(order, order, bowlers);
        var st = new InningsSimulator().Simulate(setup, MatchFormat.T20, 20,
            Guid.NewGuid(), "Bat", Guid.NewGuid(), "Bowl", new Random(seed),
            pairHasFriction: feud ? (a, b) => true : null);
        return st.Deliveries.Count(d => d.Outcome.Dismissal == DismissalType.RunOut);
    }
    int with = 0, without = 0;
    for (int s = 0; s < 90; s++) { with += RunOuts(true, s); without += RunOuts(false, s); }
    TestRunner.IsTrue(with > without, $"feuding pairs run more run-outs ({with} vs {without})");

    // A technical flaw biases the dismissal type toward its signature mode (mix-only).
    var flawed = MatchTestData.MakePlayer("Fault", 3);
    flawed.TechnicalFlaw = TechnicalFlaw.FrontFootLbwProne;
    TestRunner.AreEqual(TechnicalFlaw.FrontFootLbwProne, flawed.TechnicalFlaw!.Value, "the flaw is set and read by the ball model");
});

// ==================== FOLLOW-UP PASS 1: Coach/Board Authority & Governance Depth ====================

TestRunner.Run("Follow-up Pass 1 (§7.3, the remaining half): a weak selection panel favours reputation over merit when picking a squad", () =>
{
    var world = EmptyWorld();
    var team = new Team { Name = "T", Strength = 55 };
    team.ManagerPreferences.PreferredSquadSize = 12; // exactly one genuinely contested slot, engineered below
    world.Teams[team.Id] = team;

    // 11 clearly-strong players - guaranteed in regardless of any bias.
    for (int i = 0; i < 11; i++)
    {
        var p = MatchTestData.MakePlayer($"Strong{i}", 16, i < 4 ? PlayerRole.Bowler : PlayerRole.Batsman, i < 4 ? BowlingRoleType.OpeningBowler : BowlingRoleType.NotABowler);
        world.Players.Add(p); team.SquadPlayerIds.Add(p.Id);
    }
    // A declining, over-reputed veteran vs an in-form, low-reputation player - tied on raw merit
    // (identical level), genuinely contesting the single 12th spot.
    var veteran = MatchTestData.MakePlayer("Veteran", 10);
    veteran.Reputation = new Reputation(worldwide: 5, continental: 10, domestic: 90);
    var inFormFringe = MatchTestData.MakePlayer("Fringe", 10);
    inFormFringe.Reputation = new Reputation(worldwide: 0, continental: 0, domestic: 15);
    foreach (var p in new[] { veteran, inFormFringe }) { world.Players.Add(p); team.SquadPlayerIds.Add(p.Id); }
    // Clearly weaker fillers - never in contention for the last spot either.
    for (int i = 0; i < 3; i++)
    {
        var p = MatchTestData.MakePlayer($"Weak{i}", 5);
        world.Players.Add(p); team.SquadPlayerIds.Add(p.Id);
    }

    var ai = new AiClubManagementService();
    var sharpCoach = new Coach { FirstName = "Sharp", LastName = "C" };
    sharpCoach.Attributes.DecisionMaking = 19; sharpCoach.Attributes.ManManagement = 19; sharpCoach.Attributes.MatchReading = 19;
    var weakCoach = new Coach { FirstName = "Weak", LastName = "C" };
    weakCoach.Attributes.DecisionMaking = 2; weakCoach.Attributes.ManManagement = 2; weakCoach.Attributes.MatchReading = 2;

    var squadSharp = ai.PickSquad(world, team, MatchFormat.T20, new DateOnly(2026, 6, 1), sharpCoach);
    var squadWeak = ai.PickSquad(world, team, MatchFormat.T20, new DateOnly(2026, 6, 1), weakCoach);

    TestRunner.AreEqual(12, squadSharp.Count, "the sharp panel fills the requested squad size");
    TestRunner.AreEqual(12, squadWeak.Count, "so does the weak one");
    TestRunner.IsTrue(!squadSharp.Contains(veteran.Id) || !squadSharp.Contains(inFormFringe.Id),
        "only one of the two tied contenders takes the single contested slot");
    TestRunner.IsTrue(squadWeak.Contains(veteran.Id) && !squadWeak.Contains(inFormFringe.Id),
        "a genuinely weak, reputation-swayed panel reaches for the declining veteran over the identically-rated but unheralded fringe player");
});

TestRunner.Run("Follow-up Pass 1 (§5.2): a formal panel vote surfaces a genuine outvote, distinct from the softer dissent notes", () =>
{
    var meetingSvc = new SelectionMeetingService();
    var team = new Team { Name = "Nation", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 20, Politicisation = 85, PanelSize = 5 } };

    // A genuinely CONTESTED slot: "chosen" must be the WEAKEST of the announced squad (so
    // Hold's own weakestChosen/rival detection actually lands on this exact pair) and close
    // enough in raw merit to the omitted "rival" to register as contested (|gap| <= 5). The
    // fillers sit clearly ahead of both, so they are never in contention for this slot. The RIVAL
    // carries the reputation here - the actual decision went with the less-heralded "chosen" name
    // anyway, which is exactly what a reputation-swayed panel's own vote would disagree with.
    // Pinned to Fringe (a near-zero EstablishedProtection ceiling regardless of reputation, per
    // PlayerSelectionEvaluator's own design) so the PRE-EXISTING reputation-linked protection term
    // does not itself pull the raw merit score apart here - isolating THIS vote model's own
    // reputation-pull term as the only thing that can move the outcome in this specific test.
    var chosen = MatchTestData.MakePlayer("Chosen", 9);
    chosen.SquadStatus = SquadStatus.Fringe;
    chosen.Reputation = new Reputation(worldwide: 0, continental: 0, domestic: 10);
    var rival = MatchTestData.MakePlayer("Rival", 9);
    rival.SquadStatus = SquadStatus.Fringe;
    rival.Reputation = new Reputation(worldwide: 70, continental: 80, domestic: 90);
    // Every filler is in the announced squad - "rival" (my test player) must be the ONLY omitted
    // candidate, or a stray better-ranked filler left out by accident hijacks the "omitted rival"
    // role in the contested-slot detection before it ever reaches the pair this test cares about.
    var pool = new List<Player> { chosen, rival };
    for (int i = 0; i < 10; i++) pool.Add(MatchTestData.MakePlayer($"Filler{i}", 16));
    var chosenIds = new List<Guid> { chosen.Id }.Concat(pool.Skip(2).Select(p => p.Id)).ToList();

    var reportWeak = meetingSvc.Hold(team, MatchFormat.ODI, chosenIds, pool, new DateOnly(2026, 6, 1));
    TestRunner.IsTrue(reportWeak.Outvoted, $"a weak, political panel genuinely gets outvoted on a real reputation-vs-merit gap ({reportWeak.VotesForChosen}/{reportWeak.PanelSize})");
    TestRunner.IsTrue(reportWeak.DissentNote is not null && reportWeak.DissentNote.Contains("split panel vote"), $"and it says so specifically: {reportWeak.DissentNote}");

    // A sharp, apolitical panel is measurably less swayed by reputation than the weak, political
    // one - genuinely more of its seats back the actual pick on the same facts. (Reputation
    // already has a small, legitimate pull on the underlying merit score via EstablishedProtection,
    // so this is a comparative claim, not "a strong panel is immune to reputation entirely".)
    var strongTeam = new Team { Name = "Nation2", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 92, Politicisation = 5, PanelSize = 5 } };
    var reportStrong = meetingSvc.Hold(strongTeam, MatchFormat.ODI, chosenIds, pool, new DateOnly(2026, 6, 1));
    TestRunner.IsTrue(reportStrong.VotesForChosen > reportWeak.VotesForChosen,
        $"a sharp panel backs the actual pick more than a weak, political one does on identical facts ({reportStrong.VotesForChosen} vs {reportWeak.VotesForChosen} of {reportStrong.PanelSize})");
});

TestRunner.Run("Follow-up Pass 1 (§5.3): a pre-series planning conversation is surfaced for a genuine head-to-head series", () =>
{
    var world = EmptyWorld();
    var strong = new Team { Name = "Strong", Strength = 80 };
    var weak = new Team { Name = "Weak", Strength = 40 };
    world.Teams[strong.Id] = strong; world.Teams[weak.Id] = weak;

    var comp = new Competition { Name = "Test Series", Scope = CompetitionScope.International };
    world.Competitions.Add(comp);
    var season = new CompetitionSeason { CompetitionId = comp.Id, Year = 2026, ParticipatingTeamIds = { strong.Id, weak.Id } };
    world.CompetitionSeasons.Add(season);

    var coach = new Coach { FirstName = "Human", LastName = "Coach", IsHumanControlled = true };
    coach.CurrentTeamId = strong.Id; strong.CurrentCoachId = coach.Id;
    world.Coaches.Add(coach);
    strong.ManagerPreferences.Delegation.Set(DecisionArea.TacticalPlan, DelegationMode.Consult);

    var events = WorldClockService.SurfacePreSeriesPlanning(world, comp, new DateOnly(2026, 6, 1)).ToList();
    TestRunner.AreEqual(1, events.Count, "only the human-coached, Consult-mode side gets a recommendation - the AI side has nobody to show it to");
