    TestRunner.IsTrue(events[0].Type == GameEventType.StaffRecommendationIssued && events[0].Headline.Contains("press for the series win"),
        $"the stronger side is told to press for the win: {events[0].Headline}");

    // Left at the default (Delegate, no recommendation wanted) - nothing is surfaced at all.
    strong.ManagerPreferences.Delegation.Set(DecisionArea.TacticalPlan, DelegationMode.Delegate);
    TestRunner.AreEqual(0, WorldClockService.SurfacePreSeriesPlanning(world, comp, new DateOnly(2026, 6, 1)).Count(),
        "no recommendation surfaced once TacticalPlan is back to Delegate");

    // A big multi-team tournament (more than two participants) is not a head-to-head series - silent.
    var thirdTeam = new Team { Name = "Third", Strength = 50 };
    world.Teams[thirdTeam.Id] = thirdTeam;
    season.ParticipatingTeamIds.Add(thirdTeam.Id);
    strong.ManagerPreferences.Delegation.Set(DecisionArea.TacticalPlan, DelegationMode.Consult);
    TestRunner.AreEqual(0, WorldClockService.SurfacePreSeriesPlanning(world, comp, new DateOnly(2026, 6, 1)).Count(),
        "a genuine multi-team tournament (3+ participants) gets no pre-series conversation - there is no single opponent to plan a series around");
});

TestRunner.Run("Follow-up Pass 1 (§13.2/§13.6): a boardroom coup is a distinct governance event, and it draws a real fan protest on top of an already-collapsed mood", () =>
{
    var board = new BoardService();
    var team = new Team { Name = "Split FC", Strength = 45 };
    team.Board.Ownership = OwnershipModel.PrivateOwner;
    team.Board.BoardUnity = 20; // already fractured
    var oldAgenda = team.Board.Agenda;

    GameEvent? coup = null;
    for (int seed = 0; seed < 60 && coup is null; seed++)
    {
        var t2 = new Team { Name = "Split FC", Strength = 45 };
        t2.Board.Ownership = OwnershipModel.PrivateOwner;
        t2.Board.BoardUnity = 20;
        var events = board.ReviewBoardroom(t2, new DateOnly(2026, 6, 1), performanceScore: -0.3, netResult: -200_000, new Random(seed)).ToList();
        coup = events.FirstOrDefault(e => e.Type == GameEventType.BoardroomCoup);
        if (coup is not null) team = t2;
    }
    TestRunner.IsTrue(coup is not null, "a genuinely fractured board eventually has a real boardroom coup");

    // The fan-reaction service treats a coup as its own genuine governance-crisis trigger.
    team.Board.MoveFanSentiment(-100); // force sentiment onto the floor so the protest branch is live
    var fanSvc = new FanReactionService();
    var world = EmptyWorld();
    world.Teams[team.Id] = team;
    var reactions = fanSvc.React(new[] { coup! }, world, new DateOnly(2026, 6, 2)).ToList();
    TestRunner.IsTrue(reactions.Any(r => r.Headline.Contains("boardroom")), "the fans react specifically to the governance crisis, not a generic result swing");
    TestRunner.IsTrue(reactions.Any(r => r.Headline.Contains("protest")), "and, with sentiment already on the floor, it tips into a real protest");
});

