TestRunner.Run("Follow-up Pass 2 (§5.13): AssignedRole is a small, real, secondary batting-performance signal", () =>
{
    var deriver = new RoleTraitDeriver();
    var opener = new Player { PrimaryRole = PlayerRole.Batsman, BattingRole = BattingRole.Opener,
        Batting = new BattingAttributes { Technique = 15, Timing = 15, ShotSelection = 14 }, Mental = new MentalAttributes { Concentration = 14 } };
    deriver.ApplyTo(opener);
    var modifier = new SituationalPerformanceModifier();
    var situation = new BattingSituation(OversRemainingInInnings: 20, WicketsInHand: 9, Phase: MatchPhase.Powerplay, IsChasing: false);

    double noAssignment = modifier.GetBattingMultiplier(opener, BattingRole.Opener, situation);

    opener.AssignedRole = BattingRole.Opener;
    double inAssignedRole = modifier.GetBattingMultiplier(opener, BattingRole.Opener, situation);
    double outOfAssignedRole = modifier.GetBattingMultiplier(opener, BattingRole.LowerOrder, situation);

    TestRunner.IsTrue(inAssignedRole > noAssignment, "a player genuinely knowing his assigned job is worth a small real lift");
    TestRunner.IsTrue(outOfAssignedRole < noAssignment, "being asked to bat somewhere else entirely, away from the assigned role, carries a small real cost");
});

TestRunner.Run("Follow-up Pass 2 (§5.4): a standing cross-format workload plan genuinely protects or exposes a player, format by format", () =>
{
    var rotation = new WorkloadRotationService();
    var world = EmptyWorld();

    // A genuine, non-zero baseline rest-need (age/injury-proneness alone) for the WorkloadPriority
    // pull to actually move - MatchTestData.MakePlayer's defaults read as a fully fit, young
    // player with nothing to manage, which floors RestNeed at 0 regardless of any bias term.
    var redBallPriority = MatchTestData.MakePlayer("RedBaller", 12);
    redBallPriority.WorkloadPriority = WorkloadPriority.PrioritiseRedBall;
    redBallPriority.Physical.InjuryProneness = 16;
    var balanced = MatchTestData.MakePlayer("Balanced", 12);
    balanced.Physical.InjuryProneness = 16;

    double redBallNeedForRedBaller = rotation.RestNeed(redBallPriority, world, new DateOnly(2026, 6, 1), MatchFormat.Test);
    double whiteBallNeedForRedBaller = rotation.RestNeed(redBallPriority, world, new DateOnly(2026, 6, 1), MatchFormat.T20);
    double neutralNeed = rotation.RestNeed(balanced, world, new DateOnly(2026, 6, 1), MatchFormat.Test);

    TestRunner.IsTrue(redBallNeedForRedBaller < neutralNeed, "a red-ball-prioritised player is genuinely protected from being rested for a Test");
    TestRunner.IsTrue(whiteBallNeedForRedBaller > neutralNeed, "and genuinely more likely to be rested for the white-ball format he is not being prioritised for");

    // Omitting the format (every pre-§5.4 caller) reproduces the exact original reading.
    double noFormat = rotation.RestNeed(balanced, world, new DateOnly(2026, 6, 1));
    TestRunner.AreEqual(neutralNeed, noFormat, "the omitted-format default matches the explicit-format neutral reading exactly");
});

