TestRunner.Run("Follow-up Pass 2 (§6.4): sustained Intensive training is its own soft-tissue axis, distinct from match-load burnout", () =>
{
    var training = new TrainingService();
    var player = MatchTestData.MakePlayer("Grinder", 12);
    player.Physical.InjuryProneness = 8;
    player.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
    player.TrainingPlan.Intensity = TrainingIntensity.Intensive;
    int startingProneness = player.Physical.InjuryProneness;

    var rng = new Random(7);
    for (int month = 0; month < 8 && player.CurrentInjury is null; month++)
        training.ApplyPeriodicTraining(player, 60, Array.Empty<StaffMember>(), rng, new DateOnly(2026, 1, 1).AddMonths(month), 1.0 / 12, reassessFocus: false);

    TestRunner.IsTrue(player.Physical.InjuryProneness > startingProneness || player.CurrentInjury is not null,
        "eight straight months of Intensive training genuinely costs him - either the accumulating soft-tissue toll or a real overtraining injury along the way");

    // Easing off resets the count - a single Normal month after a long Intensive run does not
    // itself trip the threshold on its own.
    var eased = MatchTestData.MakePlayer("Eased", 12);
    eased.TrainingPlan.Focus = TrainingFocus.BattingTechnique;
    eased.ConsecutiveIntensiveTrainingPeriods = 5;
    eased.TrainingPlan.Intensity = TrainingIntensity.Normal;
    training.ApplyPeriodicTraining(eased, 60, Array.Empty<StaffMember>(), new Random(3), new DateOnly(2026, 9, 1), 1.0 / 12, reassessFocus: false);
    TestRunner.AreEqual(0, eased.ConsecutiveIntensiveTrainingPeriods, "a normal-intensity month resets the streak");
});

