TestRunner.Run("Follow-up Pass 4 (§2.11 - verification): SelectBowler's existing scoring already turns to a part-timer when the specialists are being collared", () =>
{
    double PartTimerShare(int battingLevel, int bowlingLevel, int seeds)
    {
        double totalShare = 0;
        int countedInnings = 0;
        for (int s = 0; s < seeds; s++)
        {
            var (order, bowlers) = MatchTestData.MakeEleven("X", battingLevel, bowlingLevel);
            var partTimerId = order[5].Id; // MakeEleven's own genuine part-timer: a specialist batter bowling well below the frontline's level
            var setup = new InningsSetup(order, order, bowlers);
            var state = new InningsSimulator().Simulate(setup, MatchFormat.ODI, 50, Guid.NewGuid(), "B", Guid.NewGuid(), "F", new Random(s * 7 + 3));
            int total = state.BowlerCards.Sum(c => c.LegalBallsBowled);
            if (total == 0) continue;
            int partTimer = state.BowlerCards.FirstOrDefault(c => c.PlayerId == partTimerId)?.LegalBallsBowled ?? 0;
            totalShare += (double)partTimer / total;
            countedInnings++;
        }
        return countedInnings == 0 ? 0 : totalShare / countedInnings;
    }

    // A weak attack against strong batting: the specialists are genuinely collared (well above par
    // economy once they've bowled a few overs). A dominant attack against weak batting is the
    // mirror - no reason to turn to anyone but the frontline.
    double collaredShare = PartTimerShare(battingLevel: 17, bowlingLevel: 6, seeds: 60);
    double dominantShare = PartTimerShare(battingLevel: 6, bowlingLevel: 17, seeds: 60);

    TestRunner.IsTrue(collaredShare > dominantShare,
        $"a struggling attack turns to its part-timer more than a dominant one does ({collaredShare:P1} vs {dominantShare:P1}) - §2.11 is already covered by the existing onTop/matchup scoring, no new code needed");
});

TestRunner.Run("Follow-up Pass 4 (§2.6): a bowler can set an over up and finish it differently - a genuinely separate signal from the cross-spell dot-streak trap", () =>
{
    var svc = new BowlerExecutionService();
    var bowler = MatchTestData.MakePlayer("Setup", 16, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    bowler.Mental.GameAwareness = 19; bowler.Mental.DecisionMaking = 19;
    for (int i = 0; i < 100; i++) bowler.Experience.RecordAppearance(MatchFormat.ODI, new DateOnly(2020, 1, 1));
    var approach = new BowlingApproach(BowlingLine.OutsideOff, BowlingLength.Good);

    // Four balls THIS OVER on a consistent full length outside off, no dot-streak involved
    // (RunsConceded/BallsAtThisBatter give a run rate well under the "being milked" threshold, and
    // ConsecutiveDots is 0) - this is what distinguishes the within-over signal from the existing
    // cross-spell trap.
    var withinOver = new List<(BowlingLine, BowlingLength)>
    {
        (BowlingLine.OutsideOff, BowlingLength.Full), (BowlingLine.OutsideOff, BowlingLength.Full),
        (BowlingLine.OutsideOff, BowlingLength.Full), (BowlingLine.OutsideOff, BowlingLength.Full),
    };
    var readout = new SpellReadout(20, 20, 1, 0, ConsecutiveDots: 0, RecentDeliveries: withinOver,
        WithinOverPattern: withinOver, IsLastBallOfOver: true);

    bool Finished(ExecutedDelivery d) => d.Note is not null && d.Note.Contains("finishes it with something different");

    int finishers = 0;
    for (int s = 0; s < 400; s++)
        if (Finished(svc.Execute(bowler, approach, readout, null, new Random(s)))) finishers++;
    TestRunner.IsTrue(finishers > 15, $"a sharp bowler genuinely finishes some overs differently once he's set one up ({finishers}/400)");

    // Not the last ball of the over - the mechanism never fires, however consistent the pattern.
    var midOver = readout with { IsLastBallOfOver = false };
    int midOverFinishers = 0;
    for (int s = 0; s < 400; s++)
        if (Finished(svc.Execute(bowler, approach, midOver, null, new Random(s)))) midOverFinishers++;
    TestRunner.AreEqual(0, midOverFinishers, "mid-over, with balls still to bowl, this specific finisher never fires");

    // Fewer than three balls this over is not a real pattern yet.
    var tooFew = readout with { WithinOverPattern = withinOver.Take(1).ToList() };
    int tooFewFinishers = 0;
    for (int s = 0; s < 400; s++)
        if (Finished(svc.Execute(bowler, approach, tooFew, null, new Random(s)))) tooFewFinishers++;
    TestRunner.AreEqual(0, tooFewFinishers, "a single ball this over is not a pattern - the finisher needs at least three");

    // A real dot-ball streak takes priority (mutually exclusive "else if") - the cross-spell trap
    // fires, never this within-over one, so the two can never compound on the same ball.
    var bothPatterns = readout with { ConsecutiveDots = 4 };
    int crossSpellFired = 0, withinOverFired = 0;
    for (int s = 0; s < 400; s++)
    {
        var d = svc.Execute(bowler, approach, bothPatterns, null, new Random(s));
        if (d.Note is not null && d.Note.Contains("built the pressure")) crossSpellFired++;
        if (Finished(d)) withinOverFired++;
    }
    TestRunner.AreEqual(0, withinOverFired, "when a real dot-streak is ALSO present, the cross-spell trap takes priority, never the within-over one");
    TestRunner.IsTrue(crossSpellFired > 0, "...and the cross-spell trap does still fire in that case");
});

TestRunner.Run("Follow-up Pass 4 (§2.12): T20 batting ramps up a few overs before the death, not just at the phase boundary", () =>
{
    var settled = new BatterCard { PlayerId = Guid.NewGuid(), PlayerName = "Settled", BattingPosition = 3, BallsFaced = 20 };

    // Over 13 of a T20 (death starts at over 16): still nominally MiddleOvers, but close enough
    // to the boundary that a settled batter with wickets in hand is already pushing on.
    var ramping = new InningsState
    {
        BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl",
        Format = MatchFormat.T20, MaxLegalBalls = 120, LegalBalls = 13 * 6, Wickets = 2, Runs = 90
    };
    var phase = InningsSimulator.DeterminePhase(ramping, 13);
    TestRunner.AreEqual(MatchPhase.MiddleOvers, phase, "over 13 of a T20 is still nominally MiddleOvers, not DeathOvers yet");
    TestRunner.AreEqual(BattingIntent.Attacking, InningsSimulator.DetermineBattingIntent(ramping, settled, phase),
        "a settled batter three overs before the death is already pushing on, not waiting for the phase boundary");

    // Over 8 - well before the ramp window - the same settled batter is still just building.
    var early = new InningsState
    {
        BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl",
        Format = MatchFormat.T20, MaxLegalBalls = 120, LegalBalls = 8 * 6, Wickets = 2, Runs = 55
    };
    var earlyPhase = InningsSimulator.DeterminePhase(early, 8);
    TestRunner.AreEqual(BattingIntent.Normal, InningsSimulator.DetermineBattingIntent(early, settled, earlyPhase),
        "well before the death, the same settled batter is not yet ramping up");

    // The ramp is T20-only - an ODI at the equivalent proportional point (over 32 of 50) is left to
    // the existing, dedicated §2.3 middle-overs contest, not double-handled by this new band.
    var odi = new InningsState
    {
        BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl",
        Format = MatchFormat.ODI, MaxLegalBalls = 300, LegalBalls = 32 * 6, Wickets = 2, Runs = 180
    };
    var odiPhase = InningsSimulator.DeterminePhase(odi, 32);
    TestRunner.AreEqual(MatchPhase.MiddleOvers, odiPhase, "over 32 of an ODI is still MiddleOvers");
    // §2.3 already governs this case entirely - just confirm it still resolves without the new
    // T20-only branch interfering (format-gated, so ODI's own read is untouched either way).
    var odiIntent = InningsSimulator.DetermineBattingIntent(odi, settled, odiPhase);
    TestRunner.IsTrue(odiIntent is BattingIntent.Normal or BattingIntent.Attacking or BattingIntent.Anchoring,
        $"ODI's own middle-overs contest still resolves normally, untouched by the T20-only ramp ({odiIntent})");
});

TestRunner.Run("Follow-up Pass 4 (§3.6): a genuine bunny is protected from the specific bowler he has a real, evidenced problem with", () =>
{
    var ai = new InMatchTacticalAI();
    var bowler = MatchTestData.MakePlayer("Nemesis", 14, PlayerRole.Bowler, BowlingRoleType.OpeningBowler);
    string key = MatchupKey.ForBowler(bowler.Id);

    List<Player> BuildOrder(Player bunny, Player saviour)
    {
        var order = new List<Player> { bunny };
        for (int i = 0; i < 5; i++) order.Add(MatchTestData.MakePlayer($"Rest{i}", 12));
        order.Add(saviour);
        return order;
    }

    InningsState BuildState(IReadOnlyList<Player> order)
    {
        var st = new InningsState
        {
            BattingTeamId = Guid.NewGuid(), BowlingTeamId = Guid.NewGuid(), BattingTeamName = "Bat", BowlingTeamName = "Bowl",
            Format = MatchFormat.Test, CurrentBowlerId = bowler.Id
        };
        for (int i = 0; i < order.Count; i++)
            st.BatterCards.Add(new BatterCard { PlayerId = order[i].Id, PlayerName = order[i].FullName, BattingPosition = i + 1, HasBatted = false });
        return st;
    }

    var bunny = MatchTestData.MakePlayer("Bunny", 12);
    var saviour = MatchTestData.MakePlayer("Saviour", 12);
    bunny.Matchups[key] = new MatchupConfidence();
    for (int i = 0; i < 8; i++) bunny.Matchups[key].RecordOutcome(-90);
    saviour.Matchups[key] = new MatchupConfidence();
    for (int i = 0; i < 8; i++) saviour.Matchups[key].RecordOutcome(90);

    var order = BuildOrder(bunny, saviour);
    var state = BuildState(order);

    int protections = 0;
    for (int s = 0; s < 300; s++)
        if (ai.ChooseBunnyProtection(state, order, 0, null, TacticalPlan.None, new Random(s)) == order.Count - 1) protections++;
    TestRunner.IsTrue(protections > 15, $"a genuine bunny is protected from his nemesis a real fraction of the time ({protections}/300)");

    // No real matchup sample against this bowler at all (below MinimumSampleForEffect) - never
    // protects on noise, exactly as the live ball model's own matchup multiplier never bites below
    // that same threshold.
    var noHistoryBunny = MatchTestData.MakePlayer("NoHistory", 12);
    var noHistoryOrder = BuildOrder(noHistoryBunny, MatchTestData.MakePlayer("Saviour2", 12));
    var noHistoryState = BuildState(noHistoryOrder);
    int falseProtections = 0;
    for (int s = 0; s < 200; s++)
        if (ai.ChooseBunnyProtection(noHistoryState, noHistoryOrder, 0, null, TacticalPlan.None, new Random(s)) is not null) falseProtections++;
    TestRunner.AreEqual(0, falseProtections, "with no real sample against this bowler, there is nothing to protect against");

    // A coach who keeps the batting order's final say is never overridden - same authority gate the
    // pinch-hitter already uses.
    var humanPlan = TacticalPlan.ForHumanCoach();
    int overrides = 0;
    for (int s = 0; s < 100; s++)
        if (ai.ChooseBunnyProtection(state, order, 0, null, humanPlan, new Random(s)) is not null) overrides++;
    TestRunner.AreEqual(0, overrides, "the AI never reorders a batting order the coach has kept control of");
});

