TestRunner.Run("Stage 1 / A: a Selector's effectiveness rewards analysis/statistics/diligence/communication - the scouting-panel blend", () =>
{
    var sharp = new StaffMember { Role = StaffRole.Selector, Analysis = 18, Statistics = 17, Diligence = 17, Communication = 15, TechnicalKnowledge = 8 };
    var dull = new StaffMember { Role = StaffRole.Selector, Analysis = 8, Statistics = 8, Diligence = 8, Communication = 8, TechnicalKnowledge = 18 };
    TestRunner.IsTrue(sharp.Effectiveness > dull.Effectiveness,
        $"a genuinely analytical, diligent selector rates ahead of one who is merely technically knowledgeable ({sharp.Effectiveness:F1} vs {dull.Effectiveness:F1})");

    var chief = new StaffMember { Role = StaffRole.ChiefSelector, Analysis = 18, Statistics = 17, Diligence = 17, Communication = 15, TechnicalKnowledge = 8 };
    TestRunner.IsTrue(Math.Abs(sharp.Effectiveness - chief.Effectiveness) < 0.01,
        "ChiefSelector shares the exact same blend as Selector - the panel's chair, not a different job");
});

TestRunner.Run("Stage 1 / A: FillSelectionPanel hires a chief selector + three selectors, deterministically, and tops up rather than duplicating", () =>
{
    var world = EmptyWorld();
    var national = new Team { Name = "Aardvark XI", IsNational = true, Country = "Testland" };
    national.Reputation = new Reputation(domestic: 60, continental: 40, worldwide: 25);
    world.Teams[national.Id] = national;

    var svc = new AiClubManagementService();
    svc.FillSelectionPanel(world, new DateOnly(2026, 1, 5), national, new Random(1)).ToList();

    TestRunner.AreEqual(1, world.Staff.Count(s => s.TeamId == national.Id && s.Role == StaffRole.ChiefSelector), "one chairman of selectors");
    TestRunner.AreEqual(3, world.Staff.Count(s => s.TeamId == national.Id && s.Role == StaffRole.Selector), "three ordinary selectors");
    TestRunner.AreEqual(4, world.StaffContracts.Count(c => c.Status == ContractStatus.Active), "each has a real contract");

    // Run it again - a full panel is not topped up, and nobody is duplicated.
    svc.FillSelectionPanel(world, new DateOnly(2026, 2, 5), national, new Random(2)).ToList();
    TestRunner.AreEqual(4, world.Staff.Count(s => s.TeamId == national.Id && s.Role is StaffRole.Selector or StaffRole.ChiefSelector),
        "a full panel is left alone on a second pass");

    // Deterministic: the same seed rebuilds the same panel names.
    var world2 = EmptyWorld();
    var national2 = new Team { Name = "Aardvark XI", IsNational = true, Country = "Testland" };
    national2.Reputation = new Reputation(domestic: 60, continental: 40, worldwide: 25);
    world2.Teams[national2.Id] = national2;
    new AiClubManagementService().FillSelectionPanel(world2, new DateOnly(2026, 1, 5), national2, new Random(1)).ToList();
    var names1 = world.Staff.Where(s => s.TeamId == national.Id).OrderBy(s => s.Role).Select(s => s.FullName).ToList();
    var names2 = world2.Staff.Where(s => s.TeamId == national2.Id).OrderBy(s => s.Role).Select(s => s.FullName).ToList();
    TestRunner.IsTrue(names1.SequenceEqual(names2), "same seed -> the same panel");
});

TestRunner.Run("Stage 1 / A: ShouldHoldMeeting's deterministic branches - first squad, a human opt-out, and genuine turnover", () =>
{
    var team = new Team { Name = "Test" };
    var squad = new List<Guid> { Guid.NewGuid(), Guid.NewGuid(), Guid.NewGuid() };

    TestRunner.IsTrue(AiClubManagementService.ShouldHoldMeeting(team, null, null, squad, new Random(1)),
        "the very first squad for a competition always gets a real meeting - there is nothing to carry forward");

    var humanCoach = new Coach { IsHumanControlled = true };
    team.ManagerPreferences.HoldSelectionMeetings = false;
    TestRunner.IsTrue(!AiClubManagementService.ShouldHoldMeeting(team, humanCoach, squad, squad, new Random(1)),
        "a human who has explicitly opted out never gets a meeting, whatever else changed");
    team.ManagerPreferences.HoldSelectionMeetings = true;

    var previous = new List<Guid> { squad[0] };
    var churned = new List<Guid> { squad[0], Guid.NewGuid(), Guid.NewGuid() }; // two genuinely new faces
    TestRunner.IsTrue(AiClubManagementService.ShouldHoldMeeting(team, null, previous, churned, new Random(1)),
        "genuine turnover (2+ new faces) is always worth a meeting, whoever the coach is");
});

TestRunner.Run("Stage 1 / A: ShouldHoldMeeting - a thorough coach calls a meeting on an unchanged squad far more often than a lazy one", () =>
{
    var team = new Team { Name = "Test" };
    var squad = new List<Guid> { Guid.NewGuid(), Guid.NewGuid() }; // identical to "previous" below - zero turnover

    var thorough = new Coach { IsHumanControlled = false };
    thorough.Attributes.WorkEthic = 19; thorough.Attributes.MatchPreparation = 19;
    var lazy = new Coach { IsHumanControlled = false };
    lazy.Attributes.WorkEthic = 2; lazy.Attributes.MatchPreparation = 2;

    int thoroughMeetings = 0, lazyMeetings = 0;
    for (int s = 0; s < 400; s++)
    {
        if (AiClubManagementService.ShouldHoldMeeting(team, thorough, squad, squad, new Random(s))) thoroughMeetings++;
        if (AiClubManagementService.ShouldHoldMeeting(team, lazy, squad, squad, new Random(s + 10_000))) lazyMeetings++;
    }
    TestRunner.IsTrue(thoroughMeetings > lazyMeetings * 3,
        $"a thorough coach calls far more meetings on an unchanged squad than a lazy one ({thoroughMeetings} vs {lazyMeetings} of 400)");
});

TestRunner.Run("Stage 1 / A: NationalPoolMeetingService narrates a weak panel's own findings as thin, and names its attendees", () =>
{
    var svc = new NationalPoolMeetingService();
    var team = new Team { Name = "Test XI", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 20, Politicisation = 90 } };
    var chief = new StaffMember { FirstName = "Chief", LastName = "Selector", Role = StaffRole.ChiefSelector };
    var selector = new StaffMember { FirstName = "Second", LastName = "Selector", Role = StaffRole.Selector };
    var notes = new List<string> { "X drops out", "Y is added", "Z replaces W" };

    var weak = svc.Hold(team, notes, null, new List<StaffMember> { chief, selector }, new DateOnly(2026, 1, 1));
    TestRunner.IsTrue(weak.Attendees.Any(a => a.Contains("Chief")), "the chief selector is named among the attendees");
    TestRunner.IsTrue(weak.Attendees.Any(a => a.Contains("Second")), "the ordinary selector is named too");
    TestRunner.IsTrue(weak.Findings.Count == 1 && weak.Findings[0].Contains("reputation and recent runs"),
        "a weak, political panel's own account of its changes reads thin, exactly like an individual pick under the same panel quality");
    TestRunner.IsTrue(weak.DissentNote is not null, "three real changes from a weak, political panel draws a dissent note");

    var strongTeam = new Team { Name = "Strong XI", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 90, Politicisation = 10 } };
    var strong = svc.Hold(strongTeam, notes, null, new List<StaffMember> { chief, selector }, new DateOnly(2026, 1, 1));
    TestRunner.AreEqual(3, strong.Findings.Count, "a strong panel's real findings are reported in full, not summarised as thin");
    TestRunner.IsTrue(strong.DissentNote is null, "a strong, apolitical panel draws no dissent note over the same three changes");
});

TestRunner.Run("Stage 1 / A (Phase 16 review fold-in): a repeated outvote costs the chairman's standing and raises a SelectorsAtWar storyline; a single one does not", () =>
{
    var world = EmptyWorld();
    var team = new Team { Name = "Test XI", IsNational = true, NationalBoard = new NationalBoard { ChairmanOfSelectorsQuality = 60 } };
    var carried = MatchTestData.MakePlayer("Carried", 12);
    world.Players.Add(carried);
    var date = new DateOnly(2026, 1, 1);

    var outvoted = new SelectionMeetingReport("h", Array.Empty<(string, string)>(), Array.Empty<string>(), null, null, null, "c", 40,
        Outvoted: true, VotesForChosen: 1, PanelSize: 3, OutvotedChosenPlayerId: carried.Id, OutvotedRivalPlayerId: Guid.NewGuid());
    var settled = outvoted with { Outvoted = false };

    double startingConfidence = carried.Form.Confidence;
    AiClubManagementService.ApplyOutvotedConsequences(world, team, outvoted, date).ToList();
    TestRunner.AreEqual(1, team.NationalBoard!.ConsecutiveOutvotes, "one outvote is tracked but not yet acted on");
    TestRunner.IsTrue(carried.Form.Confidence < startingConfidence, "the player carried over the room's own preference feels a real confidence dent, every time");
    TestRunner.IsTrue(!world.Storylines.Any(s => s.Kind == StorylineKind.SelectorsAtWar), "a single outvote is not yet a story");

    AiClubManagementService.ApplyOutvotedConsequences(world, team, outvoted, date).ToList();
    double qualityBeforeThreshold = team.NationalBoard.ChairmanOfSelectorsQuality;
    var raised = AiClubManagementService.ApplyOutvotedConsequences(world, team, outvoted, date).ToList();
    TestRunner.AreEqual(3, team.NationalBoard.ConsecutiveOutvotes, "three in a row");
    TestRunner.IsTrue(team.NationalBoard.ChairmanOfSelectorsQuality < qualityBeforeThreshold, "the chairman's own standing takes a real hit on the third");
    TestRunner.IsTrue(world.Storylines.Any(s => s.Kind == StorylineKind.SelectorsAtWar && s.TeamId == team.Id), "a genuine, repeated pattern raises the SelectorsAtWar storyline");
    TestRunner.IsTrue(raised.Any(e => e.Type == GameEventType.NarrativeUpdate), "the storyline's start is real news, not a silent state change");

    // A meeting that was NOT outvoted resets the streak.
    AiClubManagementService.ApplyOutvotedConsequences(world, team, settled, date).ToList();
    TestRunner.AreEqual(0, team.NationalBoard.ConsecutiveOutvotes, "a settled meeting resets the streak - the pattern has to be genuinely sustained");
});

