TestRunner.Run("Stage 2 / C: first-hand knowledge - a franchise whose core has shared a dressing room with an uncapped player reads him; a global star and a stranger read nothing", () =>
{
    var world = EmptyWorld();
    var svc = new FirstHandKnowledgeService();
    var sharedTeam = Guid.NewGuid();

    var franchise = new Team { Name = "Test Franchise", IsFranchise = true };
    world.Teams[franchise.Id] = franchise;
    for (int i = 0; i < 6; i++)
    {
        var core = MatchTestData.MakePlayer($"Core{i}", 14);
        core.CareerTeamIds.Add(sharedTeam);
        world.Players.Add(core);
        franchise.SquadPlayerIds.Add(core.Id);
    }

    var known = MatchTestData.MakePlayer("Uncapped", 12);
    known.Reputation = new Reputation(domestic: 45, continental: 10, worldwide: 15);
    known.CareerTeamIds.Add(sharedTeam);
    world.Players.Add(known);

    var star = MatchTestData.MakePlayer("Superstar", 18);
    star.Reputation = new Reputation(domestic: 90, continental: 85, worldwide: 80);
    star.CareerTeamIds.Add(sharedTeam);
    world.Players.Add(star);

    var stranger = MatchTestData.MakePlayer("Stranger", 12);
    stranger.Reputation = new Reputation(domestic: 40, continental: 10, worldwide: 10);
    stranger.CareerTeamIds.Add(Guid.NewGuid()); // never crossed paths
    world.Players.Add(stranger);

    var playersById = world.Players.ToDictionary(p => p.Id);
    TestRunner.IsTrue(svc.ReadStrength(playersById, franchise, known, null) > 0.3, "the retained core has a real first-hand read on him");
    TestRunner.AreEqual(0.0, svc.ReadStrength(playersById, franchise, star, null), "a globally-known star is no edge - everyone knows him");
    TestRunner.AreEqual(0.0, svc.ReadStrength(playersById, franchise, stranger, null), "no shared history, no read");
});

TestRunner.Run("Stage 2 / B: FranchiseArchetype evolution - the philosophy mapping, a coach-driven shift, and the results-driven shift with its cooldown", () =>
{
    var svc = new FranchiseIdentityService();
    TestRunner.AreEqual(FranchiseArchetype.StarHunter, FranchiseIdentityService.ArchetypeForPhilosophy(CoachingPhilosophy.Aggressive), "aggressive -> star hunter");
    TestRunner.AreEqual(FranchiseArchetype.Moneyball, FranchiseIdentityService.ArchetypeForPhilosophy(CoachingPhilosophy.AnalyticsDriven), "analytics -> moneyball");
    TestRunner.AreEqual(FranchiseArchetype.YouthBuilder, FranchiseIdentityService.ArchetypeForPhilosophy(CoachingPhilosophy.YouthDevelopment), "youth dev -> youth builder");

    var world = EmptyWorld();
    var f = new Team { Name = "Test F", IsFranchise = true, FranchiseArchetype = FranchiseArchetype.Balanced };
    world.Teams[f.Id] = f;

    // A strong-willed coach whose philosophy points elsewhere, with a weak-leadership captain - the direction changes.
    var cap = MatchTestData.MakePlayer("Cap", 14); cap.Mental.Leadership = 3;
    world.Players.Add(cap); f.SetCaptain(MatchFormat.T20, cap.Id);
    var coach = new Coach { FirstName = "Bold", LastName = "Coach", Philosophy = CoachingPhilosophy.Aggressive, Authority = 60 };
    coach.Attributes.ManManagement = 18;
    var e = svc.DriftFromNewCoach(world, f, coach, new DateOnly(2028, 4, 1));
    TestRunner.IsTrue(e is not null && f.FranchiseArchetype == FranchiseArchetype.StarHunter, "the new coach redraws the identity toward his own philosophy");
    TestRunner.AreEqual(2028, f.LastIdentityShiftYear, "the cooldown clock is set");

    // Same year -> in cooldown, no further shift even on a clear results signal.
    f.PlayerTradingPnL = -900_000; f.DynastyRating = 20;
    TestRunner.IsTrue(svc.DriftFromResults(f, continuity: 0.1, recentTitles: 0, date: new DateOnly(2028, 4, 2)) is null, "no second shift inside the cooldown window");

    // Years later, the results signal is acted on.
    var e2 = svc.DriftFromResults(f, continuity: 0.1, recentTitles: 0, date: new DateOnly(2032, 4, 1));
    TestRunner.IsTrue(e2 is not null && f.FranchiseArchetype == FranchiseArchetype.Moneyball, "a sustained bad spell after a splurge -> a value approach");
});

TestRunner.Run("Stage 2 / G: no fixed squad template - a franchise's archetype and identity genuinely reshape its role emphasis", () =>
{
    var moneyballAllrounder = new Team { IsFranchise = true, FranchiseArchetype = FranchiseArchetype.Moneyball, CulturalIdentity = CoachingPhilosophy.AllrounderLeaning };
