    TestRunner.IsTrue(ma["all-round balance"] > 1.5, "a Moneyball + allrounder-leaning side loads up on all-round balance");
    TestRunner.IsTrue(sh["top-order batting"] > 1.15 && sh["all-round balance"] < 1.0, "a star hunter loads the top order and sheds the filler roles");
});

TestRunner.Run("Stage 2 / D+E+F: the auction produces a pre-auction war-room meeting, an EOI conversion meeting, and a per-franchise post-auction review", () =>
{
    var seeder = new WorldSeeder(seed: 424, worldStartDate: new DateOnly(2026, 1, 1));
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia", "England", "India" }, teamsPerCountry: 4, squadSize: 15, seasonYear: 2026);
    var world = new WorldState { Teams = iw.Teams.ToDictionary(t => t.Id), Grounds = iw.Grounds.ToDictionary(g => g.Id), Players = iw.Players.ToList(), Projects = new List<InfrastructureProject>(), CountryProfiles = iw.CountryProfiles };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);
    var comp = world.Competitions.First(c => c.IsFranchiseAuctionLeague);
    var season = world.CompetitionSeasons.First(s => s.CompetitionId == comp.Id);

    var summary = new FranchiseAuctionService().RunAuctionDetailed(world, comp, season, new DateOnly(2026, 3, 20), new Random(9));
    var report = new FranchiseAuctionMediaService().Report(world, comp, season, summary, new DateOnly(2026, 3, 21), new Random(9));

