    TestRunner.IsTrue(summary.Events.Any(e => e.Type == GameEventType.EoiConversionMeeting && e.Headline.Contains("auction list")),
        "the EOI register is converted to the auction list in a genuine meeting");
    TestRunner.IsTrue(report.Count(e => e.Type == GameEventType.PostAuctionReview) >= franchiseCount - 1,
        "a post-auction squad review for (almost) every franchise");
    TestRunner.IsTrue(report.Any(e => e.Type == GameEventType.PostAuctionReview && e.Headline.Contains("Projected XI")),
        "the post-auction review names the projected XI");
});

TestRunner.Run("Stage 2 / I: GenerateTieredDomesticStructure builds an N-division promotion/relegation chain (the generic generator; live seeded-world wiring deferred - determinism)", () =>
{
    var seeder = new WorldSeeder(seed: 71, worldStartDate: new DateOnly(2026, 1, 1));
    var (teams, _) = seeder.GenerateStarterWorld("Testland", teamCount: 12, squadSize: 12);

    var (_, divisions, seasons, fixtures, _) = seeder.GenerateTieredDomesticStructure(teams, tierCount: 4, "Testland", 2026, promotionRelegationCount: 1);
    TestRunner.AreEqual(4, divisions.Count, "four divisions");
    for (int i = 0; i < 3; i++)
        TestRunner.AreEqual(divisions[i + 1].Id, divisions[i].SecondTierCompetitionId, $"division {i + 1} links down to division {i + 2}");
    TestRunner.IsTrue(divisions[3].SecondTierCompetitionId is null, "the bottom division links to nothing");
    TestRunner.IsTrue(divisions.Take(3).All(d => d.PromotionRelegationCount == 1), "every division above the bottom has a real swap count");
    TestRunner.AreEqual(4, seasons.Count, "a season per division");
    TestRunner.IsTrue(fixtures.Count > 0, "real fixtures are scheduled for the pyramid");
    // Each division has at least 3 clubs - the generator clamps a requested tier count to teams/3
    // (a 2-club division is a degenerate structure and a real lower division has more anyway).
    for (int i = 0; i < seasons.Count; i++)
        TestRunner.IsTrue(seasons[i].ParticipatingTeamIds.Count >= 3, $"division {i + 1} has >= 3 clubs");

    // NOTE: wiring this into the live seeded world (GenerateInternationalWorld) is deliberately
    // deferred - it reproducibly amplified a latent, not-fully-root-caused non-determinism over a
    // long multi-year sim. CompetitionSeasonRunner already walks an arbitrary-length chain, so the
    // wiring is a small change once that is closed. See CLAUDE.md's deferred register.
    var iw = seeder.GenerateInternationalWorld(new[] { "Pakistan", "Australia" }, teamsPerCountry: 4, squadSize: 13, seasonYear: 2026);
    TestRunner.IsTrue(iw.Competitions.Any(c => c.Scope == CricketManager.Domain.Enums.CompetitionScope.DomesticT20), "the seeded world still has a domestic T20 competition per country");
});

TestRunner.Run("Stage 2 / fold-in: the standing-status digest is always produced for a human's club and only for an AI club when something is off", () =>
{
    var world = EmptyWorld();
