});

// ==================== Corrections pass (on top of the Meeting-Driven Selection ticket) ====================

TestRunner.Run("Correction 1: NoteLostMustHave - a franchise that loses a genuine must-have to a rival has that role's plan-B promoted; the winner and a fallback-only franchise are untouched", () =>
{
    var lostPlayer = Guid.NewGuid();
    var winnerId = Guid.NewGuid();
    var loserId = Guid.NewGuid();
    var fallbackOnlyId = Guid.NewGuid();

    var winnerPlan = new FranchiseAuctionPlan
    {
        FranchiseId = winnerId,
        Targets = { new FranchiseAuctionPlan.PlanTarget(lostPlayer, "front-line pace", 0, 1_000_000, true) },
    };
    var loserPlan = new FranchiseAuctionPlan
    {
        FranchiseId = loserId,
        Targets =
        {
            new FranchiseAuctionPlan.PlanTarget(lostPlayer, "front-line pace", 0, 900_000, true),
            new FranchiseAuctionPlan.PlanTarget(Guid.NewGuid(), "front-line pace", 1, 500_000, false),
        },
    };
    var fallbackOnlyPlan = new FranchiseAuctionPlan
    {
        FranchiseId = fallbackOnlyId,
        Targets = { new FranchiseAuctionPlan.PlanTarget(lostPlayer, "front-line pace", 2, 400_000, true) },
    };
    var plans = new Dictionary<Guid, FranchiseAuctionPlan>
    {
        [winnerId] = winnerPlan, [loserId] = loserPlan, [fallbackOnlyId] = fallbackOnlyPlan,
    };

    var lot = new FranchiseAuctionService.AuctionLot(lostPlayer, "Ace Quick",
        AuctionSet.CappedPace, true, 100_000, 1_100_000, winnerId, false);
    FranchiseAuctionService.NoteLostMustHave(lot, plans);

    TestRunner.IsTrue(loserPlan.RolesWithLostMustHave.Contains("front-line pace"), "the franchise that lost its must-have has that role's plan-B promoted");
    TestRunner.IsTrue(!winnerPlan.RolesWithLostMustHave.Contains("front-line pace"), "the winner is untouched");
    TestRunner.IsTrue(!fallbackOnlyPlan.RolesWithLostMustHave.Contains("front-line pace"), "a franchise for whom he was only a fallback (tier 2) is untouched");
});

