TestRunner.Run("Correction 2: pitch doctoring is off where the home side has no influence, and a quality floor (not a % cap) means an aggressive prep on a poor square can be rated poor", () =>
{
    var doctor = new PitchDoctoringService();
    var home = new Team { Name = "H" };
    var homeXi = Enumerable.Range(0, 11).Select(i => MatchTestData.MakePlayer($"H{i}", 14, PlayerRole.Bowler, BowlingRoleType.SpecialistSpinner)).ToList();
    var awayXi = Enumerable.Range(0, 11).Select(i => MatchTestData.MakePlayer($"A{i}", 8)).ToList();
    var ground = new Ground { Name = "G", PitchSpinRating = 55, Facilities = new GroundFacilities { PitchInfrastructure = 15 } };

    // influence <= 0.05 -> never even tries, whatever the edge.
    for (int seed = 0; seed < 20; seed++)
        TestRunner.AreEqual(PitchPreparation.Neutral, doctor.Decide(home, homeXi, awayXi, ground, new Random(seed), homePitchInfluence: 0.0),
            "no attempt to shape the pitch at an ICC event");

    // High influence + a poorly-resourced square -> OverPreparedPoorly fires a real fraction of the time.
    int poor = 0;
    for (int seed = 0; seed < 400; seed++)
        if (PitchDoctoringService.OverPreparedPoorly(PitchPreparation.Dry, ground, homePitchInfluence: 1.0, new Random(seed))) poor++;
    TestRunner.IsTrue(poor > 15, $"a genuinely aggressive prep on a poor square is rated poor sometimes (was {poor}/400)");

    int poorLowInfluence = 0;
    for (int seed = 0; seed < 400; seed++)
        if (PitchDoctoringService.OverPreparedPoorly(PitchPreparation.Dry, ground, homePitchInfluence: 0.3, new Random(seed))) poorLowInfluence++;
    TestRunner.AreEqual(0, poorLowInfluence, "a low-influence (ICC / franchise) surface is prepared to a central standard and never rated poor this way");
});

TestRunner.Run("Correction 4: a per-instance selection-meeting skip is one-shot and per-competition, distinct from the blanket HoldSelectionMeetings toggle", () =>
{
