    TestRunner.IsTrue(AiClubManagementService.ShouldHoldMeeting(team, coach, squad, squad, new Random(1), comp),
        "the very next meeting for the same competition is held again");

    team.ManagerPreferences.SkipNextSelectionMeetingFor.Add(comp);
