// ==================== Seven-suggestions pass ====================

static (Team Nat, CountryProfile Profile) SeedNation(WorldState w, string country, MembershipStatus m = MembershipStatus.FullMember,
    double history = 60, double media = 55, double repWorld = 45)
{
    var nat = new Team { Name = country, Country = country, IsNational = true, NationalBoard = new NationalBoard(),
        Reputation = new Reputation(domestic: 75, continental: 55, worldwide: repWorld),
        Finances = new TeamFinances { Budget = 20_000_000 } };
    w.Teams[nat.Id] = nat;
    var profile = new CountryProfile { Nationality = country, Membership = m, CricketHistoryWeight = history, MediaIntensity = media, BoardYouthInvestment = 50 };
    w.CountryProfiles[country] = profile;
    return (nat, profile);
}

TestRunner.Run("S5: the ICC revenue split - the top nation is capped and flattened, associates get a growing share, and it feeds national finances + youth investment", () =>
{
    var w = EmptyWorld();
    w.MarketIndex = 1.0;
    var (india, _) = SeedNation(w, "India", history: 92, media: 90, repWorld: 85);
    SeedNation(w, "England", history: 94, media: 88, repWorld: 70);
    SeedNation(w, "Australia", history: 94, media: 78, repWorld: 72);
    SeedNation(w, "Pakistan", history: 78, media: 84, repWorld: 55);
    var (neth, nethProfile) = SeedNation(w, "Netherlands", MembershipStatus.Associate, history: 12, media: 30, repWorld: 15);
    double nethBudgetBefore = neth.Finances.Budget;
    double nethYouthBefore = nethProfile.BoardYouthInvestment;

    var cal = new GameCalendar(new DateOnly(2026, 1, 1), worldSeed: 1);
    var events = new IccRevenueService().DistributeAnnually(w, cal, new DateOnly(2026, 12, 1)).ToList();

    TestRunner.IsTrue(events.Any(e => e.Type == GameEventType.IccRevenueDistributed), "the distribution is news");
    // The flattening property: India gets the most, but the gap to the next nation is not the
    // 6x it is in reality - the cap + redistribution pulls the majors together.
    double indiaGross = india.Finances.Budget - 20_000_000 + 6_000_000; // net + board operating cost added back = gross
    double englandGross = w.Teams.Values.First(t => t.Country == "England").Finances.Budget - 20_000_000 + 6_000_000;
    TestRunner.IsTrue(indiaGross > englandGross, "India still gets the largest share");
    TestRunner.IsTrue(indiaGross < englandGross * 3, $"but it is flattened, not 6x (India {indiaGross:N0} vs England {englandGross:N0})");
    TestRunner.IsTrue(neth.Finances.Budget != nethBudgetBefore, "an associate board's finances move");
    TestRunner.IsTrue(nethProfile.BoardYouthInvestment > nethYouthBefore, "and its youth investment rises toward a funded target");

    // A later year: the associate share has grown.
    var e2036 = new IccRevenueService().DistributeAnnually(w, cal, new DateOnly(2036, 12, 1)).ToList();
    TestRunner.IsTrue(e2036[0].Headline.Contains("associate"), "the associate share is called out");
});

TestRunner.Run("S7: an associate with a sustained record earns Full Membership - telegraphed, then granted, and irrevocable", () =>
{
    var w = EmptyWorld();
    var (assoc, profile) = SeedNation(w, "Ireland", MembershipStatus.Associate, history: 26, repWorld: 40);
    assoc.Reputation = new Reputation(domestic: 70, continental: 62, worldwide: 44);
    profile.BoardYouthInvestment = 72; profile.PoliticalStability = 70;
    assoc.Finances.Budget = 2_000_000;
    var wtc = new Competition { Name = "World Test Championship", Scope = CompetitionScope.International, Format = MatchFormat.Test, Prestige = 90 };
    var odiC = new Competition { Name = "ODI Championship", Scope = CompetitionScope.International, Format = MatchFormat.ODI, Prestige = 80 };
    w.Competitions.Add(wtc); w.Competitions.Add(odiC);
    var qualifier = new Competition { Name = "ICC Associate Qualifier", Scope = CompetitionScope.International, Format = MatchFormat.ODI };
    w.Competitions.Add(qualifier);
    for (int y = 2024; y <= 2026; y++)
    {
        var s = new CompetitionSeason { CompetitionId = qualifier.Id, Year = y };
        s.ParticipatingTeamIds.Add(assoc.Id);
        s.Complete(assoc.Id); // Ireland wins the qualifier each year
        w.CompetitionSeasons.Add(s);
    }

    var svc = new FullMembershipService();
    bool granted = false;
    for (int y = 2027; y <= 2045 && !granted; y++)
    {
        var evs = svc.ReviewAnnually(w, new DateOnly(y, 12, 1)).ToList();
        granted = profile.Membership == MembershipStatus.FullMember;
    }
    TestRunner.IsTrue(granted, "Ireland is eventually granted Full Membership");
    TestRunner.IsTrue(profile.FullMembershipCandidateSince is not null, "it was a public candidate first");
    TestRunner.IsTrue(w.PlannedRosters.Keys.Any(k => k.Item1 == wtc.Id), "it is admitted to the World Test Championship");

    // Irrevocable - running it again, even with the credit reset, never demotes.
    profile.FullMembershipCredit = 0;
    svc.ReviewAnnually(w, new DateOnly(2046, 12, 1)).ToList();
    TestRunner.AreEqual(MembershipStatus.FullMember, profile.Membership, "Full Member status is permanent (Article 2.7)");
});

TestRunner.Run("S6: representation drift - the 3-year stand-down blocks a recently-capped player; a Loyal player retires rather than switch", () =>
{
    var w = EmptyWorld();
    SeedNation(w, "England");
    var assocN = SeedNation(w, "Scotland", MembershipStatus.Associate).Nat;
    var club = new Team { Name = "County", Country = "England" }; w.Teams[club.Id] = club;
    var drift = new RepresentationDriftService();

    // A player capped for Scotland last year cannot switch to England yet (3-year stand-down).
    var recent = MatchTestData.MakePlayer("Recent Cap", 15);
    recent.Nationality = "Scotland"; recent.CurrentTeamId = club.Id; recent.DateOfBirth = new DateOnly(1998, 1, 1);
    recent.Reputation = new Reputation(domestic: 75, continental: 50);
    recent.Personality |= PersonalityTrait.Ambitious;
    recent.Experience.RecordAppearance(MatchFormat.ODI, new DateOnly(2028, 6, 1), isInternational: true);
    w.Players.Add(recent);
    bool switchedEarly = false;
    for (int y = 2029; y <= 2030 && !switchedEarly; y++) { drift.ReviewAnnually(w, new DateOnly(y, 12, 1)).ToList(); switchedEarly = recent.Nationality == "England"; }
    TestRunner.IsTrue(!switchedEarly, "within 3 years of his last cap he is still standing down");

    // A Loyal, out-of-favour, eligible player sometimes retires rather than switch.
    var w2 = EmptyWorld();
    SeedNation(w2, "England"); SeedNation(w2, "Scotland", MembershipStatus.Associate);
    var c2 = new Team { Name = "County", Country = "England" }; w2.Teams[c2.Id] = c2;
    var loyals = new List<Player>();
    for (int i = 0; i < 60; i++)
    {
        var loyal = MatchTestData.MakePlayer($"Loyal{i}", 15);
        loyal.Nationality = "Scotland"; loyal.CurrentTeamId = c2.Id;
        loyal.DateOfBirth = new DateOnly(1999, 1, 1).AddDays(i * 9);
        loyal.Reputation = new Reputation(domestic: 76, continental: 48);
        loyal.Personality |= PersonalityTrait.Loyal;
        w2.Players.Add(loyal); loyals.Add(loyal);
    }
    for (int y = 2029; y <= 2034; y++)
        drift.ReviewAnnually(w2, new DateOnly(y, 12, 1)).ToList();
    int retiredRatherThanSwitch = loyals.Count(l => l.IsRetired && l.Nationality == "Scotland");
    TestRunner.IsTrue(retiredRatherThanSwitch >= 1, $"a Loyal player sometimes ends his career rather than switch ({retiredRatherThanSwitch}/60)");
});

TestRunner.Run("NEW-C: a retired player's second career is routed by pedigree and temperament - a legend mentors, a journeyman scouts, a disengaged one leaves", () =>
{
    var w = EmptyWorld();
    var svc = new PlayerRetirementCareerService();

    Player Retiree(string name, double repW, int caps, params PersonalityTrait[] traits)
    {
        var p = MatchTestData.MakePlayer(name, 15);
        p.Reputation = new Reputation(domestic: 70, continental: repW * 0.8, worldwide: repW);
        p.Mental.Leadership = 16; p.Mental.GameAwareness = 14;
        foreach (var t in traits) p.Personality |= t;
        for (int i = 0; i < caps; i++) p.Experience.RecordAppearance(MatchFormat.Test, new DateOnly(2020, 1, 1), isInternational: true);
        p.IsRetired = true;
        return p;
