    var legend = Retiree("The Legend", 82, 120, PersonalityTrait.Leader, PersonalityTrait.Ambitious);
    var journeyman = Retiree("Steady Pro", 20, 2, PersonalityTrait.Professional);
    journeyman.Mental.Leadership = 9;
    var disengaged = Retiree("Done With It", 35, 8, PersonalityTrait.Lazy);

    // Deterministic-ish: run with a seed that makes the take-up rolls succeed.
