    TestRunner.IsTrue(w.Staff.Any(s => s.FromPlayerId == legend.Id && s.Role == StaffRole.Mentor)
                      || evs.Any(e => e.Headline.Contains("mentor role")), "a revered name takes a mentor role");
    TestRunner.IsTrue(!w.Coaches.Any(c => c.FromPlayerId == disengaged.Id) && !w.Staff.Any(s => s.FromPlayerId == disengaged.Id),
        "a disengaged player does not move into coaching");
});

TestRunner.Run("NEW-B: a national selection panel is staffed only by eligible ex-cricketers - min caps, retired 5+ years, right nationality; chief is the most-capped", () =>
{
    var w = EmptyWorld();
    var nat = new Team { Name = "England", Country = "England", IsNational = true, Reputation = new Reputation(domestic: 80) };
    w.Teams[nat.Id] = nat;

    StaffMember ExSelector(string name, string nationality, int testCaps, int yearsRetired, double weight = 55)
    {
        var pid = Guid.NewGuid();
        var xp = PlayerExperience.FromExistingCareer(new Dictionary<MatchFormat, int> { [MatchFormat.Test] = testCaps }, internationalMatches: testCaps);
        w.Players.Add(new Player { Id = pid, FirstName = name, LastName = "X", IsRetired = true, Nationality = nationality,
            Experience = xp });
        return new StaffMember { FirstName = name, LastName = "X", Role = StaffRole.Selector, Nationality = nationality,
            FromPlayerId = pid, RetiredAsPlayerOn = new DateOnly(2026 - yearsRetired, 1, 1), PlayingCareerWeight = weight,
            Analysis = 14, Statistics = 13, Diligence = 13, Communication = 12 };
    }

    var eligibleBig = ExSelector("Chair Man", "England", testCaps: 60, yearsRetired: 8, weight: 80);
    var eligibleSmall = ExSelector("Panel A", "England", testCaps: 12, yearsRetired: 6);
    var tooRecent = ExSelector("Too Soon", "England", testCaps: 40, yearsRetired: 3);
    var wrongCountry = ExSelector("Foreigner", "Australia", testCaps: 50, yearsRetired: 10);
    var tooFewCaps = ExSelector("Club Man", "England", testCaps: 2, yearsRetired: 10); // Test 2, total 2 -> fails every caps route
    foreach (var s in new[] { eligibleBig, eligibleSmall, tooRecent, wrongCountry, tooFewCaps }) w.Staff.Add(s);

    new AiClubManagementService().FillSelectionPanel(w, new DateOnly(2026, 1, 5), nat, new Random(1)).ToList();

    var seated = w.Staff.Where(s => s.TeamId == nat.Id && s.Role is StaffRole.Selector or StaffRole.ChiefSelector).ToList();
    TestRunner.IsTrue(seated.Contains(eligibleBig) && seated.Contains(eligibleSmall), "both eligible ex-internationals are seated");
    TestRunner.IsTrue(!seated.Contains(tooRecent) && !seated.Contains(wrongCountry) && !seated.Contains(tooFewCaps), "the ineligible ones are not");
    TestRunner.AreEqual(StaffRole.ChiefSelector, eligibleBig.Role, "the most-capped panellist is the chairman of selectors");
});

