    var svc = new FranchiseCoachService();
    svc.EnsureStaffInPost(w, comp, season, new DateOnly(2026, 3, 1), new Random(1)).ToList();

    TestRunner.IsTrue(w.Staff.Any(s => s.FranchiseStaffTeamId == f1.Id && s.Role == StaffRole.Analyst), "the franchise has an analyst on a real contract");
    TestRunner.IsTrue(w.StaffContracts.Any(k => k.TeamId == f1.Id && k.Status == ContractStatus.Active && k.EndDate > new DateOnly(2027, 1, 1)), "on a multi-year deal");
    TestRunner.IsTrue(!svc.IsStaffAvailableFor(w, natStaff, comp), "a foreign national-team staffer is not available to the franchise");

    var hostStaff = new StaffMember { FirstName = "Home", LastName = "Physio", Role = StaffRole.Physiotherapist, TeamId = new Team { IsNational = true, Country = "Hostland" }.Id };
    var hostNat = new Team { Name = "Hosts", IsNational = true, Country = "Hostland" }; w.Teams[hostNat.Id] = hostNat;
    hostStaff.TeamId = hostNat.Id; w.Staff.Add(hostStaff);
    TestRunner.IsTrue(svc.IsStaffAvailableFor(w, hostStaff, comp), "a host-country national staffer IS available");
});

TestRunner.Run("S3: CommercialAppeal - a marketable star scores high, a guarded journeyman low, and it feeds the club image-rights line", () =>
{
    var star = MatchTestData.MakePlayer("Brand", 16);
    star.Reputation = new Reputation(domestic: 88, continental: 82, worldwide: 84);
    star.Personality |= PersonalityTrait.Ambitious; // -> Marketable persona
    var journeyman = MatchTestData.MakePlayer("Quiet", 12);
    journeyman.Reputation = new Reputation(domestic: 30, continental: 8, worldwide: 4);
    // no personality flags -> Guarded persona
    TestRunner.IsTrue(star.CommercialAppeal > 70, $"a marketable, in-form star has real commercial appeal ({star.CommercialAppeal:N0})");
    TestRunner.IsTrue(journeyman.CommercialAppeal < 25, $"a guarded low-profile player has little ({journeyman.CommercialAppeal:N0})");
});

TestRunner.Run("S4: after a long layoff a player needs match fitness before an international recall - domestic selection is unaffected", () =>
{
    var p = MatchTestData.MakePlayer("Long Layoff", 15);
    var avail = new PlayerAvailabilityService();
    avail.ApplyInjury(p, InjuryType.KneeInjury, InjurySeverity.Serious, new DateOnly(2026, 1, 1));
    avail.MarkRecovered(p, new DateOnly(2026, 7, 1));
    TestRunner.IsTrue(p.NeedsMatchFitnessUntil is not null && p.NeedsMatchFitnessUntil > new DateOnly(2026, 7, 1), "a match-fitness window is set");

    var natCheck = avail.GetAvailability(p, new DateOnly(2026, 7, 15), MatchFormat.ODI, selectingForNationalTeam: true);
    TestRunner.IsTrue(!natCheck.IsAvailable, "he is not available for an international recall yet");
    var clubCheck = avail.GetAvailability(p, new DateOnly(2026, 7, 15), MatchFormat.ODI, selectingForNationalTeam: false);
    TestRunner.IsTrue(clubCheck.IsAvailable, "but he is available for his club / domestic cricket");

    var later = avail.GetAvailability(p, new DateOnly(2026, 10, 1), MatchFormat.ODI, selectingForNationalTeam: true);
    TestRunner.IsTrue(later.IsAvailable, "the window expires and he is back in the international reckoning");
});

Environment.Exit(TestRunner.Summarize());

static WorldState WorldFromInternational(CricketManager.Data.Seeding.InternationalWorld iw)
{
    var world = new WorldState
    {
        Teams = iw.Teams.ToDictionary(t => t.Id),
        Grounds = iw.Grounds.ToDictionary(g => g.Id),
        Players = iw.Players.ToList(),
        Projects = new List<InfrastructureProject>(),
    };
    foreach (var c in iw.Competitions) world.Competitions.Add(c);
    foreach (var s in iw.Seasons) world.CompetitionSeasons.Add(s);
    foreach (var f in iw.Fixtures) world.Fixtures.Add(f);
    foreach (var r in iw.Rivalries) world.Rivalries.Add(r);
    foreach (var p in iw.NationalPools) world.NationalPools.Add(p);
    foreach (var u in iw.Umpires) world.Umpires.Add(u);
    foreach (var pc in iw.PlayerContracts) world.PlayerContracts.Add(pc);
    foreach (var kv in iw.CountryProfiles) world.CountryProfiles[kv.Key] = kv.Value;
    foreach (var p in iw.Pundits) world.Pundits.Add(p);
    foreach (var a in iw.Agents) world.Agents.Add(a);
    return world;
}

static WorldState EmptyWorld() => new()
{
    Teams = new Dictionary<Guid, Team>(),
    Grounds = new Dictionary<Guid, Ground>(),
    Players = new List<Player>(),
    Projects = new List<InfrastructureProject>()
};
